				}
				else if (Lua.xluaL_loadbuffer(L, val.bytes, val.bytes.Length, "@" + text) != 0)
				{
					return Lua.luaL_error(L, $"error loading module {Lua.lua_tostring(L, 1)} from resource, {Lua.lua_tostring(L, -1)}");
				}
				return 1;
