	public class OverloadMethodWrap
	{
		private ObjectTranslator translator;

		private Type targetType;

		private MethodBase method;

		private ObjectCheck[] checkArray;

		private ObjectCast[] castArray;

		private int[] inPosArray;

		private int[] outPosArray;

		private bool[] isOptionalArray;

		private object[] defaultValueArray;

		private bool isVoid = true;

		private int luaStackPosStart = 1;

		private bool targetNeeded;

		private object[] args;

		private int[] refPos;

		private Type paramsType;

		public bool HasDefalutValue { get; private set; }

		public OverloadMethodWrap(ObjectTranslator translator, Type targetType, MethodBase method)
		{
			this.translator = translator;
			this.targetType = targetType;
			this.method = method;
			HasDefalutValue = false;
		}

		public void Init(ObjectCheckers objCheckers, ObjectCasters objCasters)
		{
			if ((typeof(Delegate) != targetType && typeof(Delegate).IsAssignableFrom(targetType)) || !method.IsStatic || method.IsConstructor)
			{
				luaStackPosStart = 2;
				if (!method.IsConstructor)
				{
					targetNeeded = true;
				}
			}
			ParameterInfo[] parameters = method.GetParameters();
			refPos = new int[parameters.Length];
			List<int> list = new List<int>();
			List<int> list2 = new List<int>();
			List<ObjectCheck> list3 = new List<ObjectCheck>();
			List<ObjectCast> list4 = new List<ObjectCast>();
			List<bool> list5 = new List<bool>();
			List<object> list6 = new List<object>();
			for (int i = 0; i < parameters.Length; i++)
			{
				refPos[i] = -1;
				if (!parameters[i].IsIn && parameters[i].IsOut)
				{
					list2.Add(i);
					continue;
				}
				if (parameters[i].ParameterType.IsByRef)
				{
					Type elementType = parameters[i].ParameterType.GetElementType();
					if (CopyByValue.IsStruct(elementType) && elementType != typeof(decimal))
					{
						refPos[i] = list.Count;
					}
					list2.Add(i);
				}
				list.Add(i);
				Type type = ((parameters[i].IsDefined(typeof(ParamArrayAttribute), inherit: false) || (!parameters[i].ParameterType.IsArray && parameters[i].ParameterType.IsByRef)) ? parameters[i].ParameterType.GetElementType() : parameters[i].ParameterType);
				list3.Add(objCheckers.GetChecker(type));
				list4.Add(objCasters.GetCaster(type));
				list5.Add(parameters[i].IsOptional);
				object obj = parameters[i].DefaultValue;
				if (parameters[i].IsOptional)
				{
					if (obj != null && obj.GetType() != parameters[i].ParameterType)
					{
						obj = ((!(obj.GetType() == typeof(Missing))) ? Convert.ChangeType(obj, parameters[i].ParameterType) : (parameters[i].ParameterType.IsValueType() ? Activator.CreateInstance(parameters[i].ParameterType) : Missing.Value));
					}
					HasDefalutValue = true;
				}
				list6.Add(parameters[i].IsOptional ? obj : null);
			}
			checkArray = list3.ToArray();
			castArray = list4.ToArray();
			inPosArray = list.ToArray();
			outPosArray = list2.ToArray();
			isOptionalArray = list5.ToArray();
			defaultValueArray = list6.ToArray();
			if (parameters.Length != 0 && parameters[parameters.Length - 1].IsDefined(typeof(ParamArrayAttribute), inherit: false))
			{
				paramsType = parameters[parameters.Length - 1].ParameterType.GetElementType();
			}
			args = new object[parameters.Length];
			if (method is MethodInfo)
			{
				isVoid = (method as MethodInfo).ReturnType == typeof(void);
			}
			else if (method is ConstructorInfo)
			{
				isVoid = false;
			}
		}

		public bool Check(IntPtr L)
		{
			int num = Lua.lua_gettop(L);
			int num2 = luaStackPosStart;
			for (int i = 0; i < checkArray.Length && (i != checkArray.Length - 1 || !(paramsType != null)); i++)
			{
				if (num2 > num && !isOptionalArray[i])
				{
					return false;
				}
				if (num2 <= num && !checkArray[i](L, num2))
				{
					return false;
				}
				if (num2 <= num || !isOptionalArray[i])
				{
					num2++;
				}
			}
			if (!(paramsType != null))
			{
				return num2 == num + 1;
			}
			if (num2 >= num + 1)
			{
				return true;
			}
			return checkArray[checkArray.Length - 1](L, num2);
		}

		public int Call(IntPtr L)
		{
			try
			{
				object obj = null;
				MethodBase methodBase = method;
				if (luaStackPosStart > 1)
				{
					obj = translator.FastGetCSObj(L, 1);
					if (obj is Delegate)
					{
						methodBase = ((Delegate)obj).Method;
					}
				}
				int num = Lua.lua_gettop(L);
				int num2 = luaStackPosStart;
				for (int i = 0; i < castArray.Length; i++)
				{
					if (num2 > num)
					{
						if (paramsType != null && i == castArray.Length - 1)
						{
							args[inPosArray[i]] = Array.CreateInstance(paramsType, 0);
						}
						else
						{
							args[inPosArray[i]] = defaultValueArray[i];
						}
						continue;
					}
					if (paramsType != null && i == castArray.Length - 1)
					{
						args[inPosArray[i]] = translator.GetParams(L, num2, paramsType);
					}
					else
					{
						args[inPosArray[i]] = castArray[i](L, num2, null);
					}
					num2++;
				}
				object obj2 = null;
				obj2 = (methodBase.IsConstructor ? ((ConstructorInfo)method).Invoke(args) : method.Invoke(targetNeeded ? obj : null, args));
				if (targetNeeded && targetType.IsValueType())
				{
					translator.Update(L, 1, obj);
				}
				int num3 = 0;
				if (!isVoid)
				{
					translator.PushAny(L, obj2);
					num3++;
				}
				for (int j = 0; j < outPosArray.Length; j++)
				{
					if (refPos[outPosArray[j]] != -1)
					{
						translator.Update(L, luaStackPosStart + refPos[outPosArray[j]], args[outPosArray[j]]);
					}
					translator.PushAny(L, args[outPosArray[j]]);
					num3++;
				}
				return num3;
			}
			finally
			{
				for (int k = 0; k < args.Length; k++)
				{
					args[k] = null;
				}
			}
		}
	}
	public class MethodWrap
	{
		private string methodName;

		private List<OverloadMethodWrap> overloads = new List<OverloadMethodWrap>();

		private bool forceCheck;

		public MethodWrap(string methodName, List<OverloadMethodWrap> overloads, bool forceCheck)
		{
			this.methodName = methodName;
			this.overloads = overloads;
			this.forceCheck = forceCheck;
		}

		public int Call(IntPtr L)
		{
			try
			{
				if (overloads.Count == 1 && !overloads[0].HasDefalutValue && !forceCheck)
				{
					return overloads[0].Call(L);
				}
				for (int i = 0; i < overloads.Count; i++)
				{
					OverloadMethodWrap overloadMethodWrap = overloads[i];
					if (overloadMethodWrap.Check(L))
					{
						return overloadMethodWrap.Call(L);
					}
				}
				return Lua.luaL_error(L, "invalid arguments to " + methodName);
			}
			catch (TargetInvocationException ex)
			{
				return Lua.luaL_error(L, "c# exception:" + ex.InnerException.Message + ",stack:" + ex.InnerException.StackTrace);
			}
			catch (Exception ex2)
			{
				return Lua.luaL_error(L, "c# exception:" + ex2.Message + ",stack:" + ex2.StackTrace);
			}
		}
	}
	public class MethodWrapsCache
	{
		private ObjectTranslator translator;

		private ObjectCheckers objCheckers;

		private ObjectCasters objCasters;

		private Dictionary<Type, lua_CSFunction> constructorCache = new Dictionary<Type, lua_CSFunction>();

		private Dictionary<Type, Dictionary<string, lua_CSFunction>> methodsCache = new Dictionary<Type, Dictionary<string, lua_CSFunction>>();

		private Dictionary<Type, lua_CSFunction> delegateCache = new Dictionary<Type, lua_CSFunction>();

		public MethodWrapsCache(ObjectTranslator translator, ObjectCheckers objCheckers, ObjectCasters objCasters)
		{
			this.translator = translator;
			this.objCheckers = objCheckers;
			this.objCasters = objCasters;
		}

		public lua_CSFunction GetConstructorWrap(Type type)
		{
			if (!constructorCache.ContainsKey(type))
			{
				ConstructorInfo[] constructors = type.GetConstructors();
				if (type.IsAbstract() || constructors == null || constructors.Length == 0)
				{
					if (!type.IsValueType())
					{
						return null;
					}
					constructorCache[type] = delegate(IntPtr L)
					{
						translator.PushAny(L, Activator.CreateInstance(type));
						return 1;
					};
				}
				else
				{
					lua_CSFunction ctor = _GenMethodWrap(type, ".ctor", constructors, forceCheck: true).Call;
					if (type.IsValueType())
					{
						bool flag = false;
						for (int i = 0; i < constructors.Length; i++)
						{
							if (constructors[i].GetParameters().Length == 0)
							{
								flag = true;
								break;
							}
						}
						if (flag)
						{
							constructorCache[type] = ctor;
						}
						else
						{
							constructorCache[type] = delegate(IntPtr L)
							{
								if (Lua.lua_gettop(L) == 1)
								{
									translator.PushAny(L, Activator.CreateInstance(type));
									return 1;
								}
								return ctor(L);
							};
						}
					}
					else
					{
						constructorCache[type] = ctor;
					}
				}
			}
			return constructorCache[type];
		}

		public lua_CSFunction GetMethodWrap(Type type, string methodName)
		{
			if (!methodsCache.ContainsKey(type))
			{
				methodsCache[type] = new Dictionary<string, lua_CSFunction>();
			}
			Dictionary<string, lua_CSFunction> dictionary = methodsCache[type];
			if (!dictionary.ContainsKey(methodName))
			{
				MemberInfo[] member = type.GetMember(methodName, BindingFlags.IgnoreCase | BindingFlags.Instance | BindingFlags.Static | BindingFlags.Public);
				if (member == null || member.Length == 0 || member[0].MemberType != MemberTypes.Method)
				{
					return null;
				}
				dictionary[methodName] = _GenMethodWrap(type, methodName, member).Call;
			}
			return dictionary[methodName];
		}

		public lua_CSFunction GetMethodWrapInCache(Type type, string methodName)
		{
			if (!methodsCache.ContainsKey(type))
			{
				methodsCache[type] = new Dictionary<string, lua_CSFunction>();
			}
			Dictionary<string, lua_CSFunction> dictionary = methodsCache[type];
			if (!dictionary.ContainsKey(methodName))
			{
				return null;
			}
			return dictionary[methodName];
		}

		public lua_CSFunction GetDelegateWrap(Type type)
		{
			if (!typeof(Delegate).IsAssignableFrom(type))
			{
				return null;
			}
			if (!delegateCache.ContainsKey(type))
			{
				delegateCache[type] = _GenMethodWrap(type, type.ToString(), new MethodBase[1] { type.GetMethod("Invoke") }).Call;
			}
			return delegateCache[type];
		}

		public lua_CSFunction GetEventWrap(Type type, string eventName)
		{
			if (!methodsCache.ContainsKey(type))
			{
				methodsCache[type] = new Dictionary<string, lua_CSFunction>();
			}
			Dictionary<string, lua_CSFunction> dictionary = methodsCache[type];
			if (!dictionary.ContainsKey(eventName))
			{
				EventInfo eventInfo = type.GetEvent(eventName, BindingFlags.DeclaredOnly | BindingFlags.Instance | BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic);
				if (eventInfo == null)
				{
					throw new Exception(type.Name + " has no event named: " + eventName);
				}
				int start_idx = 0;
				MethodInfo add = eventInfo.GetAddMethod(nonPublic: true);
				MethodInfo remove = eventInfo.GetRemoveMethod(nonPublic: true);
				if (add == null && remove == null)
				{
					throw new Exception(type.Name + "'s " + eventName + " has either add nor remove");
				}
				bool is_static = ((add != null) ? add.IsStatic : remove.IsStatic);
				if (!is_static)
				{
					start_idx = 1;
				}
				dictionary[eventName] = delegate(IntPtr L)
				{
					object obj = null;
					if (!is_static)
					{
						obj = translator.GetObject(L, 1, type);
						if (obj == null)
						{
							return Lua.luaL_error(L, "invalid #1, needed:" + type);
						}
					}
					try
					{
						object obj2 = translator.CreateDelegateBridge(L, eventInfo.EventHandlerType, start_idx + 2);
						if (obj2 == null)
						{
							return Lua.luaL_error(L, "invalid #" + (start_idx + 2) + ", needed:" + eventInfo.EventHandlerType);
						}
						string text = Lua.lua_tostring(L, start_idx + 1);
						if (!(text == "+"))
						{
							if (!(text == "-"))
							{
								return Lua.luaL_error(L, "invalid #" + (start_idx + 1) + ", needed: '+' or '-'" + eventInfo.EventHandlerType);
							}
							if (remove == null)
							{
								return Lua.luaL_error(L, "no remove for event " + eventName);
							}
							remove.Invoke(obj, new object[1] { obj2 });
						}
						else
						{
							if (add == null)
							{
								return Lua.luaL_error(L, "no add for event " + eventName);
							}
							add.Invoke(obj, new object[1] { obj2 });
						}
					}
					catch (Exception ex)
					{
						return Lua.luaL_error(L, "c# exception:" + ex?.ToString() + ",stack:" + ex.StackTrace);
					}
					return 0;
				};
			}
			return dictionary[eventName];
		}

		public MethodWrap _GenMethodWrap(Type type, string methodName, IEnumerable<MemberInfo> methodBases, bool forceCheck = false)
		{
			List<OverloadMethodWrap> list = new List<OverloadMethodWrap>();
			foreach (MemberInfo methodBasis in methodBases)
			{
				MethodBase method = methodBasis as MethodBase;
				if (!(method == null) && (!method.IsGenericMethodDefinition || tryMakeGenericMethod(ref method)))
				{
					OverloadMethodWrap overloadMethodWrap = new OverloadMethodWrap(translator, type, method);
					overloadMethodWrap.Init(objCheckers, objCasters);
					list.Add(overloadMethodWrap);
				}
			}
			return new MethodWrap(methodName, list, forceCheck);
		}

		private static bool tryMakeGenericMethod(ref MethodBase method)
		{
			try
			{
				if (!(method is MethodInfo) || !Utils.IsSupportedMethod(method as MethodInfo))
				{
					return false;
				}
				Type[] genericArguments = method.GetGenericArguments();
				Type[] array = new Type[genericArguments.Length];
				for (int i = 0; i < genericArguments.Length; i++)
				{
					Type[] genericParameterConstraints = genericArguments[i].GetGenericParameterConstraints();
					array[i] = genericParameterConstraints[0];
				}
				method = ((MethodInfo)method).MakeGenericMethod(array);
				return true;
			}
			catch (Exception)
			{
				return false;
			}
		}
	}
	public delegate bool ObjectCheck(IntPtr L, int idx);
	public delegate object ObjectCast(IntPtr L, int idx, object target);
	public class ObjectCheckers
	{
		private Dictionary<Type, ObjectCheck> checkersMap = new Dictionary<Type, ObjectCheck>();

		private ObjectTranslator translator;

		public ObjectCheckers(ObjectTranslator translator)
		{
			this.translator = translator;
			checkersMap[typeof(sbyte)] = numberCheck;
			checkersMap[typeof(byte)] = numberCheck;
			checkersMap[typeof(short)] = numberCheck;
			checkersMap[typeof(ushort)] = numberCheck;
			checkersMap[typeof(int)] = numberCheck;
			checkersMap[typeof(uint)] = numberCheck;
			checkersMap[typeof(long)] = int64Check;
			checkersMap[typeof(ulong)] = uint64Check;
			checkersMap[typeof(double)] = numberCheck;
			checkersMap[typeof(char)] = numberCheck;
			checkersMap[typeof(float)] = numberCheck;
			checkersMap[typeof(decimal)] = decimalCheck;
			checkersMap[typeof(bool)] = boolCheck;
			checkersMap[typeof(string)] = strCheck;
			checkersMap[typeof(object)] = objectCheck;
			checkersMap[typeof(byte[])] = bytesCheck;
			checkersMap[typeof(IntPtr)] = intptrCheck;
			checkersMap[typeof(LuaTable)] = luaTableCheck;
			checkersMap[typeof(LuaFunction)] = luaFunctionCheck;
		}

		private static bool objectCheck(IntPtr L, int idx)
		{
			return true;
		}

		private bool luaTableCheck(IntPtr L, int idx)
		{
			if (!Lua.lua_isnil(L, idx) && !Lua.lua_istable(L, idx))
			{
				if (Lua.lua_type(L, idx) == LuaTypes.LUA_TUSERDATA)
				{
					return translator.SafeGetCSObj(L, idx) is LuaTable;
				}
				return false;
			}
			return true;
		}

		private bool numberCheck(IntPtr L, int idx)
		{
			return Lua.lua_type(L, idx) == LuaTypes.LUA_TNUMBER;
		}

		private bool decimalCheck(IntPtr L, int idx)
		{
			if (Lua.lua_type(L, idx) != LuaTypes.LUA_TNUMBER)
			{
				return translator.IsDecimal(L, idx);
			}
			return true;
		}

		private bool strCheck(IntPtr L, int idx)
		{
			if (Lua.lua_type(L, idx) != LuaTypes.LUA_TSTRING)
			{
				return Lua.lua_isnil(L, idx);
			}
			return true;
		}

		private bool bytesCheck(IntPtr L, int idx)
		{
			if (Lua.lua_type(L, idx) != LuaTypes.LUA_TSTRING && !Lua.lua_isnil(L, idx))
			{
				if (Lua.lua_type(L, idx) == LuaTypes.LUA_TUSERDATA)
				{
					return translator.SafeGetCSObj(L, idx) is byte[];
				}
				return false;
			}
			return true;
		}

		private bool boolCheck(IntPtr L, int idx)
		{
			return Lua.lua_type(L, idx) == LuaTypes.LUA_TBOOLEAN;
		}

		private bool int64Check(IntPtr L, int idx)
		{
			if (Lua.lua_type(L, idx) != LuaTypes.LUA_TNUMBER)
			{
				return Lua.lua_isint64(L, idx);
			}
			return true;
		}

		private bool uint64Check(IntPtr L, int idx)
		{
			if (Lua.lua_type(L, idx) != LuaTypes.LUA_TNUMBER)
			{
				return Lua.lua_isuint64(L, idx);
			}
			return true;
		}

		private bool luaFunctionCheck(IntPtr L, int idx)
		{
			if (!Lua.lua_isnil(L, idx) && !Lua.lua_isfunction(L, idx))
			{
				if (Lua.lua_type(L, idx) == LuaTypes.LUA_TUSERDATA)
				{
					return translator.SafeGetCSObj(L, idx) is LuaFunction;
				}
				return false;
			}
			return true;
		}

		private bool intptrCheck(IntPtr L, int idx)
		{
			return Lua.lua_type(L, idx) == LuaTypes.LUA_TLIGHTUSERDATA;
		}

		private ObjectCheck genChecker(Type type)
		{
			ObjectCheck fixTypeCheck = delegate(IntPtr L, int idx)
			{
				if (Lua.lua_type(L, idx) == LuaTypes.LUA_TUSERDATA)
				{
					object obj = translator.SafeGetCSObj(L, idx);
					if (obj != null)
					{
						return type.IsAssignableFrom(obj.GetType());
					}
					Type typeOf = translator.GetTypeOf(L, idx);
					if (typeOf != null)
					{
						return type.IsAssignableFrom(typeOf);
					}
				}
				return false;
			};
			if (!type.IsAbstract() && typeof(Delegate).IsAssignableFrom(type))
			{
				return (IntPtr L, int idx) => Lua.lua_isnil(L, idx) || Lua.lua_isfunction(L, idx) || fixTypeCheck(L, idx);
			}
			if (type.IsEnum())
			{
				return fixTypeCheck;
			}
			if (type.IsInterface())
			{
				return (IntPtr L, int idx) => Lua.lua_isnil(L, idx) || Lua.lua_istable(L, idx) || fixTypeCheck(L, idx);
			}
			if (type.IsClass() && type.GetConstructor(Type.EmptyTypes) != null)
			{
				return (IntPtr L, int idx) => Lua.lua_isnil(L, idx) || Lua.lua_istable(L, idx) || fixTypeCheck(L, idx);
			}
			if (type.IsValueType())
			{
				return (IntPtr L, int idx) => Lua.lua_istable(L, idx) || fixTypeCheck(L, idx);
			}
			if (type.IsArray)
			{
				return (IntPtr L, int idx) => Lua.lua_isnil(L, idx) || Lua.lua_istable(L, idx) || fixTypeCheck(L, idx);
			}
			return (IntPtr L, int idx) => Lua.lua_isnil(L, idx) || fixTypeCheck(L, idx);
		}

		public ObjectCheck genNullableChecker(ObjectCheck oc)
		{
			return (IntPtr L, int idx) => Lua.lua_isnil(L, idx) || oc(L, idx);
		}

		public void AddChecker(Type type, ObjectCheck oc)
		{
			checkersMap[type] = oc;
		}

		public ObjectCheck GetChecker(Type type)
		{
			if (type.IsByRef)
			{
				type = type.GetElementType();
			}
			Type underlyingType = Nullable.GetUnderlyingType(type);
			if (underlyingType != null)
			{
				return genNullableChecker(GetChecker(underlyingType));
			}
			if (!checkersMap.TryGetValue(type, out var value))
			{
				value = genChecker(type);
				checkersMap.Add(type, value);
			}
			return value;
		}
	}
