				{
					return Lua.lua_toint64(L, idx);
				}
				if (Lua.lua_isuint64(L, idx))
				{
					return Lua.lua_touint64(L, idx);
				}
				object obj = translator.SafeGetCSObj(L, idx);
				if (!(obj is RawObject))
