				{
					object obj2 = fixTypeGetter(L, idx, target);
					if (obj2 != null)
					{
						return obj2;
					}
					if (!Lua.lua_istable(L, idx))
					{
						return (object)null;
					}
					IDictionary dictionary = ((target == null) ? Activator.CreateInstance(type) : target) as IDictionary;
					int num2 = Lua.lua_gettop(L);
					idx = ((idx > 0) ? idx : (Lua.lua_gettop(L) + idx + 1));
					Lua.lua_pushnil(L);
					if (!Lua.lua_checkstack(L, 1))
					{
						throw new Exception("stack overflow while cast to IDictionary");
					}
					while (Lua.lua_next(L, idx) != 0)
					{
						if (translator.Assignable(L, num2 + 1, keyType) && translator.Assignable(L, num2 + 2, valueType))
						{
							object key = keyCaster(L, num2 + 1, null);
							dictionary[key] = valueCaster(L, num2 + 2, (!dictionary.Contains(key)) ? null : dictionary[key]);
						}
						Lua.lua_pop(L, 1);
					}
					return dictionary;
				};
			}
			if ((type.IsClass() && type.GetConstructor(Type.EmptyTypes) != null) || (type.IsValueType() && !type.IsEnum()))
			{
				return delegate(IntPtr L, int idx, object target)
				{
					object obj = fixTypeGetter(L, idx, target);
					if (obj != null)
					{
						return obj;
					}
					if (!Lua.lua_istable(L, idx))
					{
						return (object)null;
					}
					obj = ((target == null) ? Activator.CreateInstance(type) : target);
					int num = Lua.lua_gettop(L);
					idx = ((idx > 0) ? idx : (Lua.lua_gettop(L) + idx + 1));
					if (!Lua.lua_checkstack(L, 1))
					{
						throw new Exception("stack overflow while cast to " + type);
					}
					FieldInfo[] fields = type.GetFields();
					foreach (FieldInfo fieldInfo in fields)
					{
						Lua.xlua_pushasciistring(L, fieldInfo.Name);
						Lua.lua_rawget(L, idx);
						if (!Lua.lua_isnil(L, -1))
						{
							try
							{
								fieldInfo.SetValue(obj, GetCaster(fieldInfo.FieldType)(L, num + 1, (target == null || fieldInfo.FieldType.IsPrimitive() || fieldInfo.FieldType == typeof(string)) ? null : fieldInfo.GetValue(obj)));
							}
							catch (Exception ex)
							{
								throw new Exception("exception in tran " + fieldInfo.Name + ", msg=" + ex.Message);
							}
						}
						Lua.lua_pop(L, 1);
					}
					return obj;
				};
			}
			return fixTypeGetter;
		}

		private ObjectCast genNullableCaster(ObjectCast oc)
		{
			return (IntPtr L, int idx, object target) => Lua.lua_isnil(L, idx) ? null : oc(L, idx, target);
		}

		public ObjectCast GetCaster(Type type)
		{
			if (type.IsByRef)
			{
				type = type.GetElementType();
			}
			Type underlyingType = Nullable.GetUnderlyingType(type);
			if (underlyingType != null)
			{
				return genNullableCaster(GetCaster(underlyingType));
			}
			if (!castersMap.TryGetValue(type, out var value))
			{
				value = genCaster(type);
				castersMap.Add(type, value);
			}
			return value;
		}
	}
	public class ObjectPool
	{
		private struct Slot
		{
			public int next;

			public object obj;

			public Slot(int next, object obj)
			{
				this.next = next;
				this.obj = obj;
			}
		}

		private const int LIST_END = -1;

		private const int ALLOCED = -2;

		private Slot[] list = new Slot[512];

		private int freelist = -1;

		private int count;

		public object this[int i]
		{
			get
			{
				if (i >= 0 && i < count)
				{
					return list[i].obj;
				}
				return null;
			}
		}

		public void Clear()
		{
			freelist = -1;
			count = 0;
			list = new Slot[512];
		}

		private void extend_capacity()
		{
			Slot[] array = new Slot[list.Length * 2];
			for (int i = 0; i < list.Length; i++)
			{
				array[i] = list[i];
			}
			list = array;
		}

		public int Add(object obj)
		{
			int num = -1;
			if (freelist != -1)
			{
				num = freelist;
				list[num].obj = obj;
				freelist = list[num].next;
				list[num].next = -2;
			}
			else
			{
				if (count == list.Length)
				{
					extend_capacity();
				}
				num = count;
				list[num] = new Slot(-2, obj);
				count = num + 1;
			}
			return num;
		}

		public bool TryGetValue(int index, out object obj)
		{
			if (index >= 0 && index < count && list[index].next == -2)
			{
				obj = list[index].obj;
				return true;
			}
			obj = null;
			return false;
		}

		public object Get(int index)
		{
			if (index >= 0 && index < count)
			{
				return list[index].obj;
			}
			return null;
		}

		public object Remove(int index)
		{
			if (index >= 0 && index < count && list[index].next == -2)
			{
				object obj = list[index].obj;
				list[index].obj = null;
				list[index].next = freelist;
				freelist = index;
				return obj;
			}
			return null;
		}

		public object Replace(int index, object o)
		{
			if (index >= 0 && index < count)
			{
				object obj = list[index].obj;
				list[index].obj = o;
				return obj;
			}
			return null;
		}

		public int Check(int check_pos, int max_check, Func<object, bool> checker, Dictionary<object, int> reverse_map)
		{
			if (count == 0)
			{
				return 0;
			}
			for (int i = 0; i < Math.Min(max_check, count); i++)
			{
				check_pos %= count;
				if (list[check_pos].next == -2 && list[check_pos].obj != null && !checker(list[check_pos].obj))
				{
					object key = Replace(check_pos, null);
					if (reverse_map.TryGetValue(key, out var value) && value == check_pos)
					{
						reverse_map.Remove(key);
					}
				}
				check_pos++;
			}
			return check_pos %= count;
		}
	}
