			if (type.IsGenericType())
			{
				return type.FullName.Split('`')[0] + "<" + string.Join(", ", (from x in type.GetGenericArguments()
					select x.GetFriendlyName()).ToArray()) + ">";
			}
			return type.FullName;
		}
