		private int _repeatedCount;

		private TimerCallback _timerDelegate;

		private EventListener _onPlayEnd;

		/// <summary>
		///
		/// </summary>
		public EventListener onPlayEnd => _onPlayEnd ?? (_onPlayEnd = new EventListener(this, "onPlayEnd"));

		/// <summary>
		///
		/// </summary>
		public Frame[] frames
		{
			get
			{
				return _frames;
			}
			set
			{
				_frames = value;
				_scale9Grid = null;
				_scaleByTile = false;
				if (_frames == null)
				{
					_frameCount = 0;
					base.graphics.texture = null;
					CheckTimer();
					return;
				}
				_frameCount = frames.Length;
				if (_end == -1 || _end > _frameCount - 1)
				{
					_end = _frameCount - 1;
				}
				if (_endAt == -1 || _endAt > _frameCount - 1)
				{
					_endAt = _frameCount - 1;
				}
				if (_frame < 0 || _frame > _frameCount - 1)
				{
					_frame = _frameCount - 1;
				}
				InvalidateBatchingState();
				_frameElapsed = 0f;
				_repeatedCount = 0;
				_reversed = false;
				DrawFrame();
				CheckTimer();
			}
		}

		/// <summary>
		///
		/// </summary>
		public bool playing
		{
			get
			{
				return _playing;
			}
			set
			{
				if (_playing != value)
				{
					_playing = value;
					CheckTimer();
				}
			}
		}

		/// <summary>
		///
		/// </summary>
		public int frame
		{
			get
			{
				return _frame;
			}
			set
			{
				if (_frame != value)
				{
					if (_frames != null && value >= _frameCount)
					{
						value = _frameCount - 1;
					}
					_frame = value;
					_frameElapsed = 0f;
					DrawFrame();
				}
			}
		}

		/// <summary>
		///
		/// </summary>
		public MovieClip()
		{
			interval = 0.1f;
			_playing = true;
			_timerDelegate = OnTimer;
			timeScale = 1f;
			ignoreEngineTimeScale = false;
			if (Application.isPlaying)
			{
				base.onAddedToStage.Add(OnAddedToStage);
				base.onRemovedFromStage.Add(OnRemoveFromStage);
			}
			SetPlaySettings();
		}

		/// <summary>
		///
		/// </summary>
		public void Rewind()
		{
			_frame = 0;
			_frameElapsed = 0f;
			_reversed = false;
			_repeatedCount = 0;
			DrawFrame();
		}

		/// <summary>
		///
		/// </summary>
		/// <param name="anotherMc"></param>
		public void SyncStatus(MovieClip anotherMc)
		{
			_frame = anotherMc._frame;
			_frameElapsed = anotherMc._frameElapsed;
			_reversed = anotherMc._reversed;
			_repeatedCount = anotherMc._repeatedCount;
			DrawFrame();
		}

		/// <summary>
		///
		/// </summary>
		/// <param name="time"></param>
		public void Advance(float time)
		{
			int num = _frame;
			bool reversed = _reversed;
			float num2 = time;
			while (true)
			{
				float num3 = interval + _frames[_frame].addDelay;
				if (_frame == 0 && _repeatedCount > 0)
				{
					num3 += repeatDelay;
				}
				if (time < num3)
				{
					break;
				}
				time -= num3;
				if (swing)
				{
					if (_reversed)
					{
						_frame--;
						if (_frame <= 0)
						{
							_frame = 0;
							_repeatedCount++;
							_reversed = !_reversed;
						}
					}
					else
					{
						_frame++;
						if (_frame > _frameCount - 1)
						{
							_frame = Mathf.Max(0, _frameCount - 2);
							_repeatedCount++;
							_reversed = !_reversed;
						}
					}
				}
				else
				{
					_frame++;
					if (_frame > _frameCount - 1)
					{
						_frame = 0;
						_repeatedCount++;
					}
				}
				if (_frame == num && _reversed == reversed)
				{
					float num4 = num2 - time;
					time -= (float)Mathf.FloorToInt(time / num4) * num4;
				}
			}
			_frameElapsed = 0f;
			DrawFrame();
		}

		/// <summary>
		///
		/// </summary>
		public void SetPlaySettings()
		{
			SetPlaySettings(0, -1, 0, -1);
		}

		/// <summary>
		/// 从start帧开始，播放到end帧（-1表示结尾），重复times次（0表示无限循环），循环结束后，停止在endAt帧（-1表示参数end）
