		public void Begin()
		{
			began = true;
			clickCancelled = false;
			downX = x;
			downY = y;
			downTime = Time.unscaledTime;
			downFrame = Time.frameCount;
			holdTime = 0f;
			downTargets.Clear();
			if (target != null)
			{
				downTargets.Add(target);
				for (DisplayObject parent = target; parent != null; parent = parent.parent)
				{
					downTargets.Add(parent);
				}
			}
		}

		public void Move()
		{
			if (began)
			{
				holdTime = ((Time.frameCount - downFrame == 1) ? (1f / (float)Application.targetFrameRate) : (Time.unscaledTime - downTime));
			}
			UpdateEvent();
			if (Mathf.Abs(x - downX) > 50f || Mathf.Abs(y - downY) > 50f)
			{
				clickCancelled = true;
			}
			if (touchMonitors.Count > 0)
			{
				int count = touchMonitors.Count;
				for (int i = 0; i < count; i++)
				{
					EventDispatcher eventDispatcher = touchMonitors[i];
					if (eventDispatcher != null && (!(eventDispatcher is DisplayObject) || ((DisplayObject)eventDispatcher).stage != null) && (!(eventDispatcher is GObject) || ((GObject)eventDispatcher).onStage))
					{
						eventDispatcher.GetChainBridges("onTouchMove", sHelperChain, bubble: false);
					}
				}
				Stage.inst.BubbleEvent("onTouchMove", evt, sHelperChain);
				sHelperChain.Clear();
			}
			else
			{
				Stage.inst.DispatchEvent("onTouchMove", evt);
			}
		}

		public void End()
		{
			began = false;
			if (downTargets.Count == 0 || clickCancelled || Mathf.Abs(x - downX) > (float)Stage._clickTestThreshold || Mathf.Abs(y - downY) > (float)Stage._clickTestThreshold)
			{
				clickCancelled = true;
				lastClickTime = 0f;
				clickCount = 1;
			}
			else
			{
				if (Time.unscaledTime - lastClickTime < 0.35f && Mathf.Abs(x - lastClickX) < (float)Stage._clickTestThreshold && Mathf.Abs(y - lastClickY) < (float)Stage._clickTestThreshold && lastClickButton == button)
				{
					if (clickCount == 2)
					{
						clickCount = 1;
					}
					else
					{
						clickCount++;
					}
				}
				else
				{
					clickCount = 1;
				}
				lastClickTime = Time.unscaledTime;
				lastClickX = x;
				lastClickY = y;
				lastClickButton = button;
			}
			holdTime = ((Time.frameCount - downFrame == 1) ? (1f / (float)Application.targetFrameRate) : (Time.unscaledTime - downTime));
			UpdateEvent();
			if (touchMonitors.Count > 0)
			{
				int count = touchMonitors.Count;
				for (int i = 0; i < count; i++)
				{
					touchMonitors[i]?.GetChainBridges("onTouchEnd", sHelperChain, bubble: false);
				}
				target.BubbleEvent("onTouchEnd", evt, sHelperChain);
				touchMonitors.Clear();
				sHelperChain.Clear();
			}
			else
			{
				target.BubbleEvent("onTouchEnd", evt);
			}
		}

		public DisplayObject ClickTest()
		{
			if (clickCancelled)
			{
				downTargets.Clear();
				return null;
			}
			DisplayObject displayObject = downTargets[0];
			if (displayObject.stage != null)
			{
				downTargets.Clear();
				return displayObject;
			}
			displayObject = target;
			while (displayObject != null && (downTargets.IndexOf(displayObject) == -1 || displayObject.stage == null))
			{
				displayObject = displayObject.parent;
			}
			downTargets.Clear();
			return displayObject;
		}
	}
	/// <summary>
	/// Stage Camera is an orthographic camera for UI rendering.
	/// </summary>
	[ExecuteInEditMode]
	[AddComponentMenu("FairyGUI/UI Camera")]
	public class StageCamera : MonoBehaviour
	{
		/// <summary>
		///
		/// </summary>
		public bool constantSize = true;

		/// <summary>
		///
		/// </summary>
		[NonSerialized]
		public float unitsPerPixel = 0.02f;

		[NonSerialized]
		public Transform cachedTransform;

		[NonSerialized]
		public Camera cachedCamera;

		[NonSerialized]
		private int screenWidth;

		[NonSerialized]
		private int screenHeight;

		[NonSerialized]
		private bool isMain;

		[NonSerialized]
		private Display _display;

		/// <summary>
		///
		/// </summary>
		[NonSerialized]
		public static Camera main;

		/// <summary>
		///
		/// </summary>
		[NonSerialized]
		public static int screenSizeVer = 1;

		public const string Name = "Stage Camera";

		public const string LayerName = "UI";

		public static float DefaultCameraSize = 5f;

		public static float DefaultUnitsPerPixel = 0.02f;

		private void OnEnable()
		{
			cachedTransform = ((Component)this).transform;
			cachedCamera = ((Component)this).GetComponent<Camera>();
			if (((Object)((Component)this).gameObject).name == "Stage Camera")
			{
				main = cachedCamera;
				isMain = true;
			}
			if (Display.displays.Length > 1 && cachedCamera.targetDisplay != 0 && cachedCamera.targetDisplay < Display.displays.Length)
			{
				_display = Display.displays[cachedCamera.targetDisplay];
			}
			if (_display == null)
			{
				OnScreenSizeChanged(Screen.width, Screen.height);
			}
			else
			{
				OnScreenSizeChanged(_display.renderingWidth, _display.renderingHeight);
			}
		}

		private void Update()
		{
			if (_display == null)
			{
				if (screenWidth != Screen.width || screenHeight != Screen.height)
				{
					OnScreenSizeChanged(Screen.width, Screen.height);
				}
			}
			else if (screenWidth != _display.renderingWidth || screenHeight != _display.renderingHeight)
			{
				OnScreenSizeChanged(_display.renderingWidth, _display.renderingHeight);
			}
		}

		private void OnScreenSizeChanged(int newWidth, int newHeight)
		{
			//IL_00a1: Unknown result type (might be due to invalid IL or missing references)
			if (newWidth == 0 || newHeight == 0)
			{
				return;
			}
			screenWidth = newWidth;
			screenHeight = newHeight;
			if (constantSize)
			{
				cachedCamera.orthographicSize = DefaultCameraSize;
				unitsPerPixel = cachedCamera.orthographicSize * 2f / (float)screenHeight;
			}
			else
			{
				unitsPerPixel = DefaultUnitsPerPixel;
				cachedCamera.orthographicSize = (float)(screenHeight / 2) * unitsPerPixel;
			}
			cachedTransform.localPosition = new Vector3(cachedCamera.orthographicSize * (float)screenWidth / (float)screenHeight, 0f - cachedCamera.orthographicSize);
			if (!isMain)
			{
				return;
			}
			screenSizeVer++;
			if (Application.isPlaying)
			{
				Stage.inst.HandleScreenSizeChanged(screenWidth, screenHeight, unitsPerPixel);
				return;
			}
			UIContentScaler uIContentScaler = Object.FindObjectOfType<UIContentScaler>();
			if ((Object)(object)uIContentScaler != (Object)null)
			{
				uIContentScaler.ApplyChange();
			}
			else
			{
				UIContentScaler.scaleFactor = 1f;
			}
		}

		private void OnRenderObject()
		{
			if (isMain && !Application.isPlaying)
			{
				EMRenderSupport.Update();
			}
		}

		public void ApplyModifiedProperties()
		{
			screenWidth = 0;
		}

		/// <summary>
		/// Check if there is a stage camera in the scene. If none, create one.
		/// </summary>
		public static void CheckMainCamera()
		{
			if ((Object)(object)GameObject.Find("Stage Camera") == (Object)null)
			{
				int num = LayerMask.NameToLayer("UI");
				CreateCamera("Stage Camera", 1 << num);
			}
			HitTestContext.cachedMainCamera = Camera.main;
		}

		/// <summary>
		///
		/// </summary>
		public static void CheckCaptureCamera()
		{
			if ((Object)(object)GameObject.Find("Stage Camera") == (Object)null)
			{
				int num = LayerMask.NameToLayer("UI");
				CreateCamera("Stage Camera", 1 << num);
			}
		}

		/// <summary>
		///
		/// </summary>
		/// <param name="name"></param>
		/// <param name="cullingMask"></param>
		/// <returns></returns>
		public static Camera CreateCamera(string name, int cullingMask)
		{
			//IL_0001: Unknown result type (might be due to invalid IL or missing references)
			//IL_0007: Expected O, but got Unknown
			GameObject val = new GameObject(name);
			Camera obj = val.AddComponent<Camera>();
			obj.depth = 1f;
			obj.cullingMask = cullingMask;
			obj.clearFlags = (CameraClearFlags)3;
			obj.orthographic = true;
			obj.orthographicSize = DefaultCameraSize;
			obj.nearClipPlane = -30f;
			obj.farClipPlane = 30f;
			obj.stereoTargetEye = (StereoTargetEyeMask)0;
			obj.allowHDR = false;
			obj.allowMSAA = false;
			val.AddComponent<StageCamera>();
			return obj;
		}
	}
