						}
					}
					string text = match.ToString();
					num = match.Index + text.Length;
					stringBuilder.Append(text);
					match = match.NextMatch();
				}
				for (int j = num; j < source.Length; j++)
				{
					if (source[j] == '\n' || source[j] == '\t')
