		public static bool IsArabicLetter(char ch)
		{
			if (ch >= '\u0600' && ch <= 'ۿ')
			{
				if ((ch >= '٠' && ch <= '٭') || (ch >= '۰' && ch <= '۹'))
				{
					return false;
				}
				return true;
			}
			if (ch >= 'ݐ' && ch <= 'ݿ')
			{
				return true;
			}
			if (ch >= 'ﭐ' && ch <= 'ﰿ')
			{
				return true;
			}
			if (ch >= 'ﹰ' && ch <= 'ﻼ')
			{
				return true;
			}
			return false;
		}

		public static string ConvertNumber(string strNumber)
		{
			sbRep.Length = 0;
			foreach (char c in strNumber)
			{
				int num = c;
				if (num != 1644 && c != ',')
				{
					switch (num)
					{
