	public class TouchScreenKeyboard : IKeyboard
	{
		private TouchScreenKeyboard _keyboard;

		public bool done
		{
			get
			{
				if (_keyboard != null && !_keyboard.done)
				{
					return _keyboard.wasCanceled;
				}
				return true;
			}
		}

		public bool supportsCaret => false;

		public string GetInput()
		{
			if (_keyboard != null)
			{
				string text = _keyboard.text;
				if (done)
				{
					_keyboard = null;
				}
				return text;
			}
			return null;
		}

		public void Open(string text, bool autocorrection, bool multiline, bool secure, bool alert, string textPlaceholder, int keyboardType, bool hideInput)
		{
			if (_keyboard == null)
			{
				TouchScreenKeyboard.hideInput = hideInput;
				_keyboard = TouchScreenKeyboard.Open(text, (TouchScreenKeyboardType)keyboardType, autocorrection, multiline, secure, alert, textPlaceholder);
			}
		}

		public void Close()
		{
			if (_keyboard != null)
			{
				_keyboard.active = false;
				_keyboard = null;
			}
		}
	}
	/// <summary>
	/// 文字打字效果。先调用Start，然后Print。
	/// </summary>
	public class TypingEffect
	{
		protected TextField _textField;

		protected Vector3[] _backupVerts;

		protected Vector3[] _vertices;

		protected bool _stroke;

		protected bool _shadow;

		protected int _printIndex;

		protected int _mainLayerStart;

		protected int _strokeLayerStart;

		protected int _strokeDrawDirs;

		protected int _vertIndex;

		protected int _mainLayerVertCount;

