		/// </summary>
		/// <param name="strType"></param>
		public void RemoveEventListeners(string strType)
		{
			if (_dic == null)
			{
				return;
			}
			if (strType != null)
			{
				if (_dic.TryGetValue(strType, out var value))
				{
					value.Clear();
				}
				return;
			}
			foreach (KeyValuePair<string, EventBridge> item in _dic)
			{
				item.Value.Clear();
			}
		}

		/// <summary>
		///
		/// </summary>
		/// <param name="strType"></param>
