	public class ChangePageAction : ControllerAction
	{
		public string objectId;

		public string controllerName;

		public string targetPage;

		protected override void Enter(Controller controller)
		{
			if (string.IsNullOrEmpty(controllerName))
			{
				return;
			}
			GComponent gComponent = (string.IsNullOrEmpty(objectId) ? controller.parent : (controller.parent.GetChildById(objectId) as GComponent));
			if (gComponent == null)
			{
				return;
			}
			Controller controller2 = gComponent.GetController(controllerName);
			if (controller2 == null || controller2 == controller || controller2.changing)
			{
				return;
			}
			if (targetPage == "~1")
			{
				if (controller.selectedIndex < controller2.pageCount)
				{
					controller2.selectedIndex = controller.selectedIndex;
				}
			}
			else if (targetPage == "~2")
			{
				controller2.selectedPage = controller.selectedPage;
			}
			else
			{
				controller2.selectedPageId = targetPage;
			}
		}

		public override void Setup(ByteBuffer buffer)
		{
			base.Setup(buffer);
			objectId = buffer.ReadS();
			controllerName = buffer.ReadS();
			targetPage = buffer.ReadS();
		}
	}
	public class ControllerAction
	{
		public enum ActionType
		{
			PlayTransition,
			ChangePage
		}

		public string[] fromPage;

		public string[] toPage;

		public static ControllerAction CreateAction(ActionType type)
		{
			return type switch
			{
				ActionType.PlayTransition => new PlayTransitionAction(), 
				ActionType.ChangePage => new ChangePageAction(), 
				_ => null, 
			};
		}

		public void Run(Controller controller, string prevPage, string curPage)
		{
			if ((fromPage == null || fromPage.Length == 0 || Array.IndexOf(fromPage, prevPage) != -1) && (toPage == null || toPage.Length == 0 || Array.IndexOf(toPage, curPage) != -1))
			{
				Enter(controller);
			}
			else
			{
				Leave(controller);
			}
		}

		protected virtual void Enter(Controller controller)
		{
		}

		protected virtual void Leave(Controller controller)
		{
		}

		public virtual void Setup(ByteBuffer buffer)
		{
			int num = buffer.ReadShort();
			fromPage = new string[num];
			for (int i = 0; i < num; i++)
			{
				fromPage[i] = buffer.ReadS();
			}
			num = buffer.ReadShort();
			toPage = new string[num];
			for (int j = 0; j < num; j++)
			{
				toPage[j] = buffer.ReadS();
			}
		}
	}
	public class PlayTransitionAction : ControllerAction
	{
		public string transitionName;

		public int playTimes;

		public float delay;

		public bool stopOnExit;

		private Transition _currentTransition;

		public PlayTransitionAction()
		{
			playTimes = 1;
			delay = 0f;
		}

		protected override void Enter(Controller controller)
		{
			Transition transition = controller.parent.GetTransition(transitionName);
			if (transition != null)
			{
				if (_currentTransition != null && _currentTransition.playing)
				{
					transition.ChangePlayTimes(playTimes);
				}
				else
				{
					transition.Play(playTimes, delay, null);
				}
				_currentTransition = transition;
			}
		}

		protected override void Leave(Controller controller)
		{
			if (stopOnExit && _currentTransition != null)
			{
				_currentTransition.Stop();
				_currentTransition = null;
			}
		}

		public override void Setup(ByteBuffer buffer)
		{
			base.Setup(buffer);
			transitionName = buffer.ReadS();
			playTimes = buffer.ReadInt();
			delay = buffer.ReadFloat();
			stopOnExit = buffer.ReadBool();
		}
	}
	public class AsyncCreationHelper
	{
		/// <summary>
		///
		/// </summary>
		private class DisplayListItem
		{
			public PackageItem packageItem;

			public ObjectType type;

			public int childCount;

			public int listItemCount;

			public DisplayListItem(PackageItem pi, ObjectType type)
			{
				packageItem = pi;
				this.type = type;
			}
		}

		public static void CreateObject(PackageItem item, UIPackage.CreateObjectCallback callback)
		{
			Timers.inst.StartCoroutine(_CreateObject(item, callback));
		}

		private static IEnumerator _CreateObject(PackageItem item, UIPackage.CreateObjectCallback callback)
		{
			Stats.LatestObjectCreation = 0;
			Stats.LatestGraphicsCreation = 0;
			float frameTime = UIConfig.frameTimeForAsyncUIConstruction;
			List<DisplayListItem> itemList = new List<DisplayListItem>();
			DisplayListItem displayListItem = new DisplayListItem(item, ObjectType.Component);
			displayListItem.childCount = CollectComponentChildren(item, itemList);
			itemList.Add(displayListItem);
			int cnt = itemList.Count;
			List<GObject> objectPool = new List<GObject>(cnt);
			float realtimeSinceStartup = Time.realtimeSinceStartup;
			bool flag = false;
			for (int i = 0; i < cnt; i++)
			{
				displayListItem = itemList[i];
				if (displayListItem.packageItem != null)
				{
					GObject gObject = UIObjectFactory.NewObject(displayListItem.packageItem);
					objectPool.Add(gObject);
					UIPackage._constructing++;
					if (displayListItem.packageItem.type == PackageItemType.Component)
					{
						int num = objectPool.Count - displayListItem.childCount - 1;
						((GComponent)gObject).ConstructFromResource(objectPool, num);
						objectPool.RemoveRange(num, displayListItem.childCount);
					}
					else
					{
						gObject.ConstructFromResource();
					}
					UIPackage._constructing--;
				}
				else
				{
					GObject gObject = UIObjectFactory.NewObject(displayListItem.type);
					objectPool.Add(gObject);
					if (displayListItem.type == ObjectType.List && displayListItem.listItemCount > 0)
					{
						int num2 = objectPool.Count - displayListItem.listItemCount - 1;
						for (int j = 0; j < displayListItem.listItemCount; j++)
						{
							((GList)gObject).itemPool.ReturnObject(objectPool[j + num2]);
						}
						objectPool.RemoveRange(num2, displayListItem.listItemCount);
					}
				}
				if (i % 5 == 0 && Time.realtimeSinceStartup - realtimeSinceStartup >= frameTime)
				{
					yield return null;
					realtimeSinceStartup = Time.realtimeSinceStartup;
					flag = true;
				}
			}
			if (!flag)
			{
				yield return null;
			}
			callback(objectPool[0]);
		}

		/// <summary>
		/// 收集创建目标对象所需的所有类型信息
		/// </summary>
		/// <param name="item"></param>
		/// <param name="list"></param>
		private static int CollectComponentChildren(PackageItem item, List<DisplayListItem> list)
		{
			ByteBuffer rawData = item.rawData;
			rawData.Seek(0, 2);
			int num = rawData.ReadShort();
			for (int i = 0; i < num; i++)
			{
				int num2 = rawData.ReadShort();
				int position = rawData.position;
				rawData.Seek(position, 0);
				ObjectType objectType = (ObjectType)rawData.ReadByte();
				string text = rawData.ReadS();
				string text2 = rawData.ReadS();
				rawData.position = position;
				DisplayListItem displayListItem;
				if (text != null)
				{
					PackageItem packageItem = ((text2 == null) ? item.owner : UIPackage.GetById(text2))?.GetItem(text);
					displayListItem = new DisplayListItem(packageItem, objectType);
					if (packageItem != null && packageItem.type == PackageItemType.Component)
					{
						displayListItem.childCount = CollectComponentChildren(packageItem, list);
					}
				}
				else
				{
					displayListItem = new DisplayListItem(null, objectType);
					if (objectType == ObjectType.List)
					{
						displayListItem.listItemCount = CollectListChildren(rawData, list);
					}
				}
				list.Add(displayListItem);
				rawData.position = position + num2;
			}
			return num;
		}

		private static int CollectListChildren(ByteBuffer buffer, List<DisplayListItem> list)
		{
			buffer.Seek(buffer.position, 8);
			string text = buffer.ReadS();
			int num = 0;
			int num2 = buffer.ReadShort();
			for (int i = 0; i < num2; i++)
			{
				int num3 = buffer.ReadShort();
				num3 += buffer.position;
				string text2 = buffer.ReadS();
				if (text2 == null)
				{
					text2 = text;
				}
				if (!string.IsNullOrEmpty(text2))
				{
					PackageItem itemByURL = UIPackage.GetItemByURL(text2);
					if (itemByURL != null)
					{
						DisplayListItem displayListItem = new DisplayListItem(itemByURL, itemByURL.objectType);
						if (itemByURL.type == PackageItemType.Component)
						{
							displayListItem.childCount = CollectComponentChildren(itemByURL, list);
						}
						list.Add(displayListItem);
						num++;
					}
				}
				buffer.position = num3;
			}
			return num;
		}
	}
	/// <summary>
	/// Controller class.
	/// 控制器类。控制器的创建和设计需通过编辑器完成，不建议使用代码创建。
	/// 最常用的方法是通过selectedIndex获得或改变控制器的活动页面。如果要获得控制器页面改变的通知，使用onChanged事件。
	/// </summary>
	public class Controller : EventDispatcher
	{
		/// <summary>
		/// Name of the controller
		/// 控制器名称。
		/// </summary>
		public string name;

		internal GComponent parent;

		internal bool autoRadioGroupDepth;

		internal bool changing;

		private int _selectedIndex;

		private int _previousIndex;

		private List<string> _pageIds;

		private List<string> _pageNames;

		private List<ControllerAction> _actions;

		private EventListener _onChanged;

		private static uint _nextPageId;

		/// <summary>
		/// When controller page changed.
		/// 当控制器活动页面改变时，此事件被触发。
		/// </summary>
		public EventListener onChanged => _onChanged ?? (_onChanged = new EventListener(this, "onChanged"));

		/// <summary>
		/// Current page index.
		/// 获得或设置当前活动页面索引。
		/// </summary>
		public int selectedIndex
		{
			get
			{
				return _selectedIndex;
			}
			set
			{
				if (_selectedIndex != value)
				{
					if (value > _pageIds.Count - 1)
					{
						throw new IndexOutOfRangeException(value.ToString() ?? "");
					}
					changing = true;
					_previousIndex = _selectedIndex;
					_selectedIndex = value;
					parent.ApplyController(this);
					DispatchEvent("onChanged", null);
					changing = false;
				}
			}
		}

		/// <summary>
		/// Current page name.
		/// 获得当前活动页面名称
		/// </summary>
		public string selectedPage
		{
			get
			{
				if (_selectedIndex == -1)
				{
					return null;
				}
				return _pageNames[_selectedIndex];
			}
			set
			{
				int num = _pageNames.IndexOf(value);
				if (num == -1)
				{
					num = 0;
				}
				selectedIndex = num;
			}
		}

		/// <summary>
		/// Previouse page index.
		/// 获得上次活动页面索引
		/// </summary>
		public int previsousIndex => _previousIndex;

		/// <summary>
		/// Previous page name.
		/// 获得上次活动页面名称。
		/// </summary>
		public string previousPage
		{
			get
			{
				if (_previousIndex == -1)
				{
					return null;
				}
				return _pageNames[_previousIndex];
			}
		}

		/// <summary>
		/// Page count of this controller.
		/// 获得页面数量。
		/// </summary>
		public int pageCount => _pageIds.Count;

		internal string selectedPageId
		{
			get
			{
				if (_selectedIndex == -1)
				{
					return string.Empty;
				}
				return _pageIds[_selectedIndex];
			}
			set
			{
				int num = _pageIds.IndexOf(value);
				if (num != -1)
				{
					selectedIndex = num;
				}
			}
		}

		internal string oppositePageId
		{
			set
			{
				if (_pageIds.IndexOf(value) > 0)
				{
					selectedIndex = 0;
				}
				else if (_pageIds.Count > 1)
				{
					selectedIndex = 1;
				}
			}
		}

		internal string previousPageId
		{
			get
			{
				if (_previousIndex == -1)
				{
					return null;
				}
				return _pageIds[_previousIndex];
			}
		}

		public Controller()
		{
			_pageIds = new List<string>();
			_pageNames = new List<string>();
			_selectedIndex = -1;
			_previousIndex = -1;
		}

		public void Dispose()
		{
			RemoveEventListeners();
		}

		/// <summary>
		/// Set current page index, no onChanged event.
		/// 通过索引设置当前活动页面，和selectedIndex的区别在于，这个方法不会触发onChanged事件。
		/// </summary>
		/// <param name="value">Page index</param>
		public void SetSelectedIndex(int value)
		{
			if (_selectedIndex != value)
			{
				if (value > _pageIds.Count - 1)
				{
					throw new IndexOutOfRangeException(value.ToString() ?? "");
				}
				changing = true;
				_previousIndex = _selectedIndex;
				_selectedIndex = value;
				parent.ApplyController(this);
				changing = false;
			}
		}

		/// <summary>
		/// Set current page by name, no onChanged event.
		/// 通过页面名称设置当前活动页面，和selectedPage的区别在于，这个方法不会触发onChanged事件。
		/// </summary>
		/// <param name="value">Page name</param>
		public void SetSelectedPage(string value)
		{
			int num = _pageNames.IndexOf(value);
			if (num == -1)
			{
				num = 0;
			}
			SetSelectedIndex(num);
		}

		/// <summary>
		/// Get page name by an index.
		/// 通过页面索引获得页面名称。
		/// </summary>
		/// <param name="index">Page index</param>
		/// <returns>Page Name</returns>
		public string GetPageName(int index)
		{
			return _pageNames[index];
		}

		/// <summary>
		/// Get page id by an index.
		/// 通过页面索引获得页面id。
		/// </summary>
		/// <param name="index">Page index</param>
		/// <returns>Page Id</returns>
		public string GetPageId(int index)
		{
			return _pageIds[index];
		}

		/// <summary>
		/// Get page id by name
		/// </summary>
		/// <param name="aName"></param>
		/// <returns></returns>
		public string GetPageIdByName(string aName)
		{
			int num = _pageNames.IndexOf(aName);
			if (num != -1)
			{
				return _pageIds[num];
			}
			return null;
		}

		/// <summary>
		/// Add a new page to this controller.
		/// </summary>
		/// <param name="name">Page name</param>
		public void AddPage(string name)
		{
			if (name == null)
			{
				name = string.Empty;
			}
			AddPageAt(name, _pageIds.Count);
		}

		/// <summary>
		/// Add a new page to this controller at a certain index.
		/// </summary>
		/// <param name="name">Page name</param>
		/// <param name="index">Insert position</param>
		public void AddPageAt(string name, int index)
		{
			string item = "_" + _nextPageId++;
			if (index == _pageIds.Count)
			{
				_pageIds.Add(item);
				_pageNames.Add(name);
			}
			else
			{
				_pageIds.Insert(index, item);
				_pageNames.Insert(index, name);
			}
		}

		/// <summary>
		/// Remove a page.
		/// </summary>
		/// <param name="name">Page name</param>
		public void RemovePage(string name)
		{
			int num = _pageNames.IndexOf(name);
			if (num != -1)
			{
				_pageIds.RemoveAt(num);
				_pageNames.RemoveAt(num);
				if (_selectedIndex >= _pageIds.Count)
				{
					selectedIndex = _selectedIndex - 1;
				}
				else
				{
					parent.ApplyController(this);
				}
			}
		}

		/// <summary>
		/// Removes a page at a certain index.
		/// </summary>
		/// <param name="index"></param>
		public void RemovePageAt(int index)
		{
			_pageIds.RemoveAt(index);
			_pageNames.RemoveAt(index);
			if (_selectedIndex >= _pageIds.Count)
			{
				selectedIndex = _selectedIndex - 1;
			}
			else
			{
				parent.ApplyController(this);
			}
		}

		/// <summary>
		/// Remove all pages.
		/// </summary>
		public void ClearPages()
		{
			_pageIds.Clear();
			_pageNames.Clear();
			if (_selectedIndex != -1)
			{
				selectedIndex = -1;
			}
			else
			{
				parent.ApplyController(this);
			}
		}

		/// <summary>
		/// Check if the controller has a page.
		/// </summary>
		/// <param name="aName">Page name.</param>
		/// <returns></returns>
		public bool HasPage(string aName)
		{
			return _pageNames.IndexOf(aName) != -1;
		}

		internal int GetPageIndexById(string aId)
		{
			return _pageIds.IndexOf(aId);
		}

		internal string GetPageNameById(string aId)
		{
			int num = _pageIds.IndexOf(aId);
			if (num != -1)
			{
				return _pageNames[num];
			}
			return null;
		}

		public void RunActions()
		{
			if (_actions != null)
			{
				int count = _actions.Count;
				for (int i = 0; i < count; i++)
				{
					_actions[i].Run(this, previousPageId, selectedPageId);
				}
			}
		}

		public void Setup(ByteBuffer buffer)
		{
			int position = buffer.position;
			buffer.Seek(position, 0);
			name = buffer.ReadS();
			autoRadioGroupDepth = buffer.ReadBool();
			buffer.Seek(position, 1);
			int num = buffer.ReadShort();
			_pageIds.Capacity = num;
			_pageNames.Capacity = num;
			for (int i = 0; i < num; i++)
			{
				_pageIds.Add(buffer.ReadS());
				_pageNames.Add(buffer.ReadS());
			}
			int num2 = 0;
			if (buffer.version >= 2)
			{
				switch (buffer.ReadByte())
				{
				case 1:
					num2 = buffer.ReadShort();
					break;
				case 2:
					num2 = _pageNames.IndexOf(UIPackage.branch);
					if (num2 == -1)
					{
						num2 = 0;
					}
					break;
				case 3:
					num2 = _pageNames.IndexOf(UIPackage.GetVar(buffer.ReadS()));
					if (num2 == -1)
					{
						num2 = 0;
					}
					break;
				}
			}
			buffer.Seek(position, 2);
			num = buffer.ReadShort();
			if (num > 0)
			{
				if (_actions == null)
				{
					_actions = new List<ControllerAction>(num);
				}
				for (int j = 0; j < num; j++)
				{
					int num3 = buffer.ReadUshort();
					num3 += buffer.position;
					ControllerAction controllerAction = ControllerAction.CreateAction((ControllerAction.ActionType)buffer.ReadByte());
					controllerAction.Setup(buffer);
					_actions.Add(controllerAction);
					buffer.position = num3;
				}
			}
			if (parent != null && _pageIds.Count > 0)
			{
				_selectedIndex = num2;
			}
			else
			{
				_selectedIndex = -1;
			}
		}
	}
	/// <summary>
	/// Helper for drag and drop.
	/// 这是一个提供特殊拖放功能的功能类。与GObject.draggable不同，拖动开始后，他使用一个替代的图标作为拖动对象。
	/// 当玩家释放鼠标/手指，目标组件会发出一个onDrop事件。
	/// </summary>
	public class DragDropManager
	{
		private GLoader _agent;

		private object _sourceData;

		private GObject _source;

		private static DragDropManager _inst;

		public static DragDropManager inst
		{
			get
			{
				if (_inst == null)
				{
					_inst = new DragDropManager();
				}
				return _inst;
			}
		}

		/// <summary>
		/// Loader object for real dragging.
		/// 用于实际拖动的Loader对象。你可以根据实际情况设置loader的大小，对齐等。
		/// </summary>
		public GLoader dragAgent => _agent;

		/// <summary>
		/// Is dragging?
		/// 返回当前是否正在拖动。
		/// </summary>
		public bool dragging => _agent.parent != null;

		public DragDropManager()
		{
			_agent = (GLoader)UIObjectFactory.NewObject(ObjectType.Loader);
			_agent.gameObjectName = "DragDropAgent";
			_agent.SetHome(GRoot.inst);
			_agent.touchable = false;
			_agent.draggable = true;
			_agent.SetSize(100f, 100f);
			_agent.SetPivot(0.5f, 0.5f, asAnchor: true);
			_agent.align = AlignType.Center;
			_agent.verticalAlign = VertAlignType.Middle;
			_agent.sortingOrder = int.MaxValue;
			_agent.onDragEnd.Add(__dragEnd);
		}

		/// <summary>
		/// Start dragging.
		/// 开始拖动。
		/// </summary>
		/// <param name="source">Source object. This is the object which initiated the dragging.</param>
		/// <param name="icon">Icon to be used as the dragging sign.</param>
		/// <param name="sourceData">Custom data. You can get it in the onDrop event data.</param>
		/// <param name="touchPointID">Copy the touchId from InputEvent to here, if has one.</param>
		public void StartDrag(GObject source, string icon, object sourceData, int touchPointID = -1)
		{
			//IL_004b: Unknown result type (might be due to invalid IL or missing references)
			//IL_0050: Unknown result type (might be due to invalid IL or missing references)
			if (_agent.parent == null)
			{
				_sourceData = sourceData;
				_source = source;
				_agent.url = icon;
				GRoot.inst.AddChild(_agent);
				_agent.xy = GRoot.inst.GlobalToLocal(Stage.inst.GetTouchPosition(touchPointID));
				_agent.StartDrag(touchPointID);
			}
		}

		/// <summary>
		/// Cancel dragging.
		/// 取消拖动。
		/// </summary>
		public void Cancel()
		{
			if (_agent.parent != null)
			{
				_agent.StopDrag();
				GRoot.inst.RemoveChild(_agent);
				_sourceData = null;
			}
		}

		private void __dragEnd(EventContext evt)
		{
			if (_agent.parent == null)
			{
				return;
			}
			GRoot.inst.RemoveChild(_agent);
			object sourceData = _sourceData;
			GObject source = _source;
			_sourceData = null;
			_source = null;
			for (GObject gObject = GRoot.inst.touchTarget; gObject != null; gObject = gObject.parent)
			{
				if (gObject.hasEventListeners("onDrop"))
				{
					gObject.RequestFocus();
					gObject.DispatchEvent("onDrop", sourceData, source);
					break;
				}
			}
		}
	}
	/// <summary>
	///
	/// </summary>
	public interface EMRenderTarget
	{
		int EM_sortingOrder { get; }

		void EM_BeforeUpdate();

		void EM_Update(UpdateContext context);

		void EM_Reload();
	}
	/// <summary>
	/// 这是一个在编辑状态下渲染UI的功能类。EM=Edit Mode
	/// </summary>
	public class EMRenderSupport
	{
		/// <summary>
		///
		/// </summary>
		public static bool orderChanged;

		private static UpdateContext _updateContext;

		private static List<EMRenderTarget> _targets = new List<EMRenderTarget>();

		/// <summary>
		///
		/// </summary>
		public static bool packageListReady { get; private set; }

		/// <summary>
		///
		/// </summary>
		public static bool hasTarget => _targets.Count > 0;

		/// <summary>
		///
		/// </summary>
		/// <param name="value"></param>
		public static void Add(EMRenderTarget value)
		{
			if (!_targets.Contains(value))
			{
				_targets.Add(value);
			}
			orderChanged = true;
		}

		/// <summary>
		///
		/// </summary>
		/// <param name="value"></param>
		public static void Remove(EMRenderTarget value)
		{
			_targets.Remove(value);
		}

		/// <summary>
		/// 由StageCamera调用
		/// </summary>
		public static void Update()
		{
			if (Application.isPlaying)
			{
				return;
			}
			if (_updateContext == null)
			{
				_updateContext = new UpdateContext();
			}
			if (orderChanged)
			{
				_targets.Sort(CompareDepth);
				orderChanged = false;
			}
			int count = _targets.Count;
			for (int i = 0; i < count; i++)
			{
				_targets[i].EM_BeforeUpdate();
			}
			if (packageListReady)
			{
				_updateContext.Begin();
				for (int j = 0; j < count; j++)
				{
					_targets[j].EM_Update(_updateContext);
				}
				_updateContext.End();
			}
		}

		/// <summary>
		/// 当发生二进制重载时，或用户点击刷新菜单
		/// </summary>
		public static void Reload()
		{
			if (!Application.isPlaying)
			{
				UIConfig.ClearResourceRefs();
				UIConfig[] array = Object.FindObjectsOfType<UIConfig>();
				for (int i = 0; i < array.Length; i++)
				{
					array[i].Load();
				}
				packageListReady = true;
				int count = _targets.Count;
				for (int j = 0; j < count; j++)
				{
					_targets[j].EM_Reload();
				}
			}
		}

		private static int CompareDepth(EMRenderTarget c1, EMRenderTarget c2)
		{
			return c1.EM_sortingOrder - c2.EM_sortingOrder;
		}
	}
