		public GComboBox()
		{
			visibleItemCount = UIConfig.defaultComboBoxVisibleItemCount;
			_itemsUpdated = true;
			_selectedIndex = -1;
			_items = new List<string>();
			_values = new List<string>();
			_popupDirection = PopupDirection.Auto;
			soundVolumeScale = 1f;
		}

		/// <summary>
		/// Call this method after you made changes on itemList or iconList
		/// </summary>
		public void ApplyListChange()
		{
			if (_items.Count > 0)
			{
				if (_selectedIndex >= _items.Count)
				{
					_selectedIndex = _items.Count - 1;
				}
				else if (_selectedIndex == -1)
				{
					_selectedIndex = 0;
				}
				text = _items[_selectedIndex];
				if (_icons != null && _selectedIndex < _icons.Count)
				{
					icon = _icons[_selectedIndex];
				}
			}
			else
			{
				text = string.Empty;
				if (_icons != null)
				{
					icon = null;
				}
				_selectedIndex = -1;
			}
			_itemsUpdated = true;
		}

