		}

		internal void AdjustRadioGroupDepth(GObject obj, Controller c)
		{
			int count = _children.Count;
			int num = -1;
			int num2 = -1;
			for (int i = 0; i < count; i++)
			{
				GObject gObject = _children[i];
				if (gObject == obj)
				{
