		public void GetSnappingPosition(ref float xValue, ref float yValue)
		{
			GetSnappingPositionWithDir(ref xValue, ref yValue, 0f, 0f);
		}

		protected bool ShouldSnapToNext(float dir, float delta, float size)
		{
			if ((!(dir < 0f) || !(delta > UIConfig.defaultScrollSnappingThreshold * size)) && (!(dir > 0f) || !(delta > (1f - UIConfig.defaultScrollSnappingThreshold) * size)))
			{
				if (dir == 0f)
				{
					return delta > size / 2f;
				}
				return false;
			}
			return true;
		}

		/// dir正数表示右移或者下移，负数表示左移或者上移
		public virtual void GetSnappingPositionWithDir(ref float xValue, ref float yValue, float xDir, float yDir)
		{
			int count = _children.Count;
			if (count == 0)
			{
				return;
			}
			EnsureBoundsCorrect();
			GObject gObject = null;
			int i = 0;
			if (yValue != 0f)
			{
				for (; i < count; i++)
				{
					gObject = _children[i];
					if (!(yValue < gObject.y))
					{
						continue;
					}
					if (i == 0)
					{
						yValue = 0f;
						break;
					}
					GObject gObject2 = _children[i - 1];
					if (ShouldSnapToNext(yDir, yValue - gObject2.y, gObject2.height))
					{
						yValue = gObject.y;
					}
					else
					{
						yValue = gObject2.y;
					}
					break;
				}
				if (i == count)
				{
					yValue = gObject.y;
				}
			}
			if (xValue == 0f)
			{
				return;
			}
			if (i > 0)
			{
				i--;
			}
			for (; i < count; i++)
			{
				gObject = _children[i];
				if (!(xValue < gObject.x))
				{
					continue;
				}
				if (i == 0)
				{
					xValue = 0f;
					break;
				}
				GObject gObject3 = _children[i - 1];
				if (ShouldSnapToNext(xDir, xValue - gObject3.x, gObject3.width))
				{
					xValue = gObject.x;
				}
				else
				{
					xValue = gObject3.x;
				}
				break;
			}
			if (i == count)
			{
				xValue = gObject.x;
			}
		}

		internal void ChildSortingOrderChanged(GObject child, int oldValue, int newValue)
		{
			if (newValue == 0)
			{
				_sortingChildCount--;
				SetChildIndex(child, _children.Count);
				return;
			}
			if (oldValue == 0)
			{
				_sortingChildCount++;
			}
			int num = _children.IndexOf(child);
			int insertPosForSortingChild = GetInsertPosForSortingChild(child);
			if (num < insertPosForSortingChild)
			{
				_SetChildIndex(child, num, insertPosForSortingChild - 1);
			}
			else
			{
				_SetChildIndex(child, num, insertPosForSortingChild);
			}
		}

