			}
			int num3 = itemCount - 1;
			GObject gObject = null;
			while (num3 >= 0)
			{
				gObject = GetChildAt(num3);
				if (!foldInvisibleItems || gObject.visible)
				{
					break;
				}
				num3--;
			}
			if (num3 < 0)
			{
