	/// <summary>
	/// GObjectPool is use for GObject pooling.
	/// </summary>
	public class GObjectPool
	{
		/// <summary>
		/// Callback function when a new object is creating.
		/// </summary>
		/// <param name="obj"></param>
		public delegate void InitCallbackDelegate(GObject obj);

		/// <summary>
		/// Callback function when a new object is creating.
		/// </summary>
		public InitCallbackDelegate initCallback;

		private Dictionary<string, Queue<GObject>> _pool;

		private Transform _manager;

		/// <summary>
		///
		/// </summary>
		public int count => _pool.Count;

		/// <summary>
		/// 需要设置一个manager，加入池里的对象都成为这个manager的孩子
		/// </summary>
		/// <param name="manager"></param>
		public GObjectPool(Transform manager)
		{
			_manager = manager;
			_pool = new Dictionary<string, Queue<GObject>>();
		}

		/// <summary>
		/// Dispose all objects in the pool.
		/// </summary>
		public void Clear()
		{
			foreach (KeyValuePair<string, Queue<GObject>> item in _pool)
			{
				foreach (GObject item2 in item.Value)
				{
					item2.Dispose();
				}
			}
			_pool.Clear();
		}

		/// <summary>
		///
		/// </summary>
		/// <param name="url"></param>
		/// <returns></returns>
		public GObject GetObject(string url)
		{
			url = UIPackage.NormalizeURL(url);
			if (url == null)
			{
				return null;
			}
			if (_pool.TryGetValue(url, out var value) && value.Count > 0)
			{
				return value.Dequeue();
			}
			GObject gObject = UIPackage.CreateObjectFromURL(url);
			if (gObject != null && initCallback != null)
			{
				initCallback(gObject);
			}
			return gObject;
		}

		/// <summary>
		///
		/// </summary>
		/// <param name="obj"></param>
		public void ReturnObject(GObject obj)
		{
			if (!obj.displayObject.isDisposed)
			{
				string resourceURL = obj.resourceURL;
				if (!_pool.TryGetValue(resourceURL, out var value))
				{
					value = new Queue<GObject>();
					_pool.Add(resourceURL, value);
				}
				if ((Object)(object)_manager != (Object)null)
				{
					obj.displayObject.cachedTransform.SetParent(_manager, false);
				}
				value.Enqueue(obj);
			}
		}
	}
	/// <summary>
	/// GProgressBar class.
	/// </summary>
	public class GProgressBar : GComponent
	{
		private double _min;

		private double _max;

		private double _value;

		private ProgressTitleType _titleType;

		private bool _reverse;

		private GObject _titleObject;

		private GMovieClip _aniObject;

		private GObject _barObjectH;

		private GObject _barObjectV;

		private float _barMaxWidth;

		private float _barMaxHeight;

		private float _barMaxWidthDelta;

		private float _barMaxHeightDelta;

		private float _barStartX;

		private float _barStartY;

		/// <summary>
		///
		/// </summary>
		public ProgressTitleType titleType
		{
			get
			{
				return _titleType;
			}
			set
			{
				if (_titleType != value)
				{
					_titleType = value;
					Update(_value);
				}
			}
		}

		/// <summary>
		///
		/// </summary>
		public double min
		{
			get
			{
				return _min;
			}
			set
			{
				if (_min != value)
				{
					_min = value;
					Update(_value);
				}
			}
		}

		/// <summary>
		///
		/// </summary>
		public double max
		{
			get
			{
				return _max;
			}
			set
			{
				if (_max != value)
				{
					_max = value;
					Update(_value);
				}
			}
		}

		/// <summary>
		///
		/// </summary>
		public double value
		{
			get
			{
				return _value;
			}
			set
			{
				if (_value != value)
				{
					GTween.Kill(this, TweenPropType.Progress, complete: false);
					_value = value;
					Update(_value);
				}
			}
		}

		public bool reverse
		{
			get
			{
				return _reverse;
			}
			set
			{
				_reverse = value;
			}
		}

		public GProgressBar()
		{
			_value = 50.0;
			_max = 100.0;
		}

		/// <summary>
		/// 动态改变进度值。
		/// </summary>
		/// <param name="value"></param>
		/// <param name="duration"></param>
		public GTweener TweenValue(double value, float duration)
		{
			GTweener tween = GTween.GetTween(this, TweenPropType.Progress);
			double d;
			if (tween != null)
			{
				d = tween.value.d;
				tween.Kill();
			}
			else
			{
				d = _value;
			}
			_value = value;
			return GTween.ToDouble(d, _value, duration).SetEase(EaseType.Linear).SetTarget(this, TweenPropType.Progress);
		}

		/// <summary>
		///
		/// </summary>
		/// <param name="newValue"></param>
		public void Update(double newValue)
		{
			float num = Mathf.Clamp01((float)((newValue - _min) / (_max - _min)));
			if (_titleObject != null)
			{
				switch (_titleType)
				{
				case ProgressTitleType.Percent:
					if (RTLSupport.BaseDirection == RTLSupport.DirectionType.RTL)
					{
						_titleObject.text = "%" + Mathf.FloorToInt(num * 100f);
					}
					else
					{
						_titleObject.text = Mathf.FloorToInt(num * 100f) + "%";
					}
					break;
				case ProgressTitleType.ValueAndMax:
					if (RTLSupport.BaseDirection == RTLSupport.DirectionType.RTL)
					{
						_titleObject.text = Math.Round(max) + "/" + Math.Round(newValue);
					}
					else
					{
						_titleObject.text = Math.Round(newValue) + "/" + Math.Round(max);
					}
					break;
				case ProgressTitleType.Value:
					_titleObject.text = Math.Round(newValue).ToString() ?? "";
					break;
				case ProgressTitleType.Max:
					_titleObject.text = Math.Round(_max).ToString() ?? "";
					break;
				}
			}
			float num2 = base.width - _barMaxWidthDelta;
			float num3 = base.height - _barMaxHeightDelta;
			if (!_reverse)
			{
				if (_barObjectH != null && !SetFillAmount(_barObjectH, num))
				{
					_barObjectH.width = Mathf.RoundToInt(num2 * num);
				}
				if (_barObjectV != null && !SetFillAmount(_barObjectV, num))
				{
					_barObjectV.height = Mathf.RoundToInt(num3 * num);
				}
			}
			else
			{
				if (_barObjectH != null && !SetFillAmount(_barObjectH, 1f - num))
				{
					_barObjectH.width = Mathf.RoundToInt(num2 * num);
					_barObjectH.x = _barStartX + (num2 - _barObjectH.width);
				}
				if (_barObjectV != null && !SetFillAmount(_barObjectV, 1f - num))
				{
					_barObjectV.height = Mathf.RoundToInt(num3 * num);
					_barObjectV.y = _barStartY + (num3 - _barObjectV.height);
				}
			}
			if (_aniObject != null)
			{
				_aniObject.frame = Mathf.RoundToInt(num * 100f);
			}
			InvalidateBatchingState(childChanged: true);
		}

		private bool SetFillAmount(GObject bar, float amount)
		{
			if (bar is GImage && ((GImage)bar).fillMethod != 0)
			{
				((GImage)bar).fillAmount = amount;
			}
			else
			{
				if (!(bar is GLoader) || ((GLoader)bar).fillMethod == FillMethod.None)
				{
					return false;
				}
				((GLoader)bar).fillAmount = amount;
			}
			return true;
		}

		protected override void ConstructExtension(ByteBuffer buffer)
		{
			buffer.Seek(0, 6);
			_titleType = (ProgressTitleType)buffer.ReadByte();
			_reverse = buffer.ReadBool();
			_titleObject = GetChild("title");
			_barObjectH = GetChild("bar");
			_barObjectV = GetChild("bar_v");
			_aniObject = GetChild("ani") as GMovieClip;
			if (_barObjectH != null)
			{
				_barMaxWidth = _barObjectH.width;
				_barMaxWidthDelta = base.width - _barMaxWidth;
				_barStartX = _barObjectH.x;
			}
			if (_barObjectV != null)
			{
				_barMaxHeight = _barObjectV.height;
				_barMaxHeightDelta = base.height - _barMaxHeight;
				_barStartY = _barObjectV.y;
			}
		}

		public override void Setup_AfterAdd(ByteBuffer buffer, int beginPos)
		{
			base.Setup_AfterAdd(buffer, beginPos);
			if (!buffer.Seek(beginPos, 6))
			{
				Update(_value);
				return;
			}
			if ((ObjectType)buffer.ReadByte() != packageItem.objectType)
			{
				Update(_value);
				return;
			}
			_value = buffer.ReadInt();
			_max = buffer.ReadInt();
			if (buffer.version >= 2)
			{
				_min = buffer.ReadInt();
			}
			if (buffer.version >= 5)
			{
				string sound = buffer.ReadS();
				if (!string.IsNullOrEmpty(sound))
				{
					float volumeScale = buffer.ReadFloat();
					base.displayObject.onClick.Add((EventCallback0)delegate
					{
						if (UIPackage.GetItemAssetByURL(sound) is NAudioClip nAudioClip && (Object)(object)nAudioClip.nativeClip != (Object)null)
						{
							Stage.inst.PlayOneShotSound(nAudioClip.nativeClip, volumeScale);
						}
					});
				}
				else
				{
					buffer.Skip(4);
				}
			}
			Update(_value);
		}

		protected override void HandleSizeChanged()
		{
			base.HandleSizeChanged();
			if (_barObjectH != null)
			{
				_barMaxWidth = base.width - _barMaxWidthDelta;
			}
			if (_barObjectV != null)
			{
				_barMaxHeight = base.height - _barMaxHeightDelta;
			}
			if (!underConstruct)
			{
				Update(_value);
			}
		}
	}
