									rawData.Skip(2);
								}
							}
						}
						rawData.position = num10;
					}
					break;
				}
				case ObjectType.Label:
					if (rawData.Seek(position, 6) && (ObjectType)rawData.ReadByte() == objectType2)
					{
						if (value.TryGetValue(text, out value2))
						{
							rawData.WriteS(value2);
						}
						else
						{
							rawData.Skip(2);
						}
						rawData.Skip(2);
						if (rawData.ReadBool())
						{
							rawData.Skip(4);
						}
						rawData.Skip(4);
						if (rawData.ReadBool() && value.TryGetValue(text + "-prompt", out value2))
						{
							rawData.WriteS(value2);
						}
					}
					break;
				case ObjectType.Button:
					if (rawData.Seek(position, 6) && (ObjectType)rawData.ReadByte() == objectType2)
					{
						if (value.TryGetValue(text, out value2))
						{
							rawData.WriteS(value2);
						}
						else
						{
							rawData.Skip(2);
						}
						if (value.TryGetValue(text + "-0", out value2))
						{
							rawData.WriteS(value2);
						}
					}
					break;
				case ObjectType.ComboBox:
				{
					if (!rawData.Seek(position, 6) || (ObjectType)rawData.ReadByte() != objectType2)
					{
						break;
					}
					int num7 = rawData.ReadShort();
					for (int m = 0; m < num7; m++)
					{
						int num8 = rawData.ReadUshort();
						num8 += rawData.position;
						if (value.TryGetValue(text + "-" + m, out value2))
						{
							rawData.WriteS(value2);
						}
						rawData.position = num8;
					}
					if (value.TryGetValue(text, out value2))
					{
						rawData.WriteS(value2);
					}
					break;
				}
				}
				rawData.position = position + num2;
			}
		}
	}
	/// <summary>
	///
	/// </summary>
	[Obsolete("Use GTree and GTreeNode instead")]
	public class TreeNode
	{
		/// <summary>
		///
		/// </summary>
		public object data;

		private List<TreeNode> _children;

		private bool _expanded;

		/// <summary>
		///
		/// </summary>
		public TreeNode parent { get; private set; }

		/// <summary>
		///
		/// </summary>
		public TreeView tree { get; private set; }

		/// <summary>
		///
		/// </summary>
		public GComponent cell { get; internal set; }

		/// <summary>
		///
		/// </summary>
		public int level { get; private set; }

		/// <summary>
		///
		/// </summary>
		public bool expanded
		{
			get
			{
				return _expanded;
			}
			set
			{
				if (_children == null || _expanded == value)
				{
					return;
				}
				_expanded = value;
				if (tree != null)
				{
					if (_expanded)
					{
						tree.AfterExpanded(this);
					}
					else
					{
						tree.AfterCollapsed(this);
					}
				}
			}
		}

		/// <summary>
		///
		/// </summary>
		public bool isFolder => _children != null;

		/// <summary>
		///
		/// </summary>
		public string text
		{
			get
			{
				if (cell != null)
				{
					return cell.text;
				}
				return null;
			}
		}

		/// <summary>
		///
		/// </summary>
		public int numChildren
		{
			get
			{
				if (_children != null)
				{
					return _children.Count;
				}
				return 0;
			}
		}

		/// <summary>
		///
		/// </summary>
		/// <param name="hasChild"></param>
		public TreeNode(bool hasChild)
		{
			if (hasChild)
			{
				_children = new List<TreeNode>();
			}
		}

		/// <summary>
		///
		/// </summary>
		/// <param name="child"></param>
		/// <returns></returns>
		public TreeNode AddChild(TreeNode child)
		{
			AddChildAt(child, _children.Count);
			return child;
		}

		/// <summary>
		///
		/// </summary>
		/// <param name="child"></param>
		/// <param name="index"></param>
		/// <returns></returns>
		public TreeNode AddChildAt(TreeNode child, int index)
		{
			if (child == null)
			{
				throw new Exception("child is null");
			}
			int count = _children.Count;
			if (index >= 0 && index <= count)
			{
				if (child.parent == this)
				{
					SetChildIndex(child, index);
				}
				else
				{
					if (child.parent != null)
					{
						child.parent.RemoveChild(child);
					}
					int count2 = _children.Count;
					if (index == count2)
					{
						_children.Add(child);
					}
					else
					{
						_children.Insert(index, child);
					}
					child.parent = this;
					child.level = level + 1;
					child.SetTree(tree);
					if (cell != null && cell.parent != null && _expanded)
					{
						tree.AfterInserted(child);
					}
				}
				return child;
			}
			throw new Exception("Invalid child index");
		}

		/// <summary>
		///
		/// </summary>
		/// <param name="child"></param>
		/// <returns></returns>
		public TreeNode RemoveChild(TreeNode child)
		{
			int num = _children.IndexOf(child);
			if (num != -1)
			{
				RemoveChildAt(num);
			}
			return child;
		}

		/// <summary>
		///
		/// </summary>
		/// <param name="index"></param>
		/// <returns></returns>
		public TreeNode RemoveChildAt(int index)
		{
			if (index >= 0 && index < numChildren)
			{
				TreeNode treeNode = _children[index];
				_children.RemoveAt(index);
				treeNode.parent = null;
				if (tree != null)
				{
					treeNode.SetTree(null);
					tree.AfterRemoved(treeNode);
				}
				return treeNode;
			}
			throw new Exception("Invalid child index");
		}

		/// <summary>
		///
		/// </summary>
		/// <param name="beginIndex"></param>
		/// <param name="endIndex"></param>
		public void RemoveChildren(int beginIndex = 0, int endIndex = -1)
		{
			if (endIndex < 0 || endIndex >= numChildren)
			{
				endIndex = numChildren - 1;
			}
			for (int i = beginIndex; i <= endIndex; i++)
			{
				RemoveChildAt(beginIndex);
			}
		}

		/// <summary>
		///
		/// </summary>
		/// <param name="index"></param>
		/// <returns></returns>
		public TreeNode GetChildAt(int index)
		{
			if (index >= 0 && index < numChildren)
			{
				return _children[index];
			}
			throw new Exception("Invalid child index");
		}

		/// <summary>
		///
		/// </summary>
		/// <param name="child"></param>
		/// <returns></returns>
		public int GetChildIndex(TreeNode child)
		{
			return _children.IndexOf(child);
		}

		/// <summary>
		///
		/// </summary>
		/// <returns></returns>
		public TreeNode GetPrevSibling()
		{
			if (parent == null)
			{
				return null;
			}
			int num = parent._children.IndexOf(this);
			if (num <= 0)
			{
				return null;
			}
			return parent._children[num - 1];
		}

		/// <summary>
		///
		/// </summary>
		/// <returns></returns>
		public TreeNode GetNextSibling()
		{
			if (parent == null)
			{
				return null;
			}
			int num = parent._children.IndexOf(this);
			if (num < 0 || num >= parent._children.Count - 1)
			{
				return null;
			}
			return parent._children[num + 1];
		}

		/// <summary>
		///
		/// </summary>
		/// <param name="child"></param>
		/// <param name="index"></param>
		public void SetChildIndex(TreeNode child, int index)
		{
			int num = _children.IndexOf(child);
			if (num == -1)
			{
				throw new Exception("Not a child of this container");
			}
			int count = _children.Count;
			if (index < 0)
			{
				index = 0;
			}
			else if (index > count)
			{
				index = count;
			}
			if (num != index)
			{
				_children.RemoveAt(num);
				_children.Insert(index, child);
				if (cell != null && cell.parent != null && _expanded)
				{
					tree.AfterMoved(child);
				}
			}
		}

		/// <summary>
		///
		/// </summary>
		/// <param name="child1"></param>
		/// <param name="child2"></param>
		public void SwapChildren(TreeNode child1, TreeNode child2)
		{
			int num = _children.IndexOf(child1);
			int num2 = _children.IndexOf(child2);
			if (num == -1 || num2 == -1)
			{
				throw new Exception("Not a child of this container");
			}
			SwapChildrenAt(num, num2);
		}

		/// <summary>
		///
		/// </summary>
		/// <param name="index1"></param>
		/// <param name="index2"></param>
		public void SwapChildrenAt(int index1, int index2)
		{
			TreeNode child = _children[index1];
			TreeNode child2 = _children[index2];
			SetChildIndex(child, index2);
			SetChildIndex(child2, index1);
		}

		internal void SetTree(TreeView value)
		{
			tree = value;
			if (tree != null && tree.treeNodeWillExpand != null && _expanded)
			{
				tree.treeNodeWillExpand(this, expand: true);
			}
			if (_children != null)
			{
				int count = _children.Count;
				for (int i = 0; i < count; i++)
				{
					TreeNode treeNode = _children[i];
					treeNode.level = level + 1;
					treeNode.SetTree(value);
				}
			}
		}
	}
	/// <summary>
	///
	/// </summary>
	[Obsolete("Use GTree and GTreeNode instead")]
	public class TreeView : EventDispatcher
	{
		public delegate GComponent TreeNodeCreateCellDelegate(TreeNode node);

		public delegate void TreeNodeRenderDelegate(TreeNode node);

		public delegate void TreeNodeWillExpandDelegate(TreeNode node, bool expand);

		/// <summary>
		/// TreeView每级的缩进，单位像素。
		/// </summary>
		public int indent;

		/// <summary>
		/// 当TreeNode需要创建对象的显示对象时回调
		/// </summary>
		public TreeNodeCreateCellDelegate treeNodeCreateCell;

		/// <summary>
		/// 当TreeNode需要更新时回调
		/// </summary>
		public TreeNodeRenderDelegate treeNodeRender;

		/// <summary>
		/// 当TreeNode即将展开或者收缩时回调。可以在回调中动态增加子节点。
		/// </summary>
		public TreeNodeWillExpandDelegate treeNodeWillExpand;

		/// <summary>
		/// TreeView使用的List对象
		/// </summary>
		public GList list { get; private set; }

		/// <summary>
		/// TreeView的顶层节点，这是个虚拟节点，也就是他不会显示出来。
		/// </summary>
		public TreeNode root { get; private set; }

		/// <summary>
		/// 点击任意TreeNode时触发
		/// </summary>
		public EventListener onClickNode { get; private set; }

		/// <summary>
		/// 右键点击任意TreeNode时触发
		/// </summary>
		public EventListener onRightClickNode { get; private set; }

		/// <summary>
		///
		/// </summary>
		/// <param name="list"></param>
		public TreeView(GList list)
		{
			this.list = list;
			list.onClickItem.Add(__clickItem);
			list.onRightClickItem.Add(__clickItem);
			list.RemoveChildrenToPool();
			root = new TreeNode(hasChild: true);
			root.SetTree(this);
			root.cell = list;
			root.expanded = true;
			indent = 30;
			onClickNode = new EventListener(this, "onClickNode");
			onRightClickNode = new EventListener(this, "onRightClickNode");
		}

		/// <summary>
		///
		/// </summary>
		/// <returns></returns>
		public TreeNode GetSelectedNode()
		{
			if (list.selectedIndex != -1)
			{
				return (TreeNode)list.GetChildAt(list.selectedIndex).data;
			}
			return null;
		}

		/// <summary>
		///
		/// </summary>
		/// <returns></returns>
		public List<TreeNode> GetSelection()
		{
			List<int> selection = this.list.GetSelection();
			int count = selection.Count;
			List<TreeNode> list = new List<TreeNode>();
			for (int i = 0; i < count; i++)
			{
				TreeNode item = (TreeNode)this.list.GetChildAt(selection[i]).data;
				list.Add(item);
			}
			return list;
		}

		/// <summary>
		///
		/// </summary>
		/// <param name="node"></param>
		/// <param name="scrollItToView"></param>
		public void AddSelection(TreeNode node, bool scrollItToView = false)
		{
			TreeNode parent = node.parent;
			while (parent != null && parent != root)
			{
				parent.expanded = true;
				parent = parent.parent;
			}
			list.AddSelection(list.GetChildIndex(node.cell), scrollItToView);
		}

		/// <summary>
		///
		/// </summary>
		/// <param name="node"></param>
		public void RemoveSelection(TreeNode node)
		{
			list.RemoveSelection(list.GetChildIndex(node.cell));
		}

		/// <summary>
		///
		/// </summary>
		public void ClearSelection()
		{
			list.ClearSelection();
		}

		/// <summary>
		///
		/// </summary>
		/// <param name="node"></param>
		/// <returns></returns>
		public int GetNodeIndex(TreeNode node)
		{
			return list.GetChildIndex(node.cell);
		}

		/// <summary>
		///
		/// </summary>
		/// <param name="node"></param>
		public void UpdateNode(TreeNode node)
		{
			if (node.cell != null && treeNodeRender != null)
			{
				treeNodeRender(node);
			}
		}

		/// <summary>
		///
		/// </summary>
		/// <param name="nodes"></param>
		public void UpdateNodes(List<TreeNode> nodes)
		{
			int count = nodes.Count;
			for (int i = 0; i < count; i++)
			{
				TreeNode treeNode = nodes[i];
				if (treeNode.cell == null)
				{
					break;
				}
				if (treeNodeRender != null)
				{
					treeNodeRender(treeNode);
				}
			}
		}

		/// <summary>
		///
		/// </summary>
		/// <param name="folderNode"></param>
		public void ExpandAll(TreeNode folderNode)
		{
			folderNode.expanded = true;
			int numChildren = folderNode.numChildren;
			for (int i = 0; i < numChildren; i++)
			{
				TreeNode childAt = folderNode.GetChildAt(i);
				if (childAt.isFolder)
				{
					ExpandAll(childAt);
				}
			}
		}

		/// <summary>
		///
		/// </summary>
		/// <param name="folderNode"></param>
		public void CollapseAll(TreeNode folderNode)
		{
			if (folderNode != root)
			{
				folderNode.expanded = false;
			}
			int numChildren = folderNode.numChildren;
			for (int i = 0; i < numChildren; i++)
			{
				TreeNode childAt = folderNode.GetChildAt(i);
				if (childAt.isFolder)
				{
					CollapseAll(childAt);
				}
			}
		}

		/// <summary>
		///
		/// </summary>
		/// <param name="node"></param>
		private void CreateCell(TreeNode node)
		{
			if (treeNodeCreateCell != null)
			{
				node.cell = treeNodeCreateCell(node);
			}
			else
			{
				node.cell = list.itemPool.GetObject(list.defaultItem) as GComponent;
			}
			if (node.cell == null)
			{
				throw new Exception("Unable to create tree cell");
			}
			node.cell.data = node;
			GObject child = node.cell.GetChild("indent");
			if (child != null)
			{
				child.width = (node.level - 1) * indent;
			}
			GButton gButton = (GButton)node.cell.GetChild("expandButton");
			if (gButton != null)
			{
				if (node.isFolder)
				{
					gButton.visible = true;
					gButton.onClick.Add(__clickExpandButton);
					gButton.data = node;
					gButton.selected = node.expanded;
				}
				else
				{
					gButton.visible = false;
				}
			}
			if (treeNodeRender != null)
			{
				treeNodeRender(node);
			}
		}

		/// <summary>
		///
		/// </summary>
		/// <param name="node"></param>
		internal void AfterInserted(TreeNode node)
		{
			CreateCell(node);
			int insertIndexForNode = GetInsertIndexForNode(node);
			list.AddChildAt(node.cell, insertIndexForNode);
			if (treeNodeRender != null)
			{
				treeNodeRender(node);
			}
			if (node.isFolder && node.expanded)
			{
				CheckChildren(node, insertIndexForNode);
			}
		}

		/// <summary>
		///
		/// </summary>
		/// <param name="node"></param>
		/// <returns></returns>
		private int GetInsertIndexForNode(TreeNode node)
		{
			TreeNode treeNode = node.GetPrevSibling();
			if (treeNode == null)
			{
				treeNode = node.parent;
			}
			int num = list.GetChildIndex(treeNode.cell) + 1;
			int level = node.level;
			int numChildren = list.numChildren;
			for (int i = num; i < numChildren && ((TreeNode)list.GetChildAt(i).data).level > level; i++)
			{
				num++;
			}
			return num;
		}

		/// <summary>
		///
		/// </summary>
		/// <param name="node"></param>
		internal void AfterRemoved(TreeNode node)
		{
			RemoveNode(node);
		}

		/// <summary>
		///
		/// </summary>
		/// <param name="node"></param>
		internal void AfterExpanded(TreeNode node)
		{
			if (node != root && treeNodeWillExpand != null)
			{
				treeNodeWillExpand(node, expand: true);
			}
			if (node.cell == null)
			{
				return;
			}
			if (node != root)
			{
				if (treeNodeRender != null)
				{
					treeNodeRender(node);
				}
				GButton gButton = (GButton)node.cell.GetChild("expandButton");
				if (gButton != null)
				{
					gButton.selected = true;
				}
			}
			if (node.cell.parent != null)
			{
				CheckChildren(node, list.GetChildIndex(node.cell));
			}
		}

		/// <summary>
		///
		/// </summary>
		/// <param name="node"></param>
		internal void AfterCollapsed(TreeNode node)
		{
			if (node != root && treeNodeWillExpand != null)
			{
				treeNodeWillExpand(node, expand: false);
			}
			if (node.cell == null)
			{
				return;
			}
			if (node != root)
			{
				if (treeNodeRender != null)
				{
					treeNodeRender(node);
				}
				GButton gButton = (GButton)node.cell.GetChild("expandButton");
				if (gButton != null)
				{
					gButton.selected = false;
				}
			}
			if (node.cell.parent != null)
			{
				HideFolderNode(node);
			}
		}

		/// <summary>
		///
		/// </summary>
		/// <param name="node"></param>
		internal void AfterMoved(TreeNode node)
		{
			if (!node.isFolder)
			{
				list.RemoveChild(node.cell);
			}
			else
			{
				HideFolderNode(node);
			}
			int insertIndexForNode = GetInsertIndexForNode(node);
			list.AddChildAt(node.cell, insertIndexForNode);
			if (node.isFolder && node.expanded)
			{
				CheckChildren(node, insertIndexForNode);
			}
		}

		/// <summary>
		///
		/// </summary>
		/// <param name="folderNode"></param>
		/// <param name="index"></param>
		/// <returns></returns>
		private int CheckChildren(TreeNode folderNode, int index)
		{
			int numChildren = folderNode.numChildren;
			for (int i = 0; i < numChildren; i++)
			{
				index++;
				TreeNode childAt = folderNode.GetChildAt(i);
				if (childAt.cell == null)
				{
					CreateCell(childAt);
				}
				if (childAt.cell.parent == null)
				{
					list.AddChildAt(childAt.cell, index);
				}
				if (childAt.isFolder && childAt.expanded)
				{
					index = CheckChildren(childAt, index);
				}
			}
			return index;
		}

		/// <summary>
		///
		/// </summary>
		/// <param name="folderNode"></param>
		private void HideFolderNode(TreeNode folderNode)
		{
			int numChildren = folderNode.numChildren;
			for (int i = 0; i < numChildren; i++)
			{
				TreeNode childAt = folderNode.GetChildAt(i);
				if (childAt.cell != null)
				{
					if (childAt.cell.parent != null)
					{
						list.RemoveChild(childAt.cell);
					}
					list.itemPool.ReturnObject(childAt.cell);
					childAt.cell.data = null;
					childAt.cell = null;
				}
				if (childAt.isFolder && childAt.expanded)
				{
					HideFolderNode(childAt);
				}
			}
		}

		/// <summary>
		///
		/// </summary>
		/// <param name="node"></param>
		private void RemoveNode(TreeNode node)
		{
			if (node.cell != null)
			{
				if (node.cell.parent != null)
				{
					list.RemoveChild(node.cell);
				}
				list.itemPool.ReturnObject(node.cell);
				node.cell.data = null;
				node.cell = null;
			}
			if (node.isFolder)
			{
				int numChildren = node.numChildren;
				for (int i = 0; i < numChildren; i++)
				{
					TreeNode childAt = node.GetChildAt(i);
					RemoveNode(childAt);
				}
			}
		}

		private void __clickExpandButton(EventContext context)
		{
			context.StopPropagation();
			GButton gButton = (GButton)context.sender;
			TreeNode treeNode = (TreeNode)gButton.parent.data;
			if (list.scrollPane != null)
			{
				float posY = list.scrollPane.posY;
				if (gButton.selected)
				{
					treeNode.expanded = true;
				}
				else
				{
					treeNode.expanded = false;
				}
				list.scrollPane.posY = posY;
				list.scrollPane.ScrollToView(treeNode.cell);
			}
			else if (gButton.selected)
			{
				treeNode.expanded = true;
			}
			else
			{
				treeNode.expanded = false;
			}
		}

		private void __clickItem(EventContext context)
		{
			float posY = 0f;
			if (list.scrollPane != null)
			{
				posY = list.scrollPane.posY;
			}
			TreeNode treeNode = (TreeNode)((GObject)context.data).data;
			if (context.type == list.onRightClickItem.type)
			{
				onRightClickNode.Call(treeNode);
			}
			else
			{
				onClickNode.Call(treeNode);
			}
			if (list.scrollPane != null)
			{
				list.scrollPane.posY = posY;
				list.scrollPane.ScrollToView(treeNode.cell);
			}
		}
	}
