	/// <summary>
	///
	/// </summary>
	[ExecuteInEditMode]
	[AddComponentMenu("FairyGUI/UI Content Scaler")]
	public class UIContentScaler : MonoBehaviour
	{
		/// <summary>
		///
		/// </summary>
		public enum ScaleMode
		{
			ConstantPixelSize,
			ScaleWithScreenSize,
			ConstantPhysicalSize
		}

		/// <summary>
		///
		/// </summary>
		public enum ScreenMatchMode
		{
			MatchWidthOrHeight,
			MatchWidth,
			MatchHeight
		}

		/// <summary>
		///
		/// </summary>
		public ScaleMode scaleMode;

		/// <summary>
		///
		/// </summary>
		public ScreenMatchMode screenMatchMode;

		/// <summary>
		///
		/// </summary>
		public int designResolutionX;

		/// <summary>
		///
		/// </summary>
		public int designResolutionY;

		/// <summary>
		///
		/// </summary>
		public int fallbackScreenDPI = 96;

		/// <summary>
		///
		/// </summary>
		public int defaultSpriteDPI = 96;

		/// <summary>
		///
		/// </summary>
		public float constantScaleFactor = 1f;

		/// <summary>
		/// 当false时，计算比例时会考虑designResolutionX/Y的设置是针对横屏还是竖屏。否则不考虑。
		/// </summary>
		public bool ignoreOrientation;

		[NonSerialized]
		public static float scaleFactor = 1f;

		[NonSerialized]
		public static int scaleLevel = 0;

		[NonSerialized]
		private bool _changed;

		private void OnEnable()
		{
			if (Application.isPlaying)
			{
				UIContentScaler component = Stage.inst.gameObject.GetComponent<UIContentScaler>();
				if ((Object)(object)component != (Object)(object)this)
				{
					component.scaleMode = scaleMode;
					if (scaleMode == ScaleMode.ScaleWithScreenSize)
					{
						component.designResolutionX = designResolutionX;
						component.designResolutionY = designResolutionY;
						component.screenMatchMode = screenMatchMode;
						component.ignoreOrientation = ignoreOrientation;
					}
					else if (scaleMode == ScaleMode.ConstantPhysicalSize)
					{
						component.fallbackScreenDPI = fallbackScreenDPI;
						component.defaultSpriteDPI = defaultSpriteDPI;
					}
					else
					{
						component.constantScaleFactor = constantScaleFactor;
					}
					component.ApplyChange();
					GRoot.inst.ApplyContentScaleFactor();
				}
			}
			else
			{
				_changed = true;
			}
		}

		private void Update()
		{
			if (_changed)
			{
				_changed = false;
				ApplyChange();
			}
		}

		private void OnDestroy()
		{
			if (!Application.isPlaying)
			{
				scaleFactor = 1f;
				scaleLevel = 0;
			}
		}

		/// <summary>
		///
		/// </summary>
		public void ApplyModifiedProperties()
		{
			_changed = true;
		}

		/// <summary>
		///
		/// </summary>
		public void ApplyChange()
		{
			float num;
			float num2;
			if (Application.isPlaying)
			{
				num = Stage.inst.width;
				num2 = Stage.inst.height;
			}
			else
			{
				num = Screen.width;
				num2 = Screen.height;
			}
			if (scaleMode == ScaleMode.ScaleWithScreenSize)
			{
				if (designResolutionX == 0 || designResolutionY == 0)
				{
					return;
				}
				int num3 = designResolutionX;
				int num4 = designResolutionY;
				if (!ignoreOrientation && ((num > num2 && num3 < num4) || (num < num2 && num3 > num4)))
				{
					int num5 = num3;
					num3 = num4;
					num4 = num5;
				}
				if (screenMatchMode == ScreenMatchMode.MatchWidthOrHeight)
				{
					float num6 = num / (float)num3;
					float num7 = num2 / (float)num4;
					scaleFactor = Mathf.Min(num6, num7);
				}
				else if (screenMatchMode == ScreenMatchMode.MatchWidth)
				{
					scaleFactor = num / (float)num3;
				}
				else
				{
					scaleFactor = num2 / (float)num4;
				}
			}
			else if (scaleMode == ScaleMode.ConstantPhysicalSize)
			{
				float num8 = Screen.dpi;
				if (num8 == 0f)
				{
					num8 = fallbackScreenDPI;
				}
				if (num8 == 0f)
				{
					num8 = 96f;
				}
				scaleFactor = num8 / (float)((defaultSpriteDPI == 0) ? 96 : defaultSpriteDPI);
			}
			else
			{
				scaleFactor = constantScaleFactor;
			}
			if (scaleFactor > 10f)
			{
				scaleFactor = 10f;
			}
			UpdateScaleLevel();
			StageCamera.screenSizeVer++;
		}

		private void UpdateScaleLevel()
		{
			if (scaleFactor > 3f)
			{
				scaleLevel = 3;
			}
			else if (scaleFactor > 2f)
			{
				scaleLevel = 2;
			}
			else if (scaleFactor > 1f)
			{
				scaleLevel = 1;
			}
			else
			{
				scaleLevel = 0;
			}
		}
	}
	/// <summary>
	///
	/// </summary>
	public class UIObjectFactory
	{
		public delegate GComponent GComponentCreator();

		public delegate GLoader GLoaderCreator();

		private static Dictionary<string, GComponentCreator> packageItemExtensions = new Dictionary<string, GComponentCreator>();

		private static GLoaderCreator loaderCreator;

		/// <summary>
		///
		/// </summary>
		/// <param name="url"></param>
		/// <param name="type"></param>
		public static void SetPackageItemExtension(string url, Type type)
		{
			SetPackageItemExtension(url, () => (GComponent)Activator.CreateInstance(type));
		}

		/// <summary>
		///
		/// </summary>
		/// <param name="url"></param>
		/// <param name="creator"></param>
		public static void SetPackageItemExtension(string url, GComponentCreator creator)
		{
			if (url == null)
			{
				throw new Exception("Invaild url: " + url);
			}
			PackageItem itemByURL = UIPackage.GetItemByURL(url);
			if (itemByURL != null)
			{
				itemByURL.extensionCreator = creator;
			}
			packageItemExtensions[url] = creator;
		}

		/// <summary>
		///
		/// </summary>
		/// <param name="type"></param>
		public static void SetLoaderExtension(Type type)
		{
			loaderCreator = () => (GLoader)Activator.CreateInstance(type);
		}

		/// <summary>
		///
		/// </summary>
		/// <param name="creator"></param>
		public static void SetLoaderExtension(GLoaderCreator creator)
		{
			loaderCreator = creator;
		}

		internal static void ResolvePackageItemExtension(PackageItem pi)
		{
			if (!packageItemExtensions.TryGetValue("ui://" + pi.owner.id + pi.id, out pi.extensionCreator) && !packageItemExtensions.TryGetValue("ui://" + pi.owner.name + "/" + pi.name, out pi.extensionCreator))
			{
				pi.extensionCreator = null;
			}
		}

		public static void Clear()
		{
			packageItemExtensions.Clear();
			loaderCreator = null;
		}

		/// <summary>
		///
		/// </summary>
		/// <param name="pi"></param>
		/// <param name="userClass"></param>
		/// <returns></returns>
		public static GObject NewObject(PackageItem pi, Type userClass = null)
		{
			GObject gObject;
			if (pi.type == PackageItemType.Component)
			{
				if (userClass != null)
				{
					Stats.LatestObjectCreation++;
					gObject = (GComponent)Activator.CreateInstance(userClass);
				}
				else if (pi.extensionCreator != null)
				{
					Stats.LatestObjectCreation++;
					gObject = pi.extensionCreator();
				}
				else
				{
					gObject = NewObject(pi.objectType);
				}
			}
			else
			{
				gObject = NewObject(pi.objectType);
			}
			if (gObject != null)
			{
				gObject.packageItem = pi;
			}
			return gObject;
		}

		/// <summary>
		///
		/// </summary>
		/// <param name="type"></param>
		/// <returns></returns>
		public static GObject NewObject(ObjectType type)
		{
			Stats.LatestObjectCreation++;
			switch (type)
			{
			case ObjectType.Image:
				return new GImage();
			case ObjectType.MovieClip:
				return new GMovieClip();
			case ObjectType.Component:
				return new GComponent();
			case ObjectType.Text:
				return new GTextField();
			case ObjectType.RichText:
				return new GRichTextField();
			case ObjectType.InputText:
				return new GTextInput();
			case ObjectType.Group:
				return new GGroup();
			case ObjectType.List:
				return new GList();
			case ObjectType.Graph:
				return new GGraph();
			case ObjectType.Loader:
				if (loaderCreator != null)
				{
					return loaderCreator();
				}
				return new GLoader();
			case ObjectType.Button:
				return new GButton();
			case ObjectType.Label:
				return new GLabel();
			case ObjectType.ProgressBar:
				return new GProgressBar();
			case ObjectType.Slider:
				return new GSlider();
			case ObjectType.ScrollBar:
				return new GScrollBar();
			case ObjectType.ComboBox:
				return new GComboBox();
			case ObjectType.Tree:
				return new GTree();
			case ObjectType.Loader3D:
				return new GLoader3D();
			default:
				return null;
			}
		}
	}
	/// <summary>
	/// A UI Package contains a description file and some texture, sound assets.
	/// </summary>
	public class UIPackage
	{
		/// <summary>
		/// Use this callback to provide resources to the package.
		/// </summary>
		/// <param name="name">Resource name without extension.</param>
		/// <param name="extension">Resource extension. e.g. '.png' '.wav'</param>
		/// <param name="type">Resource type. e.g. 'Texture' 'AudioClip'</param>
		/// <param name="destroyMethod">How to destroy this resource.</param>
		/// <returns></returns>
		public delegate object LoadResource(string name, string extension, Type type, out DestroyMethod destroyMethod);

		/// <summary>
		/// A async load resource callback. After loaded, you should call item.owner.SetItemAsset.
		/// </summary>
		/// <param name="name">Resource name without extension.</param>
		/// <param name="extension">Resource extension. e.g. '.png' '.wav'</param>
		/// <param name="type">Resource type. e.g. 'Texture' 'AudioClip'</param>
		/// <param name="item">Resource item object.</param>
		/// <returns></returns>
		public delegate void LoadResourceAsync(string name, string extension, Type type, PackageItem item);

		/// <summary>
		///
		/// </summary>
		/// <param name="result"></param>
		public delegate void CreateObjectCallback(GObject result);

		private class AtlasSprite
		{
			public PackageItem atlas;

			public Rect rect;

			public Vector2 offset;

			public Vector2 originalSize;

			public bool rotated;
		}

		/// <summary>
		/// Unload UIAssetBundle by FairyGUI system.
		/// if use AssetBundlesManager set value to false
		/// then unload UIAssetBundle by AssetBundlesManager
		/// </summary>
		public static bool unloadBundleByFGUI = true;

