		/// Switch show and hide status.
		/// </summary>
		public void ToggleStatus()
		{
			if (isTop)
			{
				Hide();
			}
			else
			{
				Show();
			}
		}

		/// <summary>
		///
		/// </summary>
		public void BringToFront()
		{
			base.root.BringToFront(this);
		}

		/// <summary>
		///
		/// </summary>
		public void ShowModalWait()
		{
			ShowModalWait(0);
		}

		/// <summary>
		/// Display a modal waiting sign in the front.
		/// 显示一个等待标志在最前面。等待标志的资源可以通过UIConfig.windowModalWaiting。等待标志组件会设置为屏幕大小，请内部做好关联。
		/// 还可以设定一个requestingCmd作为等待的命令字，在CloseModalWait里传入相同的命令字ModalWait将结束，否则CloseModalWait无效。
		/// </summary>
		/// <param name="requestingCmd"></param>
		public void ShowModalWait(int requestingCmd)
		{
			if (requestingCmd != 0)
			{
				_requestingCmd = requestingCmd;
			}
			if (UIConfig.windowModalWaiting != null)
			{
				if (_modalWaitPane == null)
				{
					_modalWaitPane = UIPackage.CreateObjectFromURL(UIConfig.windowModalWaiting);
					_modalWaitPane.SetHome(this);
				}
				LayoutModalWaitPane();
				AddChild(_modalWaitPane);
			}
		}

		protected virtual void LayoutModalWaitPane()
		{
			//IL_000e: Unknown result type (might be due to invalid IL or missing references)
			//IL_0013: Unknown result type (might be due to invalid IL or missing references)
			//IL_0018: Unknown result type (might be due to invalid IL or missing references)
			//IL_001a: Unknown result type (might be due to invalid IL or missing references)
			//IL_001b: Unknown result type (might be due to invalid IL or missing references)
			//IL_0020: Unknown result type (might be due to invalid IL or missing references)
			//IL_0027: Unknown result type (might be due to invalid IL or missing references)
			//IL_003b: Unknown result type (might be due to invalid IL or missing references)
			if (_contentArea != null)
			{
				Vector2 pt = _frame.LocalToGlobal(Vector2.zero);
				pt = GlobalToLocal(pt);
				_modalWaitPane.SetXY((float)(int)pt.x + _contentArea.x, (float)(int)pt.y + _contentArea.y);
				_modalWaitPane.SetSize(_contentArea.width, _contentArea.height);
			}
			else
			{
				_modalWaitPane.SetSize(base.width, base.height);
			}
		}

		/// <summary>
		///
		/// </summary>
		/// <returns></returns>
		public bool CloseModalWait()
		{
			return CloseModalWait(0);
		}

		/// <summary>
		/// Close modal waiting. If rquestingCmd is equal to the value you transfer in ShowModalWait, mowal wait will be closed.
		/// Otherwise, this function has no effect.
		/// 关闭模式等待。如果requestingCmd和ShowModalWait传入的不相同，则这个函数没有任何动作，立即返回。
		/// </summary>
		/// <param name="requestingCmd"></param>
		/// <returns></returns>
		public bool CloseModalWait(int requestingCmd)
		{
			if (requestingCmd != 0 && _requestingCmd != requestingCmd)
			{
				return false;
			}
			_requestingCmd = 0;
			if (_modalWaitPane != null && _modalWaitPane.parent != null)
			{
				RemoveChild(_modalWaitPane);
			}
			return true;
		}

		/// <summary>
		///
		/// </summary>
		public void Init()
		{
			if (_inited || _loading)
			{
				return;
			}
			if (_uiSources.Count > 0)
			{
				_loading = false;
				int count = _uiSources.Count;
				for (int i = 0; i < count; i++)
				{
					IUISource iUISource = _uiSources[i];
					if (!iUISource.loaded)
					{
						iUISource.Load(__uiLoadComplete);
						_loading = true;
					}
				}
				if (!_loading)
				{
					_init();
				}
			}
			else
			{
				_init();
			}
		}

		/// <summary>
		///
		/// </summary>
		protected virtual void OnInit()
		{
		}

		/// <summary>
		///
		/// </summary>
		protected virtual void OnShown()
		{
		}

		/// <summary>
		///
		/// </summary>
		protected virtual void OnHide()
		{
		}

		/// <summary>
		///
		/// </summary>
		protected virtual void DoShowAnimation()
		{
			OnShown();
		}

		/// <summary>
		///
		/// </summary>
		protected virtual void DoHideAnimation()
		{
			HideImmediately();
		}

		private void __uiLoadComplete()
		{
			int count = _uiSources.Count;
			for (int i = 0; i < count; i++)
			{
				if (!_uiSources[i].loaded)
				{
					return;
				}
			}
			_loading = false;
			_init();
		}

		private void _init()
		{
			_inited = true;
			OnInit();
			if (isShowing)
			{
				DoShowAnimation();
			}
		}

		public override void Dispose()
		{
			if (_modalWaitPane != null && _modalWaitPane.parent == null)
			{
				_modalWaitPane.Dispose();
			}
			if (_loading)
			{
				for (int i = 0; i < _uiSources.Count; i++)
				{
					_uiSources[i].Cancel();
				}
			}
			base.Dispose();
		}

		protected virtual void closeEventHandler(EventContext context)
		{
			Hide();
		}

		private void __addedToStage()
		{
			if (!_inited)
			{
				Init();
			}
			else
			{
				DoShowAnimation();
			}
		}

		private void __removeFromStage()
		{
			CloseModalWait();
			OnHide();
		}

		private void __touchBegin(EventContext context)
		{
			if (isShowing && bringToFontOnClick)
			{
				BringToFront();
			}
		}

		private void __dragStart(EventContext context)
		{
			context.PreventDefault();
			StartDrag((int)context.data);
		}
	}
	public delegate void TimerCallback(object param);
	/// <summary>
	///
	/// </summary>
	public class Timers
	{
		public static int repeat;

		public static float time;

		public static bool catchCallbackExceptions;

		private Dictionary<TimerCallback, Anymous_T> _items;

		private Dictionary<TimerCallback, Anymous_T> _toAdd;

		private List<Anymous_T> _toRemove;

		private List<Anymous_T> _pool;

		private TimersEngine _engine;

		private GameObject gameObject;

		private static Timers _inst;

		public static Timers inst
		{
			get
			{
				if (_inst == null)
				{
					_inst = new Timers();
				}
				return _inst;
			}
		}

		public Timers()
		{
			//IL_0012: Unknown result type (might be due to invalid IL or missing references)
			//IL_001c: Expected O, but got Unknown
			_inst = this;
			gameObject = new GameObject("[FairyGUI.Timers]");
			((Object)gameObject).hideFlags = (HideFlags)1;
			gameObject.SetActive(true);
			Object.DontDestroyOnLoad((Object)(object)gameObject);
			_engine = gameObject.AddComponent<TimersEngine>();
			_items = new Dictionary<TimerCallback, Anymous_T>();
			_toAdd = new Dictionary<TimerCallback, Anymous_T>();
			_toRemove = new List<Anymous_T>();
			_pool = new List<Anymous_T>(100);
		}

		public void Add(float interval, int repeat, TimerCallback callback)
		{
			Add(interval, repeat, callback, null);
		}

		/// @interval in seconds
		/// @repeat 0 indicate loop infinitely, otherwise the run count
		public void Add(float interval, int repeat, TimerCallback callback, object callbackParam)
		{
			if (callback == null)
			{
				Debug.LogWarning((object)("timer callback is null, " + interval + "," + repeat));
				return;
			}
			if (_items.TryGetValue(callback, out var value))
			{
				value.set(interval, repeat, callback, callbackParam);
				value.elapsed = 0f;
				value.deleted = false;
				return;
			}
			if (_toAdd.TryGetValue(callback, out value))
			{
				value.set(interval, repeat, callback, callbackParam);
				return;
			}
			value = GetFromPool();
			value.interval = interval;
			value.repeat = repeat;
			value.callback = callback;
			value.param = callbackParam;
			_toAdd[callback] = value;
		}

		public void CallLater(TimerCallback callback)
		{
			Add(0.001f, 1, callback);
		}

		public void CallLater(TimerCallback callback, object callbackParam)
		{
			Add(0.001f, 1, callback, callbackParam);
		}

		public void AddUpdate(TimerCallback callback)
		{
			Add(0.001f, 0, callback);
		}

		public void AddUpdate(TimerCallback callback, object callbackParam)
		{
			Add(0.001f, 0, callback, callbackParam);
		}

		public void StartCoroutine(IEnumerator routine)
		{
			((MonoBehaviour)_engine).StartCoroutine(routine);
		}

		public bool Exists(TimerCallback callback)
		{
			if (_toAdd.ContainsKey(callback))
			{
				return true;
			}
			if (_items.TryGetValue(callback, out var value))
			{
				return !value.deleted;
			}
			return false;
		}

		public void Remove(TimerCallback callback)
		{
			if (_toAdd.TryGetValue(callback, out var value))
			{
				_toAdd.Remove(callback);
				ReturnToPool(value);
			}
			if (_items.TryGetValue(callback, out value))
			{
				value.deleted = true;
			}
		}

		private Anymous_T GetFromPool()
		{
			int count = _pool.Count;
			Anymous_T anymous_T;
			if (count > 0)
			{
				anymous_T = _pool[count - 1];
				_pool.RemoveAt(count - 1);
				anymous_T.deleted = false;
				anymous_T.elapsed = 0f;
			}
			else
			{
				anymous_T = new Anymous_T();
			}
			return anymous_T;
		}

		private void ReturnToPool(Anymous_T t)
		{
			t.callback = null;
			_pool.Add(t);
		}

		public void Update()
		{
			float unscaledDeltaTime = Time.unscaledDeltaTime;
			if (_items.Count > 0)
			{
				Dictionary<TimerCallback, Anymous_T>.Enumerator enumerator = _items.GetEnumerator();
				while (enumerator.MoveNext())
				{
					Anymous_T value = enumerator.Current.Value;
					if (value.deleted)
					{
						_toRemove.Add(value);
						continue;
					}
					value.elapsed += unscaledDeltaTime;
					if (value.elapsed < value.interval)
					{
						continue;
					}
					value.elapsed -= value.interval;
					if (value.elapsed < 0f || value.elapsed > 0.03f)
					{
						value.elapsed = 0f;
					}
					if (value.repeat > 0)
					{
						value.repeat--;
						if (value.repeat == 0)
						{
							value.deleted = true;
							_toRemove.Add(value);
						}
					}
					repeat = value.repeat;
					if (value.callback == null)
					{
						continue;
					}
					if (catchCallbackExceptions)
					{
						try
						{
							value.callback(value.param);
						}
						catch (Exception ex)
						{
							value.deleted = true;
							Debug.LogWarning((object)("FairyGUI: timer(internal=" + value.interval + ", repeat=" + value.repeat + ") callback error > " + ex.Message));
						}
					}
					else
					{
						value.callback(value.param);
					}
				}
				enumerator.Dispose();
			}
			int count = _toRemove.Count;
			if (count > 0)
			{
				for (int i = 0; i < count; i++)
				{
					Anymous_T anymous_T = _toRemove[i];
					if (anymous_T.deleted && anymous_T.callback != null)
					{
						_items.Remove(anymous_T.callback);
						ReturnToPool(anymous_T);
					}
				}
				_toRemove.Clear();
			}
			if (_toAdd.Count > 0)
			{
				Dictionary<TimerCallback, Anymous_T>.Enumerator enumerator = _toAdd.GetEnumerator();
				while (enumerator.MoveNext())
				{
					_items.Add(enumerator.Current.Key, enumerator.Current.Value);
				}
				enumerator.Dispose();
				_toAdd.Clear();
			}
		}
	}
	internal class Anymous_T
	{
		public float interval;

		public int repeat;

		public TimerCallback callback;

		public object param;

		public float elapsed;

		public bool deleted;

		public void set(float interval, int repeat, TimerCallback callback, object param)
		{
			this.interval = interval;
			this.repeat = repeat;
			this.callback = callback;
			this.param = param;
		}
	}
	internal class TimersEngine : MonoBehaviour
	{
		private void Update()
		{
			Timers.inst.Update();
		}
	}
}
