			_pointer += 4;
			if (littleEndian == BitConverter.IsLittleEndian)
			{
				return BitConverter.ToSingle(_data, num);
			}
			temp[3] = _data[num];
			temp[2] = _data[num + 1];
			temp[1] = _data[num + 2];
			temp[0] = _data[num + 3];
			return BitConverter.ToSingle(temp, 0);
		}

		/// <summary>
		///
		/// </summary>
		/// <returns></returns>
