			return (uint)((_data[num + 4] << 24) | (_data[num + 5] << 16) | (_data[num + 6] << 8) | _data[num + 7]) | ((long)num4 << 32);
		}

		/// <summary>
		///
		/// </summary>
		/// <returns></returns>
		public double ReadDouble()
		{
			int num = _offset + _pointer;
			_pointer += 8;
			if (littleEndian == BitConverter.IsLittleEndian)
			{
				return BitConverter.ToDouble(_data, num);
			}
			temp[7] = _data[num];
			temp[6] = _data[num + 1];
			temp[5] = _data[num + 2];
			temp[4] = _data[num + 3];
			temp[3] = _data[num + 4];
			temp[2] = _data[num + 5];
			temp[1] = _data[num + 6];
			temp[0] = _data[num + 7];
			return BitConverter.ToSingle(temp, 0);
		}

		/// <summary>
		///
		/// </summary>
		/// <returns></returns>
		public string ReadString()
		{
			ushort num = ReadUshort();
			string @string = Encoding.UTF8.GetString(_data, _offset + _pointer, num);
			_pointer += num;
			return @string;
		}

		/// <summary>
		///
		/// </summary>
		/// <param name="len"></param>
		/// <returns></returns>
		public string ReadString(int len)
		{
			string @string = Encoding.UTF8.GetString(_data, _offset + _pointer, len);
			_pointer += len;
			return @string;
		}

		/// <summary>
		///
		/// </summary>
		/// <returns></returns>
		public string ReadS()
		{
			int num = ReadUshort();
			return num switch
			{
				65534 => null, 
				65533 => string.Empty, 
				_ => stringTable[num], 
			};
		}

		/// <summary>
		///
		/// </summary>
		/// <param name="cnt"></param>
		/// <returns></returns>
		public string[] ReadSArray(int cnt)
		{
			string[] array = new string[cnt];
			for (int i = 0; i < cnt; i++)
			{
				array[i] = ReadS();
			}
			return array;
		}

		/// <summary>
		///
		/// </summary>
		public List<GPathPoint> ReadPath()
		{
			//IL_004b: Unknown result type (might be due to invalid IL or missing references)
			//IL_0061: Unknown result type (might be due to invalid IL or missing references)
			//IL_0088: Unknown result type (might be due to invalid IL or missing references)
			//IL_009e: Unknown result type (might be due to invalid IL or missing references)
			//IL_00b4: Unknown result type (might be due to invalid IL or missing references)
			//IL_00db: Unknown result type (might be due to invalid IL or missing references)
			helperPoints.Clear();
			int num = ReadInt();
			if (num == 0)
			{
				return helperPoints;
			}
			for (int i = 0; i < num; i++)
			{
				GPathPoint.CurveType curveType = (GPathPoint.CurveType)ReadByte();
				switch (curveType)
				{
				case GPathPoint.CurveType.Bezier:
					helperPoints.Add(new GPathPoint(new Vector3(ReadFloat(), ReadFloat(), 0f), new Vector3(ReadFloat(), ReadFloat(), 0f)));
