		public string ToXMLString(bool includeHeader)
		{
			StringBuilder stringBuilder = new StringBuilder();
			if (includeHeader)
			{
				stringBuilder.Append("<?xml version=\"1.0\" encoding=\"utf-8\"?>\n");
			}
			ToXMLString(stringBuilder, 0);
			return stringBuilder.ToString();
		}

		private void ToXMLString(StringBuilder sb, int tabs)
		{
			if (tabs > 0)
			{
				sb.Append(' ', tabs * 2);
			}
			if (name == "!")
			{
				sb.Append("<!--");
				if (text != null)
				{
					int length = sb.Length;
					sb.Append(text);
					XMLUtils.EncodeString(sb, length);
				}
				sb.Append("-->");
				return;
			}
			sb.Append('<').Append(name);
			if (_attributes != null)
			{
				foreach (KeyValuePair<string, string> attribute in _attributes)
				{
					sb.Append(' ');
					sb.Append(attribute.Key).Append('=').Append('"');
					int length2 = sb.Length;
					sb.Append(attribute.Value);
					XMLUtils.EncodeString(sb, length2, isAttribute: true);
					sb.Append("\"");
				}
			}
			int num = ((_children != null) ? _children.Count : 0);
			if (string.IsNullOrEmpty(text) && num == 0)
			{
				sb.Append("/>");
				return;
			}
			sb.Append('>');
			if (!string.IsNullOrEmpty(text))
			{
				int length3 = sb.Length;
				sb.Append(text);
				XMLUtils.EncodeString(sb, length3);
			}
			if (num > 0)
			{
				sb.Append('\n');
				int tabs2 = tabs + 1;
				for (int i = 0; i < num; i++)
				{
					_children[i].ToXMLString(sb, tabs2);
					sb.Append('\n');
				}
				if (tabs > 0)
				{
					sb.Append(' ', tabs * 2);
				}
			}
			sb.Append("</").Append(name).Append(">");
		}
	}
	public enum XMLTagType
	{
		Start,
		End,
		Void,
		CDATA,
		Comment,
		Instruction
	}
	/// <summary>
	///
	/// </summary>
	public class XMLIterator
	{
		public static string tagName;

		public static XMLTagType tagType;

		public static string lastTagName;

		private static string source;

		private static int sourceLen;

		private static int parsePos;

		private static int tagPos;

		private static int tagLength;

		private static int lastTagEnd;

		private static bool attrParsed;

		private static bool lowerCaseName;

		private static StringBuilder buffer = new StringBuilder();

		private static Dictionary<string, string> attributes = new Dictionary<string, string>();

		private const string CDATA_START = "<![CDATA[";

		private const string CDATA_END = "]]>";

		private const string COMMENT_START = "<!--";

		private const string COMMENT_END = "-->";

		public static void Begin(string source, bool lowerCaseName = false)
		{
			XMLIterator.source = source;
			XMLIterator.lowerCaseName = lowerCaseName;
			sourceLen = source.Length;
			parsePos = 0;
			lastTagEnd = 0;
			tagPos = 0;
			tagLength = 0;
			tagName = null;
		}

		public static bool NextTag()
		{
			tagType = XMLTagType.Start;
			buffer.Length = 0;
			lastTagEnd = parsePos;
			attrParsed = false;
			lastTagName = tagName;
			int num;
			if ((num = source.IndexOf('<', parsePos)) != -1)
			{
				parsePos = num;
				num++;
				if (num != sourceLen)
				{
					switch (source[num])
					{
					case '!':
						if (sourceLen > num + 7 && source.Substring(num - 1, 9) == "<![CDATA[")
						{
							num = source.IndexOf("]]>", num);
							tagType = XMLTagType.CDATA;
							tagName = string.Empty;
							tagPos = parsePos;
							if (num == -1)
							{
								tagLength = sourceLen - parsePos;
							}
							else
							{
								tagLength = num + 3 - parsePos;
							}
							parsePos += tagLength;
							return true;
						}
						if (sourceLen > num + 2 && source.Substring(num - 1, 4) == "<!--")
						{
							num = source.IndexOf("-->", num);
							tagType = XMLTagType.Comment;
							tagName = string.Empty;
							tagPos = parsePos;
							if (num == -1)
							{
								tagLength = sourceLen - parsePos;
							}
							else
							{
								tagLength = num + 3 - parsePos;
							}
							parsePos += tagLength;
							return true;
						}
						num++;
						tagType = XMLTagType.Instruction;
						break;
					case '/':
						num++;
						tagType = XMLTagType.End;
						break;
					case '?':
						num++;
						tagType = XMLTagType.Instruction;
						break;
					}
					for (; num < sourceLen; num++)
					{
						char c = source[num];
						if (char.IsWhiteSpace(c) || c == '>' || c == '/')
						{
							break;
						}
					}
					if (num != sourceLen)
					{
						buffer.Append(source, parsePos + 1, num - parsePos - 1);
						if (buffer.Length > 0 && buffer[0] == '/')
						{
							buffer.Remove(0, 1);
						}
						bool flag = false;
						bool flag2 = false;
						int num2 = -1;
						for (; num < sourceLen; num++)
						{
							char c = source[num];
							switch (c)
							{
							case '"':
								if (!flag)
								{
									flag2 = !flag2;
								}
								break;
							case '\'':
								if (!flag2)
								{
									flag = !flag;
								}
								break;
							}
							switch (c)
							{
							case '>':
								if (!(flag || flag2))
								{
									num2 = -1;
									break;
								}
								num2 = num;
								continue;
							default:
								continue;
							case '<':
								break;
							}
							break;
						}
						if (num2 != -1)
						{
							num = num2;
						}
						if (num != sourceLen)
						{
							if (source[num - 1] == '/')
							{
								tagType = XMLTagType.Void;
							}
							tagName = buffer.ToString();
							if (lowerCaseName)
							{
								tagName = tagName.ToLower();
							}
							tagPos = parsePos;
							tagLength = num + 1 - parsePos;
							parsePos += tagLength;
							return true;
						}
					}
				}
			}
			tagPos = sourceLen;
			tagLength = 0;
			tagName = null;
			return false;
		}

		public static string GetTagSource()
		{
			return source.Substring(tagPos, tagLength);
		}

		public static string GetRawText(bool trim = false)
		{
			if (lastTagEnd == tagPos)
			{
				return string.Empty;
			}
			if (trim)
			{
				int i;
				for (i = lastTagEnd; i < tagPos && char.IsWhiteSpace(source[i]); i++)
				{
				}
				if (i == tagPos)
				{
					return string.Empty;
				}
				return source.Substring(i, tagPos - i).TrimEnd();
			}
			return source.Substring(lastTagEnd, tagPos - lastTagEnd);
		}

		public static string GetText(bool trim = false)
		{
			if (lastTagEnd == tagPos)
			{
				return string.Empty;
			}
			if (trim)
			{
				int i;
				for (i = lastTagEnd; i < tagPos && char.IsWhiteSpace(source[i]); i++)
				{
				}
				if (i == tagPos)
				{
					return string.Empty;
				}
				return XMLUtils.DecodeString(source.Substring(i, tagPos - i).TrimEnd());
			}
			return XMLUtils.DecodeString(source.Substring(lastTagEnd, tagPos - lastTagEnd));
		}

		public static bool HasAttribute(string attrName)
		{
			if (!attrParsed)
			{
				attributes.Clear();
				ParseAttributes(attributes);
				attrParsed = true;
			}
			return attributes.ContainsKey(attrName);
		}

