	/// <summary>
	///
	/// </summary>
	public class XMLList
	{
		public struct Enumerator
		{
			private List<XML> _source;

			private string _selector;

			private int _index;

			private int _total;

			private XML _current;

			public XML Current => _current;

			public Enumerator(List<XML> source, string selector)
			{
				_source = source;
				_selector = selector;
				_index = -1;
				if (_source != null)
				{
					_total = _source.Count;
				}
				else
				{
					_total = 0;
				}
				_current = null;
			}

			public bool MoveNext()
			{
				while (++_index < _total)
				{
					_current = _source[_index];
					if (_selector == null || _current.name == _selector)
					{
						return true;
					}
				}
				return false;
			}

			public void Erase()
			{
				_source.RemoveAt(_index);
				_total--;
			}

			public void Reset()
			{
				_index = -1;
			}
		}

		public List<XML> rawList;

		private static List<XML> _tmpList = new List<XML>();

		public int Count => rawList.Count;

		public XML this[int index] => rawList[index];

		public XMLList()
		{
			rawList = new List<XML>();
		}

		public XMLList(List<XML> list)
		{
			rawList = list;
		}

		public void Add(XML xml)
		{
			rawList.Add(xml);
		}

		public void Clear()
		{
			rawList.Clear();
		}

		public Enumerator GetEnumerator()
		{
			return new Enumerator(rawList, null);
		}

		public Enumerator GetEnumerator(string selector)
		{
			return new Enumerator(rawList, selector);
		}

		public XMLList Filter(string selector)
		{
			bool flag = true;
			_tmpList.Clear();
			int count = rawList.Count;
			for (int i = 0; i < count; i++)
			{
				XML xML = rawList[i];
				if (xML.name == selector)
				{
					_tmpList.Add(xML);
				}
				else
				{
					flag = false;
				}
			}
			if (flag)
			{
				return this;
			}
			XMLList result = new XMLList(_tmpList);
			_tmpList = new List<XML>();
			return result;
		}

		public XML Find(string selector)
		{
			int count = rawList.Count;
			for (int i = 0; i < count; i++)
			{
				XML xML = rawList[i];
				if (xML.name == selector)
				{
					return xML;
				}
			}
			return null;
		}

		public void RemoveAll(string selector)
		{
			rawList.RemoveAll((XML xml) => xml.name == selector);
		}
	}
	/// <summary>
	///
	/// </summary>
	public class XMLUtils
	{
		private static string[] ESCAPES = new string[16]
		{
			"&", "&amp;", "<", "&lt;", ">", "&gt;", "'", "&apos;", "\"", "&quot;",
			"\t", "&#x9;", "\n", "&#xA;", "\r", "&#xD;"
		};

		public static string DecodeString(string aSource)
		{
			int length = aSource.Length;
			StringBuilder stringBuilder = new StringBuilder();
			int num = 0;
			int num2 = 0;
			while (true)
			{
				num2 = aSource.IndexOf('&', num);
				if (num2 == -1)
				{
					break;
				}
				stringBuilder.Append(aSource.Substring(num, num2 - num));
				num = num2 + 1;
				num2 = num;
				int num3;
				for (num3 = Math.Min(length, num2 + 10); num2 < num3 && aSource[num2] != ';'; num2++)
				{
				}
				if (num2 < num3 && num2 > num)
				{
					string text = aSource.Substring(num, num2 - num);
					int num4 = 0;
					if (text[0] == '#')
					{
						if (text.Length > 1)
						{
							num4 = ((text[1] != 'x') ? Convert.ToInt16(text.Substring(1)) : Convert.ToInt16(text.Substring(2), 16));
							stringBuilder.Append((char)num4);
							num = num2 + 1;
						}
						else
						{
							stringBuilder.Append('&');
						}
						continue;
					}
					switch (text)
					{
					case "amp":
						num4 = 38;
						break;
					case "apos":
						num4 = 39;
						break;
					case "gt":
						num4 = 62;
						break;
					case "lt":
						num4 = 60;
						break;
					case "nbsp":
						num4 = 32;
						break;
					case "quot":
						num4 = 34;
						break;
					}
					if (num4 > 0)
					{
						stringBuilder.Append((char)num4);
						num = num2 + 1;
					}
					else
					{
						stringBuilder.Append('&');
					}
				}
				else
				{
					stringBuilder.Append('&');
				}
			}
			stringBuilder.Append(aSource.Substring(num));
			return stringBuilder.ToString();
		}

		public static void EncodeString(StringBuilder sb, int start, bool isAttribute = false)
		{
			int num = (isAttribute ? ESCAPES.Length : 6);
			for (int i = 0; i < num; i += 2)
			{
				int count = sb.Length - start;
				sb.Replace(ESCAPES[i], ESCAPES[i + 1], start, count);
			}
		}

		public static string EncodeString(string str, bool isAttribute = false)
		{
			if (string.IsNullOrEmpty(str))
			{
				return "";
			}
			StringBuilder stringBuilder = new StringBuilder(str);
			EncodeString(stringBuilder, 0);
			return stringBuilder.ToString();
		}
	}
	/// <summary>
	/// 一个简单的Zip文件处理类。不处理解压。
	/// </summary>
	public class ZipReader
	{
		/// <summary>
		///
		/// </summary>
		public class ZipEntry
		{
			public string name;

			public int compress;

			public uint crc;

			public int size;

			public int sourceSize;

			public int offset;

			public bool isDirectory;
		}

		private ByteBuffer _stream;

		private int _entryCount;

		private int _pos;

		private int _index;

		/// <summary>
		///
		/// </summary>
		public int entryCount => _entryCount;

		/// <summary>
		///
		/// </summary>
		/// <param name="data"></param>
		public ZipReader(byte[] data)
		{
			_stream = new ByteBuffer(data);
			_stream.littleEndian = true;
			int num = _stream.length - 22;
			_stream.position = num + 10;
			_entryCount = _stream.ReadShort();
			_stream.position = num + 16;
			_pos = _stream.ReadInt();
		}

		/// <summary>
		///
		/// </summary>
		/// <returns></returns>
		public bool GetNextEntry(ZipEntry entry)
		{
			if (_index >= _entryCount)
			{
				return false;
			}
			_stream.position = _pos + 28;
			int num = _stream.ReadUshort();
			int num2 = _stream.ReadUshort() + _stream.ReadUshort();
			_stream.position = _pos + 46;
			string text = _stream.ReadString(num);
			text = (entry.name = text.Replace("\\", "/"));
			if (text[text.Length - 1] == '/')
			{
				entry.isDirectory = true;
				entry.compress = 0;
				entry.crc = 0u;
				entry.size = (entry.sourceSize = 0);
				entry.offset = 0;
			}
			else
			{
				entry.isDirectory = false;
				_stream.position = _pos + 10;
				entry.compress = _stream.ReadUshort();
				_stream.position = _pos + 16;
				entry.crc = _stream.ReadUint();
				entry.size = _stream.ReadInt();
				entry.sourceSize = _stream.ReadInt();
				_stream.position = _pos + 42;
				entry.offset = _stream.ReadInt() + 30 + num;
			}
			_pos += 46 + num + num2;
			_index++;
			return true;
		}

		/// <summary>
		///
		/// </summary>
		/// <param name="entry"></param>
		/// <returns></returns>
		public byte[] GetEntryData(ZipEntry entry)
		{
			byte[] array = new byte[entry.size];
			if (entry.size > 0)
			{
				_stream.position = entry.offset;
				_stream.ReadBytes(array, 0, entry.size);
			}
			return array;
		}
	}
