					if (context.Exception is JsonException)
					{
						WindowConfirmDialog.CreateDialog("提示", $"初始化失败！读取导出的游戏数据时发生错误，请尝试重新导出游戏数据（使用F4 -> 导出游戏数据 进行导出）\n错误信息：\n{context.Exception}", canCancel: false);
					}
					else
					{
						WindowConfirmDialog.CreateDialog("提示", $"初始化失败！错误信息：\n{context.Exception}", canCancel: false);
					}
				}
				else if (!Directory.Exists(Main.PathExportOutputDir.Value))
				{
					WindowConfirmDialog.CreateDialog("提示", "没有找到游戏数据导出目录，缺失导出数据会影响编辑器使用，是否导出游戏数据？", canCancel: true, delegate
					{
						ModManager.GenerateBaseData();
						ModEditorManager.I.LoadDefaultData();
					});
				}
			});
		}

		public void Clear()
		{
			TreeProject.RemoveAllProjects();
			DocumentView.RemoveAllTab();
		}

		protected override void OnHide()
		{
			Clear();
			base.OnHide();
		}

		private void InitProject()
		{
			HeaderBar = new CtlHeaderBar(MainView.m_comHeader);
			TreeProject = new CtlTreeProject(MainView.m_comProject);
			DocumentView = new CtlDocumentView(MainView.m_comDocument);
			TreeProject.SetClickItem(delegate(EventContext context, ProjectTreeNodeBase node)
			{
				if (context.inputEvent.isDoubleClick && node.IsLeaf && CurMod != null && node is IDocumentItem item)
				{
					DocumentView.TryAddAndSelectTab(item);
				}
			});
			TreeProject.SetRightClickItem(delegate(EventContext context, ProjectTreeNodeBase node)
			{
				ProjectPopupBuild(node).Show(null, PopupDirection.Down);
			});
			CtlDocumentView documentView = DocumentView;
			documentView.OnTabAdd = (Action<PanelPageBase>)Delegate.Combine(documentView.OnTabAdd, (Action<PanelPageBase>)delegate(PanelPageBase page)
			{
				if (page is IModDataClipboardPage modDataClipboardPage)
				{
					modDataClipboardPage.DataClipboard = DataClipboard;
				}
			});
		}

		private PopupMenu ProjectPopupBuild(ProjectTreeNodeBase node)
		{
			ProjectTreeModProject project = node as ProjectTreeModProject;
			bool num = project != null;
			PopupMenu popupMenu = new PopupMenu();
			popupMenu.AddItem("新建项目".I18NTodo(), OnCreateProject);
			popupMenu.AddSeperator();
			if (num)
			{
				popupMenu.AddItem("重命名".I18NTodo(), (EventCallback0)delegate
				{
					OnRenameProject(project.Project);
				});
				popupMenu.AddItem("删除".I18NTodo(), (EventCallback0)delegate
				{
					OnRemoveProject(project.Project);
				});
			}
			else
			{
				popupMenu.AddItem("重命名".I18NTodo(), (EventCallback0)delegate
				{
				}).enabled = false;
				popupMenu.AddItem("删除".I18NTodo(), (EventCallback0)delegate
				{
				}).enabled = false;
			}
			return popupMenu;
		}

		private void OnCreateProject()
		{
			if (CurMod == null)
			{
				return;
			}
			WindowStringInputDialog.CreateDialog("新建项目", "mod Project", canCancel: true, delegate(string newName)
			{
				if (string.IsNullOrEmpty(newName))
				{
					WindowConfirmDialog.CreateDialog("创建失败", "项目名称不能为空", canCancel: false);
				}
				else if (Directory.Exists(CurMod.Path))
				{
					WindowConfirmDialog.CreateDialog("创建失败", "项目目录已存在", canCancel: false);
				}
				else
				{
					ModProject project = CurMod.CreateProject(newName);
					ProjectTreeModProject nodeData = new ProjectTreeModProject(CurMod, project);
					TreeProject.AddProject(nodeData);
					TreeProject.Refresh();
				}
			});
		}

		private void OnRemoveProject(ModProject project)
		{
			if (CurMod == null)
			{
				return;
			}
			WindowConfirmDialog.CreateDialog("删除", "确定删除项目【" + project.ProjectName + "】？该操作无法撤回。", canCancel: true, delegate
			{
				Directory.Delete(project.ProjectPath, recursive: true);
				CurMod.RemoveProject(project);
				TreeProject.RemoveProject((ProjectTreeNodeBase node) => node is ProjectTreeModProject projectTreeModProject && projectTreeModProject.Project == project);
				TreeProject.Refresh();
			});
		}

		private void OnRenameProject(ModProject project)
		{
			if (CurMod == null)
			{
				return;
			}
			WindowStringInputDialog.CreateDialog("重命名", project.ProjectName, canCancel: true, delegate(string rename)
			{
				if (string.IsNullOrEmpty(rename))
				{
					WindowConfirmDialog.CreateDialog("重命名失败", "项目名称不能为空", canCancel: false);
				}
				else if (CurMod.Projects.Exists((ModProject p) => p.ProjectDirectory == rename))
				{
					WindowConfirmDialog.CreateDialog("重命名失败", "目标目录已存在", canCancel: false);
				}
				else
				{
					string projectPath = project.ProjectPath;
					string text = CurMod.ProjectDirPath + "/" + rename;
					Directory.Move(projectPath, text);
					project.ProjectPath = text;
					TreeProject.Refresh();
				}
			});
		}

		private void InitHeader()
		{
			HeaderBar.AddMenu("ModEditor.Main.Header.File".I18N(), FilePopupBuild);
			HeaderBar.AddMenu("工具".I18NTodo(), ToolPopupBuild);
		}

		private PopupMenu FilePopupBuild()
		{
			PopupMenu popupMenu = new PopupMenu();
			popupMenu.AddItem("新建工程".I18NTodo(), OnClickFileCreate);
			popupMenu.AddItem("ModEditor.Main.Header.File.Open".I18N(), OnClickFileOpen);
			GButton gButton = popupMenu.AddItem("ModEditor.Main.Header.File.Save".I18N(), OnClickFileSave);
			GButton gButton2 = popupMenu.AddItem("ModEditor.Main.Header.File.Export".I18N(), OnClickFileExport);
			popupMenu.AddItem("ModEditor.Main.Header.File.Exit".I18N(), OnClickFileExit);
			if (CurMod == null)
			{
				gButton.enabled = false;
				gButton2.enabled = false;
			}
			return popupMenu;
		}

		private PopupMenu ToolPopupBuild()
		{
			PopupMenu popupMenu = new PopupMenu();
			popupMenu.AddItem("创建AB包工程".I18NTodo(), OnClickCreateABProject);
			return popupMenu;
		}

		private void OnClickCreateABProject()
		{
			new WindowCreateABProjectDialogBuilder().Build().Show();
		}

		private void OnClickFileExit()
		{
			WindowConfirmDialog.CreateDialog("确认退出", "确定要退出编辑器吗？请确认数据是否保存。", canCancel: true, base.Hide);
		}

		private void OnClickFileCreate()
		{
			new WindowCreateWorkshopModDialogBuilder().SetTitle("新建工坊工程".I18NTodo()).SetItemList(new ProjectListCreateWorkshopEmpty[1]
			{
				new ProjectListCreateWorkshopEmpty()
			}).SetOnSelectMod(OnOpenMod)
				.Build()
				.Show();
		}

		private void OnClickFileOpen()
		{
			WindowModSelectorDialog.CreateDialog("打开工坊工程".I18NTodo(), ModFilter.Local, new List<TableInfo>
			{
				new TableInfo("名称", 288f, (object o) => ((ModWorkshop)o).ModInfo.Title),
				new TableInfo("位置", 576f, (object o) => ((ModWorkshop)o).Path)
			}, OnOpenMod);
		}

		private void OnClickFileSave()
		{
			if (CurMod != null)
			{
				OnSaveMod(CurMod, CurMod.Path);
			}
		}

		private void OnClickFileExport()
		{
			//IL_0009: Unknown result type (might be due to invalid IL or missing references)
			//IL_000f: Expected O, but got Unknown
			if (CurMod != null)
			{
				FolderPicker val = new FolderPicker();
				val.Title = "Mod选择文件夹";
				bool? flag = val.ShowDialog(IntPtr.Zero, false);
				if (flag.HasValue && flag.Value)
				{
					string resultPath = val.ResultPath;
					OnSaveMod(CurMod, resultPath);
					Main.LogInfo("Mod导出路径：" + resultPath);
				}
			}
		}

		private void OnOpenMod(ModWorkshop mod)
		{
			Clear();
			try
			{
				CurMod = mod;
				CurMod.LoadProjects();
				TreeProject.AddProject(new ProjectTreeModWorkshop(CurMod));
				TreeProject.AddProject(new ProjectTreeModProjectReferenced(CurMod, ModEditorManager.I.ReferenceProject));
				foreach (ModProject project in mod.Projects)
				{
					ProjectTreeModProject nodeData = new ProjectTreeModProject(CurMod, project);
					TreeProject.AddProject(nodeData);
				}
				TreeProject.Refresh();
			}
			catch (ModOpenException ex)
			{
				WindowConfirmDialog.CreateDialog("工程打开失败", "打开工程失败，错误日志：\n" + ex.Message, canCancel: false);
				Clear();
			}
			catch (Exception arg)
			{
				WindowConfirmDialog.CreateDialog("工程打开失败", $"打开工程失败，错误日志：\n{arg}", canCancel: false);
				Clear();
			}
		}

		private void OnSaveMod(ModWorkshop mod, string path)
		{
			WindowWaitDialog.CreateDialog("提示", "正在保存Mod...", 0.5f, delegate(WaitContext context)
			{
				try
				{
					ModEditorManager.I.SaveWorkshop(mod, path);
				}
				catch (Exception exception)
				{
					context.Exception = exception;
				}
			}, delegate(WaitContext context)
			{
				if (context.Exception != null)
				{
					WindowConfirmDialog.CreateDialog("提示", $"Mod保存失败！错误信息：\n{context.Exception}", canCancel: false);
				}
				else
				{
					WindowConfirmDialog.CreateDialog("提示", "保存完毕！", canCancel: false);
				}
			});
		}
	}
}
