	public class CreateWorkshopException : Exception
	{
		public CreateWorkshopException()
		{
		}

		public CreateWorkshopException(string message)
			: base(message)
		{
		}

		public CreateWorkshopException(string message, Exception innerException)
			: base(message, innerException)
		{
		}

