	public abstract class ProjectListCreateWorkshopItem : ProjectListInspectItem
	{
		public abstract ModWorkshop OnCreateWorkshop();
	}
	public class ProjectListCreateWorkshopEmpty : ProjectListCreateWorkshopItem
	{
		public override string Name => "空白项目";

		public string ModDir { get; set; } = "新工程";


		public string ModName { get; set; } = "空白Mod";


		public override void OnInspect()
		{
			base.Inspector.AddDrawer(new CtlTitleDrawer("空白工程".I18NTodo()));
			CtlTextDrawer modPathDrawer = new CtlTextDrawer(string.Format("项目路径：{0}".I18NTodo(), GetModPath()));
			base.Inspector.AddDrawer(modPathDrawer);
			base.Inspector.AddDrawer(new CtlStringPropertyDrawer("项目目录".I18NTodo(), delegate(string str)
			{
				ModDir = str;
				modPathDrawer.SetText(string.Format("项目路径：{0}".I18NTodo(), GetModPath()));
			}, () => ModDir));
			base.Inspector.AddDrawer(new CtlStringPropertyDrawer("项目名称".I18NTodo(), delegate(string str)
			{
				ModName = str;
			}, () => ModName));
		}

		public override ModWorkshop OnCreateWorkshop()
		{
			if (string.IsNullOrEmpty(ModDir))
			{
				throw new CreateWorkshopException("目标目录不能为空！");
			}
			if (Directory.Exists(GetModPath()))
			{
				throw new CreateWorkshopException("目标目录已存在！");
			}
			Directory.CreateDirectory(GetModPath());
			ModWorkshop modWorkshop = ModEditorManager.I.CreateWorkshop(GetModPath(), ModName);
			modWorkshop.CreateProject("mod新项目");
			ModEditorManager.I.SaveWorkshop(modWorkshop);
			return ModEditorManager.I.LoadWorkshop(GetModPath());
		}

		private string GetModPath()
		{
			return (Main.PathLocalModsDir.Value + "/" + ModDir).Replace("\\", "/");
		}
	}
