	public class PanelTableModAffixDataPage : PanelTablePageBase<ModAffixData>
	{
		public override ModDataTableDataList<ModAffixData> ModDataTableDataList { get; set; }

		public PanelTableModAffixDataPage(string name, ModWorkshop mod, ModProject project)
			: base(name, mod, project)
		{
		}

		protected override void OnInit()
		{
			ModDataTableDataList = new ModDataTableDataList<ModAffixData>(base.Project.AffixData);
			AddTableHeader(new TableInfo("ID".I18NTodo(), 96f, (object data) => ((ModAffixData)data).Id.ToString()));
			AddTableHeader(new TableInfo("名称".I18NTodo(), 96f, (object data) => ((ModAffixData)data).Name));
			AddTableHeader(new TableInfo("词缀项目".I18NTodo(), 96f, delegate(object data)
			{
				ModAffixData modAffixData = (ModAffixData)data;
				return $"{modAffixData.ProjectTypeNum} : {modAffixData.ProjectTypeName}";
			}));
			AddTableHeader(new TableInfo("词缀类型".I18NTodo(), 96f, delegate(object data)
			{
				ModAffixData affixData = (ModAffixData)data;
				ModAffixDataAffixType modAffixDataAffixType = ModEditorManager.I.AffixDataAffixTypes.Find((ModAffixDataAffixType x) => x.TypeID == affixData.AffixType);
				return (modAffixDataAffixType != null) ? $"{modAffixDataAffixType.TypeID} : {modAffixDataAffixType.TypeName}" : $"{affixData.AffixType} : ???";
			}));
			AddTableHeader(new TableInfo("描述".I18NTodo(), 288f, (object data) => ((ModAffixData)data).Desc));
		}

		protected override void OnInspectItem(ModAffixData data)
		{
			if (data == null)
			{
				return;
			}
			AddDrawer(new CtlIDPropertyDrawer("ID".I18NTodo(), data, () => base.Project.AffixData, delegate(IModData theData)
			{
				ModAffixData data2 = (ModAffixData)theData;
				return OnGetDataName(data2);
			}, delegate(IModData theData, int newId)
			{
				theData.Id = newId;
				base.Project.AffixData.ModSort();
				base.CurInspectIndex = base.Project.AffixData.FindIndex((ModAffixData modData) => modData == theData);
			}, delegate(IModData theData, IModData otherData)
			{
				IModData modData2 = theData;
				int id = theData.Id;
				int id2 = otherData.Id;
				otherData.Id = id;
				modData2.Id = id2;
				base.Project.AffixData.ModSort();
				base.CurInspectIndex = base.Project.AffixData.FindIndex((ModAffixData modData) => modData == theData);
			}, delegate
			{
				base.Inspector.Refresh();
			}));
			AddDrawer(new CtlStringPropertyDrawer("名称".I18NTodo(), delegate(string str)
			{
