		public override string OnGetDataName(ModItemData data)
		{
			return $"{data.Id} {data.Name}";
		}

		protected override void OnBuildCustomPopupMenu(PopupMenu menu, ModItemData[] modDataArray)
		{
			menu.AddSeperator();
			bool? flag = modDataArray?.All((ModItemData modData) => modData.ItemType == 3 || modData.ItemType == 4);
			menu.AddItem("生成请教书籍".I18NTodo(), (EventCallback0)delegate
			{
				OnGenerateSkillLearnBook(modDataArray);
			}).enabled = base.Editable && flag == true;
			menu.AddSeperator();
		}

		private void OnGenerateSkillLearnBook(ModItemData[] modDataArray)
		{
			if (!base.Editable)
			{
				return;
			}
			if (modDataArray.Any((ModItemData modData) => modData.Id > 1000000000))
			{
				ModItemData arg = modDataArray.First((ModItemData modData) => modData.Id > 1000000000);
				WindowConfirmDialog.CreateDialog("提示", $"当前物品ID:{arg}超出10,0000,0000(十亿)，无法创建对应请教书籍", canCancel: false);
				return;
			}
			if (modDataArray.Any((ModItemData modData) => modData.ItemType != 3 && modData.ItemType != 4))
			{
				ModItemData arg2 = modDataArray.First((ModItemData modData) => modData.ItemType != 3 && modData.ItemType != 4);
				WindowConfirmDialog.CreateDialog("提示", $"当前物品ID:{arg2}类型不为神通或功法书籍，无法创建对应请教书籍", canCancel: false);
				return;
			}
			if (modDataArray.Any((ModItemData modData) => ModDataTableDataList.HasId(modData.Id + 1000000000)))
			{
				ModItemData modItemData = modDataArray.First((ModItemData modData) => ModDataTableDataList.HasId(modData.Id + 1000000000));
				WindowConfirmDialog.CreateDialog("提示", $"当前物品ID:{modItemData.Id}对应的请教书籍已存在，无法创建对应请教书籍", canCancel: false);
				return;
			}
			WindowConfirmDialog.CreateDialog("提示", "是否创建ID为[" + string.Join(",", modDataArray.Select((ModItemData modData) => $"({modData.Id}){modData.Name}")) + "]的请教书籍？", canCancel: true, delegate
			{
				SequenceCommand sequenceCommand = new SequenceCommand();
				ModItemData[] array = modDataArray;
				foreach (ModItemData modItemData2 in array)
				{
					CopyData copyData = GetCopyData(modItemData2);
					int bookId = modItemData2.Id + 1000000000;
					sequenceCommand.AddCommand(new AddDataUndoCommand(delegate
					{
						ModItemData modItemData3 = OnPasteData(copyData, bookId);
						modItemData3.ShopType = 99;
						modItemData3.ItemFlagList.Clear();
						modItemData3.Price = 0;
						return modItemData3;
					}, delegate(IModData data)
					{
						AddData((ModItemData)data);
					}, delegate(IModData data)
					{
						RemoveData(data.Id);
					}));
				}
				this.Record(sequenceCommand);
				Refresh();
			});
		}

		protected override ModItemData OnPasteData(CopyData copyData, int targetId)
		{
			int id = copyData.Data.Id;
			ModItemData modItemData = ((JToken)copyData.Data.GetJsonData()).ToObject<ModItemData>();
			modItemData.Id = targetId;
			base.Project.ItemData.Add(modItemData);
			base.Project.ItemEquipSeidDataGroup.CopyAllSeid(copyData.Project.ItemEquipSeidDataGroup, id, targetId);
			base.Project.ItemUseSeidDataGroup.CopyAllSeid(copyData.Project.ItemUseSeidDataGroup, id, targetId);
			base.Project.ItemData.ModSort();
			return modItemData;
		}
	}
