		private void OnGenerateSkillBook(ModSkillData modData)
		{
			if (!base.Editable || modData == null)
			{
				return;
			}
			int itemId = modData.SkillPkId + 3000;
			if (base.Project.ItemData.HasId(itemId))
			{
				WindowConfirmDialog.CreateDialog("提示", $"ID为{itemId}的物品已经存在！", canCancel: false);
				return;
			}
			WindowConfirmDialog.CreateDialog("提示", $"是否创建ID为{itemId}的神通书籍？", canCancel: true, delegate
			{
				ModItemData modItemData = new ModItemData
				{
					Id = itemId,
					Icon = 3001,
					Name = modData.Name,
					Info = modData.SkillPkId.ToString(),
					Desc = modData.Desc,
					Quality = modData.Quality,
					Phase = modData.Phase,
					ItemType = 3,
					MaxStack = 1,
					ShopType = 99,
					StudyCostTime = ((modData.Quality - 1) * 3 + modData.Phase) * 12,
					SpecialType = 1,
					SeidList = { 1 }
				};
				base.Project.ItemData.Add(modItemData);
				base.Project.ItemUseSeidDataGroup.GetOrCreateSeid(modItemData.Id, 1).SetValue("value1", modData.SkillPkId);
			});
		}

		private void OnGenerateSkillGroup(ModSkillData modData)
		{
			if (!base.Editable || modData == null)
			{
				return;
			}
			if (modData.SkillLv != 1)
			{
				WindowConfirmDialog.CreateDialog("提示", "只有神通等级为1的神通才能生成神通组".I18NTodo(), canCancel: false);
				return;
			}
			for (int i = 1; i < 5; i++)
			{
				int num = modData.Id + i;
				if (ModDataTableDataList.HasId(num))
				{
					WindowConfirmDialog.CreateDialog("提示", $"已经存在id为{num}的神通，请确保从{modData.Id} ~ {modData.Id + 4}范围没有相应技能。".I18NTodo(), canCancel: false);
					return;
				}
			}
			WindowConfirmDialog.CreateDialog("提示", $"是否生成从{modData.Id} ~ {modData.Id + 4}的技能组？".I18NTodo(), canCancel: true, delegate
			{
				CopyData copyData = GetCopyData(modData);
				SequenceCommand sequenceCommand = new SequenceCommand();
				if (!modData.Name.EndsWith("1"))
				{
					modData.Name += "1";
				}
				for (int j = 1; j < 5; j++)
				{
					int id = modData.Id + j;
					int tagLv = j + 1;
					sequenceCommand.AddCommand(new AddDataUndoCommand(delegate
					{
						ModSkillData modSkillData = OnPasteData(copyData, id);
						modSkillData.SkillLv = tagLv;
						modSkillData.Name = modData.Name.Substring(0, modData.Name.Length - 1) + $"{tagLv}";
						return modSkillData;
					}, delegate(IModData data)
					{
						AddData((ModSkillData)data);
					}, delegate(IModData data)
					{
						RemoveData(data.Id);
					}));
				}
				this.Record(sequenceCommand);
				Refresh();
			});
		}

		protected override ModSkillData OnPasteData(CopyData copyData, int targetId)
		{
			int id = copyData.Data.Id;
			ModSkillData modSkillData = ((JToken)copyData.Data.GetJsonData()).ToObject<ModSkillData>();
			modSkillData.Id = targetId;
			base.Project.SkillData.Add(modSkillData);
			base.Project.SkillSeidDataGroup.CopyAllSeid(copyData.Project.SkillSeidDataGroup, id, targetId);
			base.Project.SkillData.ModSort();
			return modSkillData;
		}
	}
