		/// <summary>
		/// 聚焦到选中的数据
		/// </summary>
		/// <param name="indexArray"></param>
		protected virtual void Focus(params int[] indexArray)
		{
			if (indexArray.Length != 0)
			{
				int toIndex = indexArray.Min();
				int curIndex = CurInspectIndex;
				int[] curIndexArray = TableList.SelectionArea.ToArray();
				this.Record(new CommonUndoCommand(delegate
				{
					CurInspectIndex = toIndex;
					TableList.SelectionArea = (IReadOnlyCollection<int>)(object)indexArray;
					RefreshInspector();
				}, delegate
				{
					CurInspectIndex = curIndex;
					TableList.SelectionArea = (IReadOnlyCollection<int>)(object)curIndexArray;
					RefreshInspector();
				}));
			}
		}

		/// <summary>
		/// 聚焦到选中的数据组
		/// </summary>
		/// <param name="indexArray"></param>
		protected virtual void FocusWithoutRecord(params int[] indexArray)
		{
			if (indexArray.Length != 0)
			{
				int curInspectIndex = indexArray.Min();
				CurInspectIndex = curInspectIndex;
				TableList.SelectionArea = (IReadOnlyCollection<int>)(object)indexArray;
				RefreshInspector();
			}
		}

