		{
			BuildTableItemPopupMenu(selectedItems).Show(null, PopupDirection.Down);
		}

		protected virtual void OnClickPasteAsNew()
		{
			if (CanPaste(DataClipboard.CopyDatas))
			{
				PasteCopyDataAsNew(DataClipboard.CurCopyData);
				RefreshTable();
			}
