		protected virtual PopupMenu BuildTableItemPopupMenu(T[] modDataArray)
		{
			PopupMenu popupMenu = new PopupMenu();
			popupMenu.AddItem("新建", TryAddData).enabled = Editable;
			popupMenu.AddItem("复制", (EventCallback0)delegate
			{
				OnCopy(modDataArray);
			}).enabled = modDataArray != null && CanCopy(modDataArray);
			popupMenu.AddItem("粘贴", OnClickPaste).enabled = Editable && CanPaste(DataClipboard.CopyDatas);
			popupMenu.AddItem("另存为", OnClickPasteAsNew).enabled = Editable && CanPaste(DataClipboard.CopyDatas);
			OnBuildCustomPopupMenu(popupMenu, modDataArray);
			popupMenu.AddItem("删除", (EventCallback0)delegate
			{
				TryRemoveData(modDataArray);
			}).enabled = Editable && CanRemove(modDataArray);
			return popupMenu;
		}

		protected virtual void OnBuildCustomPopupMenu(PopupMenu menu, T[] modDataArray)
		{
		}

		private void InspectItem(int index)
		{
			Inspector.Editable = Editable;
			if (index >= 0 && index < TableList.GetDataCount())
			{
				CurInspectIndex = index;
				T data = (T)TableList.GetData(index);
				Inspector.Clear();
				OnInspectItem(data);
				Inspector.Refresh();
			}
			else
			{
				CurInspectIndex = -1;
				Inspector.Clear();
			}
			RefreshToolsBar();
		}

		private void RefreshToolsBar()
		{
			if (Editable)
			{
				BtnToolsAdd.enabled = true;
				int[] array = TableList.SelectionArea.ToArray();
				T[] array2 = array.Select(GetItem).ToArray();
				if (array.Length != 0)
				{
					BtnToolsRemove.enabled = CanRemove(array2);
					BtnToolsCopy.enabled = CanCopy(array2);
				}
				else
				{
					BtnToolsRemove.enabled = false;
					BtnToolsCopy.enabled = false;
				}
				BtnToolsPaste.enabled = Editable && CanPaste(DataClipboard?.CopyDatas);
				BtnToolsPasteAsNew.enabled = Editable && CanPaste(DataClipboard?.CopyDatas);
			}
			else
			{
				BtnToolsAdd.enabled = false;
				BtnToolsRemove.enabled = false;
				BtnToolsCopy.enabled = true;
				BtnToolsPaste.enabled = false;
				BtnToolsPasteAsNew.enabled = false;
			}
			BtnToolsUndo.enabled = CanUndo();
			BtnToolsRedo.enabled = CanRedo();
		}

		private void OnClickAdd()
		{
			TryAddData();
		}

		protected void TryAddData()
		{
			WindowIntInputDialog.CreateDialog("新建数据ID", canCancel: true, delegate(int id)
			{
				if (HasId(id))
				{
					WindowConfirmDialog.CreateDialog("提示", "创建数据失败，对应ID已存在。", canCancel: false);
				}
				else
				{
					this.Record(new AddDataUndoCommand(delegate
					{
						T val = new T
						{
							Id = id
						};
						AddData(val);
						return val;
					}, delegate(IModData modData)
					{
						AddData((T)modData);
					}, delegate(IModData modData)
					{
						RemoveData(modData.Id);
					}));
				}
			});
		}

		private void OnClickRemove()
		{
			T[] array = TableList.SelectedItems.Select((object d) => (T)d).ToArray();
			if (array.Length != 0)
			{
				if (array.Length == 1)
				{
					TryRemoveData(array[0]);
				}
				else
				{
					TryRemoveData(array);
				}
			}
		}

		protected void TryRemoveData(T modData)
		{
			if (NeedRemoveSeidData)
			{
				WindowConfirmDialogExtra.CreateDialog("提示", "即将删除数据【" + OnGetDataName(modData) + "】，是否确认？", "同时删除所有引用该数据的数据", canCancel: true, defaultExtra: false, delegate(bool removeSeidData)
				{
					OnRemoveData(modData, removeSeidData);
				});
			}
			else
			{
				WindowConfirmDialog.CreateDialog("提示", "即将删除数据【" + OnGetDataName(modData) + "】，是否确认？", canCancel: true, delegate
				{
					OnRemoveData(modData);
				});
			}
		}

		protected void TryRemoveData(T[] modDataArray)
		{
			WindowConfirmDialog.CreateDialog("提示", $"即将删除【{OnGetDataName(modDataArray[0])}】等{modDataArray.Length}项数据，是否确认？", canCancel: true, delegate
			{
				foreach (T modData in modDataArray)
				{
					OnRemoveData(modData);
				}
			});
		}

		/// <summary>
		/// 移除数据，基类只移除数据，不移除seid数据
		/// </summary>
		/// <param name="modData"></param>
		/// <param name="removeSeidData"></param>
		protected virtual void OnRemoveData(T modData, bool removeSeidData = false)
		{
			this.Record(new RemoveDataUndoCommand(modData, delegate(IModData data)
			{
				AddData((T)data);
			}, delegate(IModData data)
			{
				RemoveData(data.Id);
			}));
		}

		protected virtual void OnClickCopy()
