		protected virtual void OnSearchData(string input)
		{
			TableEditor.TableList.SearchItems(input);
			TableList.SelectedIndex = 0;
			InspectItem(TableList.SelectedIndex);
		}

		protected virtual TDrawer AddDrawer<TDrawer>(TDrawer drawer) where TDrawer : IPropertyDrawer
		{
			ref TDrawer reference = ref drawer;
			TDrawer val = default(TDrawer);
			if (val == null)
			{
				val = reference;
				reference = ref val;
			}
			reference.AddChangeListener(RefreshTable);
			ref TDrawer reference2 = ref drawer;
			val = default(TDrawer);
			if (val == null)
			{
				val = reference2;
				reference2 = ref val;
			}
			reference2.UndoManager = UndoManager;
			Inspector.AddDrawer(drawer);
			return drawer;
		}

		protected abstract void OnInspectItem(T data);

		public void ReloadInspector()
		{
			InspectItem(CurInspectIndex);
		}

		public virtual bool HasId(int id)
		{
			return GetIndexById(id) != -1;
		}

		public virtual T GetItemById(int id)
		{
			ModDataTableDataList.TryGetItem(id, out var item);
			return item;
		}

		public virtual int GetIndexById(int id)
		{
			for (int i = 0; i < GetDataCount(); i++)
			{
				if (GetItem(i).Id == id)
				{
					return i;
				}
			}
			return -1;
		}

		protected virtual bool CanUndo()
		{
			if (Editable)
			{
				return UndoManager.CanUndo;
			}
			return false;
		}

		protected virtual bool CanRedo()
		{
			if (Editable)
			{
				return UndoManager.CanRedo;
			}
			return false;
		}

		protected virtual bool CanCopy(T[] data)
		{
			return data != null;
		}

		protected CopyData GetCopyData(T data)
		{
			return new CopyData
			{
				Data = data,
				Project = Project,
				Name = OnGetDataName(data)
			};
		}

		public abstract string OnGetDataName(T data);

		private bool CanRemove(T[] modDataArray)
		{
			if (modDataArray != null)
			{
				return modDataArray.Length != 0;
			}
			return false;
		}

		public virtual bool CanPaste(List<CopyData> dataArray)
		{
			if (dataArray == null || dataArray.Count == 0)
			{
				return false;
			}
			return dataArray.All((CopyData copyData) => copyData.Data is T);
		}

		public void PasteCopyData(List<CopyData> copyDataArray)
		{
			if (copyDataArray.Count == 1)
			{
				CopyData copyData3 = copyDataArray[0];
				if (ModDataTableDataList.TryGetItem(copyData3.Data.Id, out var item))
				{
					if (copyData3.Data == item)
					{
						PasteCopyDataAsNew(copyData3);
						return;
					}
					WindowConfirmDialog.CreateDialog("提示", $"目标ID:【{copyData3.Data.Id}】已经存在数据，是否覆盖？", canCancel: true, delegate
					{
						ModDataTableDataList.RemoveItem(copyData3.Data.Id);
						this.Record(new AddDataUndoCommand(() => OnPasteData(copyData3, copyData3.Data.Id), delegate(IModData data)
						{
							AddData((T)data);
						}, delegate(IModData data)
						{
							RemoveData(data.Id);
						}));
						int indexById2 = GetIndexById(copyData3.Data.Id);
						Focus(indexById2);
						RefreshTable();
					});
				}
				else
				{
					this.Record(new AddDataUndoCommand(() => OnPasteData(copyData3, copyData3.Data.Id), delegate(IModData data)
					{
						AddData((T)data);
					}, delegate(IModData data)
					{
						RemoveData(data.Id);
					}));
					int indexById = GetIndexById(copyData3.Data.Id);
					Focus(indexById);
					RefreshTable();
				}
				return;
			}
			if (copyDataArray.Any((CopyData copyData) => ModDataTableDataList.HasId(copyData.Data.Id)))
			{
				CopyData[] source = copyDataArray.Where((CopyData copyData) => ModDataTableDataList.HasId(copyData.Data.Id)).ToArray();
				WindowConfirmDialog.CreateDialog("提示", "目标ID:【" + string.Join(",", source.Select((CopyData d) => d.Data.Id.ToString())) + "】已经存在数据，是否覆盖？", canCancel: true, delegate
				{
					SequenceCommand sequenceCommand2 = new SequenceCommand();
					foreach (CopyData copyData4 in copyDataArray)
					{
						if (ModDataTableDataList.HasId(copyData4.Data.Id))
						{
							T itemById = ModDataTableDataList.GetItemById(copyData4.Data.Id);
							sequenceCommand2.AddCommand(new RemoveDataUndoCommand(itemById, delegate(IModData data)
							{
								AddData((T)data);
							}, delegate(IModData data)
							{
								RemoveData(data.Id);
							}));
						}
						sequenceCommand2.AddCommand(new AddDataUndoCommand(() => OnPasteData(copyData4, copyData4.Data.Id), delegate(IModData data)
						{
							AddData((T)data);
						}, delegate(IModData data)
						{
							RemoveData(data.Id);
						}));
					}
					this.Record(sequenceCommand2);
					int[] indexArray2 = copyDataArray.Select((CopyData copyData) => GetIndexById(copyData.Data.Id)).ToArray();
					Focus(indexArray2);
					RefreshTable();
				});
				return;
			}
			SequenceCommand sequenceCommand = new SequenceCommand();
			foreach (CopyData copyData2 in copyDataArray)
			{
				sequenceCommand.AddCommand(new AddDataUndoCommand(() => OnPasteData(copyData2, copyData2.Data.Id), delegate(IModData data)
				{
					AddData((T)data);
				}, delegate(IModData data)
				{
					RemoveData(data.Id);
				}));
			}
			this.Record(sequenceCommand);
			int[] indexArray = copyDataArray.Select((CopyData copyData) => GetIndexById(copyData.Data.Id)).ToArray();
			Focus(indexArray);
			RefreshTable();
		}

		private void PasteCopyDataAsNew(CopyData copyData)
		{
			WindowIntInputDialog.CreateDialog("请输入新的数据ID", canCancel: true, delegate(int id)
			{
				if (HasId(id))
				{
					WindowConfirmDialog.CreateDialog("提示", "粘贴数据失败，对应ID已存在。", canCancel: false);
				}
				else
				{
					this.Record(new AddDataUndoCommand(() => OnPasteData(copyData, id), delegate(IModData data)
					{
						AddData((T)data);
					}, delegate(IModData data)
					{
						RemoveData(data.Id);
					}));
					RefreshTable();
				}
			});
		}

		protected abstract T OnPasteData(CopyData copyData, int targetId);

		public int GetDataCount()
		{
			return TableList.GetDataCount();
		}

		public T GetItem(int index)
		{
			if (index < 0 || index >= GetDataCount())
			{
				return null;
			}
			return (T)TableList.GetData(index);
		}
	}
}
