		public static ModProject Load(string dir, string dataDir = null, bool ignoreWarning = false)
		{
			ModConfig modConfig = ModConfig.Load(dir, ignoreWarning);
			dataDir = dataDir ?? modConfig.GetDataDir();
			ModProject obj = new ModProject
			{
				ProjectPath = dir,
				Config = modConfig,
				CreateAvatarData = ModSingleFileData<ModCreateAvatarData>.Load(dataDir).ToList(),
				CreateAvatarSeidDataGroup = ModSeidDataGroupBase<ModCreateAvatarSeidDataGroup>.Load(dataDir, ModEditorManager.I.CreateAvatarSeidMetas),
				BuffData = ModFolderFileData<ModBuffData>.Load(dataDir),
				ItemData = ModFolderFileData<ModItemData>.Load(dataDir),
				ItemFlagData = ModSingleFileData<ModItemFlagData>.Load(dataDir).ToList(),
				ItemEquipSeidDataGroup = ModSeidDataGroupBase<ModItemEquipSeidDataGroup>.Load(dataDir, ModEditorManager.I.ItemEquipSeidMetas),
				ItemUseSeidDataGroup = ModSeidDataGroupBase<ModItemUseSeidDataGroup>.Load(dataDir, ModEditorManager.I.ItemUseSeidMetas),
				BuffSeidDataGroup = ModSeidDataGroupBase<ModBuffSeidDataGroup>.Load(dataDir, ModEditorManager.I.BuffSeidMetas),
				AffixData = ModSingleFileData<ModAffixData>.Load(dataDir).ToList(),
				ForgeProperty = ModSingleFileData<ModForgePropertyData>.Load(dataDir).ToList(),
				ForgeElement = ModSingleFileData<ModForgeElementData>.Load(dataDir).ToList(),
				AlchemyElement = ModSingleFileData<ModAlchemyElementData>.Load(dataDir).ToList(),
				Comprehension = ModSingleFileData<ModComprehensionData>.Load(dataDir).ToList(),
				ComprehensionPhase = ModSingleFileData<ModComprehensionPhaseData>.Load(dataDir).ToList(),
				SkillData = ModFolderFileData<ModSkillData>.Load(dataDir),
				StaticSkillData = ModSingleFileData<ModStaticSkillData>.Load(dataDir),
				SkillSeidDataGroup = ModSeidDataGroupBase<ModSkillSeidDataGroup>.Load(dataDir, ModEditorManager.I.SkillSeidMetas),
				StaticSkillSeidDataGroup = ModSeidDataGroupBase<ModStaticSkillSeidDataGroup>.Load(dataDir, ModEditorManager.I.StaticSkillSeidMetas)
			};
			obj.CreateAvatarData.ModSort();
			obj.BuffData.ModSort();
			obj.ItemData.ModSort();
			obj.AffixData.ModSort();
			obj.SkillData.ModSort();
			obj.StaticSkillData.ModSort();
			return obj;
		}

		public static void Save(string dir, ModProject project)
		{
			ModConfig config = project.Config;
			config.Path = dir;
			Directory.CreateDirectory(config.GetConfigDir());
			Directory.CreateDirectory(config.GetDataDir());
			Directory.CreateDirectory(config.GetNDataDir());
			ModConfig.Save(config.GetConfigDir(), project.Config);
			ModSingleFileData<ModCreateAvatarData>.Save(config.GetDataDir(), project.CreateAvatarData);
			ModSeidDataGroupBase<ModCreateAvatarSeidDataGroup>.Save(config.GetDataDir(), project.CreateAvatarSeidDataGroup);
			ModFolderFileData<ModBuffData>.Save(config.GetDataDir(), project.BuffData);
			ModFolderFileData<ModItemData>.Save(config.GetDataDir(), project.ItemData);
			ModSingleFileData<ModItemFlagData>.Save(config.GetDataDir(), project.ItemFlagData);
			ModSeidDataGroupBase<ModItemEquipSeidDataGroup>.Save(config.GetDataDir(), project.ItemEquipSeidDataGroup);
			ModSeidDataGroupBase<ModItemUseSeidDataGroup>.Save(config.GetDataDir(), project.ItemUseSeidDataGroup);
			ModSeidDataGroupBase<ModBuffSeidDataGroup>.Save(config.GetDataDir(), project.BuffSeidDataGroup);
			ModSingleFileData<ModAffixData>.Save(config.GetDataDir(), project.AffixData);
			ModSingleFileData<ModForgePropertyData>.Save(config.GetDataDir(), project.ForgeProperty);
			ModSingleFileData<ModForgeElementData>.Save(config.GetDataDir(), project.ForgeElement);
			ModSingleFileData<ModAlchemyElementData>.Save(config.GetDataDir(), project.AlchemyElement);
			ModSingleFileData<ModComprehensionData>.Save(config.GetDataDir(), project.Comprehension);
			ModSingleFileData<ModComprehensionPhaseData>.Save(config.GetDataDir(), project.ComprehensionPhase);
			ModFolderFileData<ModSkillData>.Save(config.GetDataDir(), project.SkillData);
			ModSingleFileData<ModStaticSkillData>.Save(config.GetDataDir(), project.StaticSkillData);
			ModSeidDataGroupBase<ModSkillSeidDataGroup>.Save(config.GetDataDir(), project.SkillSeidDataGroup);
			ModSeidDataGroupBase<ModStaticSkillSeidDataGroup>.Save(config.GetDataDir(), project.StaticSkillSeidDataGroup);
		}
