	public static class ModUtils
	{
		public static List<T> ModSort<T>(this List<T> list) where T : IModData
		{
			list.Sort((T dataX, T dataY) => dataX.Id.CompareTo(dataY.Id));
			return list;
		}

		public static bool TryFindData<T>(this List<T> list, int id, out T data) where T : IModData
		{
			data = default(T);
			int num = list.FindIndex((T x) => x.Id == id);
			if (num < 0)
			{
				return false;
			}
			data = list[num];
			return true;
		}

		public static bool HasId<T>(this List<T> list, int id) where T : IModData
		{
			return list.FindIndex((T data) => data.Id == id) != -1;
		}

		public static int GetIndex<T>(this List<T> list, int id) where T : IModData
		{
			return list.FindIndex((T data) => data.Id == id);
		}

		public static JObject GetJsonData(this IModData modData)
		{
			return JObject.FromObject((object)modData);
		}

		public static IEnumerable<int> ModLoadIntArray(this JToken token)
		{
			if (token == null)
			{
				yield break;
			}
			if (token is JArray)
			{
				foreach (JToken item in (IEnumerable<JToken>)token)
				{
					if ((int)item.Type == 6)
					{
						yield return Extensions.Value<int>((IEnumerable<JToken>)item);
					}
				}
			}
			else if (token is JValue && (int)token.Type == 6)
			{
				yield return Extensions.Value<int>((IEnumerable<JToken>)token);
			}
		}

		public static bool TryFormatToListInt(this string str, out List<int> list)
		{
			list = new List<int>();
			string[] array = str.Split(',', '，');
			foreach (string text in array)
			{
				if (!string.IsNullOrWhiteSpace(text))
				{
					if (!int.TryParse(text, out var result))
					{
						return false;
					}
					list.Add(result);
				}
			}
			return true;
		}

		public static string ToFormatString(this List<int> list)
		{
			return string.Join(",", list);
		}

		public static void CopyDirectory(string sourceDir, string destinationDir, bool recursive)
		{
			DirectoryInfo directoryInfo = new DirectoryInfo(sourceDir);
			if (!directoryInfo.Exists)
			{
				throw new DirectoryNotFoundException("Source directory not found: " + directoryInfo.FullName);
			}
			DirectoryInfo[] directories = directoryInfo.GetDirectories();
			Directory.CreateDirectory(destinationDir);
			FileInfo[] files = directoryInfo.GetFiles();
			foreach (FileInfo fileInfo in files)
			{
				string destFileName = Path.Combine(destinationDir, fileInfo.Name);
				fileInfo.CopyTo(destFileName);
			}
			if (recursive)
			{
				DirectoryInfo[] array = directories;
				foreach (DirectoryInfo directoryInfo2 in array)
				{
					string destinationDir2 = Path.Combine(destinationDir, directoryInfo2.Name);
					CopyDirectory(directoryInfo2.FullName, destinationDir2, recursive: true);
				}
			}
		}

		public static string LoadEditorConfig(string path)
		{
			string editorConfigPath = GetEditorConfigPath(path);
			if (File.Exists(editorConfigPath))
			{
				return File.ReadAllText(editorConfigPath);
			}
			Debug.LogWarning((object)("目标文件 " + editorConfigPath + " 不存在！"));
			return string.Empty;
		}

		public static string LoadBaseConfig(string path)
		{
			string basePath = GetBasePath(path);
			if (File.Exists(basePath))
			{
				return File.ReadAllText(basePath);
			}
			Debug.LogWarning((object)("目标文件 " + basePath + " 不存在！"));
			return string.Empty;
		}

		public static string GetEditorConfigPath(string path)
		{
			if (string.IsNullOrWhiteSpace(path))
			{
				return Main.I.CurrentLanguage.LanguageDir ?? "";
			}
			return Main.I.CurrentLanguage.LanguageDir + "/Editor/" + path;
		}

		public static string GetBasePath(string path = "")
		{
			if (string.IsNullOrWhiteSpace(path))
			{
				return Main.PathBaseDataDir.Value;
			}
			return Main.PathBaseDataDir.Value + "/" + path;
		}

