			{
				return "【技能描述】" + ((item.ItemType == 3) ? "神通" : "功法") + ":" + item.Desc;
			}
			return item.Info;
		}

		public static string GetAffixDesc(this ModWorkshop mod, List<int> affixIntList)
		{
			StringBuilder stringBuilder = new StringBuilder();
			foreach (int affixInt in affixIntList)
			{
				ModAffixData affixData = mod.FindAffix(affixInt);
				stringBuilder.Append(GetAffixDesc(affixData));
				stringBuilder.Append("\n");
