		public static string GetAlchemyElementDesc(this ModWorkshop mod, int id)
		{
			if (id == 0)
			{
				return "【0】无";
			}
			ModAlchemyElementData modAlchemyElementData = mod.FindAlchemyElement(id);
			if (modAlchemyElementData == null)
			{
				return $"【{id}】未知";
			}
			return $"【{modAlchemyElementData.Id}】{modAlchemyElementData.Name}";
		}

		public static string GetComprehensionWithPhaseDesc(this ModWorkshop mod, List<int> comList)
		{
			StringBuilder stringBuilder = new StringBuilder();
			for (int i = 0; i < comList.Count; i += 2)
			{
				int num = comList[i];
				ModComprehensionData modComprehensionData = mod.FindComprehension(num);
				if (modComprehensionData != null)
				{
					stringBuilder.Append($"【{num} {modComprehensionData.Desc}】");
				}
				else
				{
					stringBuilder.Append($"【{num} 未知】");
				}
				int num2 = 0;
				if (i + 1 < comList.Count)
				{
					num2 = comList[i + 1];
				}
				ModComprehensionPhaseData modComprehensionPhaseData = mod.FindComprehensionPhase(num2);
				if (modComprehensionPhaseData != null)
				{
					stringBuilder.Append($"({num2}){modComprehensionPhaseData.Name}");
				}
				else
				{
					stringBuilder.Append($"({num2})未知");
				}
				if (i + 2 < comList.Count)
				{
					stringBuilder.Append("\n");
				}
			}
			return stringBuilder.ToString();
		}

		public static IEnumerable<Type> GetTypesWithAttribute(Assembly assembly, Type attributeType)
		{
			Type[] types = assembly.GetTypes();
			foreach (Type type in types)
			{
				if (type.GetCustomAttributes(attributeType, inherit: true).Length != 0)
				{
					yield return type;
				}
			}
		}

		public static string GetSkillLevelName(int itemQuality, int itemPhase)
		{
			ModEditorManager.I.SkillDataQuality.TryFindData(itemQuality, out var data);
			ModEditorManager.I.SkillDataPhase.TryFindData(itemPhase, out var data2);
			return (data?.Desc ?? "？") + (data2?.Desc ?? "？");
		}

		public static string AnalysisRefData(ModWorkshop mod, string str)
		{
			if (str.StartsWith("GuideLink://", StringComparison.OrdinalIgnoreCase))
			{
				StringBuilder stringBuilder = new StringBuilder();
				stringBuilder.Append("【图鉴信息】");
				stringBuilder.Append("\n");
				string[] array = str.Substring("GuideLink://".Length).Split('_');
				if (int.TryParse(array[0], out var result))
				{
					switch (result)
					{
					case 1:
						stringBuilder.Append($"类型：【{result} 实体】");
						break;
					case 2:
					{
						stringBuilder.Append($"类型：【{result} 规则】");
						stringBuilder.Append("\n");
						if (array.Length >= 2 && int.TryParse(array[1], out var subType))
						{
							ModAffixDataProjectType modAffixDataProjectType = ModEditorManager.I.AffixDataProjectTypes.Find((ModAffixDataProjectType x) => x.TypeNum == subType);
							if (modAffixDataProjectType != null)
							{
								stringBuilder.Append($"标签：【{modAffixDataProjectType.TypeNum} {modAffixDataProjectType.TypeName}】");
							}
							else
							{
								stringBuilder.Append($"标签：【{subType} 未知】");
							}
						}
						else
						{
							subType = 0;
							stringBuilder.Append($"标签：【{subType} 未知】");
						}
						stringBuilder.Append("\n");
						if (array.Length >= 3 && int.TryParse(array[2], out var affixSubType))
						{
							ModAffixDataAffixType modAffixDataAffixType = ModEditorManager.I.AffixDataAffixTypes.Find((ModAffixDataAffixType x) => x.TypeID == affixSubType);
							if (modAffixDataAffixType != null)
							{
								stringBuilder.Append($"子类：【{modAffixDataAffixType.TypeID} {modAffixDataAffixType.TypeName}】");
							}
							else
							{
								stringBuilder.Append($"子类：【{affixSubType} 未知】");
							}
						}
						else
						{
							affixSubType = 0;
							stringBuilder.Append($"子类：【{affixSubType} 未知】");
						}
						stringBuilder.Append("\n");
						if (array.Length >= 4 && int.TryParse(array[3], out var result2))
						{
							ModAffixData modAffixData = mod.FindAffix(result2);
							if (modAffixData != null)
							{
								stringBuilder.Append($"词缀：【{result2} {modAffixData.Name}】{modAffixData.Desc}");
							}
							else
							{
								stringBuilder.Append($"词缀：【{result2} 未知】");
							}
						}
						else
						{
							result2 = 0;
							stringBuilder.Append($"词缀：【{result2} 未知】");
						}
						break;
					}
					case 3:
						stringBuilder.Append($"类型：【{result} 地图】");
						break;
					default:
						stringBuilder.Append($"类型：【{result} 未知】");
						break;
					}
				}
				else
				{
					result = 0;
					stringBuilder.Append($"类型：【{result} 未知】");
				}
				return stringBuilder.ToString();
			}
			return str;
		}

		public static void CreateUnityABTemplateProject(string projectName, string projectPath, string exportABPath)
		{
			CopyDirectory(Path.Combine(Main.PathTemplateDir.Value, "ModABPackTemplate"), projectPath, recursive: true);
			string text = Path.Combine(projectPath, "Assets/NextMods/modAssets");
			Directory.CreateDirectory(text);
			string path = Path.Combine(projectPath, "Assets/NextModPackerCollection.asset");
			string text2 = File.ReadAllText(path);
			text2 = text2.Replace("%TemplateAB%", projectName).Replace("%TemplateFile%", text).Replace("%TemplateOutput%", Path.GetFullPath(exportABPath));
			File.WriteAllText(path, text2);
		}
	}
	public class ModWorkshop
	{
		public string Path { get; }

		public string ModInfoPath => Path + "/Mod.bin";

		public string ProjectDirPath => Path + "/plugins/Next";

		public WorkShopItem ModInfo { get; }

		public List<ModProject> Projects { get; } = new List<ModProject>();


		public ModWorkshop(WorkShopItem modInfo, string path)
		{
			//IL_0017: Unknown result type (might be due to invalid IL or missing references)
			ModInfo = (WorkShopItem)(((object)modInfo) ?? ((object)new WorkShopItem()));
			Path = new FileInfo(path).FullName;
		}

		public void Save()
		{
			SaveWorkshopItem();
			SaveProjects();
		}

		public void SaveWorkshopItem()
		{
			//IL_0006: Unknown result type (might be due to invalid IL or missing references)
			ModInfo.SteamID = SteamUser.GetSteamID().m_SteamID;
			ModInfo.ModPath = Path;
			ModManager.WriteConfig(ModInfoPath, ModInfo);
		}

		public void SaveProjects()
		{
			Directory.CreateDirectory(ProjectDirPath);
			foreach (ModProject project in Projects)
			{
				ModEditorManager.I.SaveProject(project, ProjectDirPath + "/" + project.ProjectDirectory);
			}
		}

		public void LoadProjects()
		{
			Dictionary<string, Exception> dictionary = new Dictionary<string, Exception>();
			if (Directory.Exists(ProjectDirPath))
			{
				string[] directories = Directory.GetDirectories(ProjectDirPath);
				foreach (string text in directories)
				{
					ModProject modProject = null;
					try
					{
						modProject = ModEditorManager.I.OpenProject(text);
					}
					catch (Exception value)
					{
						dictionary.Add(text, value);
						continue;
					}
					if (modProject != null)
					{
						Projects.Add(modProject);
					}
				}
			}
			if (dictionary.Count <= 0)
			{
				return;
			}
			StringBuilder stringBuilder = new StringBuilder();
			foreach (KeyValuePair<string, Exception> item in dictionary)
			{
				stringBuilder.Append("Mod: 【");
				stringBuilder.Append(System.IO.Path.GetFileNameWithoutExtension(item.Key));
				stringBuilder.Append("】加载失败。错误消息：");
				stringBuilder.Append(item.Value.Message);
				stringBuilder.Append("\n");
			}
			stringBuilder.Append("\n完整错误信息：\n");
			foreach (KeyValuePair<string, Exception> item2 in dictionary)
			{
				stringBuilder.Append("Mod: 【");
				stringBuilder.Append(System.IO.Path.GetFileNameWithoutExtension(item2.Key));
				stringBuilder.Append("】\n");
				stringBuilder.Append(item2.Value);
				stringBuilder.Append("\n");
			}
			throw new ModLoadException(stringBuilder.ToString());
		}

		public ModProject CreateProject(string name)
		{
			string path = System.IO.Path.Combine(ProjectDirPath, name);
			Directory.CreateDirectory(path);
			ModProject modProject = ModEditorManager.I.CreateProject(path);
			Projects.Add(modProject);
			return modProject;
		}

		public void RemoveProject(ModProject project)
		{
			Projects.Remove(project);
		}

