		public string GetImageUrl(string resPath)
		{
			foreach (ModProject project in Projects)
			{
				if (project.TryGetFilePath(resPath + ".png", out var filePath))
				{
					return "file://" + filePath;
				}
			}
			return resPath;
		}
	}
