	public abstract class ModFolderFileData<T> : IModData where T : ModFolderFileData<T>
	{
		public abstract int Id { get; set; }

		public static string FolderName { get; set; }

		public static List<T> Load(string dir)
		{
			List<T> list = new List<T>();
			string path = dir + "/" + FolderName;
			if (!Directory.Exists(path))
			{
				return list;
			}
			string[] files = Directory.GetFiles(path);
			foreach (string text in files)
			{
				T val;
				try
				{
					val = JsonConvert.DeserializeObject<T>(File.ReadAllText(text));
				}
				catch (Exception innerException)
				{
					throw new Exception("加载 " + typeof(T).Name + " 数据失败！文件路径：" + text, innerException);
				}
				if (Path.GetFileNameWithoutExtension(text) != val?.Id.ToString())
				{
					throw new ModException("文件ID与定义ID不一致");
				}
				list.Add(val);
			}
			return list;
		}

		public static void Save(string dir, List<T> dataDic)
		{
			string text = dir + "/" + FolderName;
			if (Directory.Exists(text))
			{
				Directory.Delete(text, recursive: true);
			}
			Directory.CreateDirectory(text);
			foreach (T item in dataDic)
			{
				string path = $"{text}/{item.Id}.json";
				string contents = JsonConvert.SerializeObject((object)item, (Formatting)1);
				File.WriteAllText(path, contents);
			}
		}
	}
