	public class ModItemDataArtifactTypeGroup
	{
		[JsonProperty("ShapeDesc")]
		public Dictionary<string, string> ShapeDesc { get; set; }

		[JsonProperty("PropertyDesc")]
		public Dictionary<string, string> PropertyDesc { get; set; }

		public string GetDescription(string value)
		{
			if (string.IsNullOrEmpty(value))
			{
				return "无";
			}
			string[] array = value.Split('_');
			if (array.Length < 2)
			{
				return "未知".I18NTodo();
			}
			if (!ShapeDesc.TryGetValue(array[0], out var value2))
			{
				return "未知".I18NTodo();
			}
			if (!PropertyDesc.TryGetValue(array[1], out var value3))
			{
				return "未知".I18NTodo();
			}
			return string.Format("{0}属性{1}".I18NTodo(), value3, value2);
		}
	}
