	public class ModSeidData : IModData
	{
		private static readonly string[] _FallbackSeidIds = new string[2] { "id", "skillid" };

		public int Id { get; set; }

		public Dictionary<string, ModSeidToken> DataDic { get; set; } = new Dictionary<string, ModSeidToken>();


		public static ModSeidData LoadSeidData(ModSeidMeta meta, JObject jObject)
		{
			ModSeidData modSeidData = new ModSeidData();
			JToken val = default(JToken);
			if (!jObject.TryGetValue(meta.IDName, ref val))
			{
				string[] fallbackSeidIds = _FallbackSeidIds;
				foreach (string text in fallbackSeidIds)
				{
					if (jObject.TryGetValue(text, ref val))
					{
						break;
					}
				}
				if (val == null)
				{
					throw new ModDataIdNotExistException();
				}
			}
			modSeidData.Id = val.ToObject<int>();
			foreach (ModSeidProperty property in meta.Properties)
			{
				JToken val2 = null;
				switch (property.Type)
				{
				case ModSeidPropertyType.Int:
				{
					ModSInt modSInt = new ModSInt();
					if (jObject.TryGetValue(property.ID, ref val2))
					{
						modSInt.Value = val2.ToObject<int>();
					}
					modSeidData.DataDic.Add(property.ID, modSInt);
					break;
				}
				case ModSeidPropertyType.IntArray:
				{
					ModSIntArray modSIntArray = new ModSIntArray();
					if (jObject.TryGetValue(property.ID, ref val2))
					{
						modSIntArray.Value.AddRange(val2.ModLoadIntArray());
					}
					modSeidData.DataDic.Add(property.ID, modSIntArray);
					break;
				}
				case ModSeidPropertyType.Float:
				{
					ModSFloat modSFloat = new ModSFloat();
					if (jObject.TryGetValue(property.ID, ref val2))
					{
						modSFloat.Value = val2.ToObject<float>();
					}
					modSeidData.DataDic.Add(property.ID, modSFloat);
					break;
				}
				case ModSeidPropertyType.String:
				{
					ModSString modSString = new ModSString();
					if (jObject.TryGetValue(property.ID, ref val2))
					{
						modSString.Value = val2.ToObject<string>();
					}
					modSeidData.DataDic.Add(property.ID, modSString);
					break;
				}
				}
			}
			return modSeidData;
		}

		public T GetToken<T>(string dataId) where T : ModSeidToken
		{
			return DataDic[dataId] as T;
		}

		public static ModSeidData CreateSeidData(int ID, ModSeidMeta meta)
		{
			ModSeidData modSeidData = new ModSeidData();
			modSeidData.Id = ID;
			foreach (ModSeidProperty property in meta.Properties)
			{
				switch (property.Type)
				{
				case ModSeidPropertyType.Int:
				{
					ModSInt value4 = new ModSInt();
					modSeidData.DataDic.Add(property.ID, value4);
					break;
				}
				case ModSeidPropertyType.IntArray:
				{
					ModSIntArray value3 = new ModSIntArray();
					modSeidData.DataDic.Add(property.ID, value3);
					break;
				}
				case ModSeidPropertyType.Float:
				{
					ModSFloat value2 = new ModSFloat();
					modSeidData.DataDic.Add(property.ID, value2);
					break;
				}
				case ModSeidPropertyType.String:
				{
					ModSString value = new ModSString();
					modSeidData.DataDic.Add(property.ID, value);
					break;
				}
				default:
					throw new ArgumentOutOfRangeException();
				}
			}
			return modSeidData;
		}

		public static JObject SaveSeidData(ModSeidMeta meta, ModSeidData seidData)
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			//IL_0006: Expected O, but got Unknown
			JObject val = new JObject();
			val.Add(meta.IDName, JToken.op_Implicit(seidData.Id));
			foreach (ModSeidProperty property in meta.Properties)
			{
				switch (property.Type)
				{
				case ModSeidPropertyType.Int:
					val.Add(property.ID, JToken.op_Implicit(seidData.GetToken<ModSInt>(property.ID).Value));
					break;
				case ModSeidPropertyType.IntArray:
				{
					JArray val2 = JArray.FromObject((object)seidData.GetToken<ModSIntArray>(property.ID).Value);
					val.Add(property.ID, (JToken)(object)val2);
					break;
				}
				case ModSeidPropertyType.Float:
					val.Add(property.ID, JToken.op_Implicit(seidData.GetToken<ModSFloat>(property.ID).Value));
					break;
				case ModSeidPropertyType.String:
					val.Add(property.ID, JToken.op_Implicit(seidData.GetToken<ModSString>(property.ID).Value));
					break;
				default:
					throw new ArgumentOutOfRangeException();
				}
			}
			return val;
		}

		public void SetValue(string key, int data)
		{
			if (DataDic.TryGetValue(key, out var value) && value is ModSInt modSInt)
			{
				modSInt.Value = data;
			}
			else
			{
				Main.LogError($"无法将Seid：{Id}的{key}设置为{data}，因为该属性不存在或者类型不匹配");
			}
		}
	}
	public class ModSeidDataGroup
	{
		public ModSeidMeta MetaData { get; set; }

		public List<ModSeidData> DataList { get; set; } = new List<ModSeidData>();


		private ModSeidDataGroup(ModSeidMeta meta)
		{
			MetaData = meta;
		}

		public static ModSeidDataGroup Create(ModSeidMeta meta)
		{
			return new ModSeidDataGroup(meta);
		}

		public static ModSeidDataGroup Load(string dir, ModSeidMeta meta)
		{
			//IL_00f2: Unknown result type (might be due to invalid IL or missing references)
			//IL_0054: Unknown result type (might be due to invalid IL or missing references)
			//IL_005e: Expected O, but got Unknown
			ModSeidDataGroup modSeidDataGroup = null;
			string text = $"{dir}/{meta.Id}.json";
			if (File.Exists(text))
			{
				modSeidDataGroup = new ModSeidDataGroup(meta);
				foreach (JProperty item in JObject.Parse(File.ReadAllText(text)).Properties())
				{
					try
					{
						ModSeidData modSeidData = ModSeidData.LoadSeidData(meta, (JObject)item.Value);
						if (item.Name != modSeidData.Id.ToString())
						{
							throw new ModException("Seid ID与Key ID不一致");
						}
						modSeidDataGroup.DataList.Add(modSeidData);
					}
					catch (ModDataIdNotExistException)
					{
						throw new ModException(string.Format("{0}中的{1}的ID不存在".I18NTodo(), meta.Id, item.Name));
					}
					catch (Exception ex2)
					{
						throw new JsonException("Seid Json " + text + " " + item.Name + " 读取失败", ex2);
					}
				}
			}
			if (modSeidDataGroup == null)
			{
				modSeidDataGroup = new ModSeidDataGroup(meta);
			}
			return modSeidDataGroup;
		}

		public static void Save(string dir, ModSeidDataGroup dataGroup)
		{
			//IL_0030: Unknown result type (might be due to invalid IL or missing references)
			//IL_0036: Expected O, but got Unknown
			string path = $"{dir}/{dataGroup.MetaData.Id}.json";
			if (dataGroup.DataList.Count == 0)
			{
				File.Delete(path);
				return;
			}
			JObject val = new JObject();
			foreach (ModSeidData data in dataGroup.DataList)
			{
				JObject val2 = ModSeidData.SaveSeidData(dataGroup.MetaData, data);
				val.Add(data.Id.ToString(), (JToken)(object)val2);
			}
			File.WriteAllText(path, ((JToken)val).ToString((Formatting)1, Array.Empty<JsonConverter>()));
		}
	}
	public class ModSeidDataGroupBase<TGroup> : IModSeidDataGroup where TGroup : ModSeidDataGroupBase<TGroup>, new()
	{
		public Dictionary<int, ModSeidDataGroup> DataGroups { get; set; } = new Dictionary<int, ModSeidDataGroup>();


		public static string DirPath { get; set; }

		public static TGroup Create(Dictionary<int, ModSeidMeta> metas)
		{
			TGroup val = new TGroup();
			foreach (KeyValuePair<int, ModSeidMeta> meta in metas)
			{
				if (meta.Value.Properties.Count != 0)
				{
					val.DataGroups.Add(meta.Key, ModSeidDataGroup.Create(meta.Value));
				}
			}
			return val;
		}

		public static TGroup Load(string dir, Dictionary<int, ModSeidMeta> metas)
		{
			TGroup val = new TGroup();
			string dir2 = dir + "/" + DirPath;
			foreach (KeyValuePair<int, ModSeidMeta> meta in metas)
			{
				if (meta.Value.Properties.Count != 0)
				{
					val.DataGroups.Add(meta.Key, ModSeidDataGroup.Load(dir2, meta.Value));
				}
			}
			return val;
		}

		public static void Save(string dir, TGroup dataGroup)
		{
			string text = dir + "/" + DirPath;
			Directory.CreateDirectory(text);
			foreach (KeyValuePair<int, ModSeidDataGroup> dataGroup2 in dataGroup.DataGroups)
			{
				if (dataGroup2.Value.MetaData.Properties.Count != 0)
				{
					ModSeidDataGroup.Save(text, dataGroup2.Value);
				}
			}
		}

		public ModSeidData GetSeid(int dataId, int seidId)
		{
			if (DataGroups.TryGetValue(seidId, out var value))
			{
				return value.DataList.Find((ModSeidData data) => data.Id == dataId);
			}
			return null;
		}

		public ModSeidData GetOrCreateSeid(int dataId, int seidId)
		{
			if (DataGroups.TryGetValue(seidId, out var value))
			{
				ModSeidData modSeidData = value.DataList.Find((ModSeidData d) => d.Id == dataId);
				if (modSeidData == null)
				{
					modSeidData = ModSeidData.CreateSeidData(dataId, value.MetaData);
					value.DataList.Add(modSeidData);
				}
				return modSeidData;
			}
			return null;
		}

		public bool RemoveSeid(int dataId, int seidId)
		{
			if (DataGroups.TryGetValue(seidId, out var value))
			{
				int num = value.DataList.FindIndex((ModSeidData data) => data.Id == dataId);
				if (num >= 0)
				{
					value.DataList.RemoveAt(num);
					return true;
				}
			}
			return false;
		}

		public void RemoveAllSeid(int dataId)
		{
			foreach (KeyValuePair<int, ModSeidDataGroup> dataGroup in DataGroups)
			{
				List<ModSeidData> dataList = dataGroup.Value.DataList;
				int num = dataList.FindIndex((ModSeidData data) => data.Id == dataId);
				if (num >= 0)
				{
					dataList.RemoveAt(num);
				}
			}
		}

		/// <summary>
		/// 将data的所有Seid迁移至新ID
		/// </summary>
		/// <param name="oldDataId"></param>
		/// <param name="newDataId"></param>
		public void ChangeSeidID(int oldDataId, int newDataId)
		{
			foreach (ModSeidDataGroup value in DataGroups.Values)
			{
				ModSeidData modSeidData = value.DataList.Find((ModSeidData data) => data.Id == oldDataId);
				if (modSeidData != null)
				{
					modSeidData.Id = newDataId;
				}
			}
		}

		/// <summary>
		/// 交换两个Data的Seid的ID
		/// </summary>
		/// <param name="dataId1"></param>
		/// <param name="dataId2"></param>
		public void SwiftSeidID(int dataId1, int dataId2)
		{
			foreach (ModSeidDataGroup value in DataGroups.Values)
			{
				ModSeidData modSeidData = value.DataList.Find((ModSeidData data) => data.Id == dataId1);
				ModSeidData modSeidData2 = value.DataList.Find((ModSeidData data) => data.Id == dataId2);
				if (modSeidData != null)
				{
					modSeidData.Id = dataId2;
				}
				if (modSeidData2 != null)
				{
					modSeidData2.Id = dataId1;
				}
			}
		}

		public void CopyAllSeid(ModSeidDataGroupBase<TGroup> from, int oldId, int targetId)
		{
			foreach (KeyValuePair<int, ModSeidDataGroup> dataGroup in from.DataGroups)
			{
				List<ModSeidData> dataList = dataGroup.Value.DataList;
				int num = dataList.FindIndex((ModSeidData data) => data.Id == oldId);
				if (num < 0)
				{
					continue;
				}
				JObject jObject = ModSeidData.SaveSeidData(dataGroup.Value.MetaData, dataList[num]);
				ModSeidData data2 = ModSeidData.LoadSeidData(dataGroup.Value.MetaData, jObject);
				data2.Id = targetId;
				if (DataGroups[dataGroup.Key].DataList.HasId(data2.Id))
				{
					DataGroups[dataGroup.Key].DataList.RemoveAll((ModSeidData findData) => findData.Id == data2.Id);
				}
				DataGroups[dataGroup.Key].DataList.Add(data2);
			}
		}
	}
