	public abstract class ModSingleFileData<T> : IModData where T : ModSingleFileData<T>
	{
		public abstract int Id { get; set; }

		public static string FileName { get; set; }

		public static List<T> Load(string dir)
		{
			Dictionary<string, T> dictionary = null;
			string text = dir + "/" + FileName;
			if (File.Exists(text))
			{
				try
				{
					dictionary = JsonConvert.DeserializeObject<Dictionary<string, T>>(File.ReadAllText(text));
				}
				catch (Exception innerException)
				{
					throw new Exception("加载 " + typeof(T).Name + " 数据失败！文件路径：" + text, innerException);
				}
			}
			if (dictionary == null)
			{
				dictionary = new Dictionary<string, T>();
			}
			foreach (KeyValuePair<string, T> item in dictionary)
			{
				if (item.Key != item.Value.Id.ToString())
				{
					throw new ModException($"{typeof(T)} ID与Key ID不一致");
				}
			}
			return dictionary.Select((KeyValuePair<string, T> dic) => dic.Value).ToList();
		}

		public static void Save(string dir, List<T> dataList)
		{
			string path = dir + "/" + FileName;
			Dictionary<string, T> dictionary = dataList.ToDictionary((T data) => data.Id.ToString(), (T data) => data);
			if (dictionary != null && dictionary.Count > 0)
			{
				string contents = JsonConvert.SerializeObject((object)dictionary, (Formatting)1);
				File.WriteAllText(path, contents);
			}
			else
			{
				File.Delete(path);
			}
		}
	}
