namespace SkySwordKill.NextModEditor.Event
{
	public static class EventCenter
	{
		private static Dictionary<Type, IEventSubject> _events = new Dictionary<Type, IEventSubject>();

		private static IEventSubject GetOrCreateSubject<T>() where T : class, IEventArgs
		{
			if (!_events.TryGetValue(typeof(T), out var value))
			{
				value = new EventSubject<T>();
				_events.Add(typeof(T), value);
			}
			return value;
		}

		public static void Register<T>(Action<T> callback) where T : class, IEventArgs
		{
			GetOrCreateSubject<T>().Register(callback);
		}

		public static void Unregister<T>(Action<T> callback) where T : class, IEventArgs
		{
			GetOrCreateSubject<T>().Unregister(callback);
		}

		public static void Send<T>(T args) where T : class, IEventArgs
		{
			if (_events.TryGetValue(typeof(T), out var value))
			{
				value.Send(args);
			}
		}
	}
	public interface IEventSubject
	{
		void Register<TArgs>(Action<TArgs> callback) where TArgs : class, IEventArgs;

		void Unregister<TArgs>(Action<TArgs> callback) where TArgs : class, IEventArgs;

		void Send<TArgs>(TArgs args) where TArgs : class, IEventArgs;
	}
	public class EventSubject<T> : IEventSubject where T : class, IEventArgs
	{
		private Action<T> action;

		public void Register<TArgs>(Action<TArgs> callback) where TArgs : class, IEventArgs
		{
			action = (Action<T>)Delegate.Combine(action, (Action<T>)callback);
		}

		public void Unregister<TArgs>(Action<TArgs> callback) where TArgs : class, IEventArgs
		{
			action = (Action<T>)Delegate.Remove(action, (Action<T>)callback);
		}

		public void Send<TArgs>(TArgs args) where TArgs : class, IEventArgs
		{
			action?.Invoke(args as T);
		}
	}
	public interface IEventArgs
	{
		object Sender { get; set; }
	}
	public class EventArgs : IEventArgs
	{
		public object Sender { get; set; }
	}
	public class LoadModProjectEventArgs : EventArgs
	{
		public ModProject ModProject { get; set; }
	}
}
