	public class UI_ComNumberBindDataDrawer : GLabel
	{
		public delegate void OnEndMultiDataEdit(bool isParseSuccess, List<int> ids);

		public Controller m_warning;

		public Controller m_grayed;

		public GTextInput m_inContent;

		public GTextField m_txtDesc;

		public GButton m_btnEdit;

		public const string URL = "ui://028qk31hnkvz22";

		public void BindEndEdit(Action<int> endEdit)
		{
			m_inContent.restrict = "[0-9-]";
			Controller ctrl = GetController("warning");
			m_inContent.onFocusOut.Set((EventCallback0)delegate
			{
				if (int.TryParse(m_inContent.text, out var result))
				{
					endEdit?.Invoke(result);
					ctrl.selectedIndex = 0;
				}
				else
				{
					ctrl.selectedIndex = 1;
				}
			});
		}

		public void BindEndMultiEdit(OnEndMultiDataEdit onEndEdit)
		{
			m_inContent.restrict = "[0-9-,，]";
			Controller ctrl = GetController("warning");
			m_inContent.onFocusOut.Set((EventCallback0)delegate
			{
				if (m_inContent.text.Replace("，", ",").TryFormatToListInt(out var list))
				{
					ctrl.selectedIndex = 0;
					onEndEdit?.Invoke(isParseSuccess: true, list);
				}
				else
				{
					ctrl.selectedIndex = 1;
					onEndEdit?.Invoke(isParseSuccess: false, list);
				}
			});
		}

		public void SetEditable(bool value)
		{
			base.grayed = !value;
			m_inContent.editable = value;
			m_inContent.cursor = (value ? "text" : string.Empty);
		}

		public static UI_ComNumberBindDataDrawer CreateInstance()
		{
			return (UI_ComNumberBindDataDrawer)UIPackage.CreateObject("NextCore", "ComNumberBindDataDrawer");
		}

		public override void ConstructFromXML(XML xml)
		{
			base.ConstructFromXML(xml);
			m_warning = GetController("warning");
			m_grayed = GetController("grayed");
			m_inContent = (GTextInput)GetChild("inContent");
			m_txtDesc = (GTextField)GetChild("txtDesc");
			m_btnEdit = (GButton)GetChild("btnEdit");
		}
	}
