	public class UI_ComTableRow : GButton
	{
		public GGraph m_selected;

		public GGraph m_hover;

		public GList m_list;

		public const string URL = "ui://028qk31hnkvz2d";

		public void RefreshItem(IEnumerable<TableInfo> infos, object getData, float frameWidth)
		{
			m_list.RemoveChildrenToPool();
			foreach (TableInfo info in infos)
			{
				GLabel gLabel = m_list.AddItemFromPool().asLabel;
				gLabel.title = info.Getter(getData);
				gLabel.width = info.Width;
			}
			m_list.ResizeToFit();
			base.width = Mathf.Max(m_list.width, frameWidth);
			data = getData;
		}

		public static UI_ComTableRow CreateInstance()
		{
			return (UI_ComTableRow)UIPackage.CreateObject("NextCore", "ComTableRow");
		}

