			m_selected = (GGraph)GetChild("selected");
			m_hover = (GGraph)GetChild("hover");
			m_list = (GList)GetChild("list");
		}
	}
	public class UI_LabelTableGridHeader : GLabel
	{
		private TableInfo _info;

		private Action _onChangeWidth;

		public GGraph m_dragable;

		public const string URL = "ui://028qk31hnkvz2c";

		public void BindTableInfo(TableInfo info, Action onChangeWidth)
		{
			_info = info;
			_onChangeWidth = onChangeWidth;
			m_dragable.draggable = true;
			m_dragable.cursor = "resizeH";
			m_dragable.onDragStart.Set(OnDragSegStart);
		}

		private void OnDragSegStart(EventContext context)
		{
			context.PreventDefault();
			DragDropManager.inst.StartDrag(null, null, null, (int)context.data);
			DragDropManager.inst.dragAgent.onDragMove.Set(OnDragSegMove);
		}

		private void OnDragSegMove(EventContext context)
		{
			//IL_000c: Unknown result type (might be due to invalid IL or missing references)
			//IL_0011: Unknown result type (might be due to invalid IL or missing references)
			float num = context.inputEvent.x - LocalToGlobal(Vector2.zero).x;
			num = (base.width = Mathf.Clamp(num, 24f, 960f));
			_info.Width = num;
			_onChangeWidth();
		}

		public static UI_LabelTableGridHeader CreateInstance()
		{
			return (UI_LabelTableGridHeader)UIPackage.CreateObject("NextCore", "LabelTableGridHeader");
		}

		public override void ConstructFromXML(XML xml)
		{
			base.ConstructFromXML(xml);
			m_dragable = (GGraph)GetChild("dragable");
		}
	}
