namespace SkySwordKill.Next
{
	public class DataGroup<T>
	{
		private const string DEFAULT_GROUP = "Default";

		[JsonProperty("DataDic")]
		public Dictionary<string, Dictionary<string, T>> DataDic { get; set; } = new Dictionary<string, Dictionary<string, T>>();


		public void Set(string key, T value)
		{
			Set("Default", key, value);
		}

		public void Set(string group, string key, T value)
		{
			Dictionary<string, T> group2 = GetGroup(group);
			if (value == null || value.Equals(null))
			{
				if (group2.ContainsKey(key))
				{
					group2.Remove(key);
				}
			}
			else
			{
				group2[key] = value;
			}
		}

		public T Get(string key)
		{
			return Get("Default", key);
		}

		public T Get(string group, string key)
		{
			Dictionary<string, T> group2 = GetGroup(group);
			if (group2.ContainsKey(key))
			{
				return group2[key];
			}
			return default(T);
		}

		public void AddRange(Dictionary<string, T> dic)
		{
			Dictionary<string, T> defaultGroup = GetDefaultGroup();
			foreach (KeyValuePair<string, T> item in dic)
			{
				defaultGroup[item.Key] = item.Value;
			}
		}

		public bool HasGroup(string group)
		{
			return DataDic.ContainsKey(group);
		}

		public Dictionary<string, T> GetDefaultGroup()
		{
			return GetGroup("Default");
		}

		public Dictionary<string, T> GetGroup(string group)
		{
			if (!DataDic.TryGetValue(group, out var value))
			{
				value = new Dictionary<string, T>();
				DataDic[group] = value;
			}
			return value;
		}

		public bool Has(string key)
		{
			return GetDefaultGroup().ContainsKey(key);
		}

		public bool Has(string group, string key)
		{
			if (HasGroup(group))
			{
				return GetGroup(group).ContainsKey(key);
			}
			return false;
		}
	}
	/// <summary>
	/// Next方法快捷入口
	/// </summary>
	public static class Helper
	{
		/// <summary>
		/// 运行指定的剧情事件
		/// </summary>
		/// <param name="eventName"></param>
		/// <param name="callback"></param>
		public static void StartEvent(string eventName, Action callback)
		{
			if (callback != null)
			{
				DialogAnalysis.OnDialogComplete += callback;
			}
			DialogAnalysis.StartDialogEvent(eventName);
		}

		/// <summary>
		/// 运行多行剧情事件脚本
		/// </summary>
		/// <param name="scripts"></param>
		/// <param name="callback"></param>
		public static void RunScript(string scripts, Action callback)
		{
			if (callback != null)
			{
				DialogAnalysis.OnDialogComplete += callback;
			}
			DialogAnalysis.StartTestDialogEvent(scripts);
		}

		/// <summary>
		/// 获取运行时脚本的结果
		/// 不需要添加周围的符号，例如<code>EvaluateScript("GetInt(\"变量1\")")</code>
		/// Lua里调用为CS.SkySwordKill.Next.Helper.EvaluateScript([[GetInt("变量1")]])
		/// </summary>
		/// <param name="script"></param>
		/// <returns></returns>
		public static object EvaluateScript(string script)
		{
			return DialogAnalysis.GetEvaluate(null).Evaluate(script);
		}

		/// <summary>
		/// 获取整数值
		/// </summary>
		/// <param name="key"></param>
		/// <returns></returns>
		public static int GetInt(string key)
		{
			return DialogAnalysis.GetInt(key);
		}

		/// <summary>
		/// 设置整数值
		/// </summary>
		/// <param name="key"></param>
		/// <param name="value"></param>
		public static void SetInt(string key, int value)
		{
			DialogAnalysis.SetInt(key, value);
		}

		/// <summary>
		/// 获取字符串
		/// </summary>
		/// <param name="key"></param>
		/// <returns></returns>
		public static string GetStr(string key)
		{
			return DialogAnalysis.GetStr(key);
		}

		/// <summary>
		/// 设置字符串
		/// </summary>
		/// <param name="key"></param>
		/// <param name="value"></param>
		public static void SetStr(string key, string value)
		{
			DialogAnalysis.SetStr(key, value);
		}

		/// <summary>
		/// 显示一个确认窗口
		/// </summary>
		/// <param name="title"></param>
		/// <param name="content"></param>
		/// <param name="callback"></param>
		public static void ShowConfirmWindow(string title, string content, Action<bool> callback)
		{
			WindowConfirmDialog.CreateDialog(title, content, canCancel: true, delegate
			{
				callback?.Invoke(obj: true);
			}, delegate
			{
				callback?.Invoke(obj: false);
			});
		}

		/// <summary>
		/// 显示一个提示窗口
		/// </summary>
		/// <param name="title"></param>
		/// <param name="content"></param>
		/// <param name="callback"></param>
		public static void ShowTipWindow(string title, string content, Action callback)
		{
			WindowConfirmDialog.CreateDialog(title, content, canCancel: false, delegate
			{
				callback?.Invoke();
			});
		}

		/// <summary>
		/// 显示一个文本输入窗口
		/// </summary>
		/// <param name="title"></param>
		/// <param name="defaultText"></param>
		/// <param name="callback"></param>
		public static void ShowInputStringWindow(string title, string defaultText, Action<string> callback)
		{
			WindowStringInputDialog.CreateDialog(title, defaultText, canCancel: false, delegate(string str)
			{
				callback?.Invoke(str);
			});
		}

		/// <summary>
		/// 显示一个整数输入窗口
		/// </summary>
		/// <param name="title"></param>
		/// <param name="defaultInt"></param>
		/// <param name="callback"></param>
		public static void ShowInputIntWindow(string title, int defaultInt, Action<int> callback)
		{
			WindowIntInputDialog.CreateDialog(title, canCancel: false, defaultInt, delegate(int val)
			{
				callback?.Invoke(val);
			});
		}

		/// <summary>
		/// 打开一个绑定了Lua脚本的FGUI
		/// </summary>
		/// <param name="guiRes"></param>
		/// <param name="guiCom"></param>
		/// <param name="guiScript"></param>
		/// <param name="modal"></param>
		/// <param name="callback"></param>
		public static void OpenGUI(string guiRes, string guiCom, string guiScript, bool modal, Action callback)
		{
			FGUIWindowLua fGUIWindowLua = new FGUIWindowLua(guiRes, guiCom, guiScript);
			fGUIWindowLua.OnCloseCallback = callback;
			fGUIWindowLua.modal = modal;
			fGUIWindowLua.Show();
			fGUIWindowLua.Center();
		}

		public static List<string> ToStrList(LuaTable table)
		{
			List<string> list = new List<string>();
			foreach (object key in table.GetKeys())
			{
				list.Add(table.Get<object, object>(key).ToString());
			}
			return list;
		}

		public static List<int> ToIntList(LuaTable table)
		{
			List<int> list = new List<int>();
			foreach (object key in table.GetKeys())
			{
				list.Add(int.Parse(table.Get<object, object>(key).ToString()));
			}
			return list;
		}

		public static string[] ToStrArray(LuaTable table)
		{
			List<string> list = new List<string>();
			foreach (object key in table.GetKeys())
			{
				list.Add(table.Get<object, object>(key).ToString());
			}
			return list.ToArray();
		}

		public static int[] ToIntArray(LuaTable table)
		{
			List<int> list = new List<int>();
			foreach (object key in table.GetKeys())
			{
				list.Add(int.Parse(table.Get<object, object>(key).ToString()));
			}
			return list.ToArray();
		}
	}
	public class ConfigTarget<T>
	{
		public ConfigEntry<T> configEntry;

		public ConfigDescription configDescription;

		internal ConfigurationManagerAttributes advancedSetting;

		public T Value
		{
			get
			{
				return configEntry.Value;
			}
			set
			{
				configEntry.Value = value;
			}
		}

		public ConfigTarget(ConfigFile config, string section, string key, T defaultValue, string desc)
		{
			//IL_0024: Unknown result type (might be due to invalid IL or missing references)
			//IL_002e: Expected O, but got Unknown
			advancedSetting = new ConfigurationManagerAttributes();
			configDescription = new ConfigDescription(desc, (AcceptableValueBase)null, new object[1] { advancedSetting });
			configEntry = config.Bind<T>(section, key, defaultValue, configDescription);
		}

		public void SetName(string name)
		{
			advancedSetting.DispName = name;
		}

		public void SetDesc(string desc)
		{
			advancedSetting.Description = desc;
		}
	}
	/// <summary>
	/// Class that specifies how a setting should be displayed inside the ConfigurationManager settings window.
	///
	/// Usage:
	/// This class template has to be copied inside the plugin's project and referenced by its code directly.
	/// make a new instance, assign any fields that you want to override, and pass it as a tag for your setting.
	///
	/// If a field is null (default), it will be ignored and won't change how the setting is displayed.
	/// If a field is non-null (you assigned a value to it), it will override default behavior.
	/// </summary>
	///
	/// <example> 
	/// Here's an example of overriding order of settings and marking one of the settings as advanced:
	/// <code>
	/// // Override IsAdvanced and Order
	/// Config.AddSetting("X", "1", 1, new ConfigDescription("", null, new ConfigurationManagerAttributes { IsAdvanced = true, Order = 3 }));
	/// // Override only Order, IsAdvanced stays as the default value assigned by ConfigManager
	/// Config.AddSetting("X", "2", 2, new ConfigDescription("", null, new ConfigurationManagerAttributes { Order = 1 }));
	/// Config.AddSetting("X", "3", 3, new ConfigDescription("", null, new ConfigurationManagerAttributes { Order = 2 }));
	/// </code>
	/// </example>
	///
	/// <remarks> 
	/// You can read more and see examples in the readme at https://github.com/BepInEx/BepInEx.ConfigurationManager
	/// You can optionally remove fields that you won't use from this class, it's the same as leaving them null.
	/// </remarks>
	internal sealed class ConfigurationManagerAttributes
	{
		/// <summary>
		/// Should the setting be shown as a percentage (only use with value range settings).
		/// </summary>
		public bool? ShowRangeAsPercent;

		/// <summary>
		/// Custom setting editor (OnGUI code that replaces the default editor provided by ConfigurationManager).
		/// See below for a deeper explanation. Using a custom drawer will cause many of the other fields to do nothing.
		/// </summary>
		public Action<ConfigEntryBase> CustomDrawer;

		/// <summary>
		/// Show this setting in the settings screen at all? If false, don't show.
		/// </summary>
		public bool? Browsable;

		/// <summary>
		/// Category the setting is under. Null to be directly under the plugin.
		/// </summary>
		public string Category;

		/// <summary>
		/// If set, a "Default" button will be shown next to the setting to allow resetting to default.
		/// </summary>
		public object DefaultValue;

		/// <summary>
		/// Force the "Reset" button to not be displayed, even if a valid DefaultValue is available. 
		/// </summary>
		public bool? HideDefaultButton;

		/// <summary>
		/// Force the setting name to not be displayed. Should only be used with a <see cref="F:SkySwordKill.Next.ConfigurationManagerAttributes.CustomDrawer" /> to get more space.
		/// Can be used together with <see cref="F:SkySwordKill.Next.ConfigurationManagerAttributes.HideDefaultButton" /> to gain even more space.
		/// </summary>
		public bool? HideSettingName;

		/// <summary>
		/// Optional description shown when hovering over the setting.
		/// Not recommended, provide the description when creating the setting instead.
		/// </summary>
		public string Description;

		/// <summary>
		/// Name of the setting.
		/// </summary>
		public string DispName;

		/// <summary>
		/// Order of the setting on the settings list relative to other settings in a category.
		/// 0 by default, higher number is higher on the list.
		/// </summary>
		public int? Order;

		/// <summary>
		/// Only show the value, don't allow editing it.
		/// </summary>
		public bool? ReadOnly;

		/// <summary>
		/// If true, don't show the setting by default. User has to turn on showing advanced settings or search for it.
		/// </summary>
		public bool? IsAdvanced;

		/// <summary>
		/// Custom converter from setting type to string for the built-in editor textboxes.
		/// </summary>
		public Func<object, string> ObjToStr;

		/// <summary>
		/// Custom converter from string to setting type for the built-in editor textboxes.
		/// </summary>
		public Func<string, object> StrToObj;
	}
	public class DllTools
	{
		[DllImport("kernel32.dll", CharSet = CharSet.Auto, SetLastError = true)]
		public static extern bool SetDllDirectory(string lpPathName);

		[DllImport("kernel32.dll", SetLastError = true)]
		public static extern int GetDllDirectory(int bufsize, StringBuilder buf);

		[DllImport("kernel32", CharSet = CharSet.Unicode, SetLastError = true)]
		public static extern IntPtr LoadLibrary(string librayName);

		public static void LoadDllFile(string dllfolder, string libname)
		{
			StringBuilder stringBuilder = new StringBuilder(255);
			GetDllDirectory(stringBuilder.Length, stringBuilder);
			SetDllDirectory(dllfolder);
			LoadLibrary(libname);
			SetDllDirectory(stringBuilder.ToString());
		}
	}
	/// <summary>
	/// This class allow to evaluate a string math or pseudo C# expression
	/// </summary>
	public class ExpressionEvaluator
	{
		protected enum IfBlockEvaluatedState
		{
			NoBlockEvaluated,
			If,
			ElseIf
		}

		protected enum TryBlockEvaluatedState
		{
			NoBlockEvaluated,
			Try,
			Catch
		}

		protected delegate bool ParsingMethodDelegate(string expression, Stack<object> stack, ref int i);

		protected delegate dynamic InternalDelegate(params dynamic[] args);

		protected class ValueTypeNestingTrace
		{
			public object Container { get; set; }

			public MemberInfo Member { get; set; }

			public object Value { get; set; }

			public void AssignValue()
			{
				if (!(Container is ValueTypeNestingTrace valueTypeNestingTrace))
				{
					((dynamic)Member).SetValue(Container, Value);
					return;
				}
				((dynamic)Member).SetValue(valueTypeNestingTrace.Value, Value);
				valueTypeNestingTrace.AssignValue();
			}
		}

