		protected IDictionary<string, Func<ExpressionEvaluator, List<string>, object>> complexStandardFuncsDictionary = new Dictionary<string, Func<ExpressionEvaluator, List<string>, object>>(StringComparer.Ordinal)
		{
			{
				"Array",
				(ExpressionEvaluator self, List<string> args) => args.ConvertAll<object>(self.Evaluate).ToArray()
			},
			{
				"ArrayOfType",
				delegate(ExpressionEvaluator self, List<string> args)
				{
					Array array3 = args.Skip(1).Select(self.Evaluate).ToArray();
					Array array4 = Array.CreateInstance((Type)self.Evaluate(args[0]), array3.Length);
					Array.Copy(array3, array4, array3.Length);
					return array4;
				}
			},
			{
				"Avg",
				(ExpressionEvaluator self, List<string> args) => args.ConvertAll((string arg) => Convert.ToDouble(self.Evaluate(arg))).Sum() / (double)args.Count
			},
			{
				"default",
				(ExpressionEvaluator self, List<string> args) => (self.Evaluate(args[0]) is ClassOrEnumType classOrEnumType2) ? Activator.CreateInstance(classOrEnumType2.Type) : null
			},
			{
				"in",
				(ExpressionEvaluator self, List<string> args) => args.Skip(1).ToList().ConvertAll<object>(self.Evaluate)
					.Contains(self.Evaluate(args[0]))
			},
			{
				"List",
				(ExpressionEvaluator self, List<string> args) => args.ConvertAll<object>(self.Evaluate)
			},
			{
				"ListOfType",
				delegate(ExpressionEvaluator self, List<string> args)
				{
					Type type2 = (Type)self.Evaluate(args[0]);
					Array array = args.Skip(1).Select(self.Evaluate).ToArray();
					Array array2 = Array.CreateInstance(type2, array.Length);
					Array.Copy(array, array2, array.Length);
					Type type3 = typeof(List<>).MakeGenericType(type2);
					object obj2 = Activator.CreateInstance(type3);
					type3.GetMethod("AddRange").Invoke(obj2, new object[1] { array2 });
					return obj2;
				}
			},
			{
				"Max",
				(ExpressionEvaluator self, List<string> args) => args.ConvertAll((string arg) => Convert.ToDouble(self.Evaluate(arg))).Max()
			},
			{
				"Min",
				(ExpressionEvaluator self, List<string> args) => args.ConvertAll((string arg) => Convert.ToDouble(self.Evaluate(arg))).Min()
			},
			{
				"new",
				delegate(ExpressionEvaluator self, List<string> args)
				{
					List<object> list = args.ConvertAll<object>(self.Evaluate);
					return (!(list[0] is ClassOrEnumType classOrEnumType)) ? null : Activator.CreateInstance(classOrEnumType.Type, list.Skip(1).ToArray());
				}
			},
			{
				"Round",
				delegate(ExpressionEvaluator self, List<string> args)
				{
					if (args.Count == 3)
					{
						return Math.Round(Convert.ToDouble(self.Evaluate(args[0])), Convert.ToInt32(self.Evaluate(args[1])), (MidpointRounding)self.Evaluate(args[2]));
					}
					if (args.Count == 2)
					{
						object obj = self.Evaluate(args[1]);
						if (obj is MidpointRounding mode)
						{
							return Math.Round(Convert.ToDouble(self.Evaluate(args[0])), mode);
						}
						return Math.Round(Convert.ToDouble(self.Evaluate(args[0])), Convert.ToInt32(obj));
					}
					if (args.Count == 1)
					{
						return Math.Round(Convert.ToDouble(self.Evaluate(args[0])));
					}
					throw new ArgumentException();
				}
			},
			{
				"Sign",
				(ExpressionEvaluator self, List<string> args) => Math.Sign(Convert.ToDouble(self.Evaluate(args[0])))
			},
			{
				"sizeof",
				delegate(ExpressionEvaluator self, List<string> args)
				{
					Type type = ((ClassOrEnumType)self.Evaluate(args[0])).Type;
					if (type == typeof(bool))
					{
						return 1;
					}
					return (type == typeof(char)) ? ((object)2) : ((object)Marshal.SizeOf(type));
				}
			},
			{
				"typeof",
				(ExpressionEvaluator self, List<string> args) => ((ClassOrEnumType)self.Evaluate(args[0])).Type
			}
		};

