		protected string InstanceCreationWithNewKeywordRegexPattern => "^new(?>\\s*)((?<isAnonymous>[{{])|((?<name>[\\p{L}_][\\p{L}_0-9" + (OptionInlineNamespacesEvaluationActive ? "\\." : string.Empty) + "]*)(?>\\s*)(?<isgeneric>[<](?>[^<>]+|(?<gentag>[<])|(?<-gentag>[>]))*(?(gentag)(?!))[>])?(?>\\s*)((?<isfunction>[(])|(?<isArray>\\[)|(?<isInit>[{{]))?))";

		protected string CastRegexPattern => "^\\((?>\\s*)(?<typeName>[\\p{L}_][\\p{L}_0-9" + (OptionInlineNamespacesEvaluationActive ? "\\." : string.Empty) + "\\[\\]<>]*[?]?)(?>\\s*)\\)";

