		/// </summary>
		public event EventHandler<ParameterCastEvaluationEventArg> EvaluateParameterCast;

		protected static object IndexingOperatorFunc(dynamic left, dynamic right)
		{
			if (left is NullConditionalNullValue)
			{
				return left;
			}
			if (left is BubbleExceptionContainer)
			{
				return left;
			}
			Type type = ((object)left).GetType();
			if (left is IDictionary<string, object> dictionary)
			{
				return dictionary[right];
			}
			MethodInfo method = type.GetMethod("Item", new Type[1] { ((object)right).GetType() });
			if ((object)method == null)
			{
				return left[right];
			}
			return method.Invoke(left, new object[1] { right });
		}

