		/// </summary>
		/// <param name="expression">the math or pseudo C# expression to evaluate</param>
		/// <returns>The result of the operation if syntax is correct</returns>
		public object Evaluate(string expression)
		{
			expression = expression.Trim();
			Stack<object> stack = new Stack<object>();
			evaluationStackCount++;
			try
			{
				ExpressionEvaluationEventArg expressionEvaluationEventArg = new ExpressionEvaluationEventArg(expression, this);
				this.ExpressionEvaluating?.Invoke(this, expressionEvaluationEventArg);
				expression = expressionEvaluationEventArg.Expression;
				object obj;
				if (expressionEvaluationEventArg.HasValue)
				{
					obj = expressionEvaluationEventArg.Value;
				}
				else
				{
					if (GetLambdaExpression(expression, stack))
					{
						return stack.Pop();
					}
					int i;
					for (i = 0; i < expression.Length; i++)
					{
						if (!ParsingMethods.Any((ParsingMethodDelegate parsingMethod) => parsingMethod(expression, stack, ref i)))
						{
