							if (!text.Trim().Equals(string.Empty))
							{
								throw new ExpressionEvaluatorSyntaxErrorException($"Invalid character [{(int)text[0]}:{text}]");
							}
						}
					}
					obj = ProcessStack(stack);
					expressionEvaluationEventArg = new ExpressionEvaluationEventArg(expression, this, obj);
					this.ExpressionEvaluated?.Invoke(this, expressionEvaluationEventArg);
					if (expressionEvaluationEventArg.HasValue)
					{
						obj = expressionEvaluationEventArg.Value;
					}
				}
				return obj;
			}
			finally
			{
				evaluationStackCount--;
			}
		}

		protected virtual bool EvaluateCast(string expression, Stack<object> stack, ref int i)
