					{
						throw new ExpressionEvaluatorSyntaxErrorException("Empty literal character is not valid");
					}
					stack.Push(expression[i]);
					i++;
				}
				if (expression.Substring(i, 1).Equals("'"))
				{
					return true;
				}
				throw new ExpressionEvaluatorSyntaxErrorException("Too much characters in the literal character");
			}
			return false;
		}

		protected virtual bool EvaluateOperators(string expression, Stack<object> stack, ref int i)
		{
			string pattern = "^(" + string.Join("|", operatorsDictionary.Keys.OrderByDescending((string key) => key.Length).Select(Regex.Escape)) + ")";
			Match match = Regex.Match(expression.Substring(i), pattern, (!optionCaseSensitiveEvaluationActive) ? RegexOptions.IgnoreCase : RegexOptions.None);
			if (match.Success)
			{
				string value = match.Value;
				if (value.Equals("+") && (stack.Count == 0 || (stack.Peek() is ExpressionOperator item && !LeftOperandOnlyOperatorsEvaluationDictionary.Contains(item))))
				{
					stack.Push(ExpressionOperator.UnaryPlus);
				}
				else if (value.Equals("-") && (stack.Count == 0 || (stack.Peek() is ExpressionOperator item2 && !LeftOperandOnlyOperatorsEvaluationDictionary.Contains(item2))))
				{
					stack.Push(ExpressionOperator.UnaryMinus);
				}
				else
				{
					stack.Push(operatorsDictionary[value]);
				}
				i += value.Length - 1;
				return true;
			}
			return false;
		}

		protected virtual bool EvaluateTernaryConditionalOperator(string expression, Stack<object> stack, ref int i)
		{
			if (expression.Substring(i, 1).Equals("?"))
			{
				bool flag = (bool)ProcessStack(stack);
				string text = expression.Substring(i + 1);
				for (int j = 0; j < text.Length; j++)
				{
					string text2 = text.Substring(j, 1);
					Match match = stringBeginningRegex.Match(text.Substring(j));
					if (match.Success)
					{
						string text3 = match.Value + GetCodeUntilEndOfString(text.Substring(j + match.Length), match);
						j += text3.Length - 1;
					}
					else if (text2.Equals("("))
					{
						j++;
						GetExpressionsBetweenParenthesesOrOtherImbricableBrackets(text, ref j, checkSeparator: false);
					}
					else if (text2.Equals(":"))
					{
						stack.Clear();
						stack.Push(flag ? Evaluate(text.Substring(0, j)) : Evaluate(text.Substring(j + 1)));
						i = expression.Length;
						return true;
					}
				}
			}
			return false;
		}

		protected virtual bool EvaluateParenthis(string expression, Stack<object> stack, ref int i)
		{
			string text = expression.Substring(i, 1);
			if (text.Equals(")"))
			{
				throw new Exception("To much ')' characters are defined in expression : [" + expression + "] : no corresponding '(' fund.");
			}
			if (text.Equals("("))
			{
				i++;
				if (stack.Count > 0 && stack.Peek() is InternalDelegate)
				{
					List<string> expressionsBetweenParenthesesOrOtherImbricableBrackets = GetExpressionsBetweenParenthesesOrOtherImbricableBrackets(expression, ref i, checkSeparator: true);
					InternalDelegate internalDelegate = stack.Pop() as InternalDelegate;
					stack.Push(internalDelegate(expressionsBetweenParenthesesOrOtherImbricableBrackets.ConvertAll<object>(Evaluate).ToArray()));
				}
				else
				{
					CorrectStackWithUnaryPlusOrMinusBeforeParenthisIfNecessary(stack);
					List<string> expressionsBetweenParenthesesOrOtherImbricableBrackets2 = GetExpressionsBetweenParenthesesOrOtherImbricableBrackets(expression, ref i, checkSeparator: false);
					stack.Push(Evaluate(expressionsBetweenParenthesesOrOtherImbricableBrackets2[0]));
				}
				return true;
			}
			return false;
		}

		protected virtual void CorrectStackWithUnaryPlusOrMinusBeforeParenthisIfNecessary(Stack<object> stack)
		{
			if (stack.Count > 0 && stack.Peek() is ExpressionOperator expressionOperator && (expressionOperator == ExpressionOperator.Plus || expressionOperator == ExpressionOperator.Minus))
			{
				stack.Pop();
				if (stack.Count == 0 || stack.Peek() is ExpressionOperator)
				{
					stack.Push((expressionOperator == ExpressionOperator.Plus) ? ExpressionOperator.UnaryPlus : ExpressionOperator.UnaryMinus);
				}
				else
				{
					stack.Push(expressionOperator);
				}
			}
		}

		protected virtual bool EvaluateIndexing(string expression, Stack<object> stack, ref int i)
		{
			if (!OptionIndexingActive)
			{
				return false;
			}
			Match match = indexingBeginningRegex.Match(expression.Substring(i));
			if (match.Success)
			{
				StringBuilder stringBuilder = new StringBuilder();
				i += match.Length;
				int num = 1;
				while (i < expression.Length)
				{
					Match match2 = stringBeginningRegex.Match(expression.Substring(i));
					if (match2.Success)
					{
						string text = match2.Value + GetCodeUntilEndOfString(expression.Substring(i + match2.Length), match2);
						stringBuilder.Append(text);
						i += text.Length - 1;
					}
					else
					{
						string text2 = expression.Substring(i, 1);
						if (text2.Equals("["))
						{
							num++;
						}
						if (text2.Equals("]"))
						{
							num--;
							if (num == 0)
							{
								break;
							}
						}
						stringBuilder.Append(text2);
					}
					i++;
				}
				if (num > 0)
				{
					string arg = ((num == 1) ? "is" : "are");
					throw new Exception($"{num} ']' character {arg} missing in expression : [{expression}]");
				}
				dynamic left = stack.Pop();
				if (left is NullConditionalNullValue)
				{
					stack.Push(left);
					return true;
				}
				if (left is BubbleExceptionContainer)
				{
					stack.Push(left);
					return true;
				}
				IndexingPreEvaluationEventArg indexingPreEvaluationEventArg = new IndexingPreEvaluationEventArg(stringBuilder.ToString(), this, left);
				this.PreEvaluateIndexing?.Invoke(this, indexingPreEvaluationEventArg);
				if (indexingPreEvaluationEventArg.CancelEvaluation)
				{
					throw new ExpressionEvaluatorSyntaxErrorException($"[{(object)left.GetType()}] can not be indexed.");
				}
				if (indexingPreEvaluationEventArg.HasValue)
				{
					stack.Push(indexingPreEvaluationEventArg.Value);
				}
				else
				{
					dynamic right = Evaluate(stringBuilder.ToString());
					ExpressionOperator op = ((match.Length == 2) ? ExpressionOperator.IndexingWithNullConditional : ExpressionOperator.Indexing);
					if (OptionForceIntegerNumbersEvaluationsAsDoubleByDefault && right is double && Regex.IsMatch(stringBuilder.ToString(), "^\\d+$"))
					{
						right = (int)right;
					}
					Match match3 = null;
					dynamic val = null;
					if (OptionIndexingAssignationActive && (match3 = assignationOrPostFixOperatorRegex.Match(expression.Substring(i + 1))).Success)
					{
						i += match3.Length + 1;
						bool success = match3.Groups["postfixOperator"].Success;
						string text3 = (success ? "++ or -- operator" : "an assignation");
						if (stack.Count > 1)
						{
							throw new ExpressionEvaluatorSyntaxErrorException("The left part of " + text3 + " must be a variable, a property or an indexer.");
						}
						if (op == ExpressionOperator.IndexingWithNullConditional)
						{
							throw new ExpressionEvaluatorSyntaxErrorException("Null conditional is not usable left to " + text3);
						}
						if (success)
						{
							if (left is IDictionary<string, object> dictionary)
							{
								dynamic val4;
								if (!match3.Groups["postfixOperator"].Value.Equals("++"))
								{
									IDictionary<string, object> dictionary2 = dictionary;
									dynamic val2 = right;
									dynamic val3 = dictionary2[val2];
									dictionary2[val2] = --val3;
									val4 = val3;
								}
								else
								{
									IDictionary<string, object> dictionary2 = dictionary;
									dynamic val3 = right;
									dynamic val2 = dictionary2[val3];
									dictionary2[val3] = ++val2;
									val4 = val2;
								}
								val = val4;
							}
							else
							{
								dynamic val6;
								if (!match3.Groups["postfixOperator"].Value.Equals("++"))
								{
									dynamic val2 = left;
									dynamic val3 = right;
									dynamic val5 = val2[val3];
									val2[val3] = --val5;
									val6 = val5;
								}
								else
								{
									dynamic val5 = left;
									dynamic val3 = right;
									dynamic val2 = val5[val3];
									val5[val3] = ++val2;
									val6 = val2;
								}
								val = val6;
							}
						}
						else
						{
							val = ManageKindOfAssignation(expression, ref i, match3, () => ((Func<object, object, object>)OperatorsEvaluations[0][op])(left, right));
							if (left is IDictionary<string, object> dictionary3)
							{
								dictionary3[right] = val;
							}
							else
							{
								left[right] = val;
							}
							stack.Clear();
						}
					}
					else
					{
						val = ((Func<object, object, object>)OperatorsEvaluations[0][op])(left, right);
					}
					stack.Push(val);
				}
				return true;
			}
			return false;
		}

		protected virtual bool EvaluateString(string expression, Stack<object> stack, ref int i)
		{
			if (!OptionStringEvaluationActive)
			{
				return false;
			}
			Match match = stringBeginningRegex.Match(expression.Substring(i));
			if (match.Success)
			{
				bool success = match.Groups["escaped"].Success;
				bool success2 = match.Groups["interpolated"].Success;
				i += match.Length;
				Regex regex = new Regex("^[^" + (success ? "" : "\\\\") + (success2 ? "{}" : "") + "\"]*");
				bool flag = false;
				StringBuilder stringBuilder = new StringBuilder();
				while (!flag && i < expression.Length)
				{
					Match match2 = regex.Match(expression.Substring(i, expression.Length - i));
					stringBuilder.Append(match2.Value);
					i += match2.Length;
					if (expression.Substring(i)[0] == '"')
					{
						flag = true;
						stack.Push(stringBuilder.ToString());
					}
					else if (expression.Substring(i)[0] == '{')
					{
						i++;
						if (expression.Substring(i)[0] == '{')
						{
							stringBuilder.Append("{");
							i++;
							continue;
						}
						StringBuilder stringBuilder2 = new StringBuilder();
						int num = 1;
						while (i < expression.Length)
						{
							if (i + 3 <= expression.Length && expression.Substring(i, 3).Equals("'\"'"))
							{
								stringBuilder2.Append("'\"'");
								i += 2;
							}
							else
							{
								Match match3 = stringBeginningRegex.Match(expression.Substring(i));
								if (match3.Success)
								{
									string text = match3.Value + GetCodeUntilEndOfString(expression.Substring(i + match3.Length), match3);
									stringBuilder2.Append(text);
									i += text.Length - 1;
								}
								else
								{
									string text2 = expression.Substring(i, 1);
									if (text2.Equals("{"))
									{
										num++;
									}
									if (text2.Equals("}"))
									{
										num--;
										i++;
										if (num == 0)
										{
											break;
										}
									}
									stringBuilder2.Append(text2);
								}
							}
							i++;
						}
						if (num > 0)
						{
							string arg = ((num == 1) ? "is" : "are");
							throw new Exception($"{num} '}}' character {arg} missing in expression : [{expression}]");
						}
						stringBuilder.Append(Evaluate(stringBuilder2.ToString()));
					}
					else if (expression.Substring(i, expression.Length - i)[0] == '}')
					{
						i++;
						if (expression.Substring(i, expression.Length - i)[0] != '}')
						{
							throw new ExpressionEvaluatorSyntaxErrorException("A character '}' must be escaped in a interpolated string.");
						}
						stringBuilder.Append("}");
						i++;
					}
					else if (expression.Substring(i, expression.Length - i)[0] == '\\')
					{
						i++;
						if (!stringEscapedCharDict.TryGetValue(expression.Substring(i, expression.Length - i)[0], out var value))
						{
							throw new ExpressionEvaluatorSyntaxErrorException("There is no corresponding escaped character for \\" + expression.Substring(i, 1));
						}
						stringBuilder.Append(value);
						i++;
					}
				}
				if (!flag)
				{
					throw new ExpressionEvaluatorSyntaxErrorException("A \" character is missing.");
				}
				return true;
			}
			return false;
		}

		protected virtual object ProcessStack(Stack<object> stack)
		{
			if (stack.Count == 0)
			{
				throw new ExpressionEvaluatorSyntaxErrorException("Empty expression or no token found");
			}
			List<object> list = (from e in stack
				select (!(e is ValueTypeNestingTrace valueTypeNestingTrace)) ? e : valueTypeNestingTrace.Value into e
				select (!(e is SubExpression subExpression)) ? e : Evaluate(subExpression.Expression) into e
				select (!(e is NullConditionalNullValue)) ? e : null).ToList();
			OperatorsEvaluations.ToList().ForEach(delegate(IDictionary<ExpressionOperator, Func<dynamic, dynamic, object>> operatorEvalutationsDict)
			{
				for (int parentIndex2 = list.Count - 1; parentIndex2 >= 0; parentIndex2--)
				{
					for (int k = 0; k < operatorEvalutationsDict.Keys.ToList().Count; k++)
					{
						ExpressionOperator expressionOperator = operatorEvalutationsDict.Keys.ToList()[k];
						if (list[parentIndex2] as ExpressionOperator == expressionOperator)
						{
							if (RightOperandOnlyOperatorsEvaluationDictionary.Contains(expressionOperator))
							{
								try
								{
									EvaluateFirstNextUnaryOp(parentIndex2 - 1, ref parentIndex2);
									list[parentIndex2] = (object)((Func<object, object, object>)operatorEvalutationsDict[expressionOperator])(null, (dynamic)list[parentIndex2 - 1]);
								}
								catch (Exception exception)
								{
									object obj3 = list[parentIndex2 - 1];
									if (obj3 is BubbleExceptionContainer)
									{
										list[parentIndex2] = obj3;
									}
									else
									{
										list[parentIndex2] = new BubbleExceptionContainer
										{
											Exception = exception
										};
									}
								}
								list.RemoveAt(parentIndex2 - 1);
							}
							else if (LeftOperandOnlyOperatorsEvaluationDictionary.Contains(expressionOperator))
							{
								try
								{
									EvaluateFirstPreviousUnaryOp(parentIndex2 + 1);
									list[parentIndex2] = (object)((Func<object, object, object>)operatorEvalutationsDict[expressionOperator])((dynamic)list[parentIndex2 + 1], null);
								}
								catch (Exception exception2)
								{
									object obj4 = list[parentIndex2 + 1];
									if (obj4 is BubbleExceptionContainer)
									{
										list[parentIndex2] = obj4;
									}
									else
									{
										list[parentIndex2] = new BubbleExceptionContainer
										{
											Exception = exception2
										};
									}
								}
								list.RemoveAt(parentIndex2 + 1);
							}
							else
							{
								try
								{
									list[parentIndex2] = (object)((Func<object, object, object>)operatorEvalutationsDict[expressionOperator])((dynamic)list[parentIndex2 + 1], (dynamic)list[parentIndex2 - 1]);
								}
								catch (Exception exception3)
								{
									object obj5 = list[parentIndex2 + 1];
									object obj6 = list[parentIndex2 - 1];
									if (obj5 is BubbleExceptionContainer)
									{
										list[parentIndex2] = obj5;
									}
									else if (obj6 is BubbleExceptionContainer)
									{
										list[parentIndex2] = obj6;
									}
									else
									{
										list[parentIndex2] = new BubbleExceptionContainer
										{
											Exception = exception3
										};
									}
								}
								list.RemoveAt(parentIndex2 + 1);
								list.RemoveAt(parentIndex2 - 1);
								parentIndex2--;
							}
							break;
						}
					}
				}
			});
			stack.Clear();
			for (int i = 0; i < list.Count; i++)
			{
				stack.Push(list[i]);
			}
			if (stack.Count > 1)
			{
				foreach (object item in stack)
				{
					if (item is BubbleExceptionContainer bubbleExceptionContainer)
					{
						throw bubbleExceptionContainer.Exception;
					}
				}
				throw new ExpressionEvaluatorSyntaxErrorException("Syntax error. Check that no operator is missing");
			}
			if (evaluationStackCount == 1 && stack.Peek() is BubbleExceptionContainer bubbleExceptionContainer2)
			{
				throw bubbleExceptionContainer2.Exception;
			}
			return stack.Pop();
			void EvaluateFirstNextUnaryOp(int j, ref int parentIndex)
			{
				if (j > 0)
				{
					object obj2 = list[j];
					ExpressionOperator nextOp = obj2 as ExpressionOperator;
					if (nextOp != null && RightOperandOnlyOperatorsEvaluationDictionary.Contains(nextOp))
					{
						EvaluateFirstNextUnaryOp(j - 1, ref j);
						List<object> list3 = list;
						int index = j;
						IDictionary<ExpressionOperator, Func<object, object, object>> dictionary2 = OperatorsEvaluations.FirstOrDefault((IDictionary<ExpressionOperator, Func<dynamic, dynamic, object>> od) => od.ContainsKey(nextOp));
						list3[index] = (object)((dictionary2 != null) ? dictionary2[nextOp](null, (dynamic)list[j - 1]) : null);
						list.RemoveAt(j - 1);
						parentIndex = j;
					}
				}
			}
			void EvaluateFirstPreviousUnaryOp(int j)
			{
				if (j < list.Count - 1)
				{
					object obj = list[j];
					ExpressionOperator previousOp = obj as ExpressionOperator;
					if (previousOp != null && LeftOperandOnlyOperatorsEvaluationDictionary.Contains(previousOp))
					{
						EvaluateFirstPreviousUnaryOp(j + 1);
						List<object> list2 = list;
						IDictionary<ExpressionOperator, Func<object, object, object>> dictionary = OperatorsEvaluations.FirstOrDefault((IDictionary<ExpressionOperator, Func<dynamic, dynamic, object>> od) => od.ContainsKey(previousOp));
						list2[j] = (object)((dictionary != null) ? dictionary[previousOp]((dynamic)list[j + 1], null) : null);
						list.RemoveAt(j + 1);
					}
				}
			}
		}

		/// <summary>
		/// remove all line and blocks comments of the specified C# script. (Manage in strings comment syntax ignore)
		/// based on https://stackoverflow.com/questions/3524317/regex-to-strip-line-comments-from-c-sharp/3524689#3524689
		/// </summary>
		/// <param name="scriptWithComments">The C# code with comments to remove</param>
		/// <returns>The same C# code without comments</returns>
		public string RemoveComments(string scriptWithComments)
		{
			return removeCommentsRegex.Replace(scriptWithComments, delegate(Match match)
			{
				if (match.Value.StartsWith("/"))
				{
					Match match2 = newLineCharsRegex.Match(match.Value);
					if (match.Value.StartsWith("/*") && match2.Success)
					{
						return match2.Value;
					}
					return " ";
				}
				return match.Value;
			});
		}

		protected virtual object ManageKindOfAssignation(string expression, ref int index, Match match, Func<object> getCurrentValue, Stack<object> stack = null)
		{
			if (stack != null && stack.Count > 1)
			{
				throw new ExpressionEvaluatorSyntaxErrorException("The left part of an assignation must be a variable, a property or an indexer.");
			}
			string text = expression.Substring(index);
			index = expression.Length;
			if (text.Trim().Equals(string.Empty))
			{
				throw new ExpressionEvaluatorSyntaxErrorException("Right part is missing in assignation");
			}
			object obj;
			if (match.Groups["assignmentPrefix"].Success)
			{
				ExpressionOperator prefixOp = operatorsDictionary[match.Groups["assignmentPrefix"].Value];
				obj = OperatorsEvaluations.ToList().Find((IDictionary<ExpressionOperator, Func<dynamic, dynamic, object>> dict) => dict.ContainsKey(prefixOp))[prefixOp](getCurrentValue(), Evaluate(text));
			}
			else
			{
				obj = Evaluate(text);
			}
			if (obj is BubbleExceptionContainer bubbleExceptionContainer)
			{
				throw bubbleExceptionContainer.Exception;
			}
			if (stack != null)
			{
				stack.Clear();
				stack.Push(obj);
			}
			return obj;
		}

		protected virtual void AssignVariable(string varName, object value)
		{
			if (Variables.ContainsKey(varName) && Variables[varName] is StronglyTypedVariable stronglyTypedVariable)
			{
				if (value == null && stronglyTypedVariable.Type.IsValueType && Nullable.GetUnderlyingType(stronglyTypedVariable.Type) == null)
				{
					throw new ExpressionEvaluatorSyntaxErrorException($"Can not cast null to {stronglyTypedVariable.Type} because it's not a nullable valueType");
				}
				Type type = value?.GetType();
				if (!(type == null) && !stronglyTypedVariable.Type.IsAssignableFrom(type))
				{
					throw new InvalidCastException($"A object of type {type} can not be cast implicitely in {stronglyTypedVariable.Type}");
				}
				stronglyTypedVariable.Value = value;
			}
			else
			{
				Variables[varName] = value;
			}
		}

		protected virtual object GetDefaultValueOfType(Type type)
		{
			if (!type.IsValueType)
			{
				return null;
			}
			return Activator.CreateInstance(type);
		}

		protected virtual bool GetLambdaExpression(string expression, Stack<object> stack)
		{
			Match lambdaExpressionMatch = lambdaExpressionRegex.Match(expression);
			if (lambdaExpressionMatch.Success)
			{
				List<string> argsNames = lambdaArgRegex.Matches(lambdaExpressionMatch.Groups["args"].Value).Cast<Match>().ToList()
					.ConvertAll((Match argMatch) => argMatch.Value);
				bool inScriptAtDeclaration = inScript;
				stack.Push((InternalDelegate)delegate(object[] args)
				{
					Dictionary<string, object> dictionary = new Dictionary<string, object>(variables);
					for (int i = 0; i < argsNames.Count || i < args.Length; i++)
					{
						dictionary[argsNames[i]] = args[i];
					}
					IDictionary<string, object> dictionary2 = variables;
					Variables = dictionary;
					string text = lambdaExpressionMatch.Groups["expression"].Value.Trim();
					object obj = null;
					obj = ((!(OptionCanDeclareMultiExpressionsLambdaInSimpleExpressionEvaluate || inScriptAtDeclaration) || !text.StartsWith("{") || !text.EndsWith("}")) ? Evaluate(lambdaExpressionMatch.Groups["expression"].Value) : ScriptEvaluate(text.Substring(1, text.Length - 2)));
					variables = dictionary2;
					return (dynamic)obj;
				});
				return true;
			}
			return false;
		}

		protected virtual MethodInfo GetRealMethod(ref Type type, ref object obj, string func, BindingFlags flag, List<object> args, string genericsTypes, Type[] inferedGenericsTypes, List<ArgKeywordsEncaps> argsWithKeywords, bool testForExtention = false)
		{
			MethodInfo methodInfo = null;
			List<object> modifiedArgs = new List<object>(args);
			if (OptionFluidPrefixingActive && (func.StartsWith("Fluid", StringComparisonForCasing) || func.StartsWith("Fluent", StringComparisonForCasing)))
			{
				methodInfo = GetRealMethod(ref type, ref obj, func.Substring(func.StartsWith("Fluid", StringComparisonForCasing) ? 5 : 6), flag, modifiedArgs, genericsTypes, inferedGenericsTypes, argsWithKeywords, testForExtention);
				if (methodInfo != null)
				{
					if (methodInfo.ReturnType == typeof(void))
					{
						obj = new DelegateEncaps(obj, methodInfo);
						methodInfo = typeof(DelegateEncaps).GetMethod("CallFluidMethod");
						args.Clear();
						args.Add(modifiedArgs.ToArray());
					}
					return methodInfo;
				}
			}
			List<MethodInfo> list = (from m in type.GetMethods(flag).Where(methodByNameFilter)
				orderby m.GetParameters().Length descending
				select m).ToList();
			try
			{
				if (list.Count > 1 && type == typeof(Enumerable) && args.Count == 2 && args[1] is InternalDelegate internalDelegate && args[0] is IEnumerable enumerable)
