						stringBuilder.Append(match.Value);
						stringBuilder.Append(codeUntilEndOfStringInterpolation);
						GetCodeUntilEndOfString(subExpr.Substring(match.Length + codeUntilEndOfStringInterpolation.Length), stringBeginningMatch, ref stringBuilder);
					}
				}
				else
				{
					stringBuilder.Append(subExpr);
				}
			}
			else
			{
				stringBuilder.Append(subExpr);
			}
		}

		protected virtual string GetCodeUntilEndOfStringInterpolation(string subExpr)
		{
