		private void Awake()
		{
			Init();
		}

		private void Start()
		{
			AfterInit();
		}

		private void Init()
		{
			//IL_00ec: Unknown result type (might be due to invalid IL or missing references)
			I = this;
			InitDir();
			LanguageDir = ((BaseUnityPlugin)this).Config.CreateConfig("Main.Language", "Plugin Language", "");
			WinKeyCode = ((BaseUnityPlugin)this).Config.CreateConfig<KeyCode>("Main.OpenKeyCode", "Window HotKey", (KeyCode)285);
			DebugMode = ((BaseUnityPlugin)this).Config.CreateConfig("Debug.Mode", "Debug Mode", defaultValue: false);
			_resourcesManager = ((Component)this).gameObject.AddComponent<ResourcesManager>();
			_resourcesManager.Init();
			_luaManager = ((Component)this).gameObject.AddComponent<LuaManager>();
			_luaManager.Init();
			_fguiManager = ((Component)this).gameObject.AddComponent<FGUIManager>();
			_fguiManager.Init();
			_fPatchManager = ((Component)this).gameObject.AddComponent<FPatchManager>();
			_fPatchManager.Init();
			new Harmony("skyswordkill.plugin.Next").PatchAll();
			Assembly.LoadFrom(Utility.CombinePaths(new string[2] { PathLibraryDir.Value, "Microsoft.CSharp.dll" }));
			NextLanguage.InitLanguage();
			LoadDefaultLanguage();
			LoadModSetting();
			SceneManager.sceneLoaded += OnSceneLoaded;
			RegisterUpdateEvent(OnPanelUpdate);
			RegisterSceneLoadEvent("MainMenu", delegate
			{
				ModManager.CheckModLoadState();
			});
		}

		private void AfterInit()
		{
			DialogAnalysis.Init();
			ModSettingDefinitionListConverter.Init();
			Updater.CheckVersion();
			_isWinOpen = false;
		}

		private void InitDir()
		{
			string dllPath = Directory.GetParent(typeof(Main).Assembly.Location).FullName;
			PathLocalModsDir = new Lazy<string>(() => Paths.GameRootPath + "\\本地Mod测试");
			PathLibraryDir = new Lazy<string>(() => Utility.CombinePaths(new string[2] { dllPath, "NextLib" }));
			PathConfigDir = new Lazy<string>(() => Utility.CombinePaths(new string[2] { dllPath, "NextConfig" }));
			PathExportOutputDir = new Lazy<string>(() => Utility.CombinePaths(new string[2] { dllPath, "../OutPut" }));
			PathBaseDataDir = new Lazy<string>(() => Utility.CombinePaths(new string[2] { PathExportOutputDir.Value, "Data" }));
			PathBaseFungusDataDir = new Lazy<string>(() => Utility.CombinePaths(new string[2] { PathExportOutputDir.Value, "Fungus" }));
			PathLuaLibDir = new Lazy<string>(() => Utility.CombinePaths(new string[2] { PathLibraryDir.Value, "Lua" }));
			PathInnerAbDir = new Lazy<string>(() => Utility.CombinePaths(new string[2] { PathLibraryDir.Value, "AB" }));
			PathLanguageDir = new Lazy<string>(() => Utility.CombinePaths(new string[2] { PathConfigDir.Value, "language" }));
			PathModSettingFile = new Lazy<string>(() => Utility.CombinePaths(new string[2]
			{
				Paths.GameRootPath,
				"nextModSetting.json"
			}));
			PathInnerAssetDir = new Lazy<string>(() => Utility.CombinePaths(new string[2] { dllPath, "NextAssets" }));
			PathTemplateDir = new Lazy<string>(() => Utility.CombinePaths(new string[2] { dllPath, "Template" }));
		}

		private void LoadDefaultLanguage()
		{
			if (string.IsNullOrEmpty(LanguageDir.Value) || !NextLanguage.TryGetLanguageByDir(LanguageDir.Value, out var language))
			{
				SelectLanguage(NextLanguage.Languages.FirstOrDefault());
				isSelectedLanguage = true;
			}
			else
			{
				SelectLanguage(language);
			}
			LanguageDir.SetName("Config.Main.LanguageID.Name".I18N());
			LanguageDir.SetDesc("Config.Main.LanguageID.Desc".I18N());
			WinKeyCode.SetName("Config.Main.OpenKeyCode.Name".I18N());
			WinKeyCode.SetDesc("Config.Main.OpenKeyCode.Desc".I18N());
			DebugMode.SetName("Config.Debug.Mode.Name".I18N());
			DebugMode.SetDesc("Config.Debug.Mode.Desc".I18N());
		}

		public void SelectLanguage(NextLanguage language)
		{
			CurrentLanguage = language;
			if (language != null)
			{
				LanguageDir.Value = language.LanguageDir;
				LogInfo("Misc.CurrentLanguage".I18N() + " : " + language.Config.LanguageName);
			}
		}

		internal void LoadModSetting()
		{
			NextModSetting = NextModSetting.LoadSetting();
		}

		internal void SaveModSetting()
		{
			NextModSetting.SaveSetting(NextModSetting);
		}

		private void OnSceneLoaded(Scene loadScene, LoadSceneMode loadSceneMode)
		{
			//IL_0028: Unknown result type (might be due to invalid IL or missing references)
			if (!_sceneLoadActions.TryGetValue(((Scene)(ref loadScene)).name, out var value))
			{
				return;
			}
			foreach (Action<Scene> item in value)
			{
				try
				{
					item(loadScene);
				}
				catch (Exception obj)
				{
					LogError(obj);
				}
			}
		}

		private void Update()
		{
			_updateActions?.Invoke();
		}

		public void RegisterUpdateEvent(Action action)
		{
			_updateActions = (Action)Delegate.Combine(_updateActions, action);
		}

		public void UnRegisterUpdateEvent(Action action)
		{
			_updateActions = (Action)Delegate.Remove(_updateActions, action);
		}

		public void RegisterSceneLoadEvent(string sceneName, Action<Scene> action)
		{
			if (!_sceneLoadActions.TryGetValue(sceneName, out var value))
			{
				_sceneLoadActions.Add(sceneName, value = new List<Action<Scene>>());
			}
			value.Add(action);
		}

		public static void LogLua(object obj)
