		private void SearchNpc(string searchFilter)
		{
			curNpcSelectedIndex = -1;
			curNpcSelectedPage = 0;
			npcDataList.Clear();
			bool flag = string.IsNullOrWhiteSpace(searchFilter);
			foreach (JSONObject item in jsonData.instance.AvatarJsonData.list)
			{
				int i = item["id"].I;
				if (i >= 20000)
				{
					SearchNpcData searchNpcData = new SearchNpcData();
					searchNpcData.ID = i;
					searchNpcData.Refresh();
					if (flag || searchNpcData.FilterCheck(searchFilter))
					{
						npcDataList.Add(searchNpcData);
					}
				}
			}
			npcDataListName = npcDataList.Select((SearchNpcData data) => data.ToString()).ToArray();
		}

		private SearchNpcData GetCurSelectNpcData()
		{
			if (curNpcSelectedIndex < 0 || curNpcSelectedIndex >= countEachPage)
			{
				return null;
			}
			int num = curNpcSelectedPage * countEachPage + curNpcSelectedIndex;
			if (num >= 0 && num < npcDataList.Count)
			{
				return npcDataList[num];
			}
			return null;
		}

