	public class NextModSetting
	{
		public Dictionary<string, ModGroupSetting> groupSettings = new Dictionary<string, ModGroupSetting>();

		public Dictionary<string, ModConfigSetting> modSettings = new Dictionary<string, ModConfigSetting>();

		public DataGroup<bool?> BoolGroup = new DataGroup<bool?>();

		public DataGroup<long> LongIntegerGroup = new DataGroup<long>();

		public DataGroup<double> DoubleFloatGroup = new DataGroup<double>();

		public DataGroup<string> StringGroup = new DataGroup<string>();

		public static NextModSetting LoadSetting()
		{
			NextModSetting nextModSetting = null;
			string value = Main.PathModSettingFile.Value;
			if (File.Exists(value))
			{
				try
				{
					nextModSetting = JsonConvert.DeserializeObject<NextModSetting>(File.ReadAllText(value));
				}
				catch (Exception obj)
				{
					Main.LogError("加载Next Mod设置文件失败！");
					Main.LogError(obj);
				}
			}
			if (nextModSetting == null)
			{
				nextModSetting = new NextModSetting();
			}
			return nextModSetting;
		}

		public static void SaveSetting(NextModSetting modSetting)
		{
			string value = Main.PathModSettingFile.Value;
			try
			{
				string contents = JsonConvert.SerializeObject((object)modSetting, (Formatting)1);
				File.WriteAllText(value, contents);
			}
			catch (Exception obj)
			{
				Main.LogError(obj);
			}
		}

		public ModGroupSetting GetOrCreateModGroupSetting(ModGroup modGroup)
		{
			if (!groupSettings.TryGetValue(modGroup.GroupKey, out var value))
			{
				value = new ModGroupSetting();
				groupSettings.Add(modGroup.GroupKey, value);
			}
			value.BindGroup = modGroup;
			return value;
		}

		public ModConfigSetting GetOrCreateModSetting(ModConfig config)
		{
			string settingKey = config.SettingKey;
			if (!modSettings.TryGetValue(settingKey, out var value))
			{
				value = new ModConfigSetting();
				modSettings.Add(settingKey, value);
			}
			value.BindMod = config;
			return value;
		}

		public void ClearPriority()
		{
			int num = 0;
			foreach (KeyValuePair<string, ModGroupSetting> groupSetting in groupSettings)
			{
				groupSetting.Value.priority = num++;
			}
		}
	}
	public class SearchNpcData
	{
		public int ID { get; set; }

		public int ImportantID { get; set; }

		public string Name { get; set; }

		public string Title { get; set; }

		public int AgeYear { get; set; }

		public int Gender { get; set; }

		public int Level { get; set; }

		public string LocationName { get; set; }

		public int School { get; set; }

		public int Life { get; set; }

		public int Sprite { get; set; }

		public bool IsCouple { get; set; }

		public bool IsTeacher { get; set; }

		public bool IsStudent { get; set; }

		public bool IsBrother { get; set; }

		public bool FilterCheck(string filter)
		{
			string[] array = filter.Split(' ');
			foreach (string matchStr in array)
			{
				if (!Check(matchStr))
				{
					return false;
				}
			}
			return true;
		}

		public bool Check(string matchStr)
		{
			if (string.IsNullOrWhiteSpace(matchStr))
			{
				return true;
			}
			if (ID.ToString().Contains(matchStr))
			{
				return true;
			}
			if (ImportantID.ToString().Contains(matchStr))
			{
				return true;
			}
			if (Name.Contains(matchStr))
			{
				return true;
			}
			if (Title.Contains(matchStr))
			{
				return true;
			}
			if (LocationName.Contains(matchStr))
			{
				return true;
			}
			if (DialogAnalysis.GetSchoolName(School.ToString()).Contains(matchStr))
			{
				return true;
			}
			if (DialogAnalysis.GetGenderName(Gender).Contains(matchStr))
			{
				return true;
			}
			if (DialogAnalysis.GetLevelName(Level).Contains(matchStr))
			{
				return true;
			}
			return false;
		}

		public override string ToString()
		{
			if (ImportantID != 0)
			{
				return $"{ID} {Name} ({ImportantID})";
			}
			return $"{ID} {Name}";
		}

		public void Refresh()
		{
			JSONObject npcJsonData = DialogAnalysis.GetNpcJsonData(ID);
			Name = DialogAnalysis.GetNpcName(ID);
			JSONObject obj = npcJsonData["BindingNpcID"];
			ImportantID = ((obj != null) ? obj.I : 0);
			Title = DialogAnalysis.GetNpcTitle(ID);
			Gender = DialogAnalysis.GetNpcSex(ID);
			AgeYear = DialogAnalysis.GetNpcAge(ID) / 12;
			Level = DialogAnalysis.GetNpcLevel(ID);
			LocationName = DialogAnalysis.GetNpcLocationName(ID);
			Life = DialogAnalysis.GetNpcLife(ID);
			Sprite = DialogAnalysis.GetNpcSprite(ID);
			School = DialogAnalysis.GetNpcSchool(ID);
			IsCouple = DialogAnalysis.IsPlayerCouple(ID);
			IsTeacher = DialogAnalysis.IsPlayerTeacher(ID);
			IsStudent = DialogAnalysis.IsPlayerStudent(ID);
			IsBrother = DialogAnalysis.IsPlayerBrother(ID);
		}
	}
	public static class Updater
	{
		public class VersionJson
		{
			public string Version { get; set; }
		}

		public static string VersionJsonUrlGithub => "https://raw.githubusercontent.com/magicskysword/Next/main/version.json";

		public static string VersionJsonUrlGitee => "https://gitee.com/magicskysword/Next/raw/main/version.json";

		public static string WebGitHubUrl => "https://github.com/magicskysword/Next/releases/latest";

		public static string Web3dmBBSUrl => "https://bbs.3dmgame.com/thread-6207429-1-1.html";

		public static string Web3dmModSiteUrl => "https://mod.3dmgame.com/mod/178805";

		public static string WebBWikiUrl => "https://wiki.biligame.com/mcs";

		public static bool CheckSuccess { get; private set; } = false;


		public static bool HasNewVersion { get; private set; }

		public static string CurVersionStr => "0.9.1";

		public static string NewVersionStr { get; private set; } = "0.0.0";


		public static bool IsChecking { get; set; } = false;


		public static async void CheckVersion()
		{
			if (!IsChecking)
			{
				CheckSuccess = false;
				IsChecking = true;
				try
				{
					CompareVersion((((JToken)JObject.Parse(await DownloadVersionJson())).ToObject<VersionJson>() ?? throw new Exception("Updater.JsonParseFailure".I18N())).Version);
					CheckSuccess = true;
				}
				catch (Exception innerException)
				{
					Main.LogError(new Exception("Updater.GetVersionJsonFailure".I18N(), innerException));
					CheckSuccess = false;
				}
				IsChecking = false;
			}
		}

		private static async Task<string> DownloadVersionJson()
		{
			WebClient wc = new WebClient();
			try
			{
				return await wc.DownloadStringTaskAsync(VersionJsonUrlGithub);
			}
			catch (Exception)
			{
			}
			try
			{
				return await wc.DownloadStringTaskAsync(VersionJsonUrlGitee);
			}
			catch (Exception)
			{
			}
			throw new Exception("Updater.DownloadFailure".I18N());
		}

		private static void CompareVersion(string getVersionStr)
		{
			Version version = new Version(CurVersionStr);
			Version version2 = new Version(getVersionStr);
			if (version >= version2)
			{
				HasNewVersion = false;
				NewVersionStr = CurVersionStr;
			}
			else
			{
				HasNewVersion = true;
				NewVersionStr = getVersionStr;
			}
		}
	}
}
