	public class WindowCreateABProjectDialog : WindowDialogBase
	{
		public UI_WinCreateABMod MainView => base.contentPane as UI_WinCreateABMod;

		public GTextInput InputProjectName { get; set; }

		public GTextInput InputProjectPath { get; set; }

		public GTextInput InputOutputABPath { get; set; }

		public WindowCreateABProjectDialog()
			: base("NextCore", "WinCreateABMod")
		{
		}

		protected override void OnInit()
		{
			base.OnInit();
			UI_WinCreateABMod mainView = MainView;
			mainView.m_btnOk.onClick.Add(OnClickOk);
			mainView.m_btnCancle.onClick.Add(OnClickCancel);
			mainView.m_frame.m_closeButton.onClick.Add(OnClickCancel);
			mainView.m_btnEditProjectPath.onClick.Add(OnClickEditProjectPath);
			mainView.m_btnEditOutputABPath.onClick.Add(OnClickEditOutputABPath);
			InputProjectName = mainView.m_inputABName.GetChild("inContent").asTextInput;
			InputProjectPath = mainView.m_inputProjectPath.GetChild("inContent").asTextInput;
			InputOutputABPath = mainView.m_inputExportPath.GetChild("inContent").asTextInput;
		}

		private void OnClickEditOutputABPath()
		{
			InputOutputABPath.text = FileUtils.OpenDirectorySelector("选择输出目录", InputOutputABPath.text);
		}

		private void OnClickEditProjectPath()
		{
			InputProjectPath.text = FileUtils.OpenDirectorySelector("选择Unity工程目录", InputProjectPath.text);
		}

		protected override void OnKeyDown(EventContext context)
		{
			//IL_000d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0014: Invalid comparison between Unknown and I4
			base.OnKeyDown(context);
			if ((int)context.inputEvent.keyCode == 27)
			{
				OnClickCancel();
			}
		}

		private void OnClickCancel()
		{
			Hide();
		}

		private void OnClickOk()
		{
			CreateABProjectStep1();
		}

		private void CreateABProjectStep1()
		{
			if (string.IsNullOrEmpty(InputProjectPath.text))
			{
				new WindowConfirmDialogBuilder().SetTitle("错误").SetContent("Unity工程目录不能为空").SetCanCancel(canCancel: false)
					.Build()
					.Show();
			}
			else if (string.IsNullOrEmpty(InputOutputABPath.text))
			{
				new WindowConfirmDialogBuilder().SetTitle("错误").SetContent("输出目录不能为空").SetCanCancel(canCancel: false)
					.Build()
					.Show();
			}
			else if (string.IsNullOrEmpty(InputProjectName.text))
			{
				new WindowConfirmDialogBuilder().SetTitle("错误").SetContent("AB包名称不能为空").SetCanCancel(canCancel: false)
					.Build()
					.Show();
			}
			else if (Directory.Exists(InputProjectPath.text) && Directory.GetFiles(InputProjectPath.text).Length != 0)
			{
				new WindowConfirmDialogBuilder().SetTitle("提示").SetContent("目标目录不为空，是否继续创建？").SetCanCancel(canCancel: true)
					.SetOnConfirm(CreateABProjectStep2)
					.Build()
					.Show();
			}
			else
			{
				CreateABProjectStep2();
			}
		}

		private void CreateABProjectStep2()
		{
			if (Path.GetFileNameWithoutExtension(InputOutputABPath.text) != "AssetBundles")
			{
				new WindowConfirmDialogBuilder().SetTitle("提示").SetContent("输出目录不为AssetBundles，可能导致打包AB包不能正确读取，是否继续创建？").SetCanCancel(canCancel: true)
					.SetOnConfirm(CreateABProjectStep3)
					.Build()
					.Show();
			}
			else
			{
				CreateABProjectStep3();
			}
		}

		private void CreateABProjectStep3()
		{
			string projectName = InputProjectName.text;
			string projectDir = InputProjectPath.text;
			ModUtils.CreateUnityABTemplateProject(exportABPath: InputOutputABPath.text, projectName: projectName, projectPath: projectDir);
			Hide();
			new WindowConfirmDialogBuilder().SetTitle("提示").SetContent("创建成功，是否打开Unity工程目录？").SetCanCancel(canCancel: true)
				.SetOnConfirm(delegate
				{
					Application.OpenURL(projectDir);
				})
				.Build()
				.Show();
		}
	}
