			}
			catch (CreateWorkshopException ex)
			{
				WindowConfirmDialog.CreateDialog("提示".I18NTodo(), ex.Message, canCancel: false);
				return;
			}
			Hide();
			OnConfirm(mod);
		}

		private void OnClickProjectItem(EventContext context, ProjectListBase item)
		{
			if (item is ProjectListCreateWorkshopItem workshopItem)
			{
				OnSelectWorkshopItem(workshopItem);
			}
		}

		private void OnSelectWorkshopItem(ProjectListCreateWorkshopItem workshopItem)
		{
			Inspector.Clear();
			CurrentItem = workshopItem;
			if (workshopItem != null)
			{
				workshopItem.Inspector = Inspector;
				workshopItem.OnInspect();
			}
			Inspector.Refresh();
		}
	}
	[Flags]
	public enum ModFilter
	{
		None = 0,
		Local = 1,
		Workshop = 2
	}
	public delegate void OnSelectMod(ModWorkshop mod);
	public class WindowModSelectorDialog : WindowDialogBase
	{
		public string Title { get; set; }

		public OnSelectMod OnConfirm { get; set; }

		public ModFilter Filter { get; set; }

		public List<ModWorkshop> Mods { get; } = new List<ModWorkshop>();


		public List<TableInfo> TableInfos { get; } = new List<TableInfo>();


		public CtlTableList TableList { get; private set; }

		public CtlPropertyInspector Inspector { get; private set; }

		public UI_WinModSelectorDialog SelectorDialog => base.contentPane as UI_WinModSelectorDialog;

		private WindowModSelectorDialog()
			: base("NextCore", "WinModSelectorDialog")
		{
		}

		public static WindowModSelectorDialog CreateDialog(string title, ModFilter filter, List<TableInfo> tableInfos, OnSelectMod onConfirm)
		{
			WindowModSelectorDialog windowModSelectorDialog = new WindowModSelectorDialog();
			windowModSelectorDialog.Title = title;
			windowModSelectorDialog.Filter = filter;
			windowModSelectorDialog.OnConfirm = onConfirm;
			windowModSelectorDialog.TableInfos.AddRange(tableInfos);
			windowModSelectorDialog.modal = true;
			windowModSelectorDialog.Show();
			return windowModSelectorDialog;
		}

		protected override void OnInit()
		{
			base.OnInit();
			TableList = new CtlTableList(SelectorDialog.m_table);
			Inspector = new CtlPropertyInspector(SelectorDialog.m_inspector);
			if (Filter.HasFlag(ModFilter.Local))
			{
				AddLocalMods();
			}
			if (Filter.HasFlag(ModFilter.Workshop))
			{
				AddWorkshopMods();
			}
			TableList.MultiSelect = false;
			TableList.SetClickItem(OnClickModItem);
			TableList.BindTable(TableInfos, new TableDataList<ModWorkshop>(Mods));
			SelectorDialog.m_btnConfirm.onClick.Add(OnClickConfirm);
			SelectorDialog.m_btnConfirm.enabled = false;
			SelectorDialog.m_frame.m_closeButton.onClick.Add(OnClickCancel);
			Main.LogInfo($"初始化完成，共有{Mods.Count}个模组");
		}

		private void OnClickConfirm(EventContext context)
		{
			OnConfirm?.Invoke(Mods[TableList.SelectedIndex]);
			Hide();
		}

		private void OnClickCancel()
		{
			Hide();
		}

		private void OnClickModItem(EventContext eventContext)
		{
			ModWorkshop mod = (ModWorkshop)TableList.SelectedItem;
			ShowModInfo(mod);
		}

		private void ShowModInfo(ModWorkshop mod)
		{
			Inspector.Clear();
			SelectorDialog.m_btnConfirm.enabled = mod != null;
			if (mod != null)
			{
				WorkShopItem modInfo = mod.ModInfo;
				Inspector.AddDrawer(new CtlTextDrawer(string.Format("Mod名称 : " + modInfo.Title)));
				Inspector.AddDrawer(new CtlTextDrawer(string.Format("Mod地址 : " + mod.Path)));
				Inspector.AddDrawer(new CtlTextDrawer(string.Format("Mod介绍 : " + modInfo.Des)));
			}
		}

		private void AddLocalMods()
		{
			string[] directories = Directory.GetDirectories(Main.PathLocalModsDir.Value);
			foreach (string text in directories)
			{
				Main.LogInfo("检查模组：" + text);
				if (Directory.Exists(text))
				{
					try
					{
						Mods.Add(ModEditorManager.I.LoadWorkshop(text));
					}
					catch (Exception arg)
					{
						Main.LogError($"读取Mod配置文件失败：{text}\n{arg}");
					}
				}
			}
		}

		private void AddWorkshopMods()
		{
			//IL_0021: Unknown result type (might be due to invalid IL or missing references)
			//IL_0026: Unknown result type (might be due to invalid IL or missing references)
			//IL_0029: Unknown result type (might be due to invalid IL or missing references)
			uint numSubscribedItems = SteamUGC.GetNumSubscribedItems();
			PublishedFileId_t[] array = new PublishedFileId_t[numSubscribedItems];
			SteamUGC.GetSubscribedItems((PublishedFileId_t[])(object)array, numSubscribedItems);
			List<ulong> list = new List<ulong>();
			PublishedFileId_t[] array2 = (PublishedFileId_t[])(object)array;
			foreach (PublishedFileId_t val in array2)
			{
				list.Add(val.m_PublishedFileId);
			}
			foreach (ulong item in list)
			{
				string text = $"{WorkshopTool.WorkshopRootPath}/{item}";
				Main.LogInfo("检查模组：" + text);
				if (Directory.Exists(text) && File.Exists(text + "/Mod.bin"))
				{
					try
					{
						Mods.Add(ModEditorManager.I.LoadWorkshop(text));
					}
					catch (Exception arg)
					{
						Main.LogError($"读取Mod配置文件失败：{text}\n{arg}");
					}
				}
			}
		}
	}
