namespace SkySwordKill.Next.StaticFace
{
	public class CustomStaticFaceInfo
	{
		[JsonProperty(Order = 1)]
		public Dictionary<string, int> RandomInfos = new Dictionary<string, int>();

		[JsonProperty(Order = 0)]
		public int ID { get; set; }

		public int GetRandomInfo(string type)
		{
			if (RandomInfos.ContainsKey(type))
			{
				return RandomInfos[type];
			}
			Main.LogWarning($"StaticFace [{ID}] 缺失 {type} 类型数据。");
			return -100;
		}
	}
	public static class StaticFaceUtils
	{
		public static Dictionary<int, CustomStaticFaceInfo> FaceInfos { get; set; } = new Dictionary<int, CustomStaticFaceInfo>();


		public static void Clear()
		{
			FaceInfos.Clear();
		}

		public static bool HasFace(int avatarId)
		{
			return FaceInfos.ContainsKey(avatarId);
		}

		public static CustomStaticFaceInfo GetFace(int avatarId)
		{
			return FaceInfos[avatarId];
		}

		public static int GetFaceInfo(int avatarId, InfoName type)
		{
			string type2 = ((object)(InfoName)(ref type)).ToString();
			if (FaceInfos.TryGetValue(avatarId, out var value))
			{
				return value.GetRandomInfo(type2);
			}
			return -100;
		}

		public static void RegisterFace(CustomStaticFaceInfo faceInfo)
		{
			FaceInfos[faceInfo.ID] = faceInfo;
		}

		public static CustomStaticFaceInfo GetFaceInfoByJson(JSONObject jsonObject)
		{
			CustomStaticFaceInfo customStaticFaceInfo = new CustomStaticFaceInfo();
			foreach (string key in jsonObject.keys)
			{
				if (Enum.TryParse<InfoName>(key, ignoreCase: true, out InfoName _))
				{
					customStaticFaceInfo.RandomInfos[key] = jsonObject[key].I;
				}
			}
			return customStaticFaceInfo;
		}

		public static CustomStaticFaceInfo GetFaceInfoByStaticFaceInfo(StaticFaceInfo staticFaceInfo)
		{
			CustomStaticFaceInfo customStaticFaceInfo = new CustomStaticFaceInfo();
			foreach (StaticFaceRandomInfo faceinfo in staticFaceInfo.faceinfoList)
			{
				customStaticFaceInfo.RandomInfos[((object)(InfoName)(ref faceinfo.SkinTypeName)).ToString()] = faceinfo.SkinTypeScope;
			}
			return customStaticFaceInfo;
		}
	}
