namespace SkySwordKill.Next.Lua
{
	public class LuaManager : MonoBehaviour
	{
		public Dictionary<string, LuaFileCache> LuaCaches = new Dictionary<string, LuaFileCache>();

		public LuaEnv LuaEnv;

		public void Init()
		{
			Main.LogInfo("开始加载xlua.dll");
			DllTools.LoadDllFile(Main.PathLibraryDir.Value, "xlua.dll");
			Main.LogInfo("加载完毕");
			InitLuaEnv();
		}

		public object[] DoString(string str)
		{
			return LuaEnv.DoString(str);
		}

		public object[] RunFunc(string scr, string funcName, object[] args)
		{
			object[] array = LuaEnv.DoString("return require '" + scr + "'");
			if (array.Length != 0 && array[0] is LuaTable luaTable)
			{
				return luaTable.Get<LuaFunction>(funcName).Call(args);
			}
			Main.LogError("读取Lua " + scr + " 失败");
			return null;
		}

		public T RunScript<T>(string scrPath)
		{
			string filepath = scrPath;
			byte[] chunk = LuaScriptsLoader(ref filepath);
			object[] array = LuaEnv.DoString(chunk, filepath);
			if (array.Length != 0)
			{
				object obj = array[0];
				if (obj is T)
				{
					return (T)obj;
				}
			}
			Main.LogError("Lua  " + scrPath + " 返回值数量或类型不匹配");
			return default(T);
		}

		public void Reset()
		{
			InitLuaEnv();
			LuaCaches.Clear();
		}

		private void InitLuaEnv()
		{
			GC.Collect();
			if (LuaEnv != null)
			{
				LuaEnv.DoString("\r\ncollectgarbage(\"collect\")\r\n");
				try
				{
					LuaEnv.Dispose();
				}
				catch (Exception obj)
				{
					Main.LogWarning(obj);
				}
			}
			LuaEnv = new LuaEnv();
			LuaEnv.AddLoader(LuaLibLoader);
			LuaEnv.AddLoader(LuaScriptsLoader);
			LuaEnv.DoString("\r\nfunction print(...)\r\n    local msgtb = {}\r\n    for key, value in pairs({...}) do\r\n        table.insert(msgtb,tostring(value))\r\n    end\r\n    local msg = table.concat(msgtb,\"\\t\")\r\n    CS.SkySwordKill.Next.Main.LogLua(msg)\r\nend\r\nfunction getmodpath(luafile)\r\n    return CS.SkySwordKill.Next.Main.Instance.luaManager:GetLuaModPath(luafile)\r\nend\r\n");
		}

		private byte[] LuaLibLoader(ref string filepath)
		{
			filepath = filepath.Replace(".", "/");
			filepath = (Main.PathLuaLibDir.Value + "/" + filepath + ".lua").Replace("\\", "/");
			if (File.Exists(filepath))
			{
				Main.LogDebug("Lua载入地址 " + filepath);
				return Encoding.UTF8.GetBytes(File.ReadAllText(filepath));
			}
			return null;
		}

		private byte[] LuaScriptsLoader(ref string filepath)
		{
			string key = filepath.Replace(".", "/");
			if (LuaCaches.TryGetValue(key, out var value))
			{
				filepath = value.FilePath;
				if (File.Exists(filepath))
				{
