		}

		public string GetLuaModPath(string filepath)
		{
			string key = filepath.Replace(".", "/");
			if (LuaCaches.TryGetValue(key, out var value))
			{
				return value.FromMod.Path;
			}
			return null;
		}

		public void ClearCache()
		{
			DoString("\r\nfor key, _ in pairs(package.preload) do\r\n    package.preload[key] = nil\r\nend\r\nfor key, _ in pairs(package.loaded) do\r\n    package.loaded[key] = nil\r\nend\r\n");
			LuaCaches.Clear();
		}
	}
