	public class FileUtils
	{
		public delegate void FileHandle(string virtualPath, string filePath);

		public static void DirectoryHandle(string rootPath, string dirPath, FileHandle fileHandle)
		{
			if (!Directory.Exists(dirPath))
			{
				return;
			}
			string[] directories = Directory.GetDirectories(dirPath);
			foreach (string text in directories)
			{
				string fileNameWithoutExtension = Path.GetFileNameWithoutExtension(text);
				if (string.IsNullOrEmpty(rootPath))
				{
					DirectoryHandle(fileNameWithoutExtension ?? "", text, fileHandle);
				}
				else
				{
					DirectoryHandle(rootPath + "/" + fileNameWithoutExtension, text, fileHandle);
				}
			}
			directories = Directory.GetFiles(dirPath);
			foreach (string text2 in directories)
			{
				string fileName = Path.GetFileName(text2);
				string virtualPath = rootPath + "/" + fileName;
				fileHandle(virtualPath, text2);
			}
		}

