		public void CacheAssetDir(string rootPath, bool dontDestroyOnLoad = false)
		{
			if (Directory.Exists(rootPath))
			{
				FileUtils.DirectoryHandle("Assets", rootPath, delegate(string path, string filePath)
				{
					AddFileAsset(path, filePath, dontDestroyOnLoad);
				});
			}
		}

		public void CacheAssetBundleDir(string rootPath)
		{
			if (Directory.Exists(rootPath))
			{
				string[] files = Directory.GetFiles(rootPath, "*.ab", SearchOption.AllDirectories);
				foreach (string path in files)
				{
					AddABAsset(path);
				}
			}
		}

