			return resMappers.ContainsKey(path);
		}

		/// <summary>
		/// 直接添加文件资源引用
		/// </summary>
		/// <param name="cachePath"></param>
		/// <param name="path"></param>
		/// <param name="dontDestroyOnLoad"></param>
		public void AddFileAsset(string cachePath, string path, bool dontDestroyOnLoad)
		{
			FileAsset fileAsset = new FileAsset(path);
			fileAsset.DontDestroyOnLoad = dontDestroyOnLoad;
			string text = cachePath.Replace("\\\\", "/");
			FileResLoader.AddFileAsset(text, fileAsset);
			AddResMapper(text, new ResMapper(cachePath, FileResLoader));
		}

		public void AddABAsset(string path)
		{
			ABRefAsset aBRefAsset = new ABRefAsset(path);
			aBRefAsset.LoadAssetBundle();
			string[] allAssetNames = aBRefAsset.RefAssetBundle.GetAllAssetNames();
			foreach (string text in allAssetNames)
			{
				if (text.StartsWith("Assets/", StringComparison.OrdinalIgnoreCase))
				{
					AddResMapper(text, new ResMapper(text, ABResLoader));
				}
			}
			ABResLoader.AddABAssetToFirst(aBRefAsset);
		}

		public void AddResMapper(string path, ResMapper resMapper)
		{
			if (resMappers.ContainsKey(path))
			{
				Main.LogWarning("覆盖Asset [" + resMapper.resLoader.LoaderCode + "](" + path + ")");
			}
			else
			{
				Main.LogInfo("添加Asset [" + resMapper.resLoader.LoaderCode + "](" + path + ")");
			}
			resMappers[path] = resMapper;
		}

		public Sprite GetSpriteCache(Texture2D texture)
		{
			//IL_0042: Unknown result type (might be due to invalid IL or missing references)
			//IL_0051: Unknown result type (might be due to invalid IL or missing references)
			if ((Object)(object)texture == (Object)null)
			{
				return null;
			}
			if (!spriteCache.TryGetValue(((object)texture).GetHashCode(), out var value) || (Object)(object)value == (Object)null)
			{
				value = Sprite.Create(texture, new Rect(0f, 0f, (float)((Texture)texture).width, (float)((Texture)texture).height), new Vector2(0.5f, 0.5f));
				spriteCache.Add(((object)texture).GetHashCode(), value);
			}
			return value;
		}

		public void ReleaseCache()
		{
			spriteCache.Clear();
			Resources.UnloadUnusedAssets();
		}
	}
