	public class ModGroup
	{
		public string GroupName { get; set; }

		public string GroupKey { get; set; }

		public DirectoryInfo ModDir { get; set; }

		public ModType Type { get; set; }

		public List<ModConfig> ModConfigs { get; set; } = new List<ModConfig>();


		public WorkShopItem SteamModInfo { get; set; }

		public ModGroup(DirectoryInfo directory, ModType type)
		{
			GroupKey = directory.Name;
			ModDir = directory;
			Type = type;
		}

		public void Init(bool resetModState, bool showLog)
		{
			if (resetModState)
			{
				ModConfigs.Clear();
				if (Directory.Exists(ModDir?.ToString() + "/plugins/Next/"))
				{
					DirectoryInfo[] directories = new DirectoryInfo(ModDir?.ToString() + "/plugins/Next/").GetDirectories("mod*", SearchOption.TopDirectoryOnly);
					for (int i = 0; i < directories.Length; i++)
					{
						ModConfig modConfig = ModManager.LoadModConfig(directories[i].FullName, showLog);
						modConfig.SettingKey = GroupKey + "." + Path.GetFileNameWithoutExtension(modConfig.Path);
						ModConfigs.Add(modConfig);
					}
				}
			}
			else
			{
				List<ModConfig> list = new List<ModConfig>();
				if (Directory.Exists(ModDir?.ToString() + "/plugins/Next/"))
				{
					DirectoryInfo[] directories = new DirectoryInfo(ModDir?.ToString() + "/plugins/Next/").GetDirectories("mod*", SearchOption.TopDirectoryOnly);
					foreach (DirectoryInfo modDirInfo in directories)
					{
						if (showLog)
						{
							Main.LogInfo(string.Format("ModManager.LoadMod".I18N(), modDirInfo.Name));
						}
						ModConfig modConfig2 = ModConfigs.Find((ModConfig x) => x.Path == modDirInfo.FullName);
						if (modConfig2 == null)
						{
							modConfig2 = ModManager.LoadModConfig(modDirInfo.FullName, showLog);
							modConfig2.SettingKey = GroupKey + "." + Path.GetFileNameWithoutExtension(modConfig2.Path);
						}
						else
						{
							modConfig2.Reload();
						}
						list.Add(modConfig2);
					}
				}
				ModConfigs = list;
			}
			SteamModInfo = ModManager.ReadConfig(ModDir.FullName);
			GroupName = SteamModInfo?.Title ?? string.Empty;
			ModConfigs = ModManager.SortMod(ModConfigs).ToList();
		}

		public void MoveModUp(ModConfig modConfig)
		{
			int num = ModConfigs.IndexOf(modConfig);
			if (num > 0)
			{
				MoveMod(modConfig, num - 1);
			}
		}

		public void MoveModDown(ModConfig modConfig)
		{
			int num = ModConfigs.IndexOf(modConfig);
			if (num < ModConfigs.Count - 1)
			{
				MoveMod(modConfig, num + 1);
			}
		}

		public void MoveMod(ModConfig mod, int index)
		{
			ModConfigs.Remove(mod);
			ModConfigs.Insert(index, mod);
			ApplyModSetting();
		}

		public void ApplyModSetting()
		{
			NextModSetting nextModSetting = Main.I.NextModSetting;
			int num = 0;
			foreach (ModConfig modConfig in ModConfigs)
			{
				ModConfigSetting orCreateModSetting = nextModSetting.GetOrCreateModSetting(modConfig);
				orCreateModSetting.priority = num++;
				if (Type == ModType.Workshop)
				{
					orCreateModSetting.enable = true;
				}
			}
		}
	}
