	public class ModSettingDefinitionListConverter : JsonConverter
	{
		private static Dictionary<string, Type> s_typeMap = new Dictionary<string, Type>();

		public static void Init()
		{
			Type[] types = typeof(ModSettingDefinition).Assembly.GetTypes();
			foreach (Type type in types)
			{
				if (type.IsSubclassOf(typeof(ModSettingDefinition)) && !type.IsAbstract && type.GetCustomAttribute<SettingTypeAttribute>() != null)
				{
					s_typeMap.Add(type.GetCustomAttribute<SettingTypeAttribute>().TypeName, type);
				}
			}
		}

		public override bool CanConvert(Type objectType)
		{
			return objectType == typeof(List<ModSettingDefinition>);
		}

		public override void WriteJson(JsonWriter writer, object value, JsonSerializer serializer)
		{
			serializer.Serialize(writer, value);
		}

		public override object ReadJson(JsonReader reader, Type objectType, object existingValue, JsonSerializer serializer)
		{
			//IL_0020: Unknown result type (might be due to invalid IL or missing references)
			//IL_0026: Expected O, but got Unknown
			JArray obj = JArray.Load(reader);
			List<ModSettingDefinition> list = new List<ModSettingDefinition>(((JContainer)obj).Count);
			foreach (JObject item in obj)
			{
				JObject val = item;
				string text = (string)val["Type"];
				if (s_typeMap.TryGetValue(text, out var value))
				{
					ModSettingDefinition modSettingDefinition = (ModSettingDefinition)Activator.CreateInstance(value);
					serializer.Populate(((JToken)val).CreateReader(), (object)modSettingDefinition);
					if (modSettingDefinition is ModSettingDefinition_Custom modSettingDefinition_Custom)
					{
						modSettingDefinition_Custom.RawJson = val;
					}
					list.Add(modSettingDefinition);
					continue;
				}
				throw new Exception("Unknown mod setting type: " + text);
			}
			return list;
		}
	}
