		public static void ExportMainData(MainDataContainer dataContainer, string exportDir)
		{
			if (Directory.Exists(exportDir))
			{
				Directory.Delete(exportDir, recursive: true);
			}
			Directory.CreateDirectory(exportDir);
			foreach (KeyValuePair<string, JObject> dataJObject in dataContainer.dataJObjects)
			{
				File.WriteAllText(Utility.CombinePaths(new string[2]
				{
					exportDir,
					dataJObject.Key + ".json"
				}), ((JToken)dataJObject.Value).ToString((Formatting)1, Array.Empty<JsonConverter>()));
			}
			foreach (KeyValuePair<string, JSONObject> dataJSONObject in dataContainer.dataJSONObjects)
			{
				File.WriteAllText(Utility.CombinePaths(new string[2]
				{
					exportDir,
					dataJSONObject.Key + ".json"
				}), dataJSONObject.Value.Print(true).DecodeJsonUnicode());
			}
			foreach (KeyValuePair<string, YSDictionary<string, JSONObject>> dataYSDic in dataContainer.dataYSDics)
			{
				string text = Utility.CombinePaths(new string[2] { exportDir, dataYSDic.Key });
				if (!Directory.Exists(text))
				{
					Directory.CreateDirectory(text);
				}
				foreach (KeyValuePair<string, JSONObject> item in (Dictionary<string, JSONObject>)(object)dataYSDic.Value)
				{
					File.WriteAllText(Utility.CombinePaths(new string[2]
					{
						text,
						item.Key + ".json"
					}), item.Value.Print(true).DecodeJsonUnicode());
				}
			}
			foreach (KeyValuePair<string, JSONObject[]> dataJSONObjectArray in dataContainer.dataJSONObjectArrays)
			{
				string text2 = Utility.CombinePaths(new string[2] { exportDir, dataJSONObjectArray.Key });
				if (!Directory.Exists(text2))
				{
					Directory.CreateDirectory(text2);
				}
				JSONObject[] value = dataJSONObjectArray.Value;
				for (int i = 1; i < value.Length; i++)
				{
					if (value[i] != null)
					{
						File.WriteAllText(Utility.CombinePaths(new string[2]
						{
							text2,
							$"{i}.json"
						}), value[i].Print(true).DecodeJsonUnicode());
					}
				}
			}
			string text3 = Utility.CombinePaths(new string[2] { exportDir, "AIJsonDate" });
			if (!Directory.Exists(text3))
			{
				Directory.CreateDirectory(text3);
			}
			foreach (KeyValuePair<int, JSONObject> item2 in dataContainer.AIJsonDate)
			{
				File.WriteAllText(Utility.CombinePaths(new string[2]
				{
					text3,
					$"{item2.Key}.json"
				}), item2.Value.Print(true).DecodeJsonUnicode());
			}
			string text4 = Utility.CombinePaths(new string[2] { exportDir, "FuBenJsonData" });
			if (!Directory.Exists(text4))
			{
				Directory.CreateDirectory(text4);
			}
			foreach (KeyValuePair<int, List<JSONObject>> fuBenJsonDatum in dataContainer.FuBenJsonData)
			{
				string text5 = Utility.CombinePaths(new string[2]
				{
					text4,
					fuBenJsonDatum.Key.ToString()
				});
				if (!Directory.Exists(text5))
				{
					Directory.CreateDirectory(text5);
				}
				List<JSONObject> value2 = fuBenJsonDatum.Value;
				File.WriteAllText(Utility.CombinePaths(new string[2] { text5, "RandomMap.json" }), value2[0].Print(true).DecodeJsonUnicode());
				File.WriteAllText(Utility.CombinePaths(new string[2] { text5, "ShiJian.json" }), value2[1].Print(true).DecodeJsonUnicode());
				File.WriteAllText(Utility.CombinePaths(new string[2] { text5, "XuanXiang.json" }), value2[2].Print(true).DecodeJsonUnicode());
				File.WriteAllText(Utility.CombinePaths(new string[2] { text5, "fubentime.json" }), value2[3].Print(true).DecodeJsonUnicode());
			}
		}

		private static void ResetYSDictionary(JSONObject json, YSDictionary<string, JSONObject> dict)
		{
			json.Clear();
			foreach (KeyValuePair<string, JSONObject> item in ((IEnumerable<KeyValuePair<string, JSONObject>>)dict).OrderBy((KeyValuePair<string, JSONObject> pair) => pair.Key))
			{
				json[item.Key] = ((Dictionary<string, JSONObject>)(object)dict)[item.Key];
			}
		}
	}
	public class ModConfig
	{
		[JsonIgnore]
		public Dictionary<string, string> JsonPathCache = new Dictionary<string, string>();

		public string Name { get; set; } = string.Empty;


		public string Author { get; set; } = string.Empty;


		public string Version { get; set; } = string.Empty;


		public string Description { get; set; } = string.Empty;


		[JsonConverter(typeof(ModSettingDefinitionListConverter))]
		public List<ModSettingDefinition> Settings { get; set; } = new List<ModSettingDefinition>();


		[JsonIgnore]
		public ModState State { get; set; }

		[JsonIgnore]
		public string Path { get; set; }

		[JsonIgnore]
		public Exception Exception { get; set; }

		/// <summary>
		/// 数据版本
		/// V1版本是老版本
		/// V2版本是新版本
		/// </summary>
		[JsonIgnore]
		public int DataVersion { get; set; } = 2;


		/// <summary>
		/// 设置Key，由ModConfigGroup初始化
		/// </summary>
		[JsonIgnore]
		public string SettingKey { get; set; }

		public string GetModStateDescription()
		{
			string text = string.Empty;
			string text2 = string.Empty;
			switch (State)
			{
			case ModState.Unload:
				text = "Mod.Load.Unload".I18N();
				text2 = "#000000";
				break;
			case ModState.Disable:
				text = "Mod.Load.Disable".I18N();
				text2 = "#808080";
				break;
			case ModState.Loading:
				text = "Mod.Load.Loading".I18N();
				text2 = "#000000";
				break;
			case ModState.LoadSuccess:
				text = "Mod.Load.Success".I18N();
				text2 = "#00FFFF";
				break;
			case ModState.LoadFail:
				text = "Mod.Load.Fail".I18N();
				text2 = "#FF0000";
				break;
			}
			return "[color=" + text2 + "]" + text + "[/color]";
		}

		public string GetDataDir()
		{
			return GetDataDir(DataVersion);
		}

		/// <summary>
		/// 根据版本号获取游戏数据文件夹
		/// <br /> -1 - 最新版本
		/// <br /> 1 - V1版本
		/// <br /> 2 - V2版本
		/// </summary>
		/// <returns></returns>
		public string GetDataDir(int dataVersion)
		{
			if (dataVersion == 1)
			{
				return Path;
			}
			return Path + "/Data";
		}

		public string GetNDataDir()
		{
			return GetNDataDir(DataVersion);
		}

		/// <summary>
		/// 根据版本号获取Next数据文件夹
		/// <br /> -1 - 最新版本
		/// <br /> 1 - V1版本
		/// <br /> 2 - V2版本
		/// </summary>
		/// <returns></returns>
		public string GetNDataDir(int dataVersion)
		{
			if (dataVersion == 1)
			{
				return Path;
			}
			return Path + "/NData";
		}

		/// <summary>
		/// 配置文件夹
		/// </summary>
		/// <returns></returns>
		public string GetConfigDir()
		{
			if (DataVersion == 2)
			{
				return Path + "/Config";
			}
			return Path;
		}

		public string GetAssetDir()
		{
			return Path + "/Assets";
		}

		public void Reload()
		{
			ModConfig modConfig = Load(Path, ignoreWarning: true);
			Name = modConfig.Name;
			Author = modConfig.Author;
			Version = modConfig.Version;
			Description = modConfig.Description;
			Settings = modConfig.Settings;
		}

		public static ModConfig Load(string dir, bool ignoreWarning = false)
		{
			ModConfig modConfig = null;
			string path = Utility.CombinePaths(new string[2] { dir, "modConfig.json" });
			string path2 = Utility.CombinePaths(new string[3] { dir, "Config", "modConfig.json" });
			int dataVersion;
			if (File.Exists(path))
			{
				modConfig = ((JToken)JObject.Parse(File.ReadAllText(path))).ToObject<ModConfig>();
				dataVersion = 1;
			}
			else if (File.Exists(path2))
			{
				modConfig = ((JToken)JObject.Parse(File.ReadAllText(path2))).ToObject<ModConfig>();
				dataVersion = 2;
			}
			else
			{
				dataVersion = 1;
				if (!ignoreWarning)
				{
					Main.LogWarning("ModManager.ModConfigDontExist".I18N() + " dir : " + dir);
				}
			}
			modConfig = modConfig ?? new ModConfig();
			modConfig.DataVersion = dataVersion;
			modConfig.Path = dir;
			return modConfig;
		}

		public static void Save(string dir, ModConfig modConfig)
		{
			string path = dir + "/modConfig.json";
			string contents = JsonConvert.SerializeObject((object)modConfig, (Formatting)1);
			File.WriteAllText(path, contents);
		}
	}
	public class ModLoadException : Exception
	{
		public ModLoadException()
		{
		}

		public ModLoadException(string message)
			: base(message)
		{
		}

		public ModLoadException(string message, Exception inner)
			: base(message, inner)
		{
		}
	}
