		public static void GenerateBaseDataWithoutGUI()
		{
			Main.LogInfo("ModManager.GenerateBaseData".I18N());
			Stopwatch stopwatch = Stopwatch.StartNew();
			MainDataContainer.ExportMainData(dataContainer, Main.PathBaseDataDir.Value);
			long elapsedMilliseconds = stopwatch.ElapsedMilliseconds;
			FFlowchartTools.ExportAllFungusFlowchart(Main.PathBaseFungusDataDir.Value);
			long num = stopwatch.ElapsedMilliseconds - elapsedMilliseconds;
			stopwatch.Stop();
			Main.LogInfo(string.Format("所有数据导出完毕，总耗时\t {0} s".I18NTodo(), (float)stopwatch.ElapsedMilliseconds / 1000f));
			Main.LogIndent++;
			Main.LogInfo(string.Format("Data导出耗时\t：{0} s".I18NTodo(), (float)elapsedMilliseconds / 1000f));
			Main.LogInfo(string.Format("Fungus导出耗时\t：{0} s".I18NTodo(), (float)num / 1000f));
			Main.LogIndent--;
		}

