		public static void CheckModLoadState()
		{
			bool flag = false;
			StringBuilder stringBuilder = new StringBuilder();
			if (!_buildCacheSuccess)
			{
				stringBuilder.AppendLine("Mod缓存构建失败！请检查Mod数据内容！");
				flag = true;
			}
			ModConfig[] array = (from c in modGroups.SelectMany((ModGroup g) => g.ModConfigs)
				where c.Exception != null
				select c).ToArray();
			if (array.Length != 0)
			{
				stringBuilder.AppendLine("Mod加载出错！以下Mod加载出现异常，具体信息请查看Mod面板：\n" + string.Join("\n", array.Select((ModConfig mod) => Path.GetFileNameWithoutExtension(mod.Path) + "(" + (mod.Name ?? "Mod.Unknown".I18N()) + ")")));
				flag = true;
			}
			if (flag)
			{
				WindowConfirmDialog.CreateDialog("提示".I18NTodo(), stringBuilder.ToString(), canCancel: false);
			}
		}

		public static void RestoreBaseData()
		{
			Type[] types = Assembly.GetAssembly(typeof(IJSONClass)).GetTypes();
			List<Type> list = new List<Type>();
			Type[] array = types;
			foreach (Type type in array)
			{
				if (type.IsInterface)
				{
					continue;
				}
				Type[] interfaces = type.GetInterfaces();
				for (int j = 0; j < interfaces.Length; j++)
				{
					if (interfaces[j] == typeof(IJSONClass))
					{
						list.Add(type);
					}
				}
			}
			foreach (Type item in list)
			{
				(item.GetField("DataDict", BindingFlags.Static | BindingFlags.Public)?.GetValue(null) as IDictionary)?.Clear();
				(item.GetField("DataList", BindingFlags.Static | BindingFlags.Public)?.GetValue(null) as IList)?.Clear();
			}
			SkillBox inst = SkillBox.inst;
			if (inst != null)
			{
				inst.clear();
			}
			MainDataContainer.CoverMainData(dataContainer);
		}

		public static void RestoreNextData()
		{
			DialogAnalysis.Clear();
			StaticFaceUtils.Clear();
			Main.Lua.Reset();
			Main.FGUI.Reset();
			Main.Res.Reset();
			Main.FPatch.Reset();
		}

		public static void LoadAllMod()
		{
			Main.LogInfo("===================" + "ModManager.LoadingModData".I18N() + "=====================");
			jsonData instance = jsonData.instance;
			ReloadModMeta(resetModState: true, showLog: true);
			foreach (ModGroup modGroup in modGroups)
			{
				foreach (ModConfig modConfig in modGroup.ModConfigs)
				{
					if (!Main.I.NextModSetting.GetOrCreateModSetting(modConfig).enable)
					{
						modConfig.State = ModState.Disable;
						continue;
					}
					try
					{
						LoadModData(modConfig);
					}
					catch (Exception ex)
					{
						Main.LogError(string.Format("ModManager.LoadFail".I18N(), modGroup.GroupKey, modConfig.Path));
						Main.LogError(ex);
						modConfig.Exception = ex;
					}
				}
			}
			_buildCacheSuccess = false;
			try
			{
				instance.Buff.Clear();
				instance.InitBuff();
				_buildCacheSuccess = true;
			}
			catch (Exception obj)
			{
				Main.LogError(obj);
			}
			if (!CheckData.Check())
			{
				Main.LogError(CheckData.log);
			}
		}

		/// <summary>
		/// 重载mod元数据
		/// </summary>
		/// <param name="resetModState">是否重置Mod状态</param>
		/// <param name="showLog"></param>
		public static void ReloadModMeta(bool resetModState, bool showLog = false)
		{
			if (resetModState)
			{
				modGroups.Clear();
			}
			DirectoryInfo directoryInfo = new DirectoryInfo(Main.PathLocalModsDir.Value);
			foreach (DirectoryInfo dir2 in WorkshopTool.GetAllModDirectory())
			{
				if (WorkshopTool.CheckModIsDisable(dir2.Name))
				{
					continue;
				}
				if (resetModState)
				{
					if (Directory.Exists(dir2?.ToString() + "\\plugins\\Next"))
					{
						ModGroup item = new ModGroup(dir2, ModType.Workshop);
						modGroups.Add(item);
					}
				}
				else if (Directory.Exists(dir2?.ToString() + "\\plugins\\Next"))
				{
					ModGroup modGroup = modGroups.Find((ModGroup x) => x.ModDir.FullName == dir2.FullName);
					if (modGroup == null)
					{
						modGroup = new ModGroup(dir2, ModType.Workshop);
						modGroups.Add(modGroup);
					}
				}
				else
				{
					ModGroup modGroup2 = modGroups.Find((ModGroup x) => x.ModDir.FullName == dir2.FullName);
					if (modGroup2 != null)
					{
						modGroups.Remove(modGroup2);
					}
				}
			}
			DirectoryInfo[] directories = directoryInfo.GetDirectories();
			foreach (DirectoryInfo dir in directories)
			{
				if (resetModState)
				{
					if (Directory.Exists(dir?.ToString() + "\\plugins\\Next"))
					{
						ModGroup item2 = new ModGroup(dir, ModType.Local);
						modGroups.Add(item2);
					}
				}
				else if (Directory.Exists(dir?.ToString() + "\\plugins\\Next"))
				{
					ModGroup modGroup3 = modGroups.Find((ModGroup x) => x.ModDir.FullName == dir.FullName);
					if (modGroup3 == null)
					{
						modGroup3 = new ModGroup(dir, ModType.Local);
						modGroups.Add(modGroup3);
					}
				}
				else
				{
					ModGroup modGroup4 = modGroups.Find((ModGroup x) => x.ModDir.FullName == dir.FullName);
					if (modGroup4 != null)
					{
						modGroups.Remove(modGroup4);
					}
				}
			}
			foreach (ModGroup modGroup5 in modGroups)
			{
				modGroup5.Init(resetModState, showLog);
				foreach (ModConfig modConfig in modGroup5.ModConfigs)
				{
					InitSettingData(modConfig);
				}
			}
			modGroups = SortModGroup(modGroups).ToList();
			ApplyModSetting(applySubMod: true);
			if (resetModState)
			{
				SaveSetting();
			}
		}

		private static void InitJSONClassData()
		{
			Type[] types = Assembly.GetAssembly(typeof(IJSONClass)).GetTypes();
			List<Type> list = new List<Type>();
			Type[] array = types;
			foreach (Type type in array)
			{
				if (type.IsInterface)
				{
					continue;
				}
				Type[] interfaces = type.GetInterfaces();
				for (int j = 0; j < interfaces.Length; j++)
				{
					if (interfaces[j] == typeof(IJSONClass))
					{
						list.Add(type);
					}
				}
			}
			foreach (Type item in list)
			{
				MethodInfo method = item.GetMethod("InitDataDict");
				if (method != null)
				{
					method.Invoke(null, null);
				}
			}
		}

		/// <summary>
		/// 加载Mod配置
		/// </summary>
		/// <param name="dir"></param>
		/// <param name="showLog"></param>
		/// <returns></returns>
		public static ModConfig LoadModConfig(string dir, bool showLog)
		{
			ModConfig modConfig = GetModConfig(dir);
			if (showLog)
			{
				Main.LogInfo(string.Format("ModManager.LoadMod".I18N(), dir));
			}
			return modConfig;
		}

		/// <summary>
		/// Mod组排序
		/// </summary>
		/// <param name="modEnumerable"></param>
		/// <returns></returns>
		public static IEnumerable<ModGroup> SortModGroup(IEnumerable<ModGroup> modEnumerable)
		{
			ModGroup[] source = modEnumerable.ToArray();
			NextModSetting nextModSetting = Main.I.NextModSetting;
			return from modGroup in source
				select nextModSetting.GetOrCreateModGroupSetting(modGroup) into modSetting
				orderby modSetting.priority, modSetting.BindGroup.GroupKey
				select modSetting into data
				select data.BindGroup;
		}

		/// <summary>
		/// Mod排序
		/// </summary>
		/// <param name="modEnumerable"></param>
		/// <returns></returns>
		public static IEnumerable<ModConfig> SortMod(IEnumerable<ModConfig> modEnumerable)
		{
			ModConfig[] source = modEnumerable.ToArray();
			NextModSetting nextModSetting = Main.I.NextModSetting;
			return from modConfig in source
				select nextModSetting.GetOrCreateModSetting(modConfig) into modSetting
				orderby modSetting.priority, modSetting.BindMod.SettingKey
				select modSetting into data
				select data.BindMod;
		}

		/// <summary>
		/// 应用并重设Mod排序优先级
		/// </summary>
		/// <param name="applySubMod"></param>
		public static void ApplyModSetting(bool applySubMod)
		{
			int num = 0;
			NextModSetting nextModSetting = Main.I.NextModSetting;
			foreach (ModGroup modGroup in modGroups)
			{
				nextModSetting.GetOrCreateModGroupSetting(modGroup).priority = num++;
				if (applySubMod)
				{
					modGroup.ApplyModSetting();
				}
			}
		}

		private static void LoadModData(ModConfig modConfig)
		{
			Main.LogInfo("===================" + "ModManager.StartLoadMod".I18N() + "=====================");
			string dataDir = modConfig.GetDataDir();
			string nDataDir = modConfig.GetNDataDir();
			Main.LogInfo("Mod.Directory".I18N() + " : " + Path.GetFileNameWithoutExtension(modConfig.Path));
			Main.LogIndent = 1;
			Main.LogInfo("Mod.Name".I18N() + " : " + modConfig.Name);
			Main.LogInfo("Mod.Author".I18N() + " : " + modConfig.Author);
			Main.LogInfo("Mod.Version".I18N() + " : " + modConfig.Version);
			Main.LogInfo("Mod.Description".I18N() + " : " + modConfig.Description);
			try
			{
				jsonData instance = jsonData.instance;
				modConfig.State = ModState.Loading;
				FieldInfo[] array = jsonDataFields;
				foreach (FieldInfo fieldInfo in array)
				{
					try
					{
						if (IsBanField(fieldInfo))
						{
							continue;
						}
						object value = fieldInfo.GetValue(instance);
						JSONObject val = (JSONObject)((value is JSONObject) ? value : null);
						if (val != null)
						{
							string text = Utility.CombinePaths(new string[2]
							{
								dataDir,
								fieldInfo.Name + ".json"
							});
							modConfig.JsonPathCache.Add(fieldInfo.Name, text);
							PatchJsonObject(fieldInfo, text, val);
							continue;
						}
						JObject val2 = (JObject)((value is JObject) ? value : null);
						if (val2 != null)
						{
							string text2 = Utility.CombinePaths(new string[2]
							{
								dataDir,
								fieldInfo.Name + ".json"
							});
							modConfig.JsonPathCache.Add(fieldInfo.Name, text2);
							PatchJObject(fieldInfo, text2, val2);
						}
						else if (value is YSDictionary<string, JSONObject> dicData)
						{
							string text3 = Utility.CombinePaths(new string[2] { dataDir, fieldInfo.Name });
							object value2 = typeof(jsonData).GetField("_" + fieldInfo.Name).GetValue(instance);
							JSONObject toJsonObject = (JSONObject)((value2 is JSONObject) ? value2 : null);
							modConfig.JsonPathCache.Add(fieldInfo.Name, text3);
							PatchStrDicData(fieldInfo, text3, dicData, toJsonObject);
						}
						else if (value is JSONObject[] jsonObjects)
						{
							string text4 = Utility.CombinePaths(new string[2] { dataDir, fieldInfo.Name });
							modConfig.JsonPathCache.Add(fieldInfo.Name, text4);
							PatchJsonObjectArray(fieldInfo, text4, jsonObjects);
						}
					}
					catch (Exception inner)
					{
						throw new ModLoadException(string.Format("加载 Data【{0}】数据失败".I18NTodo(), fieldInfo.Name), inner);
					}
				}
				PatchIntDicData(Utility.CombinePaths(new string[2] { dataDir, "AIJsonDate" }), instance.AIJsonDate);
				PatchFubenDicData(Utility.CombinePaths(new string[2] { dataDir, "FuBenJsonData" }), instance.FuBenJsonData);
				LoadDialogEventData(nDataDir);
				LoadDialogTriggerData(nDataDir);
				LoadCustomFaceData(nDataDir);
				LoadFPatchData(nDataDir);
				LoadCustomLuaData(modConfig, modConfig.Path + "/Lua");
				Main.Res.CacheAssetDir(modConfig.Path + "/Assets");
				Main.Res.CacheAssetBundleDir(modConfig.Path + "/AssetBundles");
			}
			catch (Exception)
			{
				modConfig.State = ModState.LoadFail;
				throw;
			}
			modConfig.State = ModState.LoadSuccess;
			Main.LogIndent = 0;
			Main.LogInfo("===================" + "ModManager.LoadModComplete".I18N() + "=====================");
		}

		public static bool IsBanField(FieldInfo fieldInfo)
		{
			if (fieldInfo.Name.StartsWith("_"))
			{
				return true;
			}
			if (fieldInfo.Name == "BadWord")
			{
				return true;
			}
			if (fieldInfo.CustomAttributes.FirstOrDefault((CustomAttributeData attr) => attr.AttributeType == typeof(ObsoleteAttribute)) != null)
			{
				return true;
			}
			return false;
		}

		private static ModConfig GetModConfig(string dir)
		{
			ModConfig modConfig = null;
			try
