		public static void PatchJsonObjectArray(FieldInfo fieldInfo, string dirPathForData, JSONObject[] jsonObjects)
		{
			if (!Directory.Exists(dirPathForData))
			{
				return;
			}
			for (int i = 0; i < jsonObjects.Length; i++)
			{
				if (jsonObjects[i] != null)
				{
					string filePath = Utility.CombinePaths(new string[2]
					{
						dirPathForData,
						$"{i}.json"
					});
					PatchJsonObject(fieldInfo, filePath, jsonObjects[i], Path.GetFileNameWithoutExtension(dirPathForData) + "/");
				}
			}
		}

		public static void PatchJsonObject(FieldInfo fieldInfo, string filePath, JSONObject jsonObject, string dirName = "")
		{
			try
			{
				JSONObject val = null;
				if (jsonObject.Count > 0)
				{
					val = jsonObject[0];
				}
				if (!File.Exists(filePath) || !IsJsonFilePath(filePath))
				{
					return;
				}
				string fileNameWithoutExtension = Path.GetFileNameWithoutExtension(filePath);
				JSONObject val2 = LoadJSONObject(filePath);
				foreach (string key in val2.keys)
				{
					JSONObject field = val2.GetField(key);
					if (jsonObject.HasField(key))
					{
						JSONObject field2 = jsonObject.GetField(key);
						foreach (string key2 in field.keys)
						{
							field2.TryAddOrReplace(key2, field.GetField(key2));
						}
						continue;
					}
					if (val != null)
					{
						foreach (string key3 in val.keys)
						{
							if (!field.HasField(key3))
							{
								field.AddField(key3, val[key3].Clone());
								Main.LogWarning(string.Format("ModManager.DataMissingField".I18N(), fieldInfo.Name, fileNameWithoutExtension, key3, val[key3]));
							}
						}
					}
					jsonObject.AddField(key, field);
				}
				Main.LogInfo(string.Format("ModManager.LoadData".I18N(), dirName + fileNameWithoutExtension + ".json"));
			}
			catch (Exception inner)
			{
				throw new ModLoadException("文件【" + filePath + "】加载失败", inner);
			}
		}

		public static void PatchJObject(FieldInfo fieldInfo, string filePath, JObject jObject)
		{
			//IL_003f: Unknown result type (might be due to invalid IL or missing references)
			//IL_0045: Invalid comparison between Unknown and I4
			//IL_0064: Unknown result type (might be due to invalid IL or missing references)
			//IL_006a: Expected O, but got Unknown
			//IL_0113: Unknown result type (might be due to invalid IL or missing references)
			//IL_0119: Invalid comparison between Unknown and I4
			//IL_0092: Unknown result type (might be due to invalid IL or missing references)
			//IL_0098: Invalid comparison between Unknown and I4
			//IL_009f: Unknown result type (might be due to invalid IL or missing references)
			//IL_00a6: Expected O, but got Unknown
			try
			{
				JToken value = jObject.Properties().First().Value;
				if (!File.Exists(filePath))
				{
					return;
				}
				foreach (JProperty item in LoadJObject(filePath).Properties())
				{
					if ((int)item.Value.Type != 1)
					{
						jObject.TryAddOrReplace(item.Name, item.Value);
						continue;
					}
					JObject val = (JObject)item.Value;
					if (jObject.ContainsKey(item.Name))
					{
						JToken value2 = jObject.GetValue(item.Name);
						if (value2 == null || (int)value2.Type != 1)
						{
							continue;
						}
						JObject val2 = (JObject)value2;
						foreach (JProperty item2 in val.Properties())
						{
							if (val2.ContainsKey(item2.Name))
							{
								val2.Remove(item2.Name);
							}
							val2.Add(item2.Name, val.GetValue(item2.Name));
						}
						continue;
					}
					if ((int)value.Type == 1)
					{
						foreach (JProperty item3 in JObject.FromObject((object)value).Properties())
						{
							if (!val.ContainsKey(item3.Name))
							{
								((JContainer)val).Add((object)item3.Value.DeepClone());
								Main.LogWarning(string.Format("ModManager.DataMissingField".I18N(), fieldInfo.Name, item.Name, item3.Name, item3.Value));
							}
						}
					}
					jObject.Add(item.Name, item.Value.DeepClone());
				}
				Main.LogInfo(string.Format("ModManager.LoadData".I18N(), Path.GetFileNameWithoutExtension(filePath) + ".json"));
			}
			catch (Exception inner)
			{
				throw new ModLoadException("文件【" + filePath + "】加载失败", inner);
			}
		}

		public static void PatchStrDicData(FieldInfo fieldInfo, string dirPathForData, YSDictionary<string, JSONObject> dicData, JSONObject toJsonObject)
		{
			if (!Directory.Exists(dirPathForData))
			{
				return;
			}
			JSONObject val = toJsonObject[0];
			string[] files = Directory.GetFiles(dirPathForData);
			foreach (string text in files)
			{
				if (!IsJsonFilePath(text))
				{
					continue;
				}
				try
				{
					JSONObject val2 = LoadJSONObject(text);
					string fileNameWithoutExtension = Path.GetFileNameWithoutExtension(text);
					if (toJsonObject.HasField(fileNameWithoutExtension))
					{
						JSONObject field = toJsonObject.GetField(fileNameWithoutExtension);
						foreach (string key in val2.keys)
						{
							field.TryAddOrReplace(key, val2.GetField(key));
						}
					}
					else
					{
						foreach (string key2 in val.keys)
						{
							if (!val2.HasField(key2))
							{
								val2.AddField(key2, val[key2].Clone());
								Main.LogWarning(string.Format("ModManager.DataMissingField".I18N(), fieldInfo.Name, fileNameWithoutExtension, key2, val[key2]));
							}
						}
						((Dictionary<string, JSONObject>)(object)dicData)[fileNameWithoutExtension] = val2;
						toJsonObject.AddField(fileNameWithoutExtension, val2);
					}
					Main.LogInfo(string.Format("ModManager.LoadData".I18N(), Path.GetFileNameWithoutExtension(dirPathForData) + "/" + Path.GetFileNameWithoutExtension(text) + ".json [" + fileNameWithoutExtension + "]"));
				}
				catch (Exception inner)
				{
					throw new ModLoadException("文件 " + text + " 解析失败", inner);
				}
			}
		}

		private static void PatchIntDicData(string dirPathForData, Dictionary<int, JSONObject> dictionary)
		{
			if (!Directory.Exists(dirPathForData))
			{
				return;
			}
			string[] files = Directory.GetFiles(dirPathForData);
			foreach (string text in files)
			{
				if (!IsJsonFilePath(text))
				{
					continue;
				}
				try
				{
					JSONObject val = LoadJSONObject(text);
					string fileNameWithoutExtension = Path.GetFileNameWithoutExtension(text);
					if (!int.TryParse(fileNameWithoutExtension, out var result))
					{
						throw new ModLoadException("不合法的文件ID " + text + " ，文件名必须为数字");
					}
					if (dictionary.TryGetValue(result, out var value))
					{
						foreach (string key in val.keys)
						{
							value.TryAddOrReplace(key, val.GetField(key));
						}
					}
					else
					{
						dictionary[result] = val;
					}
					Main.LogInfo(string.Format("ModManager.LoadData".I18N(), Path.GetFileNameWithoutExtension(dirPathForData) + "/" + Path.GetFileNameWithoutExtension(text) + ".json [" + fileNameWithoutExtension + "]"));
				}
				catch (Exception inner)
				{
					throw new ModLoadException("文件 " + text + " 解析失败", inner);
				}
			}
		}

		private static void PatchFubenDicData(string dirPathForData, Dictionary<int, List<JSONObject>> fuBenJsonData)
		{
			//IL_0062: Unknown result type (might be due to invalid IL or missing references)
			//IL_006c: Expected O, but got Unknown
			if (!Directory.Exists(dirPathForData))
			{
				return;
			}
			string[] directories = Directory.GetDirectories(dirPathForData);
			foreach (string text in directories)
			{
				if (!int.TryParse(Path.GetFileNameWithoutExtension(text), out var result))
				{
					throw new ModLoadException("不合法的文件夹ID " + text + " ，文件名必须为数字");
				}
				if (!fuBenJsonData.TryGetValue(result, out var value))
				{
					value = (fuBenJsonData[result] = new List<JSONObject>());
					for (int j = 0; j < 4; j++)
					{
						value.Add(new JSONObject());
					}
				}
				string filePath = Utility.CombinePaths(new string[2] { text, "RandomMap.json" });
				PatchFubenJsonData(value[0], filePath);
				filePath = Utility.CombinePaths(new string[2] { text, "ShiJian.json" });
				PatchFubenJsonData(value[1], filePath);
				filePath = Utility.CombinePaths(new string[2] { text, "XuanXiang.json" });
				PatchFubenJsonData(value[2], filePath);
				filePath = Utility.CombinePaths(new string[2] { text, "fubentime.json" });
				PatchFubenJsonData(value[3], filePath);
			}
		}

		private static void PatchFubenJsonData(JSONObject jsonData, string filePath)
		{
			try
			{
				JSONObject val = LoadJSONObject(filePath);
				foreach (string key in val.keys)
				{
					jsonData.TryAddOrReplace(key, val.GetField(key));
				}
			}
			catch (Exception inner)
			{
				throw new ModLoadException("文件 " + filePath + " 解析失败", inner);
			}
		}

