		private static void LoadCustomLuaData(ModConfig modConfig, string rootPath)
		{
			FileUtils.DirectoryHandle("", rootPath, delegate(string virtualPath, string filePath)
			{
				if (Path.GetExtension(filePath) != ".lua")
				{
					return;
				}
				LuaFileCache luaCache = new LuaFileCache
				{
					FromMod = modConfig,
					FilePath = filePath.Replace("\\", "/")
				};
				string text = virtualPath.Substring(0, virtualPath.Length - 4).Replace("\\", "/");
				if (text.StartsWith("/"))
				{
					text = text.Substring(1);
				}
				try
				{
					Main.Lua.AddLuaCacheFile(text, luaCache);
				}
				catch (Exception inner)
				{
					throw new ModLoadException(string.Format("Lua {0} 加载失败。".I18NTodo(), text), inner);
				}
			});
		}

		private static void InitSettingData(ModConfig modConfig)
		{
			foreach (ModSettingDefinition setting in modConfig.Settings)
			{
				if (setting is ModSettingDefinition_Custom modSettingDefinition_Custom)
				{
					(GetCustomSetting(modSettingDefinition_Custom.CustomType) ?? throw new ModLoadException(string.Format("自定义Mod设置类型：{0}不存在".I18NTodo(), modSettingDefinition_Custom.CustomType))).OnInit(modSettingDefinition_Custom);
				}
				else
				{
					setting.OnInit();
				}
			}
		}

