		public static WorkShopItem ReadConfig(string path)
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			//IL_0006: Expected O, but got Unknown
			//IL_002f: Unknown result type (might be due to invalid IL or missing references)
			//IL_0035: Expected O, but got Unknown
			WorkShopItem result = new WorkShopItem();
			string path2 = path + "/Mod.bin";
			if (File.Exists(path2))
			{
				try
				{
					FileStream fileStream = new FileStream(path2, FileMode.Open, FileAccess.Read, FileShare.Read);
					result = (WorkShopItem)new BinaryFormatter().Deserialize(fileStream);
					fileStream.Close();
				}
				catch (Exception obj)
				{
					Main.LogError(obj);
					Main.LogError("读取配置文件失败".I18NTodo());
				}
			}
			return result;
		}

