		public ModMainWindow()
			: base("NextCore", "ModMainPanel")
		{
		}

		protected override void OnInit()
		{
			base.OnInit();
			base.modal = true;
			_modLoadSettingDirty = false;
			_modDataSettingDirty = false;
			RefreshTitle();
			MainView.m_frame.m_closeButton.onClick.Add(OnClickClose);
			MainView.m_btnApply.onClick.Add(OnClickApply);
			MainView.m_btnApply.text = "应用".I18NTodo();
			InitProject();
			InitInspector();
			InitLink();
			FGUIUtils.BindHSeg(MainView.m_seg, () => MainView.width * 0.2f, () => MainView.width * 0.8f);
			MakeFullScreenAndCenter(0.8f);
			Refresh();
		}

		protected override void DoShowAnimation()
		{
			//IL_000b: Unknown result type (might be due to invalid IL or missing references)
			//IL_0021: Unknown result type (might be due to invalid IL or missing references)
			//IL_0032: Unknown result type (might be due to invalid IL or missing references)
			base.pivot = new Vector2(0.5f, 0.5f);
			base.alpha = 0f;
			base.scale = Vector2.zero;
			Center();
			TweenScale(Vector2.one, 0.3f).SetEase(EaseType.CubicOut);
			TweenFade(1f, 0.3f).OnComplete(OnShown);
		}

		protected override void DoHideAnimation()
		{
			TweenFade(0f, 0.2f).OnComplete(base.HideImmediately);
		}

		protected override void OnKeyDown(EventContext context)
		{
			//IL_000d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0014: Invalid comparison between Unknown and I4
			base.OnKeyDown(context);
			if ((int)context.inputEvent.keyCode == 27)
			{
				Close();
			}
		}

		protected override void OnHide()
		{
			base.OnHide();
			ModManager.LoadSetting();
		}

		private void RefreshTitle()
		{
			if (!ModSettingDirty)
			{
				base.frame.asLabel.title = "Next  v0.9.1";
			}
			else
			{
				base.frame.asLabel.title = "* Next  v0.9.1";
			}
		}

		private void InitInspector()
		{
			Inspector = new CtlPropertyInspector(MainView.m_inspector);
			Inspector.OnPropertyChanged += delegate
			{
				ModDataSettingDirty = true;
			};
		}

		private void InitProject()
		{
			ModTree = new CtlTreeProject(MainView.m_mods);
			ModTree.SetRenderItem(OnRenderTreeItem);
			ModTree.SetClickItem(OnInspectMod);
			ModTree.ToolsBar.AddToolBtn("ui://NextCore/icon_reset", "刷新", Refresh);
			ModTree.ToolsBar.AddToolSep();
			ModTree.ToolsBar.AddToolBtn("ui://NextCore/icon_arrow1", "上移", OnClickMoveUp);
			ModTree.ToolsBar.AddToolBtn("ui://NextCore/icon_arrow2", "下移", OnClickMoveDown);
			ModTree.ToolsBar.AddToolSep();
			ModTree.ToolsBar.AddToolBtn("ui://NextCore/icon_true", "启用全部", OnClickEnableAllMod);
			ModTree.ToolsBar.AddToolBtn("ui://NextCore/icon_false", "禁用全部", OnClickDisableAllMod);
		}

		private void InitLink()
		{
			GList listLink = MainView.m_listLink;
			GObject gObject = listLink.AddItemFromPool();
			gObject.text = "觅长生 Wiki";
			gObject.onClick.Add((EventCallback0)delegate
			{
				Application.OpenURL("https://wiki.biligame.com/mcs/%E9%A6%96%E9%A1%B5");
			});
			gObject.cursor = "hand";
			GObject gObject2 = listLink.AddItemFromPool();
			gObject2.text = "Next Mod文档";
			gObject2.onClick.Add((EventCallback0)delegate
			{
				Application.OpenURL("https://wiki.biligame.com/mcs/Next%E9%A6%96%E9%A1%B5");
			});
			gObject2.cursor = "hand";
		}

		private void Refresh()
		{
			ModManager.ReloadModMeta(resetModState: false);
			Inspector.Clear();
			ModTree.RemoveAllProjects();
			foreach (ModGroup modGroup in ModManager.modGroups)
			{
				ProjectTreeFolderModGroup projectTreeFolderModGroup = new ProjectTreeFolderModGroup(modGroup);
				projectTreeFolderModGroup.RefreshModConfigs(recreate: true);
				ModTree.AddProject(projectTreeFolderModGroup);
			}
			RefreshTitle();
		}

		private void OnInspectMod(EventContext context, ProjectTreeNodeBase node)
		{
			Inspector.Clear();
			if (node is ProjectTreeItemModConfig projectTreeItemModConfig)
			{
				projectTreeItemModConfig.OnInspector(Inspector);
			}
			else if (node is ProjectTreeFolderModGroup projectTreeFolderModGroup)
			{
				projectTreeFolderModGroup.OnInspector(Inspector);
			}
			Inspector.Refresh();
		}

		private void OnRenderTreeItem(GTreeNode gTreeNode, ProjectTreeNodeBase node)
		{
			ProjectTreeItemModConfig modItem = node as ProjectTreeItemModConfig;
			if (modItem == null)
			{
				return;
			}
			UI_BtnTreeItemMod item = (UI_BtnTreeItemMod)gTreeNode.cell;
			ModConfigSetting orCreateModSetting = Main.I.NextModSetting.GetOrCreateModSetting(modItem.ModConfig);
			item.m_tglEnable.selected = orCreateModSetting.enable;
			if (modItem.ModGroup.Type == ModType.Local)
			{
				item.m_tglEnable.enabled = true;
				item.m_tglEnable.onChanged.Set((EventCallback0)delegate
				{
					ModManager.ModSetEnable(modItem.ModConfig, item.m_tglEnable.selected);
					ModLoadSettingDirty = true;
				});
			}
			else
			{
				item.m_tglEnable.enabled = false;
				item.m_tglEnable.onChanged.Clear();
			}
		}

		private void OnClickClose(EventContext context)
		{
			Close();
		}

		private void Close()
		{
			if (ModSettingDirty)
			{
				WindowConfirmDialog.CreateDialog("提示", "检测到Mod设置已经发生变更，是否不保存并退出？", canCancel: true, base.Hide);
			}
			else
			{
				Hide();
			}
		}

