		private ProjectTreeNodeBase GetSelectedNode()
		{
			return ModTree.GetSelectedNode()?.data as ProjectTreeNodeBase;
		}

		private void OnClickMoveUp()
		{
			ProjectTreeNodeBase selectedNode = GetSelectedNode();
			if (selectedNode is ProjectTreeItemModConfig projectTreeItemModConfig)
			{
				projectTreeItemModConfig.ModGroup.MoveModUp(projectTreeItemModConfig.ModConfig);
				((ProjectTreeFolderModGroup)projectTreeItemModConfig.Parent).RefreshModConfigs();
				ModLoadSettingDirty = true;
			}
			else if (selectedNode is ProjectTreeFolderModGroup projectTreeFolderModGroup)
			{
				ModManager.ModGroupMoveUp(projectTreeFolderModGroup.ModGroup);
				ModTree.MoveProjectUp(projectTreeFolderModGroup);
				ModLoadSettingDirty = true;
			}
			if (selectedNode != null)
			{
				ModTree.SelectNode(selectedNode);
			}
		}

		private void OnClickMoveDown()
		{
			ProjectTreeNodeBase selectedNode = GetSelectedNode();
			if (selectedNode is ProjectTreeItemModConfig projectTreeItemModConfig)
			{
				projectTreeItemModConfig.ModGroup.MoveModDown(projectTreeItemModConfig.ModConfig);
				((ProjectTreeFolderModGroup)projectTreeItemModConfig.Parent).RefreshModConfigs();
				ModLoadSettingDirty = true;
			}
			else if (selectedNode is ProjectTreeFolderModGroup projectTreeFolderModGroup)
			{
				ModManager.ModGroupMoveDown(projectTreeFolderModGroup.ModGroup);
				ModTree.MoveProjectDown(projectTreeFolderModGroup);
				ModLoadSettingDirty = true;
			}
			if (selectedNode != null)
			{
				ModTree.SelectNode(selectedNode);
			}
		}

		private void OnClickDisableAllMod()
		{
			ModManager.ModSetEnableAll(b: false);
			Refresh();
			ModLoadSettingDirty = true;
		}

		private void OnClickEnableAllMod()
		{
			ModManager.ModSetEnableAll(b: true);
			Refresh();
			ModLoadSettingDirty = true;
		}
	}
	public class ProjectTreeFolderModGroup : ProjectTreeFolder
	{
		public ModGroup ModGroup { get; }

		public override string Name
		{
			get
			{
				if (string.IsNullOrEmpty(ModGroup.GroupName))
				{
					return "??? [id:" + ModGroup.GroupKey + "]";
				}
				return ModGroup.GroupName ?? "";
			}
		}

		public ProjectTreeFolderModGroup(ModGroup group)
		{
			ModGroup = group;
			switch (ModGroup.Type)
			{
			case ModType.Local:
				_icon = "ui://NextCore/icon_folder1";
				break;
			case ModType.Workshop:
				_icon = "ui://NextCore/icon_steam";
				break;
			default:
				throw new ArgumentOutOfRangeException();
			}
		}

		public void RefreshModConfigs(bool recreate = false)
		{
			List<ProjectTreeNodeBase> list = Children.ToList();
			RemoveAllChildren();
			foreach (ModConfig modConfig in ModGroup.ModConfigs)
			{
				ProjectTreeNodeBase projectTreeNodeBase = list.Find((ProjectTreeNodeBase x) => x is ProjectTreeItemModConfig projectTreeItemModConfig && projectTreeItemModConfig.ModConfig == modConfig);
				if (projectTreeNodeBase != null && !recreate)
				{
					AddChild(projectTreeNodeBase);
				}
				else
				{
					AddChild(new ProjectTreeItemModConfig(modConfig, ModGroup));
				}
			}
		}

		public void OnInspector(CtlPropertyInspector inspector)
		{
			string groupKey = ModGroup.GroupKey;
			string content = ((ModGroup.Type == ModType.Local) ? "本地Mod" : "工坊Mod");
			string fullName = ModGroup.ModDir.FullName;
			string des = ModGroup.SteamModInfo.Des;
			inspector.AddDrawer(new CtlTitleDrawer(Name));
			inspector.AddDrawer(new CtlInfoDrawer("ID".I18NTodo(), groupKey, 16));
			inspector.AddDrawer(new CtlInfoDrawer("来源".I18NTodo(), content, 16));
			inspector.AddDrawer(new CtlInfoLinkDrawer("路径".I18NTodo(), fullName, 16, fullName));
			inspector.AddDrawer(new CtlInfoDrawer("包含Mod数量".I18NTodo(), ModGroup.ModConfigs.Count.ToString(), 16));
			inspector.AddDrawer(new CtlInfoDrawer("描述".I18NTodo(), des, 16));
		}
	}
	public class ProjectTreeItemModConfig : ProjectTreeItem
	{
		public ModConfig ModConfig { get; }

		public ModGroup ModGroup { get; }

		public override string ResURL => "ui://NextCore/BtnTreeItemMod";

		public override string Name => ModConfig.Name + " - " + ModConfig.Version + " (" + Path.GetFileNameWithoutExtension(ModConfig.Path) + ")";

		public ProjectTreeItemModConfig(ModConfig config, ModGroup group)
		{
			ModConfig = config;
			ModGroup = group;
		}

		public void OnInspector(CtlInspectorBase inspector)
		{
			string text = ModConfig.Path ?? "Mod.Unknown".I18N();
			string title = ModConfig.Name ?? "Mod.Unknown".I18N();
			string content = ModConfig.Author ?? "Mod.Unknown".I18N();
			string content2 = ModConfig.Version ?? "Mod.Unknown".I18N();
			string content3 = ModConfig.Description ?? "Mod.Unknown".I18N();
			inspector.AddDrawer(new CtlTitleDrawer(title));
			CtlGroupDrawer ctlGroupDrawer = new CtlGroupDrawer("Mod信息".I18NTodo(), true, new CtlInfoDrawer("Mod.State".I18N(), ModConfig.GetModStateDescription(), 16), new CtlInfoDrawer("Mod.Author".I18N(), content, 16), new CtlInfoDrawer("Mod.Version".I18N(), content2, 16), new CtlInfoDrawer("Mod.Description".I18N(), content3, 16), new CtlInfoLinkDrawer("Mod.Directory".I18N(), text, 16, text));
			if (ModConfig.Exception != null)
			{
				ctlGroupDrawer.AddDrawer(new CtlInfoDrawer("Mod.Exception".I18N(), ModConfig.Exception.ToString(), 16));
			}
			CtlGroupDrawer ctlGroupDrawer2 = new CtlGroupDrawer("Mod设置".I18NTodo(), true);
			foreach (ModSettingDefinition setting in ModConfig.Settings)
			{
				if (setting is ModSettingDefinition_Custom modSettingDefinition_Custom)
				{
					ModManager.GetCustomSetting(modSettingDefinition_Custom.CustomType).OnDrawer(modSettingDefinition_Custom, ctlGroupDrawer2);
				}
				else
				{
					setting.OnDrawer(ctlGroupDrawer2);
				}
			}
			inspector.AddDrawer(ctlGroupDrawer);
			if (ctlGroupDrawer2.Drawers.Count > 0)
			{
				inspector.AddDrawer(ctlGroupDrawer2);
			}
		}
	}
}
