	{
		private Dictionary<string, string> _translation = new Dictionary<string, string>();

		public static List<NextLanguage> Languages { get; set; } = new List<NextLanguage>();


		public string LanguageDir { get; set; }

		public NextLanguageConfig Config { get; set; }

		public Dictionary<string, string> Translation => _translation;

		public static void InitLanguage()
		{
			//IL_009a: Unknown result type (might be due to invalid IL or missing references)
			Languages.Clear();
			Main.LogInfo("Load language folder : " + Main.PathLanguageDir.Value);
			string[] directories = Directory.GetDirectories(Main.PathLanguageDir.Value);
			foreach (string text in directories)
			{
				try
				{
					string text2 = Path.Combine(text, "language.json");
					if (!File.Exists(text2))
					{
						Main.LogWarning("language config [" + text2 + "] not find in " + text + "!");
						continue;
					}
					NextLanguageConfig nextLanguageConfig = JsonConvert.DeserializeObject<NextLanguageConfig>(File.ReadAllText(text2));
					if (nextLanguageConfig == null)
					{
						throw new JsonException("json data is invalid.");
					}
					NextLanguage nextLanguage = new NextLanguage
					{
						LanguageDir = text,
						Config = nextLanguageConfig
					};
					nextLanguage.LoadLocalization();
					Languages.Add(nextLanguage);
				}
				catch (Exception obj)
				{
					Main.LogError("Load language file " + text + " error!");
					Main.LogError(obj);
				}
			}
		}

		private void LoadLocalization()
		{
			//IL_003f: Unknown result type (might be due to invalid IL or missing references)
			string path = Path.Combine(LanguageDir, "Localization");
			if (!Directory.Exists(path))
			{
				return;
			}
			string[] files = Directory.GetFiles(path);
			foreach (string text in files)
			{
				try
				{
					foreach (KeyValuePair<string, string> item in JsonConvert.DeserializeObject<Dictionary<string, string>>(File.ReadAllText(text)) ?? throw new JsonException("json data is invalid."))
					{
						if (_translation.ContainsKey(item.Key))
						{
							Main.LogWarning("Localization key " + item.Key + " is already exist.");
						}
						_translation[item.Key] = item.Value;
					}
				}
				catch (Exception obj)
				{
					Main.LogError("Load localization file " + text + " error!");
					Main.LogError(obj);
				}
			}
		}

		public static string Get(NextLanguage language, string key)
		{
			if (language == null)
			{
				return key;
			}
			if (language.Translation.TryGetValue(key, out var value))
			{
				return value;
			}
			return key;
		}

		public static bool TryGetLanguageByDir(string languageDir, out NextLanguage language)
		{
			foreach (NextLanguage language2 in Languages)
			{
				if (language2.LanguageDir == languageDir)
				{
					language = language2;
					return true;
				}
			}
			language = null;
			return false;
		}
	}
	public class NextLanguageConfig
	{
		public string LanguageName { get; set; } = string.Empty;

	}
