	public class FGUIDragDropManager
	{
		private GLoader _agent;

		private object _sourceData;

		private GObject _source;

		private static FGUIDragDropManager _inst;

		public static FGUIDragDropManager inst
		{
			get
			{
				if (_inst == null)
				{
					_inst = new FGUIDragDropManager();
				}
				return _inst;
			}
		}

		/// <summary>
		/// Loader object for real dragging.
		/// 用于实际拖动的Loader对象。你可以根据实际情况设置loader的大小，对齐等。
		/// </summary>
		public GLoader dragAgent => _agent;

		/// <summary>
		/// Is dragging?
		/// 返回当前是否正在拖动。
		/// </summary>
		public bool dragging => _agent.parent != null;

		public FGUIDragDropManager()
		{
			_agent = (GLoader)UIObjectFactory.NewObject(ObjectType.Loader);
			_agent.gameObjectName = "DragDropAgent";
			_agent.SetHome(GRoot.inst);
			_agent.touchable = false;
			_agent.draggable = true;
			_agent.SetSize(100f, 100f);
			_agent.SetPivot(0.5f, 0.5f, asAnchor: true);
			_agent.align = AlignType.Center;
			_agent.verticalAlign = VertAlignType.Middle;
			_agent.sortingOrder = int.MaxValue;
			_agent.onDragMove.Add(__dragMove);
			_agent.onDragEnd.Add(__dragEnd);
		}

		/// <summary>
		/// Start dragging.
		/// 开始拖动。
		/// </summary>
		/// <param name="source">Source object. This is the object which initiated the dragging.</param>
		/// <param name="icon">Icon to be used as the dragging sign.</param>
		/// <param name="sourceData">Custom data. You can get it in the onDrop event data.</param>
		/// <param name="touchPointID">Copy the touchId from InputEvent to here, if has one.</param>
		public void StartDrag(GObject source, string icon, object sourceData, int touchPointID = -1)
		{
			//IL_004b: Unknown result type (might be due to invalid IL or missing references)
			//IL_0050: Unknown result type (might be due to invalid IL or missing references)
			if (_agent.parent == null)
			{
				_sourceData = sourceData;
				_source = source;
				_agent.url = icon;
				GRoot.inst.AddChild(_agent);
				_agent.xy = GRoot.inst.GlobalToLocal(Stage.inst.GetTouchPosition(touchPointID));
				_agent.StartDrag(touchPointID);
			}
		}

		/// <summary>
		/// Start dragging.
		/// 开始拖动。
		/// </summary>
		/// <param name="source">Source object. This is the object which initiated the dragging.</param>
		/// <param name="icon">Icon to be used as the dragging sign.</param>
		/// <param name="sourceData">Custom data. You can get it in the onDrop event data.</param>
		/// <param name="touchPointID">Copy the touchId from InputEvent to here, if has one.</param>
		public void StartDrag(GObject source, NTexture icon, object sourceData, int touchPointID = -1)
		{
			//IL_004b: Unknown result type (might be due to invalid IL or missing references)
			//IL_0050: Unknown result type (might be due to invalid IL or missing references)
			if (_agent.parent == null)
			{
				_sourceData = sourceData;
				_source = source;
				_agent.texture = icon;
				GRoot.inst.AddChild(_agent);
				_agent.xy = GRoot.inst.GlobalToLocal(Stage.inst.GetTouchPosition(touchPointID));
				_agent.StartDrag(touchPointID);
			}
		}

		/// <summary>
		/// Cancel dragging.
		/// 取消拖动。
		/// </summary>
		public void Cancel()
		{
			if (_agent.parent != null)
			{
				_agent.StopDrag();
				GRoot.inst.RemoveChild(_agent);
				_sourceData = null;
			}
		}

		private void __dragMove(EventContext context)
		{
			if (_source != null && _source.hasEventListeners("onDragMove"))
			{
				_source.DispatchEvent("onDragMove", _sourceData);
			}
		}

		private void __dragEnd(EventContext evt)
		{
			if (_agent.parent == null)
			{
				return;
			}
			GRoot.inst.RemoveChild(_agent);
			if (_source != null && _source.hasEventListeners("onDragEnd"))
			{
				_source.DispatchEvent("onDragEnd", _sourceData);
			}
			object sourceData = _sourceData;
			GObject source = _source;
			_sourceData = null;
			_source = null;
			for (GObject gObject = GRoot.inst.touchTarget; gObject != null; gObject = gObject.parent)
			{
				if (gObject.hasEventListeners("onDrop"))
				{
					gObject.RequestFocus();
					gObject.DispatchEvent("onDrop", sourceData, source);
					break;
				}
			}
		}
	}
	public class FGUIPanelBase
	{
		public string comName;

		public string pkgName;

		public RayBlocker RayBlocker;

		public GComponent contentPane { get; set; }

		public bool IsShowing { get; set; }

		private bool IsInit { get; set; }

		public bool IsModal { get; set; }

		public FGUIPanelBase(string pkgName, string comName)
		{
			this.pkgName = pkgName;
			this.comName = comName;
			contentPane = Main.FGUI.CreateUIObject(pkgName, comName).asCom;
		}

		protected virtual void OnInit()
		{
			//IL_0078: Unknown result type (might be due to invalid IL or missing references)
			RayBlocker = RayBlocker.CreateRayBlock(comName);
			if (!IsModal)
			{
				contentPane.onSizeChanged.Add(ResetRayBlocker);
				contentPane.onPositionChanged.Add(ResetRayBlocker);
			}
			else
			{
				RayBlocker.SetSize(new Rect(0f, 0f, GRoot.inst.width, GRoot.inst.height));
			}
		}

		public virtual void ResetRayBlocker()
		{
			//IL_0032: Unknown result type (might be due to invalid IL or missing references)
			RayBlocker.SetSize(new Rect(contentPane.x, contentPane.y, contentPane.width, contentPane.height));
		}

		public void Show()
		{
			if (!IsInit)
			{
				OnInit();
				IsInit = true;
			}
			GRoot.inst.AddChild(contentPane);
			DoShowAnimation();
		}

		public void Hide()
		{
			if (IsShowing)
			{
				DoHideAnimation();
			}
		}

		protected virtual void DoShowAnimation()
		{
			OnShown();
		}

		protected virtual void DoHideAnimation()
		{
			HideImmediately();
		}

		protected void HideImmediately()
		{
			GRoot.inst.RemoveChild(contentPane);
			IsShowing = false;
			OnHide();
		}

		protected virtual void OnShown()
		{
			IsShowing = true;
			RayBlocker.OpenBlocker();
			contentPane.RequestFocus();
		}

		protected virtual void OnHide()
		{
			RayBlocker.CloseBlocker();
			RayBlocker.DestroySelf();
			OnDispose();
			contentPane.Dispose();
		}

		protected virtual void OnDispose()
		{
		}

		/// <summary>
		/// 按缩放因子设置缩放大小并居中
		/// </summary>
		public void MakeFullScreenAndCenter()
		{
			contentPane.SetSize(GRoot.inst.width, GRoot.inst.height);
			contentPane.Center();
			ResetRayBlocker();
		}
	}
