		private void BindLuaTable()
		{
			Table = Main.Lua.RunScript<LuaTable>(ScriptPath);
			if (Table == null)
			{
				throw new Exception("Lua脚本加载失败：" + ScriptPath);
			}
			Table.Set("script", this);
			Table.Set("env", DialogEnvironment);
			Table.Set("contentPane", base.contentPane);
			Table.Get<string, Action>("OnInit", out LuaCallback_OnInit);
			Table.Get<string, Action>("DoShowAnimation", out LuaCallback_DoShowAnimation);
			Table.Get<string, Action>("DoHideAnimation", out LuaCallback_DoHideAnimation);
			Table.Get<string, Action>("OnShown", out LuaCallback_OnShown);
			Table.Get<string, Action>("OnHide", out LuaCallback_OnHide);
			Table.Get<string, Action>("OnUpdate", out LuaCallback_OnUpdate);
			Table.Get<string, EventCallback1>("OnKeyDown", out LuaCallback_OnKeyDown);
			Main.I.RegisterUpdateEvent(Update);
		}

		protected override void OnDispose()
		{
			base.OnDispose();
			Main.I.UnRegisterUpdateEvent(Update);
			OnCloseCallback?.Invoke();
		}

		protected override void OnInit()
		{
			base.OnInit();
			LuaCallback_OnInit?.Invoke();
		}

		protected override void DoShowAnimation()
		{
			if (LuaCallback_DoShowAnimation != null)
			{
				LuaCallback_DoShowAnimation();
			}
			else
			{
				base.DoShowAnimation();
			}
		}

		protected override void DoHideAnimation()
		{
			if (LuaCallback_DoHideAnimation != null)
			{
				LuaCallback_DoHideAnimation();
			}
			else
			{
				base.DoHideAnimation();
			}
		}

		protected override void OnShown()
		{
			base.OnShown();
			LuaCallback_OnShown?.Invoke();
		}

		protected override void OnHide()
		{
			LuaCallback_OnHide?.Invoke();
			base.OnHide();
		}

		protected override void OnKeyDown(EventContext context)
		{
			LuaCallback_OnKeyDown?.Invoke(context);
		}

		protected void Update()
		{
			if (base.isShowing)
			{
				LuaCallback_OnUpdate?.Invoke();
			}
		}
	}
