		public static string UHyperTextToFGUIText(string text)
		{
			if (string.IsNullOrEmpty(text))
			{
				return text;
			}
			StringBuilder stringBuilder = new StringBuilder();
			int num = 0;
			for (int i = 0; i < text.Length; i++)
			{
				char c = text[i];
				if (c == '#' && i + 1 < text.Length)
				{
					switch (text[i + 1])
					{
					case '#':
						stringBuilder.Append('#');
						i++;
						break;
					case 'R':
						stringBuilder.Append("<font color=#FF0000>");
						i++;
						num++;
						break;
					case 'G':
						stringBuilder.Append("<font color=#00FF00>");
						i++;
						num++;
						break;
					case 'B':
						stringBuilder.Append("<font color=#0000FF>");
						i++;
						num++;
						break;
					case 'K':
						stringBuilder.Append("<font color=#000000>");
						i++;
						num++;
						break;
					case 'Y':
						stringBuilder.Append("<font color=#FFFF00>");
						i++;
						num++;
						break;
					case 'W':
						stringBuilder.Append("<font color=#FFFFFF>");
						i++;
						num++;
						break;
					case 'c':
						if (i + 7 < text.Length)
						{
							string text2 = text.Substring(i + 2, 6);
							stringBuilder.Append("<font color=#" + text2 + ">");
							i += 7;
							num++;
						}
						break;
					case 'n':
					{
						for (int j = 0; j < num; j++)
						{
							stringBuilder.Append("</font>");
						}
						i++;
						num = 0;
						break;
					}
					case 'r':
						stringBuilder.Append("\n");
						break;
					}
				}
				else if (c == '<')
				{
					int num2 = text.IndexOf('>', i);
					if (num2 < 0)
					{
						continue;
					}
					List<LabelInfo> list = ParseLabel(text.Substring(i + 1, num2 - i - 2));
					if (list.Count > 0 && list[0].LabelName == "hy")
					{
						HyLabel hyLabel = new HyLabel();
						foreach (LabelInfo item in list)
						{
							switch (item.LabelName)
							{
							case "t":
								hyLabel.Text = item.Content;
								break;
							case "l":
								hyLabel.Href = "GuideLink://" + item.Content;
								break;
							case "ul":
								hyLabel.HasUnderline = item.Content != "0";
								break;
							case "fhc":
								hyLabel.HoverColor = item.Content;
								break;
							}
						}
						stringBuilder.Append("<a href='" + hyLabel.Href + "'");
						if (!string.IsNullOrWhiteSpace(hyLabel.HoverColor))
						{
							stringBuilder.Append(" hc='" + hyLabel.HoverColor + "'");
						}
						stringBuilder.Append(">");
						if (hyLabel.HasUnderline)
						{
							stringBuilder.Append("<u>");
						}
						stringBuilder.Append(hyLabel.Text);
						if (hyLabel.HasUnderline)
						{
							stringBuilder.Append("</u>");
						}
						stringBuilder.Append("</a>");
					}
					i = num2;
				}
				else
				{
					stringBuilder.Append(c);
				}
			}
			return stringBuilder.ToString();
		}

		public static List<LabelInfo> ParseLabel(string labelText)
		{
			List<LabelInfo> list = new List<LabelInfo>();
			string[] array = labelText.Split(' ');
			foreach (string text in array)
			{
				if (!string.IsNullOrEmpty(text))
				{
					string[] array2 = text.Split('=');
					LabelInfo labelInfo = new LabelInfo();
					labelInfo.LabelName = array2[0];
					if (array2.Length >= 2)
					{
						labelInfo.Content = array2[1];
					}
					list.Add(labelInfo);
				}
			}
			return list;
		}
	}
