	public static class PropertyDrawerExtension
	{
		public static void RefreshWithChain(this IEnumerable<IPropertyDrawer> drawers)
		{
			HashSet<IPropertyDrawer> hashSet = new HashSet<IPropertyDrawer>();
			Queue<IPropertyDrawer> queue = new Queue<IPropertyDrawer>();
			foreach (IPropertyDrawer drawer in drawers)
			{
				hashSet.Add(drawer);
				queue.Enqueue(drawer);
			}
			while (queue.Count > 0)
			{
				IPropertyDrawer propertyDrawer = queue.Dequeue();
				propertyDrawer.Refresh(chainRefresh: false);
				if (propertyDrawer.ChainDrawers == null)
				{
					continue;
				}
				foreach (IPropertyDrawer chainDrawer in propertyDrawer.ChainDrawers)
				{
					if (hashSet.Add(chainDrawer))
					{
						queue.Enqueue(chainDrawer);
					}
				}
			}
		}
	}
	/// <summary>
	/// 序列命令，用于将多个命令组合成一个命令
	/// 在记录命令后，就不能再添加命令了
	/// </summary>
	public class SequenceCommand : IUndoCommand
	{
		private List<IUndoCommand> _commands = new List<IUndoCommand>();

		public IReadOnlyList<IUndoCommand> Commands => _commands;

		public SequenceCommand(params IUndoCommand[] commands)
		{
			_commands.AddRange(commands);
		}

		public void AddCommand(IUndoCommand command)
		{
			_commands.Add(command);
		}

		public void AddCommands(IEnumerable<IUndoCommand> commands)
		{
			_commands.AddRange(commands);
		}

		public void AddCommands(params IUndoCommand[] commands)
		{
			_commands.AddRange(commands);
		}

		public void Execute()
		{
			for (int i = 0; i < Commands.Count; i++)
			{
				Commands[i].Execute();
			}
		}

		public void Undo()
		{
			for (int num = Commands.Count - 1; num >= 0; num--)
			{
				Commands[num].Undo();
			}
		}
	}
	public static class UndoExtension
	{
		public static void Record(this IUndoInst inst, IUndoCommand command)
		{
			command.Execute();
			inst.UndoManager?.Add(command);
		}
	}
	public class UndoInstManager
	{
		private List<IUndoCommand> UndoBuffer = new List<IUndoCommand>();

		private List<IUndoCommand> RedoBuffer = new List<IUndoCommand>();

		public int Capacity { get; set; }

		public bool CanUndo => UndoBuffer.Count > 0;

		public bool CanRedo => RedoBuffer.Count > 0;

		public event Action OnChanged;

		public UndoInstManager(int capacity = 50)
		{
			Capacity = capacity;
		}

		public void Add(IUndoCommand command)
		{
			if (UndoBuffer.Count >= Capacity)
			{
				UndoBuffer.RemoveAt(0);
			}
			UndoBuffer.Add(command);
			RedoBuffer.Clear();
			this.OnChanged?.Invoke();
		}

		/// <summary>
		/// 返回Undo的命令
		/// </summary>
		/// <returns></returns>
		public IUndoCommand Undo()
		{
			IUndoCommand undoCommand = null;
			if (UndoBuffer.Count > 0)
			{
				undoCommand = UndoBuffer[UndoBuffer.Count - 1];
				undoCommand.Undo();
				UndoBuffer.RemoveAt(UndoBuffer.Count - 1);
				RedoBuffer.Add(undoCommand);
			}
			this.OnChanged?.Invoke();
			return undoCommand;
		}

		/// <summary>
		/// 返回Redo的命令
		/// </summary>
		public void Redo()
		{
			if (RedoBuffer.Count > 0)
			{
				IUndoCommand undoCommand = RedoBuffer[RedoBuffer.Count - 1];
				undoCommand.Execute();
				RedoBuffer.RemoveAt(RedoBuffer.Count - 1);
				UndoBuffer.Add(undoCommand);
			}
			this.OnChanged?.Invoke();
		}
	}
	public class ValueChangedCommand<T> : IUndoCommand
	{
		private T _oldValue;

		private T _newValue;

		private Action<T> _onValueChanged;

		public ValueChangedCommand(T oldValue, T newValue, Action<T> onValueChanged)
		{
			_oldValue = oldValue;
			_newValue = newValue;
			_onValueChanged = onValueChanged;
		}

		public void Execute()
		{
			_onValueChanged?.Invoke(_newValue);
		}

		public void Undo()
		{
			_onValueChanged?.Invoke(_oldValue);
		}
	}
