				return;
			}
			UIPackage uIPackage = UIPackage.AddPackage(array, text, LoadResFunc);
			Packages.Add(pkgName, uIPackage);
			Dictionary<string, string>[] dependencies = uIPackage.dependencies;
			foreach (Dictionary<string, string> dictionary in dependencies)
			{
				AddPackage(dictionary["name"]);
			}
		}

		public GObject CreateUIObject(string pkgName, string resName)
		{
			AddPackage(pkgName);
			return UIPackage.CreateObject(pkgName, resName);
		}

		private void LoadFGUIAB()
		{
			FguiAB = AssetBundle.LoadFromFile(Main.PathInnerAbDir.Value + "/next_fairygui");
			Object[] array = FguiAB.LoadAllAssets();
			foreach (Object obj in array)
			{
				Shader val = (Shader)(object)((obj is Shader) ? obj : null);
				if (val != null)
				{
					ShaderMap.Add(((Object)val).name, val);
					Main.LogInfo("[FGUI]加载Shader：" + ((Object)val).name);
				}
			}
		}

		private void RegisterCursor(string cursorName, string path, float hotspotX = 0.5f, float hotspotY = 0.5f)
		{
			//IL_004d: Unknown result type (might be due to invalid IL or missing references)
			Texture2D val = Main.Res.LoadAsset<Texture2D>(path);
			if ((Object)(object)val == (Object)null)
			{
				Debug.LogWarning((object)("[FGUI]鼠标[" + cursorName + "]资源不存在，路径：" + path));
				return;
			}
			Vector2 hotspot = default(Vector2);
			((Vector2)(ref hotspot))..ctor((float)((Texture)val).width * hotspotX, (float)((Texture)val).height * hotspotY);
			Stage.inst.RegisterCursor(cursorName, val, hotspot);
		}

		private Shader GetShaderInAB(string name)
		{
			if (ShaderMap.TryGetValue(name, out var value))
			{
				return value;
			}
			return null;
		}

		private static object LoadResFunc(string name, string extension, Type type, out DestroyMethod destroyMethod)
		{
			destroyMethod = DestroyMethod.None;
			string text = (name + extension).Replace("\\", "/");
			Main.LogDebug($"[FGUI]加载文件：<{type}> {text}");
			Object obj = Main.Res.LoadAsset(text);
			if (obj == (Object)null)
			{
				Main.LogWarning($"[FGUI]不存在文件：<{type}> {text}");
			}
			return obj;
		}

		public void RegisterScenePanel(FGUIScenePanelBase scenePanel)
		{
			ScenePanels.Add(scenePanel);
		}

		public void RemoveScenePanel(FGUIScenePanelBase scenePanel)
		{
			ScenePanels.Remove(scenePanel);
		}

		public void RegisterWindow(FGUIWindowBase fguiWindowBase)
		{
			Windows.Add(fguiWindowBase);
		}

		public void UnRegisterWindow(FGUIWindowBase fguiWindowBase)
		{
			Windows.Remove(fguiWindowBase);
		}

		public void AutoCloseUIOnLoadScene()
		{
			RemoveAllWindow((FGUIWindowBase window) => window.AutoCloseInSceneChange);
		}

		public void AutoCloseUIOnSaveQuit()
		{
			RemoveAllWindow((FGUIWindowBase window) => window.AutoCloseInQuitSave);
		}
	}
	public class FGUIWindowBase : Window
	{
		public string comName;

		public string pkgName;

		public RayBlocker RayBlocker;

		/// <summary>
		/// 场景切换时是否自动关闭
		/// </summary>
		public bool AutoCloseInSceneChange = true;

		/// <summary>
		/// 退出存档时是否自动关闭
		/// </summary>
		public bool AutoCloseInQuitSave = true;

		public FGUIWindowBase(string pkgName, string comName)
		{
			this.pkgName = pkgName;
			this.comName = comName;
			base.contentPane = Main.FGUI.CreateUIObject(pkgName, comName).asCom;
			base.contentPane.onKeyDown.Add(OnKeyDown);
			Main.FGUI.RegisterWindow(this);
		}

		protected override void OnInit()
		{
			RayBlocker = RayBlocker.CreateRayBlock(comName);
			base.onSizeChanged.Add(ResetRayBlocker);
			base.onPositionChanged.Add(ResetRayBlocker);
		}

		public virtual void ResetRayBlocker()
		{
			//IL_005f: Unknown result type (might be due to invalid IL or missing references)
			//IL_0024: Unknown result type (might be due to invalid IL or missing references)
			if (base.modal)
			{
				RayBlocker.SetSize(new Rect(0f, 0f, (float)Screen.width, (float)Screen.height));
				return;
			}
			float num = base.width * base.scaleX;
			float num2 = base.height * base.scaleY;
			RayBlocker.SetSize(new Rect(base.x, base.y, num, num2));
		}

		protected override void OnShown()
		{
			base.OnShown();
			RayBlocker.OpenBlocker();
			base.contentPane.RequestFocus();
		}

		protected override void OnHide()
		{
			RayBlocker.CloseBlocker();
			RayBlocker.DestroySelf();
			OnDispose();
			Dispose();
		}

		public virtual void HideForce()
		{
			RayBlocker.CloseBlocker();
			RayBlocker.DestroySelf();
			OnDispose();
			Dispose();
		}

		protected virtual void OnDispose()
		{
			Main.FGUI.UnRegisterWindow(this);
		}

		protected virtual void OnKeyDown(EventContext context)
		{
		}

		protected override void closeEventHandler(EventContext context)
		{
		}

		/// <summary>
		/// 按缩放因子设置缩放大小并居中
		/// </summary>
		public void MakeFullScreenAndCenter(float factor = 1f)
		{
			SetSize(GRoot.inst.width * factor, GRoot.inst.height * factor);
			Center();
			ResetRayBlocker();
		}

		public void ScaleWithScreen()
		{
			float num = Mathf.Min(GRoot.inst.width / 1920f, GRoot.inst.height / 1080f);
			SetScale(num, num);
			ResetRayBlocker();
		}

		public void ResetScale()
		{
			SetScale(1f, 1f);
			ResetRayBlocker();
		}
	}
}
