	public class WindowSeidEditorDialog : WindowDialogBase
	{
		public class SeidNodeInfo
		{
			public bool IsSeid;

			public bool InSeidList;

			public string NodeName;

			public string NodeIcon;

			public int SeidID;
		}

		private bool _editable;

		private GTreeNode _nodeSeidList;

		private GTreeNode _nodeAllSeidList;

		public string Title { get; set; }

		public ModWorkshop Mod { get; private set; }

		public int OwnerId { get; private set; }

		public Dictionary<int, ModSeidMeta> SeidMetas { get; private set; }

		public IModSeidDataGroup SeidGroup { get; private set; }

		public List<int> SeidList { get; private set; }

		public List<int> AllSeidList { get; private set; }

		public Action OnClose { get; private set; }

		public bool Editable
		{
			get
			{
				return _editable;
			}
			set
			{
				_editable = value;
				Inspector.Editable = value;
				Inspector.Refresh();
				RefreshButtonState();
			}
		}

		public UI_WinSeidEditorDialog SeidEditor => base.contentPane as UI_WinSeidEditorDialog;

		public CtlPropertyInspector Inspector { get; set; }

		public GButton BtnAdd => SeidEditor.m_btnAdd;

		public GButton BtnRemove => SeidEditor.m_btnRemove;

		public GButton BtnEnable => SeidEditor.m_btnEnable;

		public GButton BtnDisable => SeidEditor.m_btnDisable;

		public GButton BtnMoveUp => SeidEditor.m_btnMoveUp;

		public GButton BtnMoveDown => SeidEditor.m_btnMoveDown;

		private int? CurrentSeidId { get; set; }

		private WindowSeidEditorDialog()
			: base("NextCore", "WinSeidEditorDialog")
		{
		}

		public static WindowSeidEditorDialog CreateDialog(string title, ModWorkshop mod, int ownerId, IModSeidDataGroup seidGroup, Dictionary<int, ModSeidMeta> seidMetas, List<int> seidList, Action onClose)
		{
			WindowSeidEditorDialog windowSeidEditorDialog = new WindowSeidEditorDialog();
			windowSeidEditorDialog.modal = true;
			windowSeidEditorDialog.Title = title;
			windowSeidEditorDialog.Mod = mod;
			windowSeidEditorDialog.OwnerId = ownerId;
			windowSeidEditorDialog.SeidGroup = seidGroup;
			windowSeidEditorDialog.SeidMetas = seidMetas;
			windowSeidEditorDialog.SeidList = seidList;
			windowSeidEditorDialog.AllSeidList = new List<int>();
			windowSeidEditorDialog.OnClose = onClose;
			windowSeidEditorDialog.Show();
			return windowSeidEditorDialog;
		}

		protected override void OnInit()
		{
			base.OnInit();
			SeidEditor.m_frame.title = Title;
			SeidEditor.m_frame.m_closeButton.onClick.Add(base.Hide);
			Inspector = new CtlPropertyInspector(SeidEditor.m_inspector);
			foreach (int seid in SeidList)
			{
				if (!AllSeidList.Contains(seid))
				{
					AllSeidList.Add(seid);
				}
			}
			foreach (KeyValuePair<int, ModSeidDataGroup> dataGroup in SeidGroup.DataGroups)
			{
				int key = dataGroup.Key;
				if (SeidGroup.GetSeid(OwnerId, key) != null && !AllSeidList.Contains(key))
				{
					AllSeidList.Add(key);
				}
			}
			AllSeidList.Sort();
			SeidEditor.m_list.treeNodeRender = OnTreeNodeRender;
			SeidEditor.m_list.onClickItem.Add(OnClickSeidItem);
			BtnAdd.onClick.Add(OnClickAdd);
			BtnRemove.onClick.Add(OnClickRemove);
			BtnEnable.onClick.Add(OnClickEnable);
			BtnDisable.onClick.Add(OnClickDisable);
			BtnMoveUp.onClick.Add(OnClickMoveUp);
			BtnMoveDown.onClick.Add(OnClickMoveDown);
			Refresh();
			UnselectTargetSeid();
		}

		protected override void OnKeyDown(EventContext context)
		{
			//IL_000d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0014: Invalid comparison between Unknown and I4
			base.OnKeyDown(context);
			if ((int)context.inputEvent.keyCode == 27)
			{
				Hide();
			}
		}

		private void Refresh()
		{
			SeidEditor.m_list.rootNode.RemoveChildren();
			_nodeSeidList = AddSeidList("特性列表", SeidList, inSeidList: true);
			_nodeAllSeidList = AddSeidList("所有特性", AllSeidList, inSeidList: false);
		}

		/// <summary>
		/// 获取选中的特性位置
		/// </summary>
		/// <param name="info"></param>
		/// <returns></returns>
		private bool GetSelectedSeid(out SeidNodeInfo info)
		{
			GTreeNode selectedNode = SeidEditor.m_list.GetSelectedNode();
			info = null;
			if (!(selectedNode?.data is SeidNodeInfo { IsSeid: not false } seidNodeInfo))
			{
				return false;
			}
			info = seidNodeInfo;
			return true;
		}

		/// <summary>
		/// 获取特性在SeidList里的位置，不存在则返回-1
		/// </summary>
		/// <param name="index"></param>
		/// <returns></returns>
		private bool GetSeidIndexInSeidList(out int index)
		{
			GTreeNode selectedNode = SeidEditor.m_list.GetSelectedNode();
			index = -1;
			if (!(selectedNode?.data is SeidNodeInfo { IsSeid: not false }))
			{
				return false;
			}
			index = _nodeSeidList.GetChildIndex(selectedNode);
			return true;
		}

		private void SelectSeid(int seidId)
		{
			GTreeNode[] array = new GTreeNode[2] { _nodeSeidList, _nodeAllSeidList };
			foreach (GTreeNode gTreeNode in array)
			{
				for (int j = 0; j < gTreeNode.numChildren; j++)
				{
					GTreeNode childAt = gTreeNode.GetChildAt(j);
					if (childAt.data is SeidNodeInfo { IsSeid: not false } seidNodeInfo && seidNodeInfo.SeidID == seidId)
					{
						SeidEditor.m_list.SelectNode(childAt);
						SetTargetSeid(seidId);
						return;
					}
				}
			}
			UnselectTargetSeid();
		}

		private void SelectSeidInSeidListByIndex(int index)
		{
			GTreeNode childAt = _nodeSeidList.GetChildAt(index);
			if (childAt.data is SeidNodeInfo { IsSeid: not false } seidNodeInfo)
			{
				SeidEditor.m_list.SelectNode(childAt);
				SetTargetSeid(seidNodeInfo.SeidID);
			}
			else
			{
				UnselectTargetSeid();
			}
		}

		private void SelectSeidInAllSeidList(int seidId)
		{
			for (int i = 0; i < _nodeAllSeidList.numChildren; i++)
			{
				GTreeNode childAt = _nodeAllSeidList.GetChildAt(i);
				if (childAt.data is SeidNodeInfo { IsSeid: not false } seidNodeInfo && seidNodeInfo.SeidID == seidId)
				{
					SeidEditor.m_list.SelectNode(childAt);
					SetTargetSeid(seidNodeInfo.SeidID);
					return;
				}
			}
			UnselectTargetSeid();
		}

		private void OnClickAdd(EventContext context)
		{
			List<IModData> list = ((IEnumerable<KeyValuePair<int, ModSeidMeta>>)SeidMetas).Select((Func<KeyValuePair<int, ModSeidMeta>, IModData>)((KeyValuePair<int, ModSeidMeta> pair) => pair.Value)).ToList();
			list.ModSort();
			WindowTableSelectorDialog.CreateDialog("创建特性", new List<TableInfo>
			{
				new TableInfo("ID", 38.4f, (object obj) => ((ModSeidMeta)obj).Id.ToString()),
				new TableInfo("特性名称", 172.79999f, (object obj) => ((ModSeidMeta)obj).Name),
				new TableInfo("特性描述", 192f, (object obj) => ((ModSeidMeta)obj).Desc)
			}, null, allowEmpty: false, list, allowMulti: false, delegate(List<int> ids)
			{
				int seidId = ids[0];
				AddSeid(seidId);
				SelectSeid(seidId);
			});
		}

		private void OnClickRemove(EventContext context)
		{
			if (GetSelectedSeid(out var nodeInfo))
			{
				WindowConfirmDialog.CreateDialog("提示", $"即将完全删除特性【{nodeInfo.SeidID} {nodeInfo.NodeName}】，是否确认？", canCancel: true, delegate
				{
					RemoveSeid(nodeInfo.SeidID);
					Refresh();
				});
			}
		}

		private void OnClickDisable(EventContext context)
		{
			if (GetSeidIndexInSeidList(out var index))
			{
				int seidId = SeidList[index];
				DisableSeidByIndex(index);
				SelectSeidInAllSeidList(seidId);
			}
		}

		private void OnClickEnable(EventContext context)
		{
			if (GetSelectedSeid(out var info))
			{
				EnableSeid(info.SeidID);
				SelectSeidInSeidListByIndex(SeidList.Count - 1);
			}
		}

		private void OnClickMoveUp(EventContext context)
		{
			if (GetSeidIndexInSeidList(out var index))
			{
				SelectSeidInSeidListByIndex(SeidMoveUpByIndex(index));
			}
		}

		private void OnClickMoveDown(EventContext context)
		{
			if (GetSeidIndexInSeidList(out var index))
			{
				SelectSeidInSeidListByIndex(SeidMoveDownByIndex(index));
			}
		}

		private void AddSeid(int seidId)
		{
			if (SeidList.Contains(seidId))
			{
				WindowConfirmDialog.CreateDialog("提示", "该特性已存在！是否继续添加？", canCancel: true, delegate
				{
					AddSeidWithoutCheck(seidId);
				});
			}
			else
			{
				AddSeidWithoutCheck(seidId);
			}
		}

		private void AddSeidWithoutCheck(int seidId)
		{
			SeidList.Add(seidId);
			if (!AllSeidList.Contains(seidId))
			{
				AllSeidList.Add(seidId);
				AllSeidList.Sort();
			}
			SeidGroup.GetOrCreateSeid(OwnerId, seidId);
			Refresh();
		}

		private void RemoveSeid(int seidId)
		{
			if (SeidList.Contains(seidId))
			{
				SeidList.RemoveAll((int target) => target == seidId);
			}
			if (AllSeidList.Contains(seidId))
			{
				AllSeidList.RemoveAll((int target) => target == seidId);
			}
			SeidGroup.RemoveSeid(OwnerId, seidId);
			Refresh();
		}

		private void EnableSeid(int seidId)
		{
			if (AllSeidList.Contains(seidId))
			{
				SeidList.Add(seidId);
			}
			Refresh();
		}

		private void DisableSeidByIndex(int index)
		{
			if (index >= 0 && index < SeidList.Count)
			{
				SeidList.RemoveAt(index);
				Refresh();
			}
		}

		private int SeidMoveUpByIndex(int index)
		{
			if (index == 0 || index >= SeidList.Count)
			{
				return 0;
			}
			int item = SeidList[index];
			SeidList.RemoveAt(index);
			SeidList.Insert(index - 1, item);
			Refresh();
			return index - 1;
		}

		private int SeidMoveDownByIndex(int index)
		{
			if (index < 0 || index == SeidList.Count - 1)
			{
				return SeidList.Count - 1;
			}
			int item = SeidList[index];
			SeidList.RemoveAt(index);
			SeidList.Insert(index + 1, item);
			Refresh();
			return index + 1;
		}

		protected override void OnHide()
		{
			OnClose();
			base.OnHide();
		}

		private void OnClickSeidItem(EventContext context)
		{
			if (((context.data as GObject)?.treeNode).data is SeidNodeInfo { IsSeid: not false } seidNodeInfo)
			{
				SetTargetSeid(seidNodeInfo.SeidID);
			}
			else
			{
				UnselectTargetSeid();
			}
		}

		private void RefreshButtonState()
		{
			if (Editable)
			{
				BtnAdd.enabled = true;
				if (GetSelectedSeid(out var info))
				{
					BtnRemove.enabled = true;
					bool inSeidList = info.InSeidList;
					BtnMoveUp.enabled = inSeidList;
					BtnMoveDown.enabled = inSeidList;
					BtnEnable.enabled = !inSeidList;
					BtnDisable.enabled = inSeidList;
				}
				else
				{
					BtnRemove.enabled = false;
					BtnMoveUp.enabled = false;
					BtnMoveDown.enabled = false;
					BtnEnable.enabled = false;
					BtnDisable.enabled = false;
				}
			}
			else
			{
				BtnAdd.enabled = false;
				BtnRemove.enabled = false;
				BtnMoveUp.enabled = false;
				BtnMoveDown.enabled = false;
				BtnEnable.enabled = false;
				BtnDisable.enabled = false;
			}
		}

		private void UnselectTargetSeid()
		{
			Inspector.Clear();
			CurrentSeidId = null;
			RefreshButtonState();
		}

		private void SetTargetSeid(int seidId)
		{
			Inspector.Clear();
			CurrentSeidId = seidId;
			RefreshButtonState();
			if (SeidMetas.TryGetValue(seidId, out var value))
			{
				Inspector.AddDrawer(new CtlTitleDrawer(value.Name));
				Inspector.AddDrawer(new CtlTextDrawer(value.Desc));
				ModSeidData orCreateSeid = SeidGroup.GetOrCreateSeid(OwnerId, seidId);
				foreach (ModSeidProperty property in value.Properties)
				{
					switch (property.Type)
					{
					case ModSeidPropertyType.Int:
						CreateIntDrawer(property, orCreateSeid);
						break;
					case ModSeidPropertyType.IntArray:
						CreateIntArrayDrawer(property, orCreateSeid);
						break;
					case ModSeidPropertyType.Float:
						CreateFloatDrawer(property, orCreateSeid);
						break;
					case ModSeidPropertyType.String:
						CreateStringDrawer(property, orCreateSeid);
						break;
					default:
						throw new ArgumentOutOfRangeException();
					}
				}
			}
			Inspector.Refresh();
		}

