		private void OnTreeNodeRender(GTreeNode node, GComponent item)
		{
			GButton gButton = item.asButton;
			SeidNodeInfo seidNodeInfo = (SeidNodeInfo)node.data;
			gButton.title = seidNodeInfo.NodeName;
			gButton.icon = seidNodeInfo.NodeIcon;
		}

		private GTreeNode AddSeidList(string listName, List<int> seidList, bool inSeidList)
		{
			SeidNodeInfo seidNodeInfo = new SeidNodeInfo
			{
				IsSeid = false,
				NodeName = listName,
				NodeIcon = ""
			};
			GTreeNode gTreeNode = new GTreeNode(hasChild: true)
			{
				data = seidNodeInfo
			};
			foreach (int seid in seidList)
			{
				SeidNodeInfo seidNodeInfo2 = new SeidNodeInfo
				{
					IsSeid = true,
					InSeidList = inSeidList,
					NodeIcon = "ui://NextCore/icon_dao",
					SeidID = seid
				};
				if (SeidMetas.TryGetValue(seid, out var value))
				{
					seidNodeInfo2.NodeName = $"{seid} {value.Name}";
				}
				else
				{
					seidNodeInfo2.NodeName = $"{seid}";
				}
				GTreeNode child = new GTreeNode(hasChild: false)
				{
					data = seidNodeInfo2
				};
				gTreeNode.AddChild(child);
			}
			gTreeNode.expanded = true;
			SeidEditor.m_list.rootNode.AddChild(gTreeNode);
			return gTreeNode;
		}
	}
