		public static void CreateDialog(string title, List<TableInfo> tableInfos, IEnumerable<int> curIds, bool allowEmpty, List<IModData> dataList, bool allowMulti, Action<List<int>> onConfirm = null, Action onCancel = null, Func<IModData, int> idGetter = null)
		{
			WindowTableSelectorDialog windowTableSelectorDialog = new WindowTableSelectorDialog();
			windowTableSelectorDialog._title = title;
			windowTableSelectorDialog._tableInfos.AddRange(tableInfos);
			windowTableSelectorDialog._onConfirm = onConfirm;
			windowTableSelectorDialog._onCancel = onCancel;
			windowTableSelectorDialog._idGetter = idGetter;
			windowTableSelectorDialog._allowEmpty = allowEmpty;
			windowTableSelectorDialog._allowMulti = allowMulti;
			if (curIds != null)
			{
				windowTableSelectorDialog._curIds.AddRange(curIds);
			}
			windowTableSelectorDialog._tableDataList = new TableDataList<IModData>(dataList);
			windowTableSelectorDialog.modal = true;
			windowTableSelectorDialog.Show();
		}

		protected override void OnInit()
		{
			base.OnInit();
			MainView.m_frame.title = _title;
			base.closeButton.onClick.Set(Cancel);
			MainView.m_closeButton.onClick.Set(Cancel);
			MainView.m_btnOk.onClick.Set(Confirm);
			ToolsBar = new CtlToolsBar(MainView.m_toolsBar);
			ToolsBar.AddToolSearch(OnSearch);
			TableList = new CtlTableList(MainView.m_table.As<UI_ComTableList>());
			TableList.MultiSelect = _allowMulti;
			TableList.AllowClickToSelect = true;
			TableList.SetItemRenderer(OnItemRenderer);
			TableList.SetItemSelectedChanged(OnItemSelectedChanged);
			TableList.BindTable(_tableInfos, _tableDataList);
			RefreshConfirm();
			RefreshTipText();
		}

