	public class CtlGroupDrawer : CtlPropertyDrawerBase, IInspector
	{
		private List<IPropertyDrawer> _drawers { get; } = new List<IPropertyDrawer>();


		private string DrawerName { get; set; }

		private bool IsExpand { get; set; }

		private UI_ComGroupDrawer GroupDrawer => (UI_ComGroupDrawer)base.Component;

		private CtlGroupInspector Inspector { get; set; }

		public IReadOnlyList<IPropertyDrawer> Drawers => _drawers;

		public CtlGroupDrawer(string title, bool isExpend, params IPropertyDrawer[] drawers)
		{
			DrawerName = title;
			IsExpand = isExpend;
			_drawers.AddRange(drawers);
		}

		protected override GComponent OnCreateCom()
		{
			UI_ComGroupDrawer uI_ComGroupDrawer = UI_ComGroupDrawer.CreateInstance();
			uI_ComGroupDrawer.title = DrawerName;
			uI_ComGroupDrawer.onSizeChanged.Add(OnSizeChanged);
			Inspector = new CtlGroupInspector(uI_ComGroupDrawer.m_list);
			Inspector.OnPropertyChanged += OnDrawerChanged;
			IPropertyDrawer[] array = _drawers.ToArray();
			_drawers.Clear();
			IPropertyDrawer[] array2 = array;
			foreach (IPropertyDrawer drawer in array2)
			{
				AddDrawer(drawer);
			}
			GButton btnExpand = uI_ComGroupDrawer.m_btnExpand;
			btnExpand.selected = IsExpand;
			btnExpand.onClick.Add((EventCallback0)delegate
			{
				SetExpand(btnExpand.selected);
			});
			return uI_ComGroupDrawer;
		}

		protected override void OnRemoveCom(GComponent component)
		{
			base.OnRemoveCom(component);
			Inspector = null;
		}

		public void AddDrawer(IPropertyDrawer drawer)
		{
			drawer.UndoManager = base.UndoManager;
			_drawers.Add(drawer);
			if (Inspector != null)
			{
				Inspector.AddDrawer(drawer);
			}
		}

		private void OnDrawerChanged()
		{
			base.OnChanged?.Invoke();
		}

		public void Clear()
		{
			_drawers.Clear();
			if (Inspector != null)
			{
				Inspector.Clear();
			}
		}

		protected override void SetDrawerEditable(bool value)
		{
			Inspector.Editable = value;
			Inspector.Refresh();
		}

		protected override void OnRefresh()
		{
			base.OnRefresh();
			if (IsExpand)
			{
				Inspector.Show();
			}
			else
			{
				Inspector.Hide();
			}
		}

		private void OnSizeChanged()
		{
			Inspector.Resize();
		}

		private void SetExpand(bool isExpand)
		{
			IsExpand = isExpand;
			Refresh();
		}
	}
