	public class CtlDocumentNodeView
	{
		public UI_ComMainDocumentNodeView MainView { get; set; }

		public CtlTableList TableList { get; set; }

		public CtlNodeCanvas NodeCanvas { get; set; }

		public CtlPropertyInspector Inspector { get; set; }

		public List<TableInfo> TableInfos { get; set; }

		public List<FFlowchart> FFlowcharts { get; set; }

		public FFlowchart CurFlowchart { get; set; }

		public CtlDocumentNodeView(UI_ComMainDocumentNodeView com)
		{
			//IL_0077: Unknown result type (might be due to invalid IL or missing references)
			MainView = com;
			TableList = new CtlTableList(MainView.m_list);
			NodeCanvas = new CtlNodeCanvas(MainView.m_nodeCanvas);
			Inspector = new CtlPropertyInspector(MainView.m_inspector);
			NodeCanvas.OnContentPosChange = RefreshNodeCanvasPos;
			NodeCanvas.PosScale = new Vector2(2f, 4f);
			NodeCanvas.SetOnClickCommand(OnClickCommand);
		}

		protected virtual void RefreshNodeCanvasPos()
		{
			//IL_0015: Unknown result type (might be due to invalid IL or missing references)
			//IL_001a: Unknown result type (might be due to invalid IL or missing references)
			//IL_002b: Unknown result type (might be due to invalid IL or missing references)
			//IL_0036: Unknown result type (might be due to invalid IL or missing references)
			Vector3 position = NodeCanvas.MainView.m_zoom.m_container.position;
			MainView.m_txtState.text = $"X : {position.x}  Y : {position.y}";
		}

		public void Init(List<TableInfo> tableInfos, List<FFlowchart> fFlowcharts)
		{
			FFlowcharts = fFlowcharts;
			TableInfos = tableInfos;
			TableList.BindTable(tableInfos, new ModDataTableDataList<FFlowchart>(fFlowcharts));
			TableList.SetClickItem(OnClickLeftListItem);
			Inspector.Clear();
			if (FFlowcharts.Count > 0)
			{
				SetFlowchart(FFlowcharts[0]);
			}
		}

		private void OnClickCommand(FCommand command)
		{
			Inspector.Clear();
			Inspector.AddDrawer(new CtlButtonDrawerBuilder().SetTitle("流程图").SetButtonText("返回").SetOnClick(RefreshFlowchartInspector)
				.Build());
			if (command != null)
			{
				Inspector.AddDrawer(new CtlGroupDrawerBuilder().SetTitle("Command信息".I18NTodo()).SetExpand(isExpand: true).AddDrawer(new CtlInfoDrawerBuilder().SetTitle("ID".I18NTodo()).SetContent(command.ItemID.ToString()).Build())
					.AddDrawer(new CtlInfoDrawerBuilder().SetTitle("类型".I18NTodo()).SetContent(command.CmdType).Build())
					.AddDrawer(new CtlInfoDrawerBuilder().SetTitle("描述".I18NTodo()).SetContent(command.GetSummary()).Build())
					.Build());
			}
		}

		private void OnClickLeftListItem(EventContext context)
		{
			if (TableList.SelectedIndex >= 0 && TableList.SelectedIndex < FFlowcharts.Count)
			{
				SetFlowchart(FFlowcharts[TableList.SelectedIndex]);
			}
		}

		private void SetFlowchart(FFlowchart fFlowchart)
		{
			CurFlowchart = fFlowchart;
			NodeCanvas.Bind(fFlowchart);
			NodeCanvas.FocusToFirstBlock();
			RefreshFlowchartInspector();
		}

		private void RefreshFlowchartInspector()
		{
			FFlowchart curFlowchart = CurFlowchart;
			Inspector.Clear();
			Inspector.AddDrawer(new CtlGroupDrawerBuilder().SetTitle("流程图信息".I18NTodo()).AddDrawer(new CtlInfoDrawerBuilder().SetTitle("ID".I18NTodo()).SetContent(curFlowchart.Name).Build()).AddDrawer(new CtlInfoDrawerBuilder().SetTitle("Block数量".I18NTodo()).SetContent(curFlowchart.Blocks.Count.ToString()).Build())
				.Build());
			CtlGroupDrawerBuilder ctlGroupDrawerBuilder = new CtlGroupDrawerBuilder().SetTitle("Variables".I18NTodo());
			foreach (FVariable variable in curFlowchart.Variables)
			{
				ctlGroupDrawerBuilder.AddDrawer(new CtlInfoDrawerBuilder().SetTitle(variable.Key).SetContent(variable.Value).SetTooltips("变量名：\t" + variable.Key + "\n变量类型：\\t" + variable.Type + "\n变量值：\\t" + variable.Value)
					.Build());
			}
			Inspector.AddDrawer(ctlGroupDrawerBuilder.Build());
		}
	}
