		private List<PanelPageBase> Tabs { get; } = new List<PanelPageBase>();


		public GObject currentContent { get; set; }

		public UI_ComMainDocumentView DocumentView { get; }

		public int CurTabIndex => _curTabIndex;

		public CtlDocumentView(UI_ComMainDocumentView documentView)
		{
			_onRemoveTabItem = OnRemoveTabItem;
			DocumentView = documentView;
			DocumentView.onKeyDown.Add(OnKeyDown);
			GList lstTab = DocumentView.m_lstTab;
			lstTab.itemRenderer = TabItemRenderer;
			lstTab.onClickItem.Set(OnClickTabItem);
			lstTab.scrollPane._displayOnTop = true;
			lstTab.SetSize(lstTab.width, lstTab.height);
		}

		private void OnClickTabItem(EventContext context)
		{
			UI_BtnTab child = (UI_BtnTab)context.data;
			int childIndex = DocumentView.m_lstTab.GetChildIndex(child);
			OnSelectTab(childIndex);
		}

		private void OnSelectTab(int index, bool forceRefresh = false)
		{
			if (_curTabIndex == index && !forceRefresh)
			{
				return;
			}
			PanelPageBase obj = ((index > 0 && index < Tabs.Count) ? Tabs[index] : null);
			OnTabClose?.Invoke(obj);
			_curTabIndex = index;
			DocumentView.m_lstTab.selectedIndex = _curTabIndex;
			DocumentView.m_placeholder.visible = false;
			if (currentContent != null)
			{
				DocumentView.RemoveChild(currentContent);
			}
			currentContent = null;
			if (index >= 0 && index < Tabs.Count)
			{
				PanelPageBase panelPageBase = Tabs[index];
				if (panelPageBase.Content != null)
				{
					currentContent = panelPageBase.Content;
					DocumentView.AddChild(panelPageBase.Content);
					currentContent.SetSize(DocumentView.m_placeholder.width, DocumentView.m_placeholder.height);
					currentContent.SetXY(DocumentView.m_placeholder.x, DocumentView.m_placeholder.y);
					currentContent.AddRelation(DocumentView.m_placeholder, RelationType.Size);
				}
				panelPageBase.Open();
				OnTabOpen?.Invoke(panelPageBase);
			}
		}

		private void OnRemoveTabItem(EventContext context)
		{
			context.StopPropagation();
			PanelPageBase panelPageBase = (PanelPageBase)((UI_BtnTab)((GButton)context.sender).parent).data;
			OnTabRemove?.Invoke(panelPageBase);
			RemoveTab(panelPageBase);
		}

		private void OnKeyDown(EventContext context)
		{
			if (CurTabIndex >= 0 && CurTabIndex < Tabs.Count && Tabs[CurTabIndex].OnHandleKey(context.inputEvent))
			{
				context.StopPropagation();
			}
		}

		private void TabItemRenderer(int index, GObject item)
		{
			UI_BtnTab obj = (UI_BtnTab)item;
			PanelPageBase panelPageBase = Tabs[index];
			obj.title = panelPageBase.Name;
			obj.data = panelPageBase;
			obj.m_closeButton.onClick.Set(_onRemoveTabItem);
			obj.m_dragArea.draggable = true;
			obj.m_dragArea.onDragStart.Add(OnTabDragStart);
			obj.onDragStart.Add(OnTabItemDragStart);
			obj.onDragEnd.Add(OnTabItemDragEnd);
		}

		private void OnTabDragStart(EventContext context)
		{
			GObject obj = (GObject)context.sender;
			UI_BtnTab uI_BtnTab = (UI_BtnTab)obj.parent;
			obj.StopDrag();
			uI_BtnTab.StartDrag((int)context.data);
		}

		private void OnTabItemDragStart(EventContext context)
		{
			//IL_001f: Unknown result type (might be due to invalid IL or missing references)
			context.PreventDefault();
			UI_BtnTab tabItem = (UI_BtnTab)context.sender;
			UniTaskExtensions.Forget(StartTabDrag(tabItem, (int)context.data));
		}

		private void OnTabItemDragEnd(EventContext context)
		{
			_ctsDrag?.Cancel();
			UI_BtnTab uI_BtnTab = (UI_BtnTab)context.sender;
			GObject gObject = Stage.inst.touchTarget?.gOwner;
			if (gObject == null || !gObject.IsChildOf(DocumentView.m_lstTab))
			{
				return;
			}
			UI_BtnTab uI_BtnTab2 = gObject.FindParent<UI_BtnTab>();
			if (uI_BtnTab2 != uI_BtnTab)
			{
				int childIndex = DocumentView.m_lstTab.GetChildIndex(uI_BtnTab);
				int childIndex2 = DocumentView.m_lstTab.GetChildIndex(uI_BtnTab2);
				if (childIndex != -1 && childIndex2 != -1 && childIndex != childIndex2)
				{
					DocumentView.m_lstTab.RemoveChildAt(childIndex, dispose: false);
					DocumentView.m_lstTab.AddChildAt(uI_BtnTab, childIndex2);
					PanelPageBase item = Tabs[childIndex];
					Tabs.RemoveAt(childIndex);
					Tabs.Insert(childIndex2, item);
					OnSelectTab(childIndex2);
				}
			}
		}

