		private void RefreshTabs()
		{
			DocumentView.m_lstTab.numItems = Tabs.Count;
		}

		public void TryAddAndSelectTab(IDocumentItem item)
		{
			if (!TryGetTab(item.ID, out var page))
			{
				page = item.CreatePage();
				page.ID = item.ID;
				AddTab(page);
			}
			SelectTab(page);
		}

		public bool TryGetTab(string tabID, out PanelPageBase page)
		{
			page = Tabs.Find((PanelPageBase t) => t.ID == tabID);
			return page != null;
		}

		public bool HasTab(string tabID)
		{
			return Tabs.Find((PanelPageBase tab) => tab.ID == tabID) != null;
		}

		public void AddTab(PanelPageBase page)
		{
			Tabs.Add(page);
			page.Create();
			RefreshTabs();
			OnTabAdd?.Invoke(page);
		}

		public void RemoveTab(PanelPageBase page)
		{
			int selectedIndex = DocumentView.As<UI_ComMainDocumentView>().m_lstTab.selectedIndex;
			int num = 0;
			Tabs.Remove(page);
			if (page.Content == currentContent)
			{
				DocumentView.RemoveChild(page.Content);
				currentContent = null;
			}
			page.Close();
			RefreshTabs();
			num = ((Tabs.Count <= 0) ? (-1) : Mathf.Clamp(selectedIndex, 0, Tabs.Count - 1));
			OnSelectTab(num, forceRefresh: true);
		}

		public void SelectTab(PanelPageBase page)
		{
			int index = Tabs.IndexOf(page);
			OnSelectTab(index, forceRefresh: true);
		}

		public void RemoveAllTab()
		{
			foreach (PanelPageBase tab in Tabs)
			{
				tab.Close();
			}
			Tabs.Clear();
			RefreshTabs();
		}
	}
