		{
			MainView = tagList;
			MainView.onSizeChanged.Add(OnSizeChanged);
		}

		private void OnSizeChanged()
		{
			OnRefresh();
		}

		protected override void OnRefresh()
		{
			if (MainView.visible)
			{
				MainView.ResizeToFit();
			}
			else
			{
				MainView.height = 0f;
			}
		}

		public void Show()
		{
			MainView.visible = true;
			Refresh();
		}

		public void Hide()
		{
			MainView.visible = false;
			Refresh();
		}

		public void Resize()
		{
			MainView.ResizeToFit();
		}
	}
