	public class CtlNodeBlock
	{
		public UI_ComNodeBlock MainView { get; set; }

		public FBlock FBlock { get; set; }

		public Action OnPosChanged { get; set; }

		public GList Content { get; set; }

		protected Action<FCommand> OnCommandClick { get; set; }

		public CtlNodeBlock(UI_ComNodeBlock com, FBlock fBlock)
		{
			MainView = com;
			FBlock = fBlock;
			MainView.title = $"{fBlock.ItemID}[{fBlock.Name}]";
			Content = MainView.m_content;
			MainView.m_dragArea.draggable = true;
			MainView.m_dragArea.onDragStart.Add(delegate(EventContext context)
			{
				context.PreventDefault();
				MainView.StartDrag((int)context.data);
			});
			MainView.onDragEnd.Add((EventCallback0)delegate
			{
				OnPosChanged?.Invoke();
			});
			Content.onClickItem.Add(delegate(EventContext context)
			{
				if (context.data is GObject child)
				{
					int childIndex = Content.GetChildIndex(child);
					if (childIndex >= 0 && childIndex < FBlock.Commands.Count)
					{
						FCommand obj = FBlock.Commands[childIndex];
						OnCommandClick?.Invoke(obj);
					}
				}
			});
		}

		public void SetOnClickCommand(Action<FCommand> action)
		{
			OnCommandClick = action;
		}

		public void RefreshBlock()
		{
			int num = 0;
			int num2 = 0;
			int num3 = 0;
			Content.numItems = 0;
			for (int i = 0; i < FBlock.Commands.Count; i++)
			{
				FCommand fCommand = FBlock.Commands[i];
				GComponent asCom = Content.AddItemFromPool("ui://NextCore/ComCmdText").asCom;
				asCom.text = fCommand.GetSummary();
				if (!(fCommand is While) && !(fCommand is SkySwordKill.Next.FCanvas.FakerCommand.If))
				{
					if (!(fCommand is ElseIf))
					{
						if (!(fCommand is Else))
						{
							if (fCommand is End)
							{
								num--;
							}
						}
						else
						{
							num--;
							num2++;
						}
					}
					else
					{
						num--;
						num2++;
					}
				}
				else
				{
					num2++;
				}
				Controller controller = asCom.GetController("bg");
				if (controller != null)
				{
					controller.selectedIndex = i % 2;
				}
				GObject child = asCom.GetChild("indent");
				if (child != null)
				{
					child.width = num * 20;
				}
				num3 = Math.Max(num3, num);
				num += num2;
				num2 = 0;
			}
			Content.width += num3 * 20;
			Content.ResizeToFit();
		}

		public void ResetPosition(bool notifyResize, Vector2 posScale)
		{
			//IL_0007: Unknown result type (might be due to invalid IL or missing references)
			//IL_0011: Unknown result type (might be due to invalid IL or missing references)
			//IL_001e: Unknown result type (might be due to invalid IL or missing references)
			//IL_0028: Unknown result type (might be due to invalid IL or missing references)
			SetPosition(FBlock.Position.x * posScale.x, FBlock.Position.y * posScale.y, notifyResize);
		}

		public void SetPosition(float x, float y, bool notifyResize = true)
		{
			MainView.x = x;
			MainView.y = y;
			if (notifyResize)
			{
				OnPosChanged?.Invoke();
			}
		}
	}
	public class CtlNodeCanvas
	{
		/// <summary>
		/// 画布边缘宽度
		/// </summary>
		private int CANVAS_EDGE = 400;

		public UI_ComNodeCanvas MainView { get; set; }

		public List<CtlNodeBlock> Blocks { get; set; } = new List<CtlNodeBlock>();


		public Action OnContentPosChange { get; set; }

		public Margin Margin { get; set; }

		public GComponent Container => MainView.m_zoom.m_container;

		public GComponent Zoom => MainView.m_zoom;

		public Vector2 PosScale { get; set; } = new Vector2(1f, 1f);


		private Action<FCommand> OnClickCommandCallback { get; set; }

		public CtlNodeCanvas(UI_ComNodeCanvas com)
		{
			//IL_0021: Unknown result type (might be due to invalid IL or missing references)
			//IL_0026: Unknown result type (might be due to invalid IL or missing references)
			MainView = com;
			MainView.draggable = true;
			MainView.onDragStart.Add(delegate(EventContext context)
			{
				context.PreventDefault();
				if (context.inputEvent.button != 0)
				{
					Container.StartDrag((int)context.data);
				}
			});
			Container.onPositionChanged.Add((EventCallback1)delegate
			{
				float xv = Mathf.Clamp(Container.x, (float)Margin.left, (float)Margin.right);
				float yv = Mathf.Clamp(Container.y, (float)Margin.top, (float)Margin.bottom);
				Container.SetXY(xv, yv);
				OnContentPosChange?.Invoke();
			});
			MainView.onRollOver.Add((EventCallback1)delegate
			{
				Stage.inst.onMouseWheel.Add(OnScrollChanged);
			});
			MainView.onRollOut.Add((EventCallback1)delegate
			{
				Stage.inst.onMouseWheel.Remove(OnScrollChanged);
			});
		}

		private void OnScrollChanged(EventContext context)
		{
			//IL_0063: Unknown result type (might be due to invalid IL or missing references)
			if (context.inputEvent.ctrlOrCmd)
			{
				float num = (0f - context.inputEvent.mouseWheelDelta) * 0.2f;
				float scaleX = Zoom.scaleX;
				if (scaleX <= 1f)
				{
					num /= 3f;
				}
				scaleX = Mathf.Clamp(scaleX + num, 0.2f, 4f);
				GTween.Kill(Zoom);
				Zoom.TweenScale(new Vector2(scaleX, scaleX), 0.3f);
			}
		}

		public void Resize()
		{
			int num = 0;
			int num2 = 0;
			int num3 = 0;
			int num4 = 0;
			if (Container.numChildren > 0)
			{
				GObject childAt = Container.GetChildAt(0);
				num = (int)childAt.x;
				num3 = (int)(childAt.x + childAt.width);
				num2 = (int)childAt.y;
				num4 = (int)(childAt.y + childAt.height);
			}
			GObject[] children = Container.GetChildren();
			foreach (GObject gObject in children)
			{
				if (gObject.x < (float)num)
				{
					num = (int)gObject.x;
				}
				if (gObject.x + gObject.width > (float)num3)
				{
					num3 = (int)(gObject.x + gObject.width);
				}
				if (gObject.y < (float)num2)
				{
					num2 = (int)gObject.y;
				}
				if (gObject.y + gObject.height > (float)num4)
				{
					num4 = (int)(gObject.y + gObject.height);
				}
			}
			num -= CANVAS_EDGE;
			num3 += CANVAS_EDGE;
			num2 -= CANVAS_EDGE;
			num4 += CANVAS_EDGE;
			Margin = new Margin
			{
				left = -num3,
				right = -num,
				top = -num4,
				bottom = -num2
			};
		}

		public void AddBlock(CtlNodeBlock block, bool notifyResize = true)
		{
			//IL_0033: Unknown result type (might be due to invalid IL or missing references)
			block.OnPosChanged = Resize;
			Blocks.Add(block);
			Container.AddChild(block.MainView);
			block.ResetPosition(notifyResize, PosScale);
			block.RefreshBlock();
			block.SetOnClickCommand(OnClickCommand);
			Main.LogDebug($"添加Block：{block.FBlock.Name}，位置：{block.MainView.x},{block.MainView.y}");
		}

		public void SetOnClickCommand(Action<FCommand> callback)
		{
			OnClickCommandCallback = callback;
		}

		private void OnClickCommand(FCommand obj)
		{
			OnClickCommandCallback?.Invoke(obj);
		}

		public void RemoveBlock(CtlNodeBlock block, bool notifyResize = true)
		{
			block.OnPosChanged = null;
			Blocks.Remove(block);
			Container.RemoveChild(block.MainView);
			if (notifyResize)
			{
				Resize();
			}
		}

		public void Bind(FFlowchart fFlowchart)
		{
			Clear();
			foreach (FBlock block2 in fFlowchart.Blocks)
			{
				CtlNodeBlock block = new CtlNodeBlock(UI_ComNodeBlock.CreateInstance(), block2);
				AddBlock(block, notifyResize: false);
			}
			Container.SetXY(0f, 0f);
			Resize();
			Main.LogDebug($"当前Block数量：{Blocks.Count}");
			Main.LogDebug($"当前margin：l:{Margin.left} r:{Margin.right} t:{Margin.top} b:{Margin.bottom}");
		}

		public void FocusToFirstBlock()
		{
			//IL_0045: Unknown result type (might be due to invalid IL or missing references)
			if (Blocks.Count > 0)
			{
				CtlNodeBlock block = Blocks.MinBy((CtlNodeBlock b) => b.MainView.x);
				SetPosition(block, new Vector2(200f, 200f));
			}
		}

		public void SetPosition(float x, float y)
		{
			Container.SetXY(x, y);
		}

		public void SetPosition(CtlNodeBlock block, Vector2 offset = default(Vector2))
		{
			//IL_002e: Unknown result type (might be due to invalid IL or missing references)
			//IL_002f: Unknown result type (might be due to invalid IL or missing references)
			//IL_0030: Unknown result type (might be due to invalid IL or missing references)
			//IL_0035: Unknown result type (might be due to invalid IL or missing references)
			//IL_003c: Unknown result type (might be due to invalid IL or missing references)
			//IL_0042: Unknown result type (might be due to invalid IL or missing references)
			if (block?.MainView != null)
			{
				Vector2 val = default(Vector2);
				((Vector2)(ref val))..ctor(0f - block.MainView.x, 0f - block.MainView.y);
				val += offset;
				Container.SetXY(val.x, val.y);
			}
		}

		public void Clear()
		{
			foreach (CtlNodeBlock block in Blocks)
			{
				block.OnPosChanged = null;
				block.MainView.Dispose();
			}
			Blocks.Clear();
			Container.RemoveChildren();
		}
	}
