	public class CtlDropdownPropertyDrawer : CtlPropertyDrawerBase
	{
		private string _drawerName;

		private Func<IEnumerable<string>> _optionsGetter;

		private readonly Action<int> _indexSetter;

		private readonly Func<int> _indexGetter;

		private UI_ComDropdownDrawer Drawer => (UI_ComDropdownDrawer)base.Component;

		private CtlComboSearchBox SearchBox { get; set; }

		public CtlDropdownPropertyDrawer(string drawerName, Func<IEnumerable<string>> optionsGetter, Action<int> indexSetter, Func<int> indexGetter)
		{
			_drawerName = drawerName;
			_optionsGetter = optionsGetter;
			_indexSetter = indexSetter;
			_indexGetter = indexGetter;
		}

		protected override GComponent OnCreateCom()
		{
			UI_ComDropdownDrawer uI_ComDropdownDrawer = UI_ComDropdownDrawer.CreateInstance();
			uI_ComDropdownDrawer.title = _drawerName;
			SearchBox = new CtlComboSearchBox(uI_ComDropdownDrawer.m_searchDropdown);
			SearchBox.SetItems(_optionsGetter().ToArray());
			SearchBox.SelectedIndex = OnGetPropertyIndex();
			CtlComboSearchBox searchBox = SearchBox;
