		public ChangeIdUndoCommand(IModData modData, int oldId, int newId, Action<IModData, int> onChangeId)
		{
			_modData = modData;
			_oldId = oldId;
			_newId = newId;
			_onChangeId = onChangeId;
		}

		public void Execute()
		{
