	public class CtlIDPropertyDrawer : CtlPropertyDrawerBase
	{
		private string _drawerName;

		private Func<IEnumerable<IModData>> _dataListGetter;

		private Action<int> _onChangeID;

		private IModData _modData;

		private UI_ComNumberDrawer Drawer => (UI_ComNumberDrawer)base.Component;

		public IEnumerable<IModData> DataList => _dataListGetter();

		public CtlIDPropertyDrawer(string drawerName, IModData modData, Func<IEnumerable<IModData>> dataListGetter, Func<IModData, string> dataTitleGetter, Action<IModData, int> onChangeId, Action<IModData, IModData> onSwiftId, Action onCancel)
		{
			CtlIDPropertyDrawer ctlIDPropertyDrawer = this;
			_drawerName = drawerName;
			_dataListGetter = dataListGetter;
			_modData = modData;
			_onChangeID = delegate(int num)
			{
				if (num != modData.Id)
				{
					IModData otherData = ctlIDPropertyDrawer.DataList.FirstOrDefault((IModData data) => data.Id == num && data != modData);
					if (otherData != null)
					{
						WindowConfirmDialog.CreateDialog("提示", $"已经存在ID为 {num} 的数据，是否交换 {dataTitleGetter(modData)} 与 {dataTitleGetter(otherData)} ID？", canCancel: true, delegate
						{
							ctlIDPropertyDrawer.Record(new SwiftIdUndoCommand(modData, otherData, onSwiftId));
							ctlIDPropertyDrawer.OnChanged?.Invoke();
						}, delegate
						{
							onCancel?.Invoke();
						});
					}
					else
					{
						WindowConfirmDialog.CreateDialog("提示", $"即将把 {dataTitleGetter(modData)} 的ID修改为 {num}，是否继续？", canCancel: true, delegate
						{
							ctlIDPropertyDrawer.Record(new ChangeIdUndoCommand(modData, modData.Id, num, onChangeId));
							ctlIDPropertyDrawer.OnChanged?.Invoke();
						}, delegate
						{
							onCancel?.Invoke();
						});
					}
				}
			};
		}

		protected override GComponent OnCreateCom()
		{
			UI_ComNumberDrawer uI_ComNumberDrawer = UI_ComNumberDrawer.CreateInstance();
			uI_ComNumberDrawer.BindIntEndEdit(_onChangeID);
			uI_ComNumberDrawer.m_inContent.text = _modData.Id.ToString();
			uI_ComNumberDrawer.title = _drawerName;
			return uI_ComNumberDrawer;
		}

		protected override void OnRefresh()
		{
			Drawer.m_inContent.text = _modData.Id.ToString();
		}

		protected override void SetDrawerEditable(bool value)
		{
			Drawer.SetEditable(value);
		}
	}
