	{
		protected GTreeNode _bindNode;

		protected string _icon;

		public abstract bool IsLeaf { get; }

		protected abstract List<ProjectTreeNodeBase> Children { get; }

		public virtual ProjectTreeNodeBase Parent { get; set; }

		public virtual string ResURL { get; }

		public override string Icon => _icon;

		public virtual GTreeNode BindNode
		{
			get
			{
				if (_bindNode == null)
				{
					GTreeNode gTreeNode = new GTreeNode(!IsLeaf);
					gTreeNode.data = this;
					gTreeNode.expanded = true;
					gTreeNode._resURL = ResURL;
					_bindNode = gTreeNode;
				}
				return _bindNode;
			}
			set
			{
				_bindNode = value;
				_bindNode.data = this;
			}
		}

		public virtual void SetIcon(string icon)
		{
			_icon = icon;
			_bindNode.icon = icon;
		}
	}
	public abstract class ProjectTreeFolder : ProjectTreeNodeBase
	{
		public override bool IsLeaf => false;

		protected override List<ProjectTreeNodeBase> Children { get; } = new List<ProjectTreeNodeBase>();


		public IReadOnlyList<ProjectTreeNodeBase> AllChildren => Children;

		public virtual void AddChild(ProjectTreeNodeBase child)
		{
			child.Parent = this;
			Children.Add(child);
			BindNode.AddChild(child.BindNode);
		}

		public virtual void RemoveChild(ProjectTreeNodeBase child)
		{
			child.Parent = null;
			Children.Remove(child);
			BindNode.RemoveChild(child.BindNode);
		}

		public virtual void InsertChild(int index, ProjectTreeNodeBase child)
		{
			child.Parent = this;
			Children.Insert(index, child);
			BindNode.AddChildAt(child.BindNode, index);
		}

		public virtual void RemoveChildAt(int index)
		{
			ProjectTreeNodeBase projectTreeNodeBase = Children[index];
			projectTreeNodeBase.Parent = null;
			Children.RemoveAt(index);
			BindNode.RemoveChild(projectTreeNodeBase.BindNode);
		}

		public virtual void RemoveAllChildren()
		{
			foreach (ProjectTreeNodeBase child in Children)
			{
				child.Parent = null;
			}
			Children.Clear();
			BindNode.RemoveChildren();
		}
	}
