	public class FCommandConverter : JsonConverter
	{
		public override void WriteJson(JsonWriter writer, object value, JsonSerializer serializer)
		{
			serializer.Serialize(writer, value);
		}

		public override object ReadJson(JsonReader reader, Type objectType, object existingValue, JsonSerializer serializer)
		{
			JObject val = JObject.Load(reader);
			string text = ((object)val["CmdType"])?.ToString();
			FCommand fCommand = ((!string.IsNullOrEmpty(text)) ? FFlowchartTools.CreateFCommand(text) : new FCommand());
			serializer.Populate(((JToken)val).CreateReader(), (object)fCommand);
			return fCommand;
		}

		public override bool CanConvert(Type objectType)
		{
			return typeof(FCommand).IsAssignableFrom(objectType);
		}
	}
