	public class FPatchManager : MonoBehaviour
	{
		public Dictionary<string, List<FPatch>> PatchGroup = new Dictionary<string, List<FPatch>>();

		public void Init()
		{
		}

		public void Reset()
		{
			PatchGroup.Clear();
		}

		public void AddPatch(FPatch patch)
		{
			string targetFlowchart = patch.TargetFlowchart;
			if (!PatchGroup.ContainsKey(targetFlowchart))
			{
				PatchGroup.Add(targetFlowchart, new List<FPatch>());
			}
			PatchGroup[targetFlowchart].Add(patch);
		}

		public List<FPatch> GetAllPatch()
		{
			List<FPatch> list = new List<FPatch>();
			foreach (KeyValuePair<string, List<FPatch>> item in PatchGroup)
			{
				list.AddRange(item.Value);
			}
			return list;
		}

		public List<FPatch> GetPatches(string flowchartName)
		{
			List<FPatch> list = new List<FPatch>();
			if (PatchGroup.ContainsKey(flowchartName))
			{
				list.AddRange(PatchGroup[flowchartName]);
			}
			return list;
		}

		public void PatchFlowchart(Flowchart flowchart)
		{
			List<FPatch> patches = GetPatches(flowchart.GetParentName());
			if (patches.Count == 0 || (Object)(object)((Component)flowchart).GetComponent<FPatchRecord>() != (Object)null)
			{
				return;
			}
			((Component)flowchart).gameObject.AddComponent<FPatchRecord>();
			ILookup<int, FPatch> lookup = patches.ToLookup((FPatch p) => p.TargetBlock);
			Block[] components = ((Component)flowchart).GetComponents<Block>();
			foreach (Block val in components)
			{
				if (!lookup.Contains(val.ItemId))
				{
					continue;
				}
				ILookup<int, FPatch> lookup2 = lookup[val.ItemId].ToLookup((FPatch p) => p.TargetCommand);
				List<Command> list = new List<Command>();
				for (int j = 0; j < val.CommandList.Count; j++)
				{
					Command val2 = val.CommandList[j];
					if (!lookup2.Contains(val2.ItemId))
					{
						continue;
					}
					List<FPatch> list2 = lookup2[val2.ItemId].ToList();
					list2.Sort((FPatch a, FPatch b) => a.Priority.CompareTo(b.Priority));
					foreach (FPatch item3 in list2)
					{
						switch (item3.Type)
						{
						case FPatch.PatchType.Insert:
						{
							PCommand item = CreatePatchCommand(flowchart, val, item3);
							val.CommandList.Insert(j, (Command)(object)item);
							j++;
							break;
						}
						case FPatch.PatchType.Delete:
							if (!list.Contains(val2))
							{
								list.Add(val2);
							}
							break;
						default:
							throw new ArgumentOutOfRangeException(item3.Type.ToString());
						}
					}
				}
				if (lookup2.Contains(-1))
				{
					List<FPatch> list3 = lookup2[-1].ToList();
					list3.Sort((FPatch a, FPatch b) => -a.Priority.CompareTo(b.Priority));
					foreach (FPatch item4 in list3)
					{
						if (item4.Type == FPatch.PatchType.Insert)
						{
							PCommand item2 = CreatePatchCommand(flowchart, val, item4);
							val.CommandList.Add((Command)(object)item2);
							continue;
						}
						throw new ArgumentOutOfRangeException(item4.Type.ToString());
					}
				}
				foreach (Command item5 in list)
				{
					val.CommandList.Remove(item5);
				}
				for (int k = 0; k < val.CommandList.Count; k++)
				{
					val.CommandList[k].CommandIndex = k;
				}
			}
			Main.LogInfo("为" + flowchart.GetParentName() + " 添加Patch");
		}

		private PCommand CreatePatchCommand(Flowchart flowchart, Block block, FPatch fPatch)
		{
			PCommand pCommandType = FFlowchartTools.GetPCommandType(((Component)block).gameObject, fPatch.Command.CmdType);
			pCommandType.Init(block, fPatch.Command);
			((Command)pCommandType).ItemId = flowchart.NextItemId();
			return pCommandType;
		}
	}
