	public class FBlock
	{
		public int ItemID { get; set; }

		public string Name { get; set; }

		public string Description { get; set; }

		[JsonConverter(typeof(Vector2Converter))]
		public Vector2 Position { get; set; }

		[JsonProperty(ItemConverterType = typeof(FCommandConverter))]
		public List<FCommand> Commands { get; set; } = new List<FCommand>();


		public void ReadBlock(Block block)
		{
			//IL_003e: Unknown result type (might be due to invalid IL or missing references)
			//IL_0043: Unknown result type (might be due to invalid IL or missing references)
			//IL_0047: Unknown result type (might be due to invalid IL or missing references)
			ItemID = block.ItemId;
			Name = block.BlockName;
			Description = block.BlockName;
			Rect val = (Rect)AccessTools.Field(typeof(Block), "nodeRect").GetValue(block);
			Position = ((Rect)(ref val)).position;
			foreach (Command command in block.CommandList)
			{
				FCommand fCommand = ((object)command).GetType().CreateBindFCommand();
				fCommand.ReadCommand(command);
				Commands.Add(fCommand);
			}
		}
	}
