	public class FFlowchart : IModData
	{
		public List<FBlock> Blocks = new List<FBlock>();

		public List<FVariable> Variables = new List<FVariable>();

		public int Id { get; set; }

		public string Name { get; set; }

		public int Version { get; set; } = 1;


		public void ReadFlowchart(Flowchart flowchart)
		{
			//IL_0211: Unknown result type (might be due to invalid IL or missing references)
			//IL_0216: Unknown result type (might be due to invalid IL or missing references)
			//IL_0233: Unknown result type (might be due to invalid IL or missing references)
			//IL_0238: Unknown result type (might be due to invalid IL or missing references)
			//IL_0255: Unknown result type (might be due to invalid IL or missing references)
			//IL_025a: Unknown result type (might be due to invalid IL or missing references)
			Id = ((Object)flowchart).GetInstanceID();
			Name = flowchart.GetParentName();
			Block[] components = ((Component)flowchart).GetComponents<Block>();
			foreach (Block block in components)
			{
				FBlock fBlock = new FBlock();
				fBlock.ReadBlock(block);
				Blocks.Add(fBlock);
			}
			foreach (Variable variable in flowchart.Variables)
			{
				FVariable fVariable = new FVariable();
				fVariable.Key = variable.Key;
				fVariable.Type = ((object)variable).GetType().Name;
				StringVariable val = (StringVariable)(object)((variable is StringVariable) ? variable : null);
				if (val == null)
				{
					IntegerVariable val2 = (IntegerVariable)(object)((variable is IntegerVariable) ? variable : null);
					if (val2 == null)
					{
						FloatVariable val3 = (FloatVariable)(object)((variable is FloatVariable) ? variable : null);
						if (val3 == null)
						{
							BooleanVariable val4 = (BooleanVariable)(object)((variable is BooleanVariable) ? variable : null);
							if (val4 == null)
							{
								GameObjectVariable val5 = (GameObjectVariable)(object)((variable is GameObjectVariable) ? variable : null);
								if (val5 == null)
								{
									TransformVariable val6 = (TransformVariable)(object)((variable is TransformVariable) ? variable : null);
									if (val6 == null)
									{
										Vector2Variable val7 = (Vector2Variable)(object)((variable is Vector2Variable) ? variable : null);
										if (val7 == null)
										{
											Vector3Variable val8 = (Vector3Variable)(object)((variable is Vector3Variable) ? variable : null);
											if (val8 == null)
											{
												ColorVariable val9 = (ColorVariable)(object)((variable is ColorVariable) ? variable : null);
												if (val9 == null)
												{
													MaterialVariable val10 = (MaterialVariable)(object)((variable is MaterialVariable) ? variable : null);
													if (val10 == null)
													{
														TextureVariable val11 = (TextureVariable)(object)((variable is TextureVariable) ? variable : null);
														if (val11 == null)
														{
															Rigidbody2DVariable val12 = (Rigidbody2DVariable)(object)((variable is Rigidbody2DVariable) ? variable : null);
															if (val12 == null)
															{
																ObjectVariable val13 = (ObjectVariable)(object)((variable is ObjectVariable) ? variable : null);
																if (val13 == null)
																{
																	SpriteVariable val14 = (SpriteVariable)(object)((variable is SpriteVariable) ? variable : null);
																	if (val14 != null)
																	{
																		fVariable.Value = ((Object)((VariableBase<Sprite>)(object)val14).Value).name;
																	}
																	else
																	{
																		fVariable.Value = "[Unknown]";
																	}
																}
																else
																{
																	fVariable.Value = ((VariableBase<Object>)(object)val13).Value.name;
																}
															}
															else
															{
																fVariable.Value = ((Object)((VariableBase<Rigidbody2D>)(object)val12).Value).name;
															}
														}
														else
														{
															fVariable.Value = ((Object)((VariableBase<Texture>)(object)val11).Value).name;
														}
													}
													else
													{
														fVariable.Value = ((Object)((VariableBase<Material>)(object)val10).Value).name;
													}
												}
												else
												{
													Color value = ((VariableBase<Color>)(object)val9).Value;
													fVariable.Value = ((object)(Color)(ref value)).ToString();
												}
											}
											else
											{
												Vector3 value2 = ((VariableBase<Vector3>)(object)val8).Value;
												fVariable.Value = ((object)(Vector3)(ref value2)).ToString();
											}
										}
										else
										{
											Vector2 value3 = ((VariableBase<Vector2>)(object)val7).Value;
											fVariable.Value = ((object)(Vector2)(ref value3)).ToString();
										}
									}
									else
									{
										fVariable.Value = ((Object)((VariableBase<Transform>)(object)val6).Value).name;
									}
								}
								else
								{
									fVariable.Value = ((Object)((VariableBase<GameObject>)(object)val5).Value).name;
								}
							}
							else
							{
								fVariable.Value = ((VariableBase<bool>)(object)val4).Value.ToString();
							}
						}
						else
						{
							fVariable.Value = ((VariableBase<float>)(object)val3).Value.ToString("F2");
						}
					}
					else
					{
						fVariable.Value = ((VariableBase<int>)(object)val2).Value.ToString();
					}
				}
				else
				{
					fVariable.Value = ((VariableBase<string>)(object)val).Value;
				}
			}
		}
	}
	public static class FFlowchartTools
	{
		private static Dictionary<string, Type> _fCommandBinderDic;

		private static Dictionary<string, Type> _pCommandBinderDic;

		public static Dictionary<string, Type> FCommandBinderDic
		{
			get
			{
				if (_fCommandBinderDic == null)
				{
					_fCommandBinderDic = new Dictionary<string, Type>();
					Type[] types = Assembly.GetExecutingAssembly().GetTypes();
					foreach (Type type in types)
					{
						FCommandBinderAttribute customAttribute = type.GetCustomAttribute<FCommandBinderAttribute>();
						if (customAttribute != null && customAttribute.Type?.FullName != null)
						{
							Main.LogInfo($"Bind FCommand {customAttribute.Type} {type}");
							_fCommandBinderDic.Add(customAttribute.Type.FullName, type);
						}
					}
				}
				return _fCommandBinderDic;
			}
		}

		public static Dictionary<string, Type> PCommandBinderDic
		{
			get
			{
				if (_pCommandBinderDic == null)
				{
					_pCommandBinderDic = new Dictionary<string, Type>();
					Type[] types = Assembly.GetExecutingAssembly().GetTypes();
					foreach (Type type in types)
					{
						PCommandBinderAttribute customAttribute = type.GetCustomAttribute<PCommandBinderAttribute>();
						if (customAttribute != null && customAttribute.BindType != null)
						{
							Main.LogInfo($"Bind PCommand {customAttribute.BindType} {type}");
							_pCommandBinderDic.Add(customAttribute.BindType, type);
						}
					}
				}
				return _pCommandBinderDic;
			}
		}

		public static FFlowchart ConvertToFFlowchart(this Flowchart flowchart)
		{
			FFlowchart fFlowchart = new FFlowchart();
			fFlowchart.ReadFlowchart(flowchart);
			return fFlowchart;
		}

		public static void ExportAllFungusFlowchart(string outputPath)
		{
			IEnumerable<Flowchart> enumerable = from g in Resources.LoadAll<GameObject>("")
				select g.GetComponentInChildren<Flowchart>();
			if (Directory.Exists(outputPath))
			{
				Directory.Delete(outputPath, recursive: true);
			}
			Directory.CreateDirectory(outputPath);
			foreach (Flowchart item in enumerable)
			{
				if (!((Object)(object)item == (Object)null))
				{
					try
					{
						ExportFungusFlowchart(item, outputPath);
					}
					catch (Exception obj)
					{
						Main.LogError(obj);
					}
				}
			}
		}

		public static void ExportCurrentSceneFungusFlowchart(string outputPath)
		{
			List<Flowchart> list = new List<Flowchart>();
			Flowchart[] array = Resources.FindObjectsOfTypeAll<Flowchart>();
			for (int i = 0; i < array.Length; i++)
			{
				((Component)array[i]).GetComponentsInChildren<Flowchart>(true, list);
				foreach (Flowchart item in list)
				{
					try
					{
						ExportFungusFlowchart(item, outputPath);
					}
					catch (Exception obj)
					{
						Main.LogError(obj);
					}
					Resources.UnloadAsset((Object)(object)item);
				}
			}
			Resources.UnloadUnusedAssets();
		}

		private static void ExportFungusFlowchart(Flowchart flowchart, string outputPath)
		{
			FFlowchart fFlowchart = flowchart.ConvertToFFlowchart();
			string contents = JsonConvert.SerializeObject((object)fFlowchart, (Formatting)1);
			string text = outputPath + "/" + fFlowchart.Name + ".json";
			File.WriteAllText(text, contents);
			Main.LogInfo("Export Fungus " + fFlowchart.Name + " to " + text);
		}

		public static Dictionary<string, FFlowchart> ImportAllFFlowchart(string dir)
		{
			Dictionary<string, FFlowchart> dictionary = new Dictionary<string, FFlowchart>();
			if (!Directory.Exists(dir))
			{
				return dictionary;
			}
			string[] files = Directory.GetFiles(dir);
			foreach (string text in files)
			{
				FFlowchart fFlowchart = ImportFFlowchart(text);
				if (fFlowchart == null)
				{
					Main.LogWarning("FFlowchart为空， Path : " + text);
					continue;
				}
				if (dictionary.ContainsKey(fFlowchart.Name))
				{
					Main.LogWarning("存在相同的FFlowchart，Name : " + fFlowchart.Name + " Path : " + text);
				}
				dictionary[fFlowchart.Name] = fFlowchart;
			}
			return dictionary;
		}

		public static FFlowchart ImportFFlowchart(string path)
		{
			return JsonConvert.DeserializeObject<FFlowchart>(File.ReadAllText(path));
		}

		public static FCommand CreateBindFCommand(this Type cmdType)
		{
			return (FCommand)Activator.CreateInstance(cmdType.GetFCommandType());
		}

		public static Type GetFCommandType(this Type cmdType)
		{
			string key = cmdType.FullName ?? "";
			if (!FCommandBinderDic.TryGetValue(key, out var value))
			{
				return typeof(FCommand);
			}
			return value;
		}

		public static FCommand CreateFCommand(string cmdType)
		{
			if (FCommandBinderDic.ContainsKey(cmdType))
			{
				return (FCommand)Activator.CreateInstance(FCommandBinderDic[cmdType]);
			}
			return new FCommand();
		}

		public static PCommand GetPCommandType(GameObject go, string cmdType)
		{
			Type type = typeof(PCommand);
			if (PCommandBinderDic.ContainsKey(cmdType))
			{
				type = PCommandBinderDic[cmdType];
			}
			return (PCommand)(object)go.AddComponent(type);
		}
	}
