			{
				Main.LogDebug("Fungus 满足条件" + condition + " 跳转NextEvent: " + nextEvent);
				DialogAnalysis.OnDialogComplete += ((Command)this).Continue;
				DialogAnalysis.StartDialogEvent(nextEvent, env);
			}
			else
