			}
			else
			{
				stringBuilder.AppendLine("敌方ID: " + MonsterFungusID);
			}
			stringBuilder.AppendLine("战斗类型: " + GetFightTypeSummary(FightType));
			if (MonstarAddBuffList.Count > 0)
			{
				stringBuilder.Append("敌方Buff:");
				stringBuilder.AppendLine(string.Join("|", MonstarAddBuffList));
			}
			if (HeroAddBuffList.Count > 0)
			{
				stringBuilder.Append("我方Buff:");
				stringBuilder.AppendLine(string.Join("|", HeroAddBuffList));
			}
			if (BackgroundSetType == 0)
			{
				stringBuilder.AppendLine($"背景ID: {BackgroundID}");
			}
			else
			{
				stringBuilder.AppendLine("背景ID: " + BackgroundFungusID);
			}
			if (FightTalk > 0)
			{
				stringBuilder.AppendLine("战场对话: " + ((FightTalk == 1) ? "开启" : "关闭"));
			}
			if (FightCard > 0)
			{
				stringBuilder.AppendLine("固定抽排: " + ((FightCard == 1) ? "开启" : "关闭"));
			}
			stringBuilder.AppendLine("战前逃跑: " + ((CanFpRun == 1) ? "允许" : "禁止"));
			stringBuilder.AppendLine("战场音乐: " + FightMusic);
			if (SeaRemoveNPCFlag)
			{
				stringBuilder.AppendLine("海域移除NPC: " + SeaRemoveNPCUUID);
			}
			return stringBuilder.ToString();
		}

