namespace SkySwordKill.Next.DialogSystem
{
	public class AvatarNextData
	{
		public DataGroup<int> IntGroup { get; set; } = new DataGroup<int>();


		public DataGroup<string> StrGroup { get; set; } = new DataGroup<string>();


		public Dictionary<string, TriggerState> TriggerStates { get; set; } = new Dictionary<string, TriggerState>();


		public TriggerState GetTriggerState(string triggerID, bool createNew = true, bool triggerDefault = true)
		{
			if (TriggerStates.TryGetValue(triggerID, out var value))
			{
				return value;
			}
			if (createNew)
			{
				value = new TriggerState();
				TriggerStates.Add(triggerID, value);
				value.Enabled = triggerDefault;
				return value;
			}
			return null;
		}

		/// <summary>
		/// 设置触发器开关
		/// </summary>
		/// <param name="triggerID"></param>
		/// <param name="on"></param>
		public void SetTrigger(string triggerID, bool on)
		{
			GetTriggerState(triggerID).Enabled = on;
		}

		/// <summary>
		/// 修改触发器触发次数
		/// </summary>
		/// <param name="triggerID"></param>
		/// <param name="delta"></param>
		public void ChangeTriggerCount(string triggerID, int delta)
		{
			GetTriggerState(triggerID).Count += delta;
		}
	}
	public static class DialogAnalysis
	{
		public static Lazy<MethodInfo> addOptionMethod = new Lazy<MethodInfo>(() => typeof(MenuDialog).GetMethod("AddOption", BindingFlags.Instance | BindingFlags.NonPublic, null, new Type[4]
		{
			typeof(string),
			typeof(bool),
			typeof(bool),
			typeof(UnityAction)
		}, null));

		/// <summary>
		/// 对话注册事件
		/// </summary>
		private static Dictionary<string, IDialogEvent> _registerEvents = new Dictionary<string, IDialogEvent>();

		private static Dictionary<string, IDialogEnvQuery> _registerEnvQueries = new Dictionary<string, IDialogEnvQuery>();

		public static AvatarNextData AvatarNextData = new AvatarNextData();

		/// <summary>
		/// 对话数据
		/// </summary>
		public static Dictionary<string, DialogEventData> DialogDataDic { get; set; } = new Dictionary<string, DialogEventData>();


		/// <summary>
		/// 对话触发器
		/// </summary>
		public static Dictionary<string, DialogTriggerData> DialogTriggerDataDic { get; set; } = new Dictionary<string, DialogTriggerData>();


		/// <summary>
		/// 对话临时储存角色
		/// </summary>
		public static Dictionary<string, int> TmpCharacter { get; set; } = new Dictionary<string, int>();


		public static DialogEnvironment CurEnv { get; set; }

		public static Queue<DialogEventRtData> EventQueue { get; set; } = new Queue<DialogEventRtData>();


		private static ExpressionEvaluator CurEvaluator { get; set; }

		public static bool IsRunningEvent { get; private set; } = false;


		public static bool IsBreakTalk { get; private set; } = false;


		public static event Action OnDialogComplete;

		public static void OnEnterWorld()
		{
			CancelEvent();
		}

		public static void Init()
		{
			foreach (Type[] item in from assembly in AppDomain.CurrentDomain.GetAssemblies()
				select assembly.GetTypes())
			{
				foreach (Type type in item)
				{
					if (typeof(IDialogEvent).IsAssignableFrom(type))
					{
						foreach (DialogEventAttribute customAttribute in type.GetCustomAttributes<DialogEventAttribute>())
						{
							RegisterCommand(customAttribute.RegisterCommand, Activator.CreateInstance(type) as IDialogEvent);
						}
					}
					else
					{
						if (!typeof(IDialogEnvQuery).IsAssignableFrom(type))
						{
							continue;
						}
						foreach (DialogEnvQueryAttribute customAttribute2 in type.GetCustomAttributes<DialogEnvQueryAttribute>())
						{
							RegisterEnvQuery(customAttribute2.RegisterMethod, Activator.CreateInstance(type) as IDialogEnvQuery);
						}
					}
				}
			}
		}

		public static void RegisterCommand(string command, IDialogEvent cEvent)
		{
			_registerEvents[command] = cEvent;
		}

		private static void RegisterEnvQuery(string method, IDialogEnvQuery cQuery)
		{
			_registerEnvQueries[method] = cQuery;
		}

		private static void Evaluator_PreEvaluateFunction(object sender, FunctionPreEvaluationEventArg e)
		{
			IDialogEnvQuery envQuery = GetEnvQuery(e.Name);
			DialogEnvironment dialogEnvironment = ((e.This != null) ? (e.This as DialogEnvironment) : (e.Evaluator.Context as DialogEnvironment));
			if (envQuery != null && dialogEnvironment != null)
			{
				e.Value = envQuery.Execute(new DialogEnvQueryContext(dialogEnvironment, e.EvaluateArgs()));
				e.FunctionReturnedValue = true;
			}
		}

		public static ExpressionEvaluator GetEvaluate(DialogEnvironment env)
		{
			if (CurEvaluator == null)
			{
				CurEvaluator = CreateNewEvaluate(env);
			}
			else
			{
				CurEvaluator.Context = env;
			}
			return CurEvaluator;
		}

		public static ExpressionEvaluator CreateNewEvaluate(DialogEnvironment env)
		{
			ExpressionEvaluator expressionEvaluator = new ExpressionEvaluator();
			expressionEvaluator.Context = env ?? new DialogEnvironment();
			expressionEvaluator.PreEvaluateFunction += Evaluator_PreEvaluateFunction;
			return expressionEvaluator;
		}

		public static bool TryTriggerByID(string triggerID, DialogEnvironment env = null)
		{
			DialogEnvironment env2 = env ?? new DialogEnvironment();
			if (DialogTriggerDataDic.TryGetValue(triggerID, out var value))
			{
				try
				{
					if (!IsTriggerOn(value))
					{
						return false;
					}
					if (CheckCondition(value.Condition, env2))
					{
						Main.LogInfo("触发器 [" + triggerID + "] " + value.Condition + " 触发成功。");
						if (value.Once)
						{
							AvatarNextData.SetTrigger(triggerID, on: false);
						}
						AvatarNextData.ChangeTriggerCount(triggerID, 1);
						SwitchDialogEvent(triggerID, env2);
						return true;
					}
				}
				catch (Exception obj)
				{
					Main.LogError("触发器 [" + triggerID + "] " + value.Condition + " 触发失败。");
					Main.LogError(obj);
				}
			}
			else
			{
				Main.LogError("触发器 [" + triggerID + "] 不存在。");
			}
			return false;
		}

		public static bool TryTrigger(IEnumerable<string> triggerTypes, DialogEnvironment env = null, bool triggerAll = false)
		{
			DialogEnvironment env2 = env ?? new DialogEnvironment();
			IOrderedEnumerable<DialogTriggerData> orderedEnumerable = from triggerData in DialogTriggerDataDic.Values
				where triggerTypes.Contains(triggerData.Type)
				orderby triggerData.Priority descending
				select triggerData;
			bool result = false;
			foreach (DialogTriggerData item in orderedEnumerable)
			{
				try
				{
					if (IsTriggerOn(item) && CheckCondition(item.Condition, env2))
					{
						Main.LogInfo("触发器 [" + item.ID + "] " + item.Condition + " 触发成功。");
						if (item.Once)
						{
							AvatarNextData.SetTrigger(item.ID, on: false);
						}
						AvatarNextData.ChangeTriggerCount(item.ID, 1);
						if (!triggerAll)
						{
							SwitchDialogEvent(item.TriggerEvent, env2);
							return true;
						}
						StartDialogEvent(item.TriggerEvent, env2);
						result = true;
					}
				}
				catch (Exception obj)
				{
					Main.LogError("触发器 [" + item.ID + "] " + item.Condition + " 触发判断失败！请检查表达式是否正确！");
					Main.LogError(obj);
				}
			}
			return result;
		}

		public static bool IsTriggerOn(DialogTriggerData triggerData)
		{
			return AvatarNextData.GetTriggerState(triggerData.ID, createNew: false)?.Enabled ?? triggerData.Default;
		}

		public static void StartDialogEvent(string eventID, DialogEnvironment env = null)
		{
			if (!DialogDataDic.TryGetValue(eventID, out var value))
			{
				Main.LogWarning("对话事件 " + eventID + " 不存在。");
			}
			else
			{
				StartDialogEvent(value, env);
			}
		}

		public static void StartTestDialogEvent(string dialog, DialogEnvironment env = null)
		{
			DialogEventData dialogEventData = new DialogEventData
			{
				ID = "next_test",
				Option = new string[0],
				Character = new Dictionary<string, int>()
			};
			dialogEventData.Dialog = (from str in dialog.Trim().Split('\n')
				where !string.IsNullOrWhiteSpace(str)
				select str).ToArray();
			StartDialogEvent(dialogEventData, env);
		}

		/// <summary>
		/// 显示对话跳转选项
		/// </summary>
		/// <param name="optionCommands"></param>
		/// <param name="env"></param>
		/// <param name="jumpEvent"></param>
		/// <returns></returns>
		/// <exception cref="T:System.ArgumentException"></exception>
		public static bool RunDialogEventOption(DialogOptionCommand[] optionCommands, DialogEnvironment env, ref string jumpEvent)
		{
			ClearMenu();
			bool result = false;
			foreach (DialogOptionCommand optionCommand in optionCommands)
			{
				if (optionCommand.Option == "Default")
				{
					jumpEvent = optionCommand.TagEvent;
					continue;
				}
				try
				{
					if (!CheckCondition(optionCommand.Condition, env))
					{
						continue;
					}
					result = true;
					AddMenu(optionCommand.Option, delegate
					{
						if (!string.IsNullOrEmpty(optionCommand.TagEvent))
						{
							SwitchDialogEvent(optionCommand.TagEvent);
						}
						else
						{
							CompleteEvent();
						}
					});
				}
				catch (Exception innerException)
				{
					throw new ArgumentException("选项 [" + optionCommand.Option + "] " + optionCommand.Condition + " 触发判断失败！请检查表达式是否正确！", innerException);
				}
			}
			return result;
		}

		/// <summary>
		/// 运行剧情指令
		/// </summary>
		/// <param name="command"></param>
		/// <param name="environment"></param>
		/// <param name="callback"></param>
		/// <exception cref="T:System.ArgumentNullException"></exception>
		public static void RunDialogEventCommand(DialogCommand command, DialogEnvironment environment, Action callback = null)
		{
			if (_registerEvents.TryGetValue(command.Command, out var value))
			{
				try
				{
					value.Execute(command, environment, delegate
					{
						callback?.Invoke();
					});
					return;
				}
				catch (Exception innerException)
				{
					throw new ArgumentNullException("指令 " + command.RawCommand + " 执行错误！", innerException);
				}
			}
			throw new ArgumentNullException("指令 " + command.Command + " 不存在！");
		}

		/// <summary>
		///
		/// </summary>
		/// <param name="str"></param>
		/// <returns></returns>
		public static bool StringIsNullOrTrue(string str)
		{
			if (!string.IsNullOrWhiteSpace(str))
			{
				return str.Equals("true", StringComparison.OrdinalIgnoreCase);
			}
			return true;
		}

		public static bool CheckCondition(string condition, DialogEnvironment env = null)
		{
			ExpressionEvaluator evaluate = GetEvaluate(env);
			if (!string.IsNullOrWhiteSpace(condition))
			{
				return evaluate.Evaluate<bool>(condition);
			}
			return true;
		}

		public static void TryAddTmpChar(string name, int id)
		{
			TmpCharacter[name] = id;
		}

		public static void Clear()
		{
			DialogDataDic.Clear();
			DialogTriggerDataDic.Clear();
			TmpCharacter.Clear();
			CurEvaluator = null;
			IsRunningEvent = false;
		}

		public static void CancelEvent()
		{
			EventQueue.Clear();
			DialogAnalysis.OnDialogComplete = null;
			CompleteEvent();
		}

		public static void CompleteEvent()
		{
			if (EventQueue.Count > 0)
			{
				RunDialogEvent(EventQueue.Dequeue(), 0);
				return;
			}
			IsRunningEvent = false;
			DialogAnalysis.OnDialogComplete?.Invoke();
			DialogAnalysis.OnDialogComplete = null;
			if (IsBreakTalk)
			{
				Tools.instance.isNeedSetTalk = IsBreakTalk;
				IsBreakTalk = false;
			}
		}

		public static void SwitchDialogEvent(string eventId, DialogEnvironment env = null)
		{
			if (!DialogDataDic.TryGetValue(eventId, out var value))
			{
				Main.LogWarning("对话事件 " + eventId + " 不存在。");
				CompleteEvent();
			}
			SwitchDialogEvent(value, env);
		}

		/// <summary>
		/// 事件开始入口，事件进入队列执行
		/// </summary>
		/// <param name="eventData"></param>
		/// <param name="env"></param>
		public static void StartDialogEvent(DialogEventData eventData, DialogEnvironment env = null)
		{
			DialogEnvironment bindEnv = ((env == null) ? new DialogEnvironment() : env.Clone());
			DialogEventRtData dialogEventRtData = new DialogEventRtData
			{
				BindEventData = eventData,
				BindEnv = bindEnv
			};
			if (!IsRunningEvent)
			{
				RunDialogEvent(dialogEventRtData, 0);
			}
			else
			{
				EventQueue.Enqueue(dialogEventRtData);
			}
		}

		/// <summary>
		/// 事件开始入口，替换当前事件
		/// </summary>
		/// <param name="eventData"></param>
		/// <param name="env"></param>
		public static void SwitchDialogEvent(DialogEventData eventData, DialogEnvironment env = null)
		{
			DialogEnvironment bindEnv = ((env == null) ? new DialogEnvironment() : env.Clone());
			RunDialogEvent(new DialogEventRtData
			{
				BindEventData = eventData,
				BindEnv = bindEnv
			}, 0);
		}

		private static void RunDialogEvent(DialogEventRtData rtEvent, int index)
		{
			CurEnv = rtEvent.BindEnv;
			DialogEventData bindEventData = rtEvent.BindEventData;
			IsRunningEvent = true;
			if (Tools.instance.isNeedSetTalk)
			{
				Tools.instance.isNeedSetTalk = false;
				IsBreakTalk = true;
			}
			CurEnv.curDialogID = bindEventData.ID;
			CurEnv.curDialogIndex = index;
			if (index < 0 || index >= bindEventData.Dialog.Length)
			{
				Main.LogWarning("对话事件 " + CurEnv.curDialogID + " 超出索引。");
				CompleteEvent();
				return;
			}
			bool flag = false;
			string jumpEvent = string.Empty;
			DialogCommand command;
			try
			{
				command = bindEventData.GetDialogCommand(index, CurEnv);
			}
			catch (Exception obj)
			{
				Main.LogError($"事件 [{CurEnv.curDialogID}] 第 {index} 行指令 {bindEventData.Dialog[index]} 解析错误");
				Main.LogError(obj);
				CancelEvent();
				return;
			}
			if (command.IsEnd)
			{
				DialogOptionCommand[] optionCommands = bindEventData.GetOptionCommands();
				try
				{
					flag = RunDialogEventOption(optionCommands, CurEnv, ref jumpEvent);
				}
				catch (Exception obj2)
				{
					Main.LogError("事件 [" + CurEnv.curDialogID + "] 选项判断出错，已清空选项。");
					Main.LogError(obj2);
					ClearMenu();
					CancelEvent();
					return;
				}
			}
			try
			{
				if (flag)
				{
					RunDialogEventCommand(command, CurEnv);
					return;
				}
				RunDialogEventCommand(command, CurEnv, delegate
				{
					if (!command.IsEnd)
					{
						RunDialogEvent(rtEvent, index + 1);
					}
					else if (!string.IsNullOrEmpty(jumpEvent))
					{
						SwitchDialogEvent(jumpEvent);
					}
					else
					{
						CompleteEvent();
					}
				});
			}
			catch (Exception obj3)
			{
				Main.LogError($"事件 [{CurEnv.curDialogID}] 第 {index} 行指令 {command.RawCommand} 执行错误");
				Main.LogError(obj3);
				CancelEvent();
			}
		}

		public static IDialogEnvQuery GetEnvQuery(string method)
		{
			if (_registerEnvQueries.TryGetValue(method, out var value))
			{
				return value;
			}
			return null;
		}

		public static string AnalysisInlineScript(string text, DialogEnvironment env = null)
		{
			StringBuilder stringBuilder = new StringBuilder(text);
			MatchCollection matchCollection = new Regex("\\[&(?<expression>[\\s\\S]*?)&]").Matches(text);
			ExpressionEvaluator evaluate = GetEvaluate(env);
			foreach (Match item in matchCollection)
			{
				string value = item.Groups["expression"].Value;
				string newValue = evaluate.Evaluate(value).ToString();
				stringBuilder.Replace(item.Value, newValue);
			}
			return stringBuilder.ToString();
		}

