		public static string DealSayText(string text, int sayRoleID)
		{
			StringBuilder stringBuilder = new StringBuilder(text);
			int num = NPCEx.NPCIDToNew(sayRoleID);
			Avatar player = Tools.instance.getPlayer();
			if (PlayerEx.IsDaoLv(num))
			{
				string daoLvNickName = PlayerEx.GetDaoLvNickName(num);
				stringBuilder.Replace("{FirstName}", "").Replace("{gongzi}", daoLvNickName).Replace("{xiongdi}", daoLvNickName)
					.Replace("{shidi}", daoLvNickName)
					.Replace("{shixiong}", daoLvNickName);
			}
			else
			{
				stringBuilder.Replace("{FirstName}", player.firstName).Replace("{gongzi}", (player.Sex == 1) ? "公子" : "姑娘").Replace("{xiongdi}", (player.Sex == 1) ? "兄弟" : "姑娘")
					.Replace("{shidi}", (player.Sex == 1) ? "师弟" : "师妹")
					.Replace("{shixiong}", (player.Sex == 1) ? "师兄" : "师姐");
			}
			stringBuilder.Replace("{LastName}", player.lastName).Replace("{xiaozi}", (player.Sex == 1) ? "小子" : "丫头").Replace("{ta}", (player.Sex == 1) ? "他" : "她")
				.Replace("{menpai}", Tools.getStr("menpai" + ((AvatarBase)player).menPai));
			return stringBuilder.ToString();
		}

