		public static void AddMenu(string text, Action callback)
		{
			//IL_0059: Unknown result type (might be due to invalid IL or missing references)
			//IL_005f: Expected O, but got Unknown
			MenuDialog menuDialog = MenuDialog.GetMenuDialog();
			menuDialog.SetActive(true);
			addOptionMethod.Value.Invoke(menuDialog, new object[4]
			{
				text,
				true,
				false,
				(object)new UnityAction(OptionAction)
			});
			void OptionAction()
			{
				((MonoBehaviour)menuDialog).StopAllCoroutines();
				menuDialog.Clear();
				menuDialog.HideSayDialog();
				menuDialog.SetActive(false);
				SayDialog.GetSayDialog().Stop();
				callback?.Invoke();
			}
		}

