				File.WriteAllText(path, JsonConvert.SerializeObject((object)AvatarNextData, (Formatting)1));
			}
			catch (Exception obj)
			{
				Main.LogError("保存Next存档数据失败！");
				Main.LogError(obj);
			}
		}

