		public static CustomStaticFaceInfo GetNpcFaceInfo(int npcId)
		{
			JSONObject npcRandomJsonData = GetNpcRandomJsonData(npcId);
			JSONObject npcJsonData = GetNpcJsonData(npcId);
			JSONObject obj = npcJsonData["BindingNpcID"];
			int importantID = ((obj != null) ? obj.I : 0);
			if (npcRandomJsonData == null)
			{
				return null;
			}
			StaticFaceInfo val = SetAvatarFaceRandomInfo.inst.StaticRandomInfo.Find((StaticFaceInfo item) => item.AvatarScope == importantID);
			if (val != null)
			{
				return StaticFaceUtils.GetFaceInfoByStaticFaceInfo(val);
			}
			return StaticFaceUtils.GetFaceInfoByJson(npcRandomJsonData);
		}

