		public static string GetNpcLocationName(int npcId)
		{
			NPCMap npcMap = NpcJieSuanManager.inst.npcMap;
			string result = "Map.Unknown".I18N();
			if (npcMap.bigMapNPCDictionary != null)
			{
				foreach (KeyValuePair<int, List<int>> item in npcMap.bigMapNPCDictionary)
				{
					foreach (int item2 in item.Value)
					{
						if (item2 != npcId)
						{
							continue;
						}
						result = GetSceneName("AllMaps") + " - " + GetMapRoadName(item.Key.ToString());
						goto IL_01e9;
					}
				}
			}
			if (npcMap.threeSenceNPCDictionary != null)
			{
				foreach (KeyValuePair<string, List<int>> item3 in npcMap.threeSenceNPCDictionary)
				{
					foreach (int item4 in item3.Value)
					{
						if (item4 != npcId)
						{
							continue;
						}
						result = GetSceneName(item3.Key);
						goto IL_01e9;
					}
				}
			}
			if (npcMap.fuBenNPCDictionary != null)
			{
				foreach (KeyValuePair<string, Dictionary<int, List<int>>> item5 in npcMap.fuBenNPCDictionary)
				{
					string key = item5.Key;
					foreach (KeyValuePair<int, List<int>> item6 in item5.Value)
					{
						foreach (int item7 in item6.Value)
						{
							if (item7 == npcId)
							{
								result = GetSceneName(key);
								goto end_IL_01cd;
							}
						}
					}
					continue;
					end_IL_01cd:
					break;
				}
			}
			goto IL_01e9;
			IL_01e9:
			return result;
		}

