	public class DialogCommand
	{
		public string Command { get; set; }

		public string[] ParamList { get; set; }

		public DialogEventData BindEventData { get; set; }

		public bool IsEnd { get; set; }

		public string RawCommand { get; set; }

		public DialogCommand()
		{
		}

		public DialogCommand(string commandStr, DialogEventData bindEventData, DialogEnvironment env, bool isEnd)
		{
			RawCommand = commandStr;
			BindEventData = bindEventData;
			IsEnd = isEnd;
			string text = DialogAnalysis.AnalysisInlineScript(RawCommand, env);
			string[] array = text.Split('*');
			int num = text.IndexOf('#');
			int num2 = text.IndexOf('*');
			if (array.Length >= 2 && (num2 < num || num == -1))
			{
				Command = array[0];
				string text2 = string.Join("*", array.Where((string s, int i) => i > 0));
				ParamList = text2.Split('#');
			}
			else
			{
				Command = "";
				string text3 = array[0];
				ParamList = text3.Split('#');
			}
		}

		public DialogCommand(string commandHead, string[] paramList, DialogEventData bindEventData, bool isEnd)
		{
			RawCommand = "Call " + commandHead + "()";
			Command = commandHead;
			ParamList = paramList;
			BindEventData = bindEventData;
			IsEnd = isEnd;
		}

		public int GetInt(int index, int defaultValue = 0)
		{
			if (index >= ParamList.Length)
			{
				return defaultValue;
			}
			return Convert.ToInt32(ParamList[index]);
		}

		public float GetFloat(int index, float defaultValue = 0f)
		{
			if (index >= ParamList.Length)
			{
				return defaultValue;
			}
			return Convert.ToSingle(ParamList[index]);
		}

		public bool GetBool(int index, bool defaultValue = false)
		{
			if (index >= ParamList.Length)
			{
				return defaultValue;
			}
			return Convert.ToInt32(ParamList[index]) != 0;
		}

		public string GetStr(int index, string defaultValue = "")
		{
			if (index >= ParamList.Length)
			{
				return defaultValue;
			}
			return ParamList[index];
		}
	}
	public class DialogOptionCommand
	{
		public string Option { get; set; }

		public string TagEvent { get; set; }

		public string Condition { get; set; }

		public DialogOptionCommand()
		{
		}

		public DialogOptionCommand(string optionStr)
		{
			string[] array = optionStr.Split('#');
			Option = array[0];
			TagEvent = ((array.Length >= 2) ? array[1] : "");
			Condition = ((array.Length >= 3) ? array[2] : "");
		}
	}
	public class DialogEventData
	{
		[JsonProperty(PropertyName = "id")]
		public string ID { get; set; }

		[JsonProperty(PropertyName = "character")]
		public Dictionary<string, int> Character { get; set; }

		[JsonProperty(PropertyName = "dialog")]
		public string[] Dialog { get; set; }

		[JsonProperty(PropertyName = "option")]
		public string[] Option { get; set; }

		public DialogCommand GetDialogCommand(int index, DialogEnvironment env)
		{
			string commandStr = Dialog[index];
			bool isEnd = index == Dialog.Length - 1;
			return new DialogCommand(commandStr, this, env, isEnd);
		}

		public DialogOptionCommand[] GetOptionCommands()
		{
			if (Option == null)
			{
				return Array.Empty<DialogOptionCommand>();
			}
			DialogOptionCommand[] array = new DialogOptionCommand[Option.Length];
			for (int i = 0; i < array.Length; i++)
			{
				DialogOptionCommand dialogOptionCommand = new DialogOptionCommand(Option[i]);
				array[i] = dialogOptionCommand;
			}
			return array;
		}
	}
	public class DialogEventRtData
	{
		public DialogEventData BindEventData { get; set; }

		public DialogEnvironment BindEnv { get; set; }
	}
	public class DialogTriggerData
	{
		/// <summary>
		/// 触发器ID
		/// </summary>
		[JsonProperty(PropertyName = "id")]
		public string ID { get; set; } = string.Empty;


		/// <summary>
		/// 触发类型
		/// </summary>
		[JsonProperty(PropertyName = "type")]
		public string Type { get; set; } = string.Empty;


		/// <summary>
		/// 触发条件
		/// </summary>
		[JsonProperty(PropertyName = "condition")]
		public string Condition { get; set; } = string.Empty;


		/// <summary>
		/// 触发事件
		/// </summary>
		[JsonProperty(PropertyName = "triggerEvent")]
		public string TriggerEvent { get; set; } = string.Empty;


		/// <summary>
		/// 绑定数据
		/// </summary>
		[JsonProperty(PropertyName = "bindData")]
		public string BindData { get; set; } = string.Empty;


		/// <summary>
		/// 触发优先级
		/// </summary>
		[JsonProperty(PropertyName = "priority")]
		public int Priority { get; set; }

		/// <summary>
		/// 初始状态
		/// </summary>
		[JsonProperty(PropertyName = "default")]
		public bool Default { get; set; } = true;


		/// <summary>
		/// 触发一次后关闭
		/// </summary>
		[JsonProperty(PropertyName = "once")]
		public bool Once { get; set; }
	}
	[AttributeUsage(AttributeTargets.Class, AllowMultiple = true)]
	public class DialogEnvQueryAttribute : Attribute
	{
		public string RegisterMethod { get; set; }

		public DialogEnvQueryAttribute(string method)
		{
			RegisterMethod = method;
		}
	}
	public interface IDialogEnvQuery
	{
		object Execute(DialogEnvQueryContext context);
	}
	public class DialogEnvQueryContext
	{
		public DialogEnvironment Env { get; }

		public object[] Args { get; }

		public DialogEnvQueryContext(DialogEnvironment env, object[] args)
		{
			Env = env;
			Args = args;
		}

		public object GetArg(int index, object defaultValue = null)
		{
			if (index < 0 || index >= Args.Length)
			{
				return defaultValue;
			}
			return Args[index];
		}

		public T GetArg<T>(int index, T defaultValue = default(T))
		{
			if (index < 0 || index >= Args.Length)
			{
				return defaultValue;
			}
			if (Args[index] is T)
			{
				return (T)Args[index];
			}
			return defaultValue;
		}
	}
	public class TriggerState
	{
		public bool Enabled { get; set; } = true;


		public int Count { get; set; }
	}
