	/// <summary>
	/// 添加关系
	/// </summary>
	[DialogEvent("AddRelation")]
	public class AddRelation : IDialogEvent
	{
		public void Execute(DialogCommand command, DialogEnvironment env, Action callback)
		{
			int num = NPCEx.NPCIDToNew(command.GetInt(0));
			switch (command.GetInt(1))
			{
			case 0:
				if (!PlayerEx.IsTheather(num))
				{
					PlayerEx.Player.TeatherId.Add(num);
				}
				break;
			case 1:
				if (!PlayerEx.IsTuDi(num))
				{
					PlayerEx.Player.TuDiId.Add(num);
				}
				break;
			case 2:
				if (!PlayerEx.IsDaoLv(num))
				{
					PlayerEx.Player.DaoLvId.Add(num);
				}
				break;
			case 3:
				if (!PlayerEx.IsBrother(num))
				{
					PlayerEx.Player.Brother.Add(num);
				}
				break;
			}
			callback?.Invoke();
		}
	}
