				{
					break;
				}
				List<int> list = PlayerEx.Player.Brother.ToList();
				list.Remove(num);
				PlayerEx.Player.Brother = new JSONObject((Type)4);
				foreach (int item4 in list)
				{
					PlayerEx.Player.Brother.Add(item4);
				}
