	[DialogEvent("ShowOption")]
	[DialogEvent("SayOption")]
	public class ShowOption : IDialogEvent
	{
		public void Execute(DialogCommand command, DialogEnvironment env, Action callback)
		{
			bool flag = false;
			bool flag2 = false;
			int num = 0;
			int num2 = command.ParamList.Length;
			if (command.Command == "SayOption")
			{
				flag2 = true;
				num += 2;
			}
			DialogAnalysis.ClearMenu();
			for (int i = num; i < num2; i++)
			{
				string[] array = command.GetStr(i, "0::").Split(':');
				int optionID = int.Parse(array[0]);
				string text = array[1];
				string str = ((array.Length <= 2) ? string.Empty : array[2]);
				if (DialogAnalysis.StringIsNullOrTrue(str))
				{
					flag = true;
					DialogAnalysis.AddMenu(text, delegate
					{
						env.optionID = optionID;
						callback?.Invoke();
					});
				}
			}
			if (flag2)
			{
				string str2 = command.GetStr(0);
				string str3 = command.GetStr(1);
				if (!command.BindEventData.Character.TryGetValue(str2, out var value) && !DialogAnalysis.TmpCharacter.TryGetValue(str2, out value))
				{
					value = 0;
				}
				string text2 = DialogAnalysis.DealSayText(str3, value);
				DialogAnalysis.SetCharacter(value);
				if (flag)
				{
					DialogAnalysis.Say(text2, delegate
					{
					});
					return;
				}
				DialogAnalysis.Say(text2, delegate
				{
					callback?.Invoke();
				});
			}
			else if (!flag)
			{
				callback?.Invoke();
			}
		}
	}
