		[HarmonyPatch(typeof(UI_Manager), "Update")]
		public class AfterBattleDialogPatch
		{
			[HarmonyPrefix]
			public static void Prefix()
			{
				//IL_000d: Unknown result type (might be due to invalid IL or missing references)
				//IL_0012: Unknown result type (might be due to invalid IL or missing references)
				if (Tools.instance.getPlayer() == null)
				{
					return;
				}
				Scene activeScene = SceneManager.GetActiveScene();
				string name = ((Scene)(ref activeScene)).name;
				bool flag = DialogAnalysis.GetInt("Fight", "IsEventFight") == 1;
				bool flag2 = name == "YSNewFight";
				if (!(Tools.instance.isNeedSetTalk && flag))
				{
					return;
				}
				if (Tools.instance.loadSceneType == 0)
				{
					if (name.Equals(Tools.instance.ohtherSceneName) && flag2)
					{
						OnFightStart.Trigger();
					}
				}
				else if (name.Equals(Tools.jumpToName))
				{
					Tools.instance.CanShowFightUI = 0;
					string str = DialogAnalysis.GetStr("Fight", "VictoryEvent");
					string str2 = DialogAnalysis.GetStr("Fight", "DefeatEvent");
					bool flag3 = DialogAnalysis.GetInt("Fight", "IsVictory") == 1;
					ResetEventFight();
					if (flag3 && !string.IsNullOrEmpty(str))
					{
						DialogAnalysis.StartDialogEvent(str);
					}
					else if (!flag3 && !string.IsNullOrEmpty(str2))
					{
						DialogAnalysis.StartDialogEvent(str2);
					}
				}
			}
		}

		[HarmonyPatch(typeof(RoundManager), "Awake")]
		public class BackgroundPatch
