		public static string[] FightTags;

		private static string lastScene = string.Empty;

		public void Execute(DialogCommand command, DialogEnvironment env, Action callback)
		{
			//IL_001f: Unknown result type (might be due to invalid IL or missing references)
			//IL_01e3: Unknown result type (might be due to invalid IL or missing references)
			//IL_01e4: Unknown result type (might be due to invalid IL or missing references)
			try
			{
				int num = NPCEx.NPCIDToNew(command.GetInt(0));
				int @int = command.GetInt(1);
				FightEnumType fightType = (FightEnumType)command.GetInt(2);
				int int2 = command.GetInt(3);
				string str = command.GetStr(4);
				string str2 = command.GetStr(5);
				string str3 = command.GetStr(6);
				string str4 = command.GetStr(7);
				string str5 = command.GetStr(8);
				string str6 = command.GetStr(9);
				SetEventFight(str4, str5, str6.Split(','));
				string[] array = str2.Split('|');
				foreach (string text in array)
				{
					if (!string.IsNullOrEmpty(text))
					{
						string[] array2 = text.Split(',');
						int key = int.Parse(array2[0]);
						int value = int.Parse(array2[1]);
						if (!Tools.instance.monstarMag.HeroAddBuff.ContainsKey(key))
						{
							Tools.instance.monstarMag.HeroAddBuff.Add(key, value);
						}
					}
				}
				array = str3.Split('|');
				foreach (string text2 in array)
				{
					if (!string.IsNullOrEmpty(text2))
					{
						string[] array3 = text2.Split(',');
						int key2 = int.Parse(array3[0]);
						int value2 = int.Parse(array3[1]);
						if (!Tools.instance.monstarMag.monstarAddBuff.ContainsKey(key2))
						{
							Tools.instance.monstarMag.monstarAddBuff.Add(key2, value2);
						}
					}
				}
				DialogAnalysis.CancelEvent();
				MusicMag.instance.playMusic(str);
				Tools.instance.monstarMag.FightImageID = int2;
				Tools.instance.CanFpRun = @int;
				Tools.instance.monstarMag.FightType = fightType;
				Tools.instance.startFight(num);
			}
			catch (Exception)
			{
				ResetEventFight();
				throw;
			}
		}

		public static void SetEventFight(string victory, string defeat, string[] tags)
		{
			FightTags = tags;
			DialogAnalysis.SetStr("Fight", "VictoryEvent", victory);
			DialogAnalysis.SetStr("Fight", "DefeatEvent", defeat);
			DialogAnalysis.SetInt("Fight", "IsVictory", 0);
			DialogAnalysis.SetInt("Fight", "IsEventFight", 1);
		}

		public static void ResetEventFight()
		{
			if (Tools.instance.getPlayer() != null)
			{
				FightTags = null;
				DialogAnalysis.SetStr("Fight", "VictoryEvent", "");
				DialogAnalysis.SetStr("Fight", "DefeatEvent", "");
				DialogAnalysis.SetInt("Fight", "IsVictory", 0);
				DialogAnalysis.SetInt("Fight", "IsEventFight", 0);
			}
		}
	}
	[DialogEvent("UseItem")]
	public class UseItem : IDialogEvent
	{
		public void Execute(DialogCommand command, DialogEnvironment env, Action callback)
		{
			int @int = command.GetInt(0);
			if (!command.GetBool(1) && env.player.getItemNum(@int) > 0)
			{
				env.player.addItem(@int, 1, (JSONObject)null, false);
			}
			BaseItem.Create(@int, 1, Tools.getUUID(), Tools.CreateItemSeid(@int)).Use();
			MessageMag.Instance.Send(MessageName.MSG_PLAYER_USE_ITEM, (MessageData)null);
			callback?.Invoke();
		}
	}
